// ── GLOBAL ERROR HANDLER ────────────────────────────────────
(function(){
  window.addEventListener('error', function(e){
    console.error('[Velo Premium]', e.message, e.filename, e.lineno);
  });
  window.addEventListener('unhandledrejection', function(e){
    console.error('[Velo Premium] Promise:', e.reason);
  });
})();

// ── FIX DEFINITIVO banda muerta bajo la barra al cerrar el teclado (iOS PWA) ──
// v1389 — HISTORIA: v1347 pinneaba shell.style.height = visualViewport.height
// mientras el teclado estaba abierto; v1378 intentó restaurarlo al cerrar. Ese
// enfoque es la CAUSA del bug: al cerrar, la altura quedaba fijada en un valor
// chico (o el restore corría contra la animación de iOS), dejando el app-shell
// más corto que la pantalla → la barra de navegación quedaba flotando en el
// medio con fondo vacío abajo.
//
// AHORA: NO se toca nunca la altura del shell. El CSS usa 100dvh, que iOS
// recalcula solo (el teclado es un "interactive widget" que NO achica el dvh),
// así el shell SIEMPRE ocupa la pantalla completa y la barra queda pegada
// abajo. Lo único que hacemos por JS es:
//   1) toggle body.keyboard-open (el CSS esconde la barra mientras se escribe),
//   2) forzar window.scrollTo(0,0) cuando el teclado se cierra — iOS scrollea
//      la ventana para revelar el input y no lo deshace; el scroll real del
//      contenido vive en .p-page-scroll, así que resetear la ventana es seguro.
(function(){
  if(!window.visualViewport) return;
  var vv = window.visualViewport;
  var kbWasOpen = false;
  function _resetWindowScroll(){
    try{
      window.scrollTo(0, 0);
      if(document.documentElement) document.documentElement.scrollTop = 0;
      if(document.body) document.body.scrollTop = 0;
    }catch(_){}
  }
  function onVvChange(){
    try{
      var isKeyboardOpen = vv.height < window.innerHeight * 0.82;
      document.body.classList.toggle('keyboard-open', isKeyboardOpen);
      if(isKeyboardOpen){
        kbWasOpen = true;
      } else if(kbWasOpen){
        kbWasOpen = false;
        // iOS puede re-aplicar el offset durante la animación de cierre — varios
        // intentos escalonados cubren toda la ventana de la animación.
        _resetWindowScroll();
        setTimeout(_resetWindowScroll, 80);
        setTimeout(_resetWindowScroll, 250);
        setTimeout(_resetWindowScroll, 500);
      }
    }catch(e){}
  }
  vv.addEventListener('resize', onVvChange);
  vv.addEventListener('scroll', onVvChange);
  // Fallback: al perder foco un input (a veces el resize no dispara en iOS PWA)
  document.addEventListener('focusout', function(){
    setTimeout(function(){
      if(!document.body.classList.contains('keyboard-open')){
        _resetWindowScroll();
        setTimeout(_resetWindowScroll, 250);
      }
    }, 200);
  }, true);
  onVvChange();
})();

// ── DIAGNÓSTICO DE LAYOUT (v1401) — tocar la versión en el menú ☰ ─────
// Muestra las medidas reales del viewport y de la barra para diagnosticar
// el espacio bajo la barra en el dispositivo del usuario, sin adivinar.
function _veloLayoutDiag(){
  try{
    var nav = document.querySelector('.p-bottomnav');
    var shell = document.querySelector('.p-app-shell');
    var nr = nav ? nav.getBoundingClientRect() : null;
    var sr = shell ? shell.getBoundingClientRect() : null;
    var cs = nav ? getComputedStyle(nav) : null;
    // Probe de safe-area
    var probe = document.createElement('div');
    probe.style.cssText = 'position:fixed;bottom:0;padding-bottom:env(safe-area-inset-bottom,0px);visibility:hidden';
    document.body.appendChild(probe);
    var safeB = getComputedStyle(probe).paddingBottom;
    probe.remove();
    var lines = [
      'Velo v1478',
      'standalone: ' + (navigator.standalone === true ? 'SÍ (app instalada)' : (navigator.standalone === false ? 'NO (Safari)' : 'desconocido')),
      'innerH: ' + window.innerHeight + ' · screenH: ' + (screen && screen.height),
      'vv.height: ' + (window.visualViewport ? Math.round(window.visualViewport.height) : '—'),
      'safe-area-bottom: ' + safeB,
      nav ? ('NAV → position:' + cs.position + ' · display:' + cs.display) : 'NAV: no encontrada',
      nr ? ('NAV rect → top:' + Math.round(nr.top) + ' bottom:' + Math.round(nr.bottom) + ' h:' + Math.round(nr.height)) : '',
      nr ? ('GAP bajo la barra: ' + Math.round(window.innerHeight - nr.bottom) + 'px') : '',
      cs ? ('NAV min-h:' + cs.minHeight + ' · pad-b:' + cs.paddingBottom) : '',
      sr ? ('SHELL bottom:' + Math.round(sr.bottom) + ' (innerH ' + window.innerHeight + ')') : ''
    ].filter(Boolean);
    var ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.88);display:flex;align-items:center;justify-content:center;padding:24px';
    ov.onclick = function(){ ov.remove(); };
    ov.innerHTML = '<div style="background:#0e1f14;border:1px solid rgba(116,198,157,.4);border-radius:16px;padding:20px;font-family:monospace;font-size:13px;line-height:1.9;color:#c8f0d8;max-width:360px;word-break:break-all">'
      + lines.map(function(l){ return '<div>'+l+'</div>'; }).join('')
      + '<div style="margin-top:12px;font-family:Jost,sans-serif;font-size:11px;color:rgba(200,240,216,.55)">Sacale captura y mandala · tocá para cerrar</div></div>';
    document.body.appendChild(ov);
  }catch(e){ try{ alert('diag err: '+e.message); }catch(_){} }
}

