var SUPABASE_URL  = 'https://yuravtnjvvztsxdtggod.supabase.co';
var SUPABASE_ANON = 'sb_publishable_mBoqW2t3QoJvp5jFecEGgQ_1wrPiT9C';
var STRIPE_PK     = 'pk_live_51TXmCcV05dCjGGP2F9YnbPBIantFoxurCpISx86i0DFNFcmM2sovtp5LcV5tOVxI72V4AfgY8sK5GtJVTyYnnI1L00QwkGS6P4';
var VELO_EMAIL    = 'consultas@heyvelo.app';
var SUPABASE_FN   = SUPABASE_URL + '/functions/v1/stripe-checkout';

var _supabaseLib = (typeof window !== 'undefined') ? window.supabase : null;
var sbClient = null;

function _initSupabase(){
  if(sbClient) return;
  if(!_supabaseLib || !_supabaseLib.createClient){
    _supabaseLib = (typeof window !== 'undefined') ? window.supabase : null;
  }
  if(_supabaseLib && _supabaseLib.createClient){
    sbClient = _supabaseLib.createClient(SUPABASE_URL, SUPABASE_ANON);
    // Cross-account session guard: if another user's token becomes active while this
    // app is running (same browser, second tab, or refresh token swap), detect it and
    // force re-login to prevent one account's data from leaking into another.
    // Realtime usa la anon key por defecto. Con RLS que exigen auth.uid() (DMs,
    // notificaciones, guardian_requests, circle_messages, etc.), el realtime-como-anon
    // NO recibe filas -> las actualizaciones solo llegaban al recargar/cambiar de
    // sección (el REST sí manda el JWT). Pasarle el token al websocket lo arregla.
    function _syncRealtimeAuth(tok){
      if(tok) _veloAccessToken = tok; // v1594: cachear el JWT para autenticar los proxies de IA
      try{ if(tok && sbClient.realtime && sbClient.realtime.setAuth) sbClient.realtime.setAuth(tok); }catch(_){}
    }
    try{ sbClient.auth.getSession().then(function(r){ var s=r&&r.data&&r.data.session; if(s&&s.access_token) _syncRealtimeAuth(s.access_token); }).catch(function(){}); }catch(_){}
    sbClient.auth.onAuthStateChange(function(event, session){
      if(session && session.access_token) _syncRealtimeAuth(session.access_token); // mantener el realtime autenticado (login/refresh/sesión inicial)
      if(!_authenticated) return; // ignore events during login/init flow
      var _storedUid = safeLS('get','velo_user_id') || '';
      if(!_storedUid) return; // no stored user yet — still setting up
      if(event === 'SIGNED_OUT'){
        _veloAccessToken = '';
        _clearSession();
        _authenticated = false;
        if(typeof pGoTo === 'function') pGoTo('landing');
        if(typeof pToast === 'function') pToast('🌿','Sesión cerrada');
      } else if(session && session.user && session.user.id !== _storedUid){
        // A different user's session became active — this device was shared or
        // another tab logged in. Force re-login to prevent cross-user data leaks.
        _clearSession();
        _authenticated = false;
        try{ sbClient.auth.signOut(); }catch(e){}
        if(typeof pGoTo === 'function') pGoTo('landing');
        if(typeof pToast === 'function') pToast('⚠️','Cambio de cuenta detectado, ingresá nuevamente');
      }
    });
  }
}

// ── LOCAL STORAGE WRAPPER ───────────────────────────────────
function safeLS(action, key, val){
  try{
    if(action==='get') return localStorage.getItem(key);
    if(action==='set') localStorage.setItem(key, val);
    // v1594: 'remove' era un no-op (solo se manejaba 'del') → 3 call sites que
    // limpiaban la push_subscription vieja no hacían nada y dejaban a la app
    // creyendo que las notis ya estaban activas. Ahora 'remove' == 'del'.
    if(action==='del' || action==='remove') localStorage.removeItem(key);
  }catch(e){ return null; }
}

// ── DAILY LIMITS ────────────────────────────────────────────
// v1510: la clave usa la fecha LOCAL (antes UTC → en Argentina el cupo se
// renovaba a las 21:00, dando usos extra). Y el bypass de plan usa _isPremium()
// (antes solo velo_plan → un usuario Plus legítimo por subscribers/user_type
// quedaba limitado incorrectamente).
function _dailyKey(type){
  var d = new Date();
  var f = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  return 'velo_daily_'+type+'_'+f;
}
function _checkDailyLimit(type){
  var limits = { bottle:4, help:4, guardian:4, calmai:25 };
  if(_isPremium()) return true;
  var used = parseInt(safeLS('get',_dailyKey(type))||'0',10);
  return used < (limits[type]||99);
}
function _incDailyLimit(type){
  var k = _dailyKey(type);
  safeLS('set',k, String(parseInt(safeLS('get',k)||'0',10)+1));
}

