  _obData = type === 'pro' ? _obDataPro : _obDataUser;
  var dotsEl = document.getElementById('obDots');
  if(dotsEl) dotsEl.innerHTML = _obData.map(function(_,i){ return '<div class="ob-dot'+(i===0?' active':'')+'"></div>'; }).join('');
