function _checkAndShowNameBanner(name){
  var email = safeLS('get','velo_user_email')||'';
  var emailPfx = email.split('@')[0];
  var looksAutoGen = !name || name === emailPfx || name === email ||
                     /^[a-zA-Z0-9._-]+\d{3,}$/.test(name) ||
                     (name.indexOf(' ') < 0 && /^\w+\.\w+\d+$/.test(name));
  var banner = document.getElementById('homeNameBanner');
  if(!looksAutoGen){ if(banner) banner.remove(); return; }
  if(banner) return; // already showing
  var b = document.createElement('div');
  b.id = 'homeNameBanner';
  b.className = 'home-name-banner';
  b.innerHTML = '<div class="home-name-banner-title">👋 ¿Cuál es tu nombre real?</div>'
    +'<div style="font-size:13px;color:var(--ink3);line-height:1.4">Tu nombre se muestra como usuario técnico. Ingresá tu nombre real para que se vea en todos tus dispositivos.</div>'
    +'<div style="display:flex;gap:8px;align-items:center">'
    +'<input id="homeNameInput" type="text" placeholder="Tu nombre o apodo" value="'+_escHtml(name !== emailPfx ? name : '')+'" class="home-name-banner-input">'
    +'<button onclick="_saveNameFromBanner()" style="padding:8px 16px;border-radius:10px;border:none;background:var(--sage);color:#fff;font-size:15px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer;white-space:nowrap">Guardar →</button>'
    +'</div>';
  var scrollEl = document.querySelector('#pg-home .p-page-scroll');
  if(scrollEl) scrollEl.insertBefore(b, scrollEl.querySelector('.home-header') || scrollEl.firstChild);
}

async function _saveNameFromBanner(){
  var inp = document.getElementById('homeNameInput');
  if(!inp) return;
  var newName = inp.value.trim();
  if(!newName || newName.length < 2){ pToast('⚠️','Ingresá un nombre válido'); return; }
  safeLS('set','velo_user_name', newName);
  var un = document.getElementById('homeUserName');
  if(un) un.textContent = newName;
  var unf = document.getElementById('homeUserNameFab');
  if(unf) unf.textContent = newName;
  _initSupabase();
  if(!sbClient){ pToast('✅','Nombre guardado en este dispositivo'); var b=document.getElementById('homeNameBanner'); if(b)b.remove(); _updateSidebarUser(); return; }
  // Get UID from session (don't rely solely on velo_user_id which may be stale)
  var uid = safeLS('get','velo_user_id');
  try{
    var {data:sd} = await sbClient.auth.getSession();
    if(sd && sd.session && sd.session.user && sd.session.user.id){
      uid = sd.session.user.id;
      safeLS('set','velo_user_id', uid);
    }
  }catch(e){}
  if(!uid){ pToast('✅','Nombre guardado en este dispositivo'); var b2=document.getElementById('homeNameBanner'); if(b2)b2.remove(); _updateSidebarUser(); return; }
  var email = safeLS('get','velo_user_email')||'';
  try{
    // Always UPSERT — UPDATE on missing row returns no error but saves nothing.
    // v1598: NO incluir email si está vacío en LS (cross-device) — si no, el upsert
    // pisaría el email real del perfil con '' y rompería el mapeo de Plus/admin.
    var _profUpd = { id:uid, nombre:newName };
    if(email) _profUpd.email = email;
    var r = await sbClient.from('profiles').upsert(_profUpd,{onConflict:'id'});
    if(r && r.error){ pToast('⚠️','Error al guardar: '+r.error.message); return; }
    pToast('✅','¡Nombre guardado! Ya se verá en todos tus dispositivos 🌿');
    var banner = document.getElementById('homeNameBanner');
    if(banner) banner.remove();
    _updateSidebarUser();
    // Push other profile fields in background.
    // v1598: incluir SOLO los campos que tenemos localmente. Antes se mandaban
    // todos con ||'' → si guardabas el nombre en un dispositivo sin esos valores
    // en LS (los pusiste en otro), el upsert pisaba avatar/motto/estados del server
    // con '' (pérdida de datos). Solo sincronizamos lo que existe.
    try{
      var av = safeLS('get','velo_user_av')||'';
      if(av.length > 8000) av = '';
      var _sUpd = { id: uid };
      if(av) _sUpd.avatar = av;
      var _sf = { motto:'velo_user_motto', status_music:'velo_status_music', status_book:'velo_status_book', status_phrase:'velo_status_phrase', status_film:'velo_status_film' };
      Object.keys(_sf).forEach(function(k){ var _v = safeLS('get', _sf[k])||''; if(_v) _sUpd[k] = _v; });
      if(Object.keys(_sUpd).length > 1){
        sbClient.from('profiles').upsert(_sUpd,{onConflict:'id'}).then(function(){}).catch(function(){});
      }
    }catch(e2){}
  }catch(e){ pToast('⚠️','Error de conexión'); }
}

// ── CROSS-DEVICE MOOD SYNC ─────────────────────────────────────
// On first load in a fresh browser, pull this week's moods from Supabase
// into localStorage so the home graph, share card, etc. show real data.
var _moodSyncDone = false;
var _moodResetPending = false; // blocks _pushMissingMoodsToSb during/after cleanup
async function _syncMoodsFromSb(){
  if(_moodSyncDone) return;
  _moodSyncDone = true;
  _initSupabase();
  if(!sbClient) return;
  try{
    var ok = await _ensureSbSession();
    if(!ok){ _moodSyncDone = false; return; }
    // Privacy guard: verify Supabase auth session belongs to the current localStorage user
    var {data:_authD} = await sbClient.auth.getUser();
    if(!_authD || !_authD.user){ _moodSyncDone = false; return; }
    var _lsUid = safeLS('get','velo_user_id') || '';
    if(_lsUid && _authD.user.id !== _lsUid){ _moodSyncDone = false; return; }
    var now = new Date();
    var months = {};
    // Cover last 90 days so stale keys from older months (other users) are also purged
    for(var i=0;i<90;i++){
      var d2=new Date(now.getFullYear(),now.getMonth(),now.getDate()-i);
      var mk=d2.getFullYear()+'-'+String(d2.getMonth()+1).padStart(2,'0');
      if(!months[mk]) months[mk]={year:d2.getFullYear(),month:d2.getMonth()+1};
    }
    // Also nuke any velo_mood_* key outside the covered range (belt-and-suspenders)
    var _coveredPfx = {};
    Object.values(months).forEach(function(m){ _coveredPfx['velo_mood_'+m.year+'-'+String(m.month).padStart(2,'0')] = true; });
    for(var _ei = localStorage.length - 1; _ei >= 0; _ei--){
      var _ek = localStorage.key(_ei);
      if(_ek && _ek.startsWith('velo_mood_')){
        var _matched = Object.keys(_coveredPfx).some(function(pfx){ return _ek.startsWith(pfx); });
        if(!_matched) localStorage.removeItem(_ek);
      }
    }
    await Promise.all(Object.values(months).map(async function(m){
      var rows = await sbLoadAllMoods(m.year, m.month);
      if(rows !== null){
        // Build set of date_keys Supabase actually has for this user
        var _sbKeys = {};
        rows.forEach(function(e){ if(e.emoji) _sbKeys[e.date_key] = true; });
        // Purge contaminated localStorage keys: any velo_mood_YYYY-MM-* NOT in Supabase must go
        var _pfx = 'velo_mood_'+m.year+'-'+String(m.month).padStart(2,'0');
        for(var _li = localStorage.length - 1; _li >= 0; _li--){
          var _lk = localStorage.key(_li);
          if(_lk && _lk.startsWith(_pfx)){
            var _dk = _lk.replace('velo_mood_','');
            if(!_sbKeys[_dk]) localStorage.removeItem(_lk);
          }
        }
        // Write authoritative Supabase data
        rows.forEach(function(e){
          if(e.emoji){
            safeLS('set','velo_mood_'+e.date_key, JSON.stringify({emoji:e.emoji,label:e.label||'',note:e.note||'',ts:0}));
          }
        });
      }
    }));
    // Re-render graph now that localStorage is clean and populated
    _renderHomeWeekMoodGraph().catch(function(){});
    _initShareWeekBtn();
    _updateHomeStreak(); // re-render with clean count
  }catch(e){}
}

// Push any local moods that are missing from Supabase (covers cases where sbSaveMoodEntry failed silently)
async function _pushMissingMoodsToSb(){
  if(_moodResetPending) return; // don't restore moods that were just intentionally deleted
  // Sync from Supabase FIRST so we have the authoritative count before deciding what to push.
  // Without this, _pushMissingMoodsToSb can run before the 800ms setTimeout(_syncMoodsFromSb)
  // fires, uploading stale local moods to a Supabase that was intentionally emptied.
  if(!_moodSyncDone) await _syncMoodsFromSb();
  if(_moodResetPending) return; // re-check after await
  _initSupabase();
  if(!sbClient) return;
  try{
    var ok = await _ensureSbSession();
    if(!ok) return;
    // Privacy guard: abort if Supabase session doesn't match current user
    var {data:_authDP} = await sbClient.auth.getUser();
    if(!_authDP || !_authDP.user) return;
    var _lsUidP = safeLS('get','velo_user_id') || '';
    if(_lsUidP && _authDP.user.id !== _lsUidP) return;
    // Collect last 60 days of local moods
    var now = new Date();
    var _todayKey = now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
    var _clearedAt = parseInt(safeLS('get','velo_mood_cleared_at')||'0');
    var localMoods = {};
    var months = {};
    for(var i=0; i<60; i++){
      var _ld = new Date(now.getFullYear(), now.getMonth(), now.getDate()-i);
      var _lk = _ld.getFullYear()+'-'+String(_ld.getMonth()+1).padStart(2,'0')+'-'+String(_ld.getDate()).padStart(2,'0');
      var _lm = null; try{ _lm = JSON.parse(safeLS('get','velo_mood_'+_lk)||'null'); }catch(e){}
      if(_lm && _lm.emoji){
        // If Supabase confirmed 0 entries this session, only allow today's mood —
        // older local entries are stale from before an intentional clear
        if(_moodSyncDone && _sbVerifiedMoodCount === 0 && _lk !== _todayKey){
          safeLS('del','velo_mood_'+_lk); // purge stale local entry
          continue;
        }
        // If a cleared_at timestamp exists, skip moods from before the clear.
        // v1594: comparar por el timestamp REAL de registro (o el FIN del día local
        // como fallback), no por new Date(_lk) que es UTC-midnight — en husos
        // negativos eso hacía que el ánimo de HOY quedara "antes" del clear y se
        // borrara. Además, nunca purgar el día de hoy.
        if(_clearedAt && _lk !== _todayKey){
          var _mt = _lm.ts ? parseInt(_lm.ts) : new Date(_lk+'T23:59:59').getTime();
          if(_mt < _clearedAt){
            safeLS('del','velo_mood_'+_lk);
            continue;
          }
        }
        localMoods[_lk] = _lm;
      }
      var _mk = _ld.getFullYear()+'-'+String(_ld.getMonth()+1).padStart(2,'0');
      if(!months[_mk]) months[_mk] = {year:_ld.getFullYear(), month:_ld.getMonth()+1};
    }
    if(!Object.keys(localMoods).length) return;
    // Fetch what Supabase already has for those months
    var sbKeys = {};
    await Promise.all(Object.values(months).map(async function(m){
      var rows = await sbLoadAllMoods(m.year, m.month);
      if(rows) rows.forEach(function(e){ sbKeys[e.date_key] = true; });
    }));
    // Push missing ones
    var toSync = Object.keys(localMoods).filter(function(k){ return !sbKeys[k]; });
    await Promise.all(toSync.map(function(k){
      var m = localMoods[k];
      return sbSaveMoodEntry(k, m.emoji, m.label||'', m.note||'');
    }));
  }catch(e){}
}

// El banner se puede cerrar con la cruz; queda oculto hasta el día siguiente (v1368)
function pDismissPushBanner(){
  var banner = document.getElementById('homePushBanner');
  if(banner) banner.style.display = 'none';
  try{ safeLS('set','velo_push_banner_dismissed', new Date().toISOString().slice(0,10)); }catch(_){}
}
function _renderHomePushBanner(){
  var banner = document.getElementById('homePushBanner');
  if(!banner) return;
  // Cerrado hoy con la cruz → no volver a mostrar hasta mañana
  try{
    if(safeLS('get','velo_push_banner_dismissed') === new Date().toISOString().slice(0,10)){
      banner.style.display = 'none'; return;
    }
  }catch(_){}
  // Inyectar la cruz de cierre una sola vez (esquina superior derecha del banner)
  if(!document.getElementById('homePushBannerClose')){
    try{
      banner.style.position = 'relative';
      var xBtn = document.createElement('button');
      xBtn.id = 'homePushBannerClose';
      xBtn.setAttribute('aria-label','Cerrar');
      xBtn.textContent = '✕';
      xBtn.style.cssText = 'position:absolute;top:8px;right:8px;background:rgba(255,255,255,.16);border:1.5px solid rgba(255,255,255,.35);border-radius:100px;width:28px;height:28px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:900;color:inherit;cursor:pointer;line-height:1;padding:0;z-index:2;box-shadow:0 2px 6px rgba(0,0,0,.25)';
      xBtn.onclick = function(e){ e.stopPropagation(); pDismissPushBanner(); };
      banner.appendChild(xBtn);
      banner.style.paddingRight = '44px'; // que el texto no quede debajo de la cruz
    }catch(_){}
  }
  var ua = navigator.userAgent;
  var isIOS = /iPhone|iPad|iPod/.test(ua);
  var isAndroid = /Android/.test(ua);
  // On iOS, only Safari supports PWA install + Web Push. Chrome/Firefox/etc. can't do it.
  var isIOSNonSafari = isIOS && /CriOS|FxiOS|OPiOS|mercury|EdgiOS/.test(ua);
  var isIOSSafari = isIOS && !isIOSNonSafari;
  var isMobile = isIOS || isAndroid;
  var isStandalone = !!(window.navigator.standalone || window.matchMedia('(display-mode: standalone)').matches);
  var hasNotifAPI = 'Notification' in window && 'serviceWorker' in navigator && 'PushManager' in window;
  var hasSub = !!safeLS('get','velo_push_sub');
  var perm = hasNotifAPI ? Notification.permission : 'default';
  var icon = document.getElementById('homePushBannerIcon');
  var txt  = document.getElementById('homePushBannerText');
  var btn  = document.getElementById('homePushBannerBtn');
  if(hasSub || perm === 'denied'){ banner.style.display = 'none'; return; }
  if(isIOSNonSafari && !isStandalone){
    // iOS Chrome/Firefox: must switch to Safari — no PWA install possible here
    banner.style.display = 'flex';
    if(icon) icon.textContent = '🦁';
    if(txt)  txt.textContent  = 'En iPhone, solo Safari puede instalar apps con notificaciones — es una limitación de Apple. Abrí heyvelo.app en Safari para continuar 🦁';
    if(btn){ btn.textContent = 'Copiar enlace'; btn.setAttribute('data-action','copy-url'); }
  } else if(!isStandalone && isMobile){
    banner.style.display = 'flex';
    if(icon) icon.textContent = '📲';
    if(txt)  txt.textContent  = 'Agregá Velo a tu pantalla de inicio para usarla como cualquier app de tu teléfono. Desde ahí también podés activar las notificaciones 📣';
    if(btn){ btn.textContent = '¿Cómo?'; btn.setAttribute('data-action', isIOSSafari ? 'how-ios' : 'how-android'); }
  } else if(isStandalone && hasNotifAPI && perm !== 'granted'){
    banner.style.display = 'flex';
    if(icon) icon.textContent = '🔔';
    if(txt)  txt.textContent  = 'Activá las notificaciones para recibir tu recordatorio diario 📣';
    if(btn){ btn.textContent = 'Activar'; btn.setAttribute('data-action','activate'); }
  } else {
    banner.style.display = 'none';
  }
}
function _homePushBannerAction(){
  var btn = document.getElementById('homePushBannerBtn');
  var action = btn ? btn.getAttribute('data-action') : '';
  if(action === 'how-ios') _showIOSPushModal();
  else if(action === 'how-android') _showAndroidInstallModal();
  else if(action === 'activate') pTogglePushNotifications();
  else if(action === 'copy-url'){
    try{ navigator.clipboard.writeText('https://heyvelo.app'); }catch(e){}
    pToast('🔗','Enlace copiado — pegalo en Safari 🦁');
  }
}
function _showAndroidInstallModal(){
  var ov = document.getElementById('androidInstallInstrOv');
  if(ov) ov.style.display = 'flex';
}
function _closeAndroidInstallModal(){
  var ov = document.getElementById('androidInstallInstrOv');
  if(ov) ov.style.display = 'none';
}

