// ── HOME DATA ──────────────────────────────────────────────────
function _loadHomeData(){
  _initHomeNavTiles();
  _initDqThemeObserver();
  _initMoodChip();
  _checkVeloNotifs();
  _initHomeQuickCtaStrip();
  // Banners contextuales (ritual dominical + aniversario emocional)
  try{ setTimeout(function(){ _renderSundayRitualBanner(); }, 400); }catch(e){}
  try{ setTimeout(function(){ _checkEmotionalAnniversary(); }, 800); }catch(e){}
  try{ setTimeout(function(){ _checkReferralQualification(); }, 1200); }catch(e){}
  try{ setTimeout(function(){ _checkBuddyExpiry(); }, 1600); }catch(e){}
  try{ setTimeout(function(){ _renderCommunityPulseBanner(); }, 2000); }catch(e){}
  try{ setTimeout(function(){ _checkStreakRecovery(); }, 2400); }catch(e){}
  try{ setTimeout(function(){ _checkAchievements(); }, 3000); }catch(e){}
  // Widget de respiración removido del home a pedido del user (ocupaba mucho).
  // Sigue accesible desde el menú hamburguesa.
  try{ var _br = document.getElementById('veloBreathWidget'); if(_br) _br.remove(); }catch(e){}
  try{ _startInAppNotifPolling(); }catch(e){}
  try{ _scheduleWellbeingCheck(); }catch(e){}
  // v1228: mensual NO se dispara automático. Solo desde admin (pAdminSendMonthlyReport).
  // _checkMonthlyMoodReport();
  var d = new Date();
  var h = d.getHours();
  var greet = (h < 6 || h >= 20) ? 'Buenas noches' : h < 12 ? 'Buenos días' : 'Buenas tardes';
  var months = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  var dateStr = d.getDate() + ' de ' + months[d.getMonth()];

  var gt = document.getElementById('homeGreetTxt');
  var dt = document.getElementById('homeDateTxt');
  if(dt) dt.textContent = dateStr;

  var name = safeLS('get','velo_user_name') || '';
  var firstName = name ? name.trim().split(/\s+/)[0] : '';
  if(gt){
    var safeName = firstName ? firstName.replace(/[<>&"]/g, function(c){ return {'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]; }) : '';
    gt.innerHTML = safeName
      ? greet + ', <span style="color:rgba(200,155,40,.92)">' + safeName + '</span>'
      : greet;
  }
  // Warm contextual sub-message — 7 per period so every day of the week is different
  var _greetSubs = {
    mañana: [
      '¿Cómo empezás el día? 🌱',
      'Hoy puede ser un buen día ☀️',
      'Un nuevo comienzo, un nuevo día 🌿',
      'Respirá profundo y arrancá 🍃',
      '¿Qué querés sentir hoy? ✨',
      'Hoy también cuenta 🌸',
      'El día empieza y vos también 💚'
    ],
    tarde:  [
      'Tomá un respiro en este momento 🍃',
      '¿Cómo va la tarde? ✨',
      'Un momento de calma para vos ☕',
      '¿Ya te cuidaste hoy? 🌿',
      'A veces parar es avanzar 💚',
      'Estamos acá si necesitás 🌱',
      'La tarde también merece un momento 🌸'
    ],
    noche:  [
      'Qué lindo que estás acá esta noche 🌙',
      'Gracias por pasar por acá ✨',
      'Cuidate y descansá bien 🌿',
      'Hoy hiciste lo que pudiste 💚',
      'La noche es tuya para descansar 🌙',
      'Respirá, el día ya pasó 🍃',
      'Estás acá y eso importa ✨'
    ]
  };
  _periodo = h < 12 ? 'mañana' : h < 20 ? 'tarde' : 'noche'; // update module-level
  var _subs = _greetSubs[_periodo];
  // Index by absolute day number so every calendar day gets a different message
  var _dayIdx = Math.floor(Date.now() / 86400000) % _subs.length;
  var gs = document.getElementById('homeGreetSub');
  if(gs) gs.textContent = _subs[_dayIdx];

  // Section stagger fade-in (re-triggers on every home visit)
  var _stagPairs = [
    ['#homeGreetBlock','velo-sec-a0'],
    ['#homeRegisterOuter','velo-sec-a1'],
    ['#homeDailyQuoteWrap','velo-sec-a2']
  ];
  _stagPairs.forEach(function(pair){
    var _se = document.querySelector(pair[0]);
    if(_se){ _se.classList.remove(pair[1]); void _se.offsetWidth; _se.classList.add(pair[1]); }
  });

  // Time-of-day ambient class on body — changes accent colors per period
  document.body.classList.remove('velo-t-manana','velo-t-tarde','velo-t-noche');
  document.body.classList.add(_periodo === 'mañana' ? 'velo-t-manana' : _periodo === 'tarde' ? 'velo-t-tarde' : 'velo-t-noche');
  // Apply background using shared helper (also called on theme toggle)
  _applyBodyGrad();

  var av = safeLS('get','velo_user_av') || '🧑';
  var un = document.getElementById('homeUserName');
  var ha = document.getElementById('homeAv');
  if(un) un.textContent = name || 'Hola';
  var unf = document.getElementById('homeUserNameFab');
  if(unf) unf.textContent = name || 'Perfil';
  // Show name-fix banner only after Supabase sync has had time to run.
  // If name is already in localStorage (returning user on same device), check immediately.
  // If localStorage is empty (new device), wait 3s so _sbSyncProfile can populate it first —
  // this prevents a flash of the banner when Supabase already has a valid real name.
  if(name){
    _checkAndShowNameBanner(name);
  } else {
    setTimeout(function(){ _checkAndShowNameBanner(safeLS('get','velo_user_name')||''); }, 3000);
  }
  if(ha){ _renderAvatarEl('homeAv', av); }
  _renderAvatarEl('homeAvFab', av);

  // Guardian button in home header
  var gWrap = document.getElementById('homeGuardianWrap');
  var gBtn  = document.getElementById('homeGuardianBtn');
  var isOn  = safeLS('get','velo_is_guardian') === 'true';
  if(gWrap) gWrap.style.display = 'flex';
  if(gBtn){
    var _gs = _gBtnStyle(isOn);
    gBtn.style.background  = _gs.bg;
    gBtn.style.borderColor = _gs.border;
    gBtn.style.color       = _gs.color;
    gBtn.textContent       = isOn ? '🛡️ Activado' : '🛡️ Actívame';
  }
  // Update label
  var gLabel = gWrap ? gWrap.querySelector('span') : null;
  if(gLabel) gLabel.textContent = isOn ? 'Activo' : 'Activarme';

  // Availability status toggle
  _renderHomeStatusToggle();

  // Today's mood
  _loadTodayMoodHome();
  _updateHomeCurrentMoodLine();
  _updateHomeMottoLine();
  _updateTopbarMoodBadge();
  _updateSidebarUser();
  _updateHomeStreak();
  _renderPersonalizedSuggestions();
  _loadHomeMemoryCard();
  _checkRequestPushPermission();
  _renderHomePushBanner();
  // Sync local push subscription to Supabase — runs once, exits early if already synced
  setTimeout(_syncPushSubOnStartup, 3000);
  _loadDailyQ();
  _loadCommunityPulse();
  _loadGuardianActivity();
  _initShareWeekBtn();
  _updateHomeBell();
  // Show unread alert once per session if there are pending messages
  if(!_buzónAlertedSession){
    setTimeout(function(){
      var _msgs=[]; try{_msgs=JSON.parse(safeLS('get','velo_inbox')||'[]');}catch(e){}
      var _localUnread = _msgs.filter(function(m){ return !m.leido && !safeLS('get','velo_read_'+m.id); }).length;
      var _ubcUnread=[]; try{_ubcUnread=JSON.parse(safeLS('get','velo_bcast_unread')||'[]');}catch(e){}
      var _total = _localUnread + _ubcUnread.length;
      if(_total > 0){
        _buzónAlertedSession = true;
        var _label = _total === 1 ? 'Tenés 1 mensaje sin leer' : 'Tenés '+_total+' mensajes sin leer';
        _showBuzónAlert(_label, null, null, '📬');
      }
    }, 2000);
  }
  // Hero entrance animation — retriggers on every navigation to home
  var _ha = document.querySelector('#pg-home .r-hero-v2');
  if(_ha){ _ha.classList.remove('r-greeting-anim'); void _ha.offsetHeight; setTimeout(function(){ _ha.classList.add('r-greeting-anim'); }, 80); }
  // Daily quote in home header (Gemini, cached per day)
  setTimeout(_loadDailyMotivationalQuote, 200);
  // 7-day mood mini-graph (renders immediately from localStorage, then syncs from Supabase)
  _renderHomeWeekMoodGraph().catch(function(){});
  setTimeout(_syncMoodsFromSb, 800); // sync after auth settles
  // Meditation home widget (featured meditation of the day)
  _renderHomeMedWidget();
  // Bitácora home widget
  setTimeout(_renderHomeBitacoraWidget, 700);
}

// ── HOME NAV TILES ────────────────────────────────────────────
// ── STRIP DE CTAs GRANDES arriba del saludo: Wrapped + Invitar + Buddy ──
var _ctaStripBuilding = false;
async function _initHomeQuickCtaStrip(){
  // Defensive cleanup: si por bug previo hay N strips, dejamos solo una
  var existing = document.querySelectorAll('#homeQuickCtaStrip');
  if(existing.length > 1){
    for(var _i=1; _i<existing.length; _i++) existing[_i].remove();
  }
  // Guardas sync antes del await, evitan que dos llamadas simultáneas dupliquen
  if(document.getElementById('homeQuickCtaStrip')) return;
  if(_ctaStripBuilding) return;
  _ctaStripBuilding = true;
  var host = document.querySelector('.r-hero-left');
  if(!host){ _ctaStripBuilding = false; return; }
  var strip = document.createElement('div');
  strip.id = 'homeQuickCtaStrip';
  strip.style.cssText = 'display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;width:100%;box-sizing:border-box;margin:0 0 10px;order:-2';
  // Tiles compactas: solo icon + label, sin subtitle. Height ~50-55px.
  var tile = function(icon, label, sub, bg, bdr, action){
    return '<button onclick="'+action+'" style="cursor:pointer;background:'+bg+';border:1px solid '+bdr+';border-radius:12px;padding:8px 6px;display:flex;align-items:center;justify-content:center;gap:6px;-webkit-tap-highlight-color:transparent;touch-action:manipulation;font-family:Jost,sans-serif;text-align:center" onmousedown="this.style.transform=\'scale(.94)\'" onmouseup="this.style.transform=\'\'" onmouseleave="this.style.transform=\'\'" ontouchstart="this.style.transform=\'scale(.94)\'" ontouchend="this.style.transform=\'\'">'
      +'<span style="font-size:16px;line-height:1">'+icon+'</span>'
      +'<span style="font-size:11.5px;font-weight:800;color:rgba(255,255,255,.92);letter-spacing:.1px;line-height:1.1;white-space:nowrap">'+label+'</span>'
      +'</button>';
  };
  // Chequeo si tiene buddy para adaptar la tile
  var buddyTile = tile('🤝','Compañero','','rgba(155,120,220,.14)','rgba(155,120,220,.42)','pOpenBuddyModal()');
  try{
    var uid = safeLS('get','velo_user_id') || '';
    _initSupabase();
    if(uid && sbClient){
      var me = await sbClient.from('profiles').select('buddy_id,buddy_name,buddy_started_at,buddy_available_at').eq('id',uid).maybeSingle();
      if(me && me.data && me.data.buddy_id){
        // v1386: el tile mostraba solo el nombre ("💬 Dieguito") — fuera de
        // contexto parecía un atajo de chat cualquiera. Ahora al tocarlo abre
        // el panel de Compañero (que dice "Tu compañero/a de bienestar es X"
        // con el ciclo, cómo se usa y el botón de mensaje), y la etiqueta lleva
        // "Compañer@" para que se entienda qué es de un vistazo.
        var startedTs = me.data.buddy_started_at ? new Date(me.data.buddy_started_at).getTime() : Date.now();
        var daysLeft = Math.max(0, 30 - Math.floor((Date.now() - startedTs) / 86400000));
        var lbl = daysLeft === 0 ? '¡renová!' : 'Compañer@';
        buddyTile = tile('🤝', lbl, '', 'rgba(155,120,220,.18)','rgba(155,120,220,.52)', 'pOpenBuddyModal()');
      } else if(me && me.data && me.data.buddy_available_at){
        buddyTile = tile('🌿','Anotado/a','','rgba(155,120,220,.18)','rgba(155,120,220,.52)','pOpenBuddyModal()');
      }
    }
  }catch(e){}
  strip.innerHTML =
    tile('🌸','Wrapped','','rgba(228,178,80,.14)','rgba(228,178,80,.40)','pOpenMonthlyWrapped()')
    + tile('💌','Invitar','','rgba(116,198,157,.14)','rgba(116,198,157,.42)','pOpenInviteFriends()')
    + buddyTile;
  // Re-check: si otra invocación ya insertó una strip mientras esperábamos el await, no dupliques
  if(document.getElementById('homeQuickCtaStrip')){ _ctaStripBuilding = false; return; }
  host.insertAdjacentElement('afterbegin', strip);
  _ctaStripBuilding = false;
}

