// ── HOME AUTO-REFRESH ─────────────────────────────────────────
function _startHomeRefresh(){
  if(_homeRefreshTmr) return;
  _homeRefreshTmr = setInterval(_homeRefreshLive, 60000);
}
function _stopHomeRefresh(){
  if(_homeRefreshTmr){ clearInterval(_homeRefreshTmr); _homeRefreshTmr = null; }
}
function _homeRefreshLive(){
  if(document.visibilityState === 'hidden') return;
  if(_curPage !== 'home'){ _stopHomeRefresh(); return; }
  // Guardian availability chip
  _loadGuardianActivity();
  // Community pulse counter
  _loadCommunityPulse();
  // Daily question: refresh feed if user already answered, else update count
  var openEl = document.getElementById('homeDailyQOpen');
  if(openEl && openEl.style.display !== 'none'){
    _fetchDailyFeed(_getDailyQuestion().id);
  } else {
    _fetchDailyCount();
  }
}

function _updateHomeBell(){
  var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  var localUnread = msgs.filter(function(m){ return !m.leido && !safeLS('get','velo_read_'+m.id); }).length;
  var _ubcIds = []; try{ _ubcIds = JSON.parse(safeLS('get','velo_bcast_unread')||'[]'); }catch(e){}
  var unread = localUnread + _ubcIds.length;
  var label  = unread > 9 ? '9+' : String(unread);
  // Home bell badge
  var bell = document.getElementById('homeBellBadge');
  if(bell){ bell.style.display = unread > 0 ? 'block' : 'none'; bell.textContent = label; }
  // Home buzón card badge
  var buzón = document.getElementById('homeBuzónBadge');
  if(buzón){ buzón.style.display = unread > 0 ? 'block' : 'none'; buzón.textContent = label; }
  // Topbar mail button badge
  var mail = document.getElementById('homeMailBadge');
  if(mail){ mail.style.display = unread > 0 ? 'block' : 'none'; mail.textContent = label; }
  // Sidebar inbox badge
  var snBadge = document.getElementById('sn-inbox-badge');
  if(snBadge){ snBadge.textContent = unread > 0 ? '!' : ''; snBadge.classList.toggle('p-hidden', unread === 0); }
  // Desktop sidebar bell badge
  var sbBell = document.getElementById('sidebarBellBadge');
  if(sbBell){ sbBell.style.display = unread > 0 ? 'inline-block' : 'none'; sbBell.textContent = label; }
}

function _updateInboxDot(){
  _updateHomeBell();
}

function pTogglePassVis(id, btn){
  var inp = document.getElementById(id);
  if(!inp) return;
  var isPass = inp.type === 'password';
  inp.type = isPass ? 'text' : 'password';
  if(btn) btn.textContent = isPass ? '🙈' : '👁️';
}

function _loadTodayMoodHome(){
  var today = _dateKey();
  var stored = safeLS('get','velo_mood_'+today);
  var emoji = '🌤️';
  if(stored){ try{ var m = JSON.parse(stored); if(m.emoji) emoji = m.emoji; }catch(e){} }
  var me = document.getElementById('homeMoodEmoji');
  if(me) me.textContent = emoji;
}

// ── QUICK MOOD PICKER ─────────────────────────────────────────
var _selectedQuickMoodEmoji = '';

function pQuickMood(){
  _selectedQuickMoodEmoji = '';
  var saveBtn = document.getElementById('quickMoodSaveBtn');
  if(saveBtn) saveBtn.disabled = true;
  document.querySelectorAll('.quick-mood-emoji').forEach(function(b){ b.style.background=''; b.style.transform=''; });
  var inp = document.getElementById('quickMoodPhrase');
  if(inp) inp.value = '';
  openModal('quickMoodOv');
}

function pCloseQuickMood(){
  closeModal('quickMoodOv');
}

function pSelectQuickMood(el, emoji, label){
  _selectedQuickMoodEmoji = emoji;
  document.querySelectorAll('.quick-mood-emoji').forEach(function(b){
    b.style.background = '';
    b.style.transform = '';
    b.style.boxShadow = '';
  });
  el.style.background = 'rgba(45,106,79,.12)';
  el.style.transform = 'scale(1.25)';
  el.style.boxShadow = '0 0 0 2px var(--sage4)';
  var saveBtn = document.getElementById('quickMoodSaveBtn');
  if(saveBtn) saveBtn.disabled = false;
}

function pSaveQuickMood(){
  if(!_selectedQuickMoodEmoji) return;
  var phrase = (document.getElementById('quickMoodPhrase')||{}).value || '';
  var today = _dateKey();
  var labels = {'😄':'Muy bien','😊':'Bien','😐':'Regular','😞':'Mal','😢':'Muy mal'};
  var moodObj = { emoji: _selectedQuickMoodEmoji, label: labels[_selectedQuickMoodEmoji]||'', note: phrase.trim(), ts: Date.now() };
  safeLS('set','velo_mood_'+today, JSON.stringify(moodObj));
  // Update mood log for suggestions
  var log = []; try{ log = JSON.parse(safeLS('get','velo_mood_log')||'[]'); }catch(e){}
  log = log.filter(function(m){ return m.dateKey !== today; }); // dedupe hoy (una entrada por día)
  log.unshift(Object.assign({}, moodObj, {dateKey: today}));
  safeLS('set','velo_mood_log', JSON.stringify(log.slice(0,90)));
  sbSaveMoodEntry(today, _selectedQuickMoodEmoji, labels[_selectedQuickMoodEmoji]||'', phrase.trim());
  // Update UI
  var moodLine = document.getElementById('homeCurrentMoodLine');
  if(moodLine) moodLine.textContent = _selectedQuickMoodEmoji + ' ' + (labels[_selectedQuickMoodEmoji]||'') + (phrase.trim() ? ' — ' + phrase.trim() : '');
  pCloseQuickMood();
  _updateTopbarMoodBadge();
  _renderHomeWeekMoodGraph().catch(function(){});
  pToast(_selectedQuickMoodEmoji, 'Estado de ánimo guardado 💚');
  _showStreakCelebration();
  // Success bloom — partículas floreciendo desde el chip
  try{
    var _anchor = document.getElementById('homeMoodChip') || document.querySelector('.r-hero-left');
    if(_anchor) setTimeout(function(){ veloParticleBloom(_anchor, { emojis: [_selectedQuickMoodEmoji, '💚', '🌿', '✨'] }); }, 100);
  }catch(e){}
  // v1503: sugerencia contextual según el ánimo (1 vez por día)
  var _qmEmoji = _selectedQuickMoodEmoji;
  setTimeout(function(){ try{ _showMoodFollowUp(_qmEmoji); }catch(_){} }, 1000);
}

// ── v1503: SUGERENCIA CONTEXTUAL SEGÚN EL ÁNIMO ─────────────────────
// El momento en que alguien registra su ánimo es EL momento para ofrecerle
// lo que necesita: triste → compañía · feliz → compartir · neutro → un
// momento para sí. Descubrimiento en contexto, máx. 1 vez por día.
function _showMoodFollowUp(emoji){
  try{
    var today = _dateKey();
    if(safeLS('get','velo_mood_followup_'+today)) return false;
    safeLS('set','velo_mood_followup_'+today, '1');
    var score = (typeof _VELO_MOOD_SCORE !== 'undefined' && _VELO_MOOD_SCORE[emoji]) || 3;
    var kind = score <= 2.4 ? 'low' : (score >= 4 ? 'high' : 'mid');
    var cfg = {
      low: {
        icon:'💙', title:'Gracias por contarlo',
        sub:'No tenés que atravesarlo en soledad. Esto puede ayudarte ahora:',
        actions:[
          { e:'🛡️', t:'Hablar con un Guardián',            s:'Personas reales, listas para escucharte', a:"pGoTo('guardians')" },
          { e:'💬', t:'Pedir compañía en la Sala de Ayuda', s:'Apoyo de la comunidad en tiempo real',    a:"pGoTo('help')" },
          { e:'📔', t:'Descargarlo en mi diario',           s:'Privado — solo para vos',                 a:"pGoTo('diary')" }
        ],
        close:'Estoy bien así 🌿'
      },
      high: {
        icon:'✨', title:'¡Se nota un buen día!',
        sub:'Los momentos lindos también merecen compartirse:',
        actions:[
          { e:'✨', t:'Publicar una vibe',            s:'Compartí este momento con la comunidad', a:"pStartCreateVibe(null,'public')" },
          { e:'💭', t:'Responder la Pregunta del día', s:'Tu perspectiva puede ayudar a alguien',  a:'pOpenDailyResponse()' },
          { e:'🌞', t:'Leer Buenas Noticias',          s:'Sumale más luz al día',                  a:"pGoTo('news')" }
        ],
        close:'Seguir 🌿'
      },
      mid: {
        icon:'🌿', title:'Gracias por registrarlo',
        sub:'Un momento para vos, si querés:',
        actions:[
          { e:'📔', t:'Escribir en mi diario',         s:'Ordenar lo que sentís ayuda a verlo claro', a:"pGoTo('diary')" },
          { e:'💭', t:'La Pregunta del día',           s:'Respondé y mirá qué siente la comunidad',   a:'pOpenDailyResponse()' },
          { e:'🌬️', t:'Respirar 2 minutos',            s:'Guiado, para aflojar el cuerpo',            a:'veloOpenBreathingModal()' }
        ],
        close:'Seguir 🌿'
      }
    }[kind];
    var ex = document.getElementById('moodFollowUpOv'); if(ex) ex.remove();
    var ov = document.createElement('div');
    ov.className = 'p-modal-ov show';
    ov.id = 'moodFollowUpOv';
    ov.innerHTML = '<div class="p-sheet">'
      + '<div class="p-sheet-handle"></div>'
      + '<div style="text-align:center;margin-bottom:16px">'
      + '<div style="font-size:38px;margin-bottom:8px">'+cfg.icon+'</div>'
      + '<div style="font-family:\'Cormorant Garamond\',serif;font-size:23px;color:var(--ink);margin-bottom:6px">'+cfg.title+'</div>'
      + '<div style="font-size:14px;color:var(--ink4);line-height:1.55">'+cfg.sub+'</div>'
      + '</div>'
      + cfg.actions.map(function(x){
          return '<button onclick="document.getElementById(\'moodFollowUpOv\').remove();'+x.a+'" style="width:100%;display:flex;align-items:center;gap:12px;padding:13px 14px;margin-bottom:9px;background:var(--cream2);border:1.5px solid var(--border2);border-radius:15px;cursor:pointer;text-align:left;font-family:\'Jost\',sans-serif;-webkit-tap-highlight-color:transparent">'
            + '<span style="font-size:22px;flex-shrink:0">'+x.e+'</span>'
            + '<span style="flex:1;min-width:0"><span style="display:block;font-size:14px;font-weight:700;color:var(--ink)">'+x.t+'</span>'
            + '<span style="display:block;font-size:11.5px;color:var(--ink4);margin-top:1px;line-height:1.35">'+x.s+'</span></span>'
            + '<span style="flex-shrink:0;font-size:14px;color:var(--ink5);font-weight:800">›</span>'
            + '</button>';
        }).join('')
      + '<button onclick="document.getElementById(\'moodFollowUpOv\').remove()" style="width:100%;padding:12px;margin-top:3px;background:none;border:none;color:var(--ink4);font-size:13.5px;font-weight:600;cursor:pointer;font-family:\'Jost\',sans-serif">'+cfg.close+'</button>'
      + '</div>';
    document.body.appendChild(ov);
    ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
    return true;
  }catch(e){ return false; }
}

// ── MI ESTADO VISIBLE ──────────────────────────────────────────
function pOpenMyStatus(){
  // Pre-fill modal inputs from saved values
  var fields = { modalStatusMusic:'velo_status_music', modalStatusBook:'velo_status_book', modalStatusFilm:'velo_status_film', modalStatusPhrase:'velo_status_phrase' };
  Object.keys(fields).forEach(function(id){
    var el = document.getElementById(id);
    if(el) el.value = safeLS('get', fields[id]) || '';
  });
  openModal('myStatusOv');
}

async function pSaveStatusFromModal(){
  var music  = (document.getElementById('modalStatusMusic')||{}).value  || '';
  var book   = (document.getElementById('modalStatusBook')||{}).value   || '';
  var film   = (document.getElementById('modalStatusFilm')||{}).value   || '';
  var phrase = (document.getElementById('modalStatusPhrase')||{}).value || '';
  safeLS('set','velo_status_music',  music.trim());
  safeLS('set','velo_status_book',   book.trim());
  safeLS('set','velo_status_film',   film.trim());
  safeLS('set','velo_status_phrase', phrase.trim());
  // Sync profile page inputs if visible
  var syncMap = { profStatusMusic: music, profStatusBook: book, profStatusFilm: film, profStatusPhrase: phrase };
  Object.keys(syncMap).forEach(function(id){ var el=document.getElementById(id); if(el) el.value=syncMap[id]; });
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(sbClient){
    try{
      var {data:_ms} = await sbClient.auth.getSession();
      if(_ms && _ms.session && _ms.session.user && _ms.session.user.id) uid = _ms.session.user.id;
    }catch(e){}
  }
  if(sbClient && uid){
    try{
      await sbClient.from('profiles').upsert({
        id: uid, status_music:music.trim(), status_book:book.trim(),
        status_film:film.trim(), status_phrase:phrase.trim()
      },{ onConflict:'id' });
      pToast('✨','Estado actualizado y visible para todos 💚');
    }catch(e){ pToast('✨','Estado actualizado 💚'); }
  } else {
    pToast('✨','Estado actualizado 💚');
  }
  closeModal('myStatusOv');
}

function pSaveMyStatus(){
  // Legacy alias
  pSaveStatusFromModal();
}

