// ── v1485: REACCIONES A LA REFLEXIÓN DEL DÍA ──────────────────────
// 🌱 me tocó · 💭 me hizo pensar · 💪 me dio fuerza — contadores en vivo
// (tabla quote_reactions; si aún no existe, la fila se oculta sola).
var _RFX_REACTS = [
  { e:'🌱', k:'toco',   lbl:'Me identifico' },
  { e:'💭', k:'pensar', lbl:'Me hizo pensar' },
  { e:'💪', k:'fuerza', lbl:'Me dio fuerza' }
];
async function _loadQuoteReactions(){
  var row = document.getElementById('rfxReactRow');
  if(!row) return;
  _initSupabase();
  if(!sbClient) return;
  var today = _dateKey();
  var uid = safeLS('get','velo_user_id')||'';
  var counts = {toco:0,pensar:0,fuerza:0}, mine = {};
  try{
    var r = await sbClient.from('quote_reactions').select('emoji,user_id').eq('date_key', today);
    if(r.error){ row.style.display = 'none'; return; } // tabla aún no creada
    (r.data||[]).forEach(function(x){
      if(counts[x.emoji] != null) counts[x.emoji]++;
      if(uid && x.user_id === uid) mine[x.emoji] = true;
    });
  }catch(e){ return; }
  _renderQuoteReactRow(counts, mine);
}
function _renderQuoteReactRow(counts, mine){
  var row = document.getElementById('rfxReactRow');
  if(!row) return;
  row.style.display = 'flex';
  row.style.flexWrap = 'nowrap'; // v1507: siempre las 3 en UNA fila
  row._counts = counts; row._mine = mine;
  var _lt = !document.body.classList.contains('r-dark'); // v1492: en claro la card es crema
  var _onCss  = _lt ? 'background:rgba(190,145,35,.18);border:1.5px solid rgba(190,145,35,.65);color:rgba(110,80,10,.95)'
                    : 'background:rgba(255,215,110,.22);border:1.5px solid rgba(255,215,110,.65);color:rgba(255,235,170,.98)';
  var _offCss = _lt ? 'background:rgba(0,0,0,.05);border:1px solid rgba(140,105,25,.32);color:rgba(95,70,15,.85)'
                    : 'background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.16);color:rgba(255,255,255,.72)';
  row.innerHTML = _RFX_REACTS.map(function(rx){
    var on = !!mine[rx.k];
    var n = counts[rx.k]||0;
    return '<button onclick="pReactQuote(\''+rx.k+'\')" style="flex:1;min-width:0;display:inline-flex;align-items:center;justify-content:center;gap:4px;padding:6px 4px;border-radius:20px;cursor:pointer;font-family:Jost,sans-serif;font-size:10px;font-weight:700;letter-spacing:.1px;white-space:nowrap;overflow:hidden;-webkit-tap-highlight-color:transparent;transition:transform .12s;'
      + (on ? _onCss : _offCss)
      + '">'+rx.e+' '+rx.lbl+(n>0 ? ' · '+n : '')+'</button>';
  }).join('');
}
async function pReactQuote(k){
  var row = document.getElementById('rfxReactRow');
  if(!row) return;
  _initSupabase();
  var uid = safeLS('get','velo_user_id')||'';
  if(!sbClient || !uid){ pToast('🌿','Iniciá sesión para reaccionar'); return; }
  var counts = row._counts||{toco:0,pensar:0,fuerza:0};
  var mine   = row._mine||{};
  var today  = _dateKey();
  if(mine[k]){
    // Quitar mi reacción (toggle off) — optimista
    mine[k] = false; counts[k] = Math.max(0,(counts[k]||1)-1);
    _renderQuoteReactRow(counts, mine);
    try{ await sbClient.from('quote_reactions').delete().eq('date_key',today).eq('user_id',uid).eq('emoji',k); }catch(e){}
  } else {
    mine[k] = true; counts[k] = (counts[k]||0)+1;
    _renderQuoteReactRow(counts, mine);
    try{
      var r = await sbClient.from('quote_reactions').insert({ date_key:today, user_id:uid, emoji:k });
      if(r && r.error && String(r.error.code) !== '23505'){
        // tabla faltante u otro error → revertir el optimista
        mine[k] = false; counts[k] = Math.max(0,(counts[k]||1)-1);
        _renderQuoteReactRow(counts, mine);
      }
    }catch(e){}
  }
}

async function _loadDailyMotivationalQuote(){
  var textEl   = document.getElementById('homeDailyQuoteText');
  var authorEl = document.getElementById('homeDailyQuoteAuthor');
  if(!textEl) return;
  // v1485: PÓSTER del día — cada día un degradado rico distinto (7 paletas)
  try{
    var _rfxCard = document.querySelector('#homeReflexionDia > div');
    if(_rfxCard && _rfxCard.className.indexOf('rfx-poster') < 0){
      var _rfxIdx = Math.floor((Date.now() - new Date().getTimezoneOffset()*60000) / 86400000) % 7;
      _rfxCard.className = (_rfxCard.className ? _rfxCard.className + ' ' : '') + 'rfx-poster rfx-p' + _rfxIdx;
    }
  }catch(_){}
  // v1485: reacciones de la comunidad a la reflexión (no bloquea el render)
  try{ setTimeout(function(){ _loadQuoteReactions(); }, 400); }catch(_){}
  // Set day label for quote card
  var _qDayEl = document.getElementById('homeDailyQuoteDay');
  if(_qDayEl && !_qDayEl.textContent){ var _qd=new Date(); var _qDias=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']; var _qMes=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic']; _qDayEl.textContent=_qDias[_qd.getDay()]+' '+_qd.getDate()+' '+_qMes[_qd.getMonth()]; }
  // Use LOCAL date so quote rotates at local midnight, not UTC midnight
  var _d0 = new Date();
  var today = _d0.getFullYear()+'-'+String(_d0.getMonth()+1).padStart(2,'0')+'-'+String(_d0.getDate()).padStart(2,'0');
  var cacheKey = 'velo_dq3_'+today; // v3 prefix forces regeneration if stale cache exists

  // Load history first — needed for dedup check and avoid clause
  var history = [];
  try{ history = JSON.parse(safeLS('get','velo_quote_history')||'[]'); }catch(e){}
  // Only look at PREVIOUS days (not today's entry) to avoid false positives on re-load
  var prevHistory = history.filter(function(q){ return q.date !== today; });
  var prevTexts   = prevHistory.slice(0,7).map(function(q){ return q.text; }).filter(Boolean);
  var prevAuthors = prevHistory.slice(0,14).map(function(q){ return q.author; }).filter(Boolean);

  var cached = safeLS('get', cacheKey);
  if(cached){
    try{
      var obj = JSON.parse(cached);
      // If this exact quote appeared in the last 7 days → delete cache, regenerate
      if(obj.text && prevTexts.indexOf(obj.text) !== -1){
        safeLS('del', cacheKey);
      } else {
        textEl.textContent   = obj.text   || cached;
        if(authorEl) authorEl.textContent = obj.author ? '— ' + obj.author : '';
        return;
      }
    }catch(e){ textEl.textContent = cached; return; }
  }

  // Check Supabase for today's quote before calling Gemini (cross-browser sync)
  _initSupabase();
  var _sqUid = safeLS('get','velo_user_id');
  if(sbClient && _sqUid){
    try{
      var _sqRes = await sbClient.from('profiles').select('daily_quote_cache').eq('id',_sqUid).limit(1);
      if(_sqRes.data && _sqRes.data[0] && _sqRes.data[0].daily_quote_cache){
        var _sqObj = JSON.parse(_sqRes.data[0].daily_quote_cache);
        if(_sqObj.date === today && _sqObj.text && _sqObj.author && prevTexts.indexOf(_sqObj.text) === -1){
          safeLS('set', cacheKey, JSON.stringify({text:_sqObj.text,author:_sqObj.author}));
          textEl.style.opacity = '';
          textEl.textContent = _sqObj.text;
          if(authorEl) authorEl.textContent = '— ' + _sqObj.author;
          return;
        }
      }
    }catch(e){}
  }

  // Show loading skeleton while Gemini generates the quote
  textEl.style.opacity = '.45';
  textEl.textContent = 'Cargando frase del día...';
  if(authorEl) authorEl.textContent = '✨ Velo IA';

  var d = new Date();
  var dias = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
  var avoidClause = prevAuthors.length
    ? 'NO uses ninguno de estos autores que ya se mostraron recientemente: '+prevAuthors.join(', ')+'. '
    : '';
  // Also send recent quote texts so Gemini doesn't repeat word-for-word
  var avoidTextClause = prevTexts.length
    ? 'NO repitas estas frases que ya aparecieron recientemente: '+prevTexts.map(function(t){ return '"'+t.slice(0,35)+'..."'; }).join('; ')+'. '
    : '';
  // Pick a random source category each day using date as seed (forces variety)
  var _cats = [
    'un filósofo griego o estoico (Epicteto, Marco Aurelio, Sócrates, Platón, Aristóteles, Séneca)',
    'un escritor o poeta latinoamericano (Pablo Neruda, Gabriel García Márquez, Octavio Paz, Borges, Isabel Allende, Mario Benedetti, Juana de Ibarbourou)',
    'un pensador, humanista o filósofo moderno (Bertrand Russell, Albert Camus, Simone de Beauvoir, Hannah Arendt, Jean-Paul Sartre)',
    'un científico, inventor o explorador (Marie Curie, Stephen Hawking, Carl Sagan, Leonardo da Vinci, Nikola Tesla, Charles Darwin)',
    'un artista visual, músico o cantante (Frida Kahlo, Pablo Picasso, Beethoven, Bob Marley, Mercedes Sosa, Violeta Parra, Leonard Cohen)',
    'un personaje de literatura universal inspirador (El Principito de Saint-Exupéry, El Alquimista de Paulo Coelho, Siddharta de Hesse)',
    'un deportista, empresario o emprendedor reconocido (Muhammad Ali, Serena Williams, Roger Federer, Ayrton Senna, Coco Chanel)',
    'un proverbio sabio de cultura africana, árabe, china, japonesa o indígena latinoamericana',
    'un poeta o escritor universal (Rainer Maria Rilke, Walt Whitman, Emily Dickinson, Khalil Gibran, Rumi, Pablo Neruda)',
    'un líder histórico o activista de derechos humanos (Nelson Mandela, Eleanor Roosevelt, Simón Bolívar, Sor Juana Inés de la Cruz, Rosa Parks)',
    'un psicólogo o autor de autoayuda y bienestar (Viktor Frankl, Brené Brown, Wayne Dyer, Jorge Bucay, Louise Hay, Nathaniel Branden)',
    'un escritor, poeta o novelista universal del siglo XX (Gabriel García Márquez, Pablo Neruda, Marguerite Yourcenar, Jorge Luis Borges, Milan Kundera)'
  ];
  var _catIdx = (d.getDate() * 7 + d.getMonth() * 31 + d.getFullYear()) % _cats.length;
  var _chosenCat = _cats[_catIdx];
  var prompt = 'Dame UNA frase célebre, inspiradora y positiva de '+_chosenCat+'. '
    +'Hoy es '+dias[d.getDay()]+' '+d.getDate()+'/'+(d.getMonth()+1)+'/'+d.getFullYear()+'. '
    +avoidClause+avoidTextClause
    +'La frase debe transmitir autoestima, esperanza, superación personal, amor, bienestar, alegría, calma o reflexión profunda. '
    +'NO uses frases de la Biblia, el Corán, ni de ningún texto religioso sagrado. '
    +'Que sea una frase REAL y conocida de un pensador, poeta, artista, científico, escritor o personaje histórico. No la inventes. Traducida al español si es en otro idioma. '
    +'Entre 10 y 35 palabras. '
    +'Devolvé SOLO un objeto JSON sin markdown: {"text":"frase en español","author":"Nombre completo del autor o fuente"}.';

  var raw = await _geminiCall(prompt, { temperature:0.92, maxOutputTokens:120 });
  var quote = null;
  if(raw){
    try{
      var jsonMatch = raw.match(/\{[\s\S]*"text"[\s\S]*"author"[\s\S]*\}/);
      if(jsonMatch) quote = JSON.parse(jsonMatch[0]);
    }catch(e){}
  }
  // Fallback if Gemini failed or returned a duplicate
  if(!quote || !quote.text || !quote.author || prevTexts.indexOf(quote.text) !== -1){
    var idx = (d.getDate() - 1 + d.getMonth() * 31 + d.getFullYear()) % _dailyQuoteFallbacks.length;
    quote = _dailyQuoteFallbacks[idx];
    // If that fallback is also a recent duplicate, use the next one
    if(prevTexts.indexOf(quote.text) !== -1){
      quote = _dailyQuoteFallbacks[(idx + 1) % _dailyQuoteFallbacks.length];
    }
  }

  // Save to history (keep last 30 days)
  history.unshift({ text: quote.text, author: quote.author, date: today });
  safeLS('set', 'velo_quote_history', JSON.stringify(history.slice(0,30)));

  safeLS('set', cacheKey, JSON.stringify(quote));
  // Save to Supabase so other browsers get the same quote today
  if(sbClient && _sqUid){
    sbClient.from('profiles').update({daily_quote_cache: JSON.stringify({date:today,text:quote.text,author:quote.author})}).eq('id',_sqUid).then(function(){}).catch(function(){});
  }
  textEl.style.opacity = '';
  textEl.textContent   = quote.text;
  if(authorEl) authorEl.textContent = '— ' + quote.author;
}

function _updateTopbarMoodBadge(){
  var emojiEl = document.getElementById('topbarMoodEmoji');
  if(!emojiEl) return;
  var today = _dateKey();
  var stored = safeLS('get','velo_mood_'+today);
  var emoji = '🤗';
  if(stored){ try{ var m=JSON.parse(stored); if(m.emoji) emoji=m.emoji; }catch(e){} }
  emojiEl.textContent = emoji;
  var sidebarEmoji = document.getElementById('sidebarMoodEmoji');
  if(sidebarEmoji) sidebarEmoji.textContent = emoji;
  var desktopEmoji = document.getElementById('homeDesktopMoodEmoji');
  if(desktopEmoji) desktopEmoji.textContent = emoji;
  var streak = 0;
  var d = new Date();
  for(var i=0;i<90;i++){
    var k = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    if(safeLS('get','velo_mood_'+k)) streak++;
    else if(i>0) break;
    d.setDate(d.getDate()-1);
  }
  var streakEl = document.getElementById('topbarMoodStreak');
  var streakNumEl = document.getElementById('topbarMoodStreakNum');
  if(streakEl){ streakEl.style.display = streak>=2 ? '' : 'none'; }
  if(streakNumEl) streakNumEl.textContent = streak;
}

