function _getDailyQuestion(){
  // Use local date so question changes at local midnight, not UTC midnight
  var d = new Date();
  var dayIdx = Math.floor((Date.now() - d.getTimezoneOffset() * 60000) / 86400000);
  return _DAILY_QUESTIONS[dayIdx % _DAILY_QUESTIONS.length];
}

var _dqTimerInterval = null;
function _initDqTimer(){
  var el = document.getElementById('dqTimerTxt');
  if(!el) return;
  function _tick(){
    var now = new Date();
    var midnight = new Date(now); midnight.setHours(24,0,0,0);
    var diff = Math.floor((midnight - now) / 1000);
    var h = Math.floor(diff / 3600);
    var m = Math.floor((diff % 3600) / 60);
    el.textContent = 'Nueva en '+h+'h '+m+'m';
    // v1485: anillo de cuenta regresiva — se va vaciando a medida que pasa el día
    try{
      var ring = document.getElementById('dqTimerRingFill');
      if(ring){
        var C = 2*Math.PI*8; // r=8 → circunferencia ~50.27
        var frac = Math.max(0, Math.min(1, diff/86400)); // fracción del día restante
        ring.setAttribute('stroke-dasharray', String(C));
        ring.setAttribute('stroke-dashoffset', String(C*(1-frac)));
      }
    }catch(_){}
  }
  _tick();
  if(_dqTimerInterval) clearInterval(_dqTimerInterval);
  _dqTimerInterval = setInterval(_tick, 60000);
}

// ── v1485: RACHA DE RESPUESTAS a la Pregunta del Día ────────────────
// 🔥 días consecutivos respondiendo + fichas de la semana (Lu→Do).
// Se calcula desde Supabase (multi-device) con caché local instantáneo.
async function _fetchDqStreak(showToast){
  _initSupabase();
  var uid = safeLS('get','velo_user_id')||'';
  if(!sbClient || !uid) return;
  // Render instantáneo desde caché mientras llega lo fresco
  if(!showToast){
    try{ var c = JSON.parse(safeLS('get','velo_dq_streak')||'null'); if(c && c.streak != null) _renderDqStreak(c.streak, c.week||[]); }catch(_){}
  }
  try{
    var r = await sbClient.from('daily_responses').select('question_date').eq('user_id', uid).order('question_date',{ascending:false}).limit(90);
    if(r.error) return;
    var dates = {}; (r.data||[]).forEach(function(x){ if(x.question_date) dates[x.question_date] = 1; });
    var _fk = function(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); };
    // Racha: días consecutivos terminando hoy (o ayer, si hoy todavía no respondió)
    var streak = 0;
    var d = new Date();
    if(!dates[_fk(d)]) d.setDate(d.getDate()-1);
    for(var i=0; i<365; i++){
      if(dates[_fk(d)]){ streak++; d.setDate(d.getDate()-1); } else break;
    }
    // Fichas de la semana (Lun→Dom)
    var now = new Date();
    var dow = (now.getDay()+6)%7; // 0 = lunes
    var week = [];
    for(var wi=0; wi<7; wi++){
      var wd = new Date(now.getFullYear(), now.getMonth(), now.getDate()-dow+wi);
      week.push({ lbl:['Lu','Ma','Mi','Ju','Vi','Sa','Do'][wi], done:!!dates[_fk(wd)], today:wi===dow });
    }
    try{ safeLS('set','velo_dq_streak', JSON.stringify({streak:streak, week:week, ts:Date.now()})); }catch(_){}
    _renderDqStreak(streak, week);
    if(showToast && streak >= 2){
      setTimeout(function(){ pToast('🔥','¡'+streak+' días seguidos respondiendo! Volvé mañana para mantener tu racha'); }, 1200);
    }
  }catch(e){}
}
function _renderDqStreak(streak, week){
  ['dqStreakBadge'].forEach(function(id){
    var b = document.getElementById(id);
    if(!b) return;
    if(streak >= 1){ b.style.display = 'inline-block'; b.textContent = '🔥 '+streak+' día'+(streak!==1?'s':''); }
    else b.style.display = 'none';
  });
  // v1494: en el estado RESPONDIDA la racha es UNA línea compacta: 🔥 N días + mini-puntos
  var lineO = document.getElementById('dqStreakLineO');
  if(lineO){
    if(streak >= 1 && week && week.length){
      var _dLt = !document.body.classList.contains('r-dark');
      var dots = week.map(function(c){
        var col = c.done ? '#e9b949' : (_dLt ? 'rgba(0,0,0,.14)' : 'rgba(255,255,255,.16)');
        var ring = (c.today && !c.done) ? ';box-shadow:0 0 0 1.5px rgba(233,185,73,.6)' : '';
        return '<span style="width:7px;height:7px;border-radius:50%;background:'+col+ring+';flex-shrink:0"></span>';
      }).join('');
      lineO.style.display = 'flex';
      lineO.innerHTML = '<span style="font-size:10.5px;font-weight:800;color:'+(_dLt?'rgba(190,105,20,.95)':'rgba(255,175,75,.95)')+';font-family:Jost,sans-serif;letter-spacing:.3px;flex-shrink:0">🔥 '+streak+' día'+(streak!==1?'s':'')+'</span>'
        + '<span style="display:inline-flex;gap:5px;align-items:center">'+dots+'</span>';
    } else lineO.style.display = 'none';
  }
  var _wkLt = !document.body.classList.contains('r-dark'); // v1492: modo claro legible
  var chipsHtml = (week||[]).map(function(c){
    var fill = c.done
      ? 'background:linear-gradient(90deg,#e9b949,#f0cf6a)'
      : 'background:'+(_wkLt?'rgba(0,0,0,.10)':'rgba(255,255,255,.10)') + (c.today ? ';box-shadow:0 0 0 1.5px rgba(233,185,73,.55)' : '');
    var _lblCol = c.done ? (_wkLt?'rgba(150,110,20,.95)':'rgba(240,207,106,.9)') : (_wkLt?'rgba(70,55,20,.50)':'rgba(255,255,255,.38)');
    return '<div style="flex:1;min-width:0;text-align:center">'
      + '<div style="font-size:8.5px;font-weight:800;color:'+_lblCol+';font-family:Jost,sans-serif;letter-spacing:.4px;margin-bottom:3px">'+c.lbl+'</div>'
      + '<div style="height:5px;border-radius:3px;'+fill+'"></div>'
      + '</div>';
  }).join('');
  ['dqWeekChips'].forEach(function(id){
    var w = document.getElementById(id);
    if(!w) return;
    if(chipsHtml){ w.style.display = 'flex'; w.innerHTML = chipsHtml; }
    else w.style.display = 'none';
  });
}

// v1494: burbuja "Tu respuesta" — kicker + texto completo (hasta 110 caracteres)
function _dqMyRespHtml(emoji, text, extra){
  var t = (text||'').trim();
  if(t.length > 110) t = t.slice(0,110)+'…';
  return '<div style="font-size:8.5px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;opacity:.62;margin-bottom:3px">Tu respuesta</div>'
    + '<div>'+(emoji||'💬')+(t?' '+_escHtml(t):'')+(extra||'')+'</div>';
}

function _loadDailyQ(){
  var el = document.getElementById('homeDailyQ');
  if(!el) return;
  el.style.display = 'block';
  _initDqTimer();
  try{ _fetchDqStreak(); }catch(_){}
  var q = _getDailyQuestion();
  var qtEl = document.getElementById('homeDailyQText');
  if(qtEl) qtEl.textContent = q.text;
  var qhEl = document.getElementById('homeDailyQHint');
  if(qhEl) qhEl.textContent = q.hint || '';
  var dateKey = _dateKey();
  var currentUid = safeLS('get','velo_user_id') || '';
  var myResp = safeLS('get','velo_daily_resp_'+dateKey);
  // Validate that stored response belongs to the current user (multi-account fix)
  if(myResp && currentUid){
    try{
      var _rv = JSON.parse(myResp);
      if(!_rv.uid || _rv.uid !== currentUid) myResp = null;
    }catch(e){ myResp = null; }
  }
  // Always init Supabase so _fetchDailyFeed works regardless of which path we take
  _initSupabase();
  if(myResp){
    _applyDailyQAnswered(myResp, q);
  } else {
    // Not in localStorage — check Supabase (cross-device: answered on another browser)
    if(sbClient && currentUid){
      sbClient.from('daily_responses')
        .select('id,mood_emoji,response_text')
        .eq('user_id', currentUid).eq('question_date', dateKey).limit(1)
        .then(function(r){
          if(r.data && r.data.length){
            var _sb = r.data[0];
            // If the user already deleted this locally, don't re-restore it
            var _dqHid2 = []; try{ _dqHid2 = JSON.parse(safeLS('get','velo_dq_hidden')||'[]'); }catch(e){}
            if(_sb.id && _dqHid2.indexOf(String(_sb.id)) !== -1){ _fetchDailyCount(); return; }
            var _restored = JSON.stringify({emoji:_sb.mood_emoji, text:_sb.response_text||'', uid:currentUid});
            safeLS('set','velo_daily_resp_'+dateKey, _restored);
            _applyDailyQAnswered(_restored, q);
          } else {
            _fetchDailyCount();
          }
        }).catch(function(){ _fetchDailyCount(); });
    } else {
      _fetchDailyCount();
    }
  }
}

function _applyDailyQAnswered(myResp, q){
  var lockedEl = document.getElementById('homeDailyQLocked');
  var openEl   = document.getElementById('homeDailyQOpen');
  if(lockedEl) lockedEl.style.display = 'none';
  if(openEl)   openEl.style.display   = 'block';
  var openQEl = document.getElementById('homeDailyQOpenText');
  if(openQEl) openQEl.textContent = q.text;
  try{
    var _r = JSON.parse(myResp);
    var myBadge = document.getElementById('homeDailyQMyResp');
    if(myBadge) myBadge.innerHTML = _dqMyRespHtml(_r.emoji, _r.text, '');
  }catch(e){}
  _fetchDailyFeed(q.id);
}

async function _fetchDailyCount(){
  if(!sbClient) return;
  var today = _dateKey();
  try{
    // v1590: cuenta comunitaria vía la vista enmascarada (la tabla cruda queda
    // owner-only por RLS; la vista security-definer devuelve todas las filas).
    var res = await sbClient.from('daily_responses_feed').select('id',{count:'exact',head:true}).eq('question_date',today);
    var n = res.count || 0;
    var t = n === 0 ? 'Sé el primero en responder ✨' : n+(n===1?' persona respondió hoy':' personas respondieron hoy');
    var countEl = document.getElementById('homeDailyQCount');
    var openEl  = document.getElementById('homeDailyQOpenCount');
    if(countEl) countEl.textContent = t;
    if(openEl)  openEl.textContent  = t;
    // v1485: adelanto de 2 respuestas reales — la card deja de sentirse vacía
    var tz = document.getElementById('dqTeaser');
    if(tz){
      if(n > 0){
        try{
          var pv = await sbClient.from('daily_responses_feed').select('mood_emoji,response_text,user_name')
            .eq('question_date',today).neq('response_text','').order('created_at',{ascending:false}).limit(2);
          var rows = ((pv && pv.data)||[]).filter(function(x){ return x.response_text && x.response_text.trim(); });
          if(rows.length){
            tz.style.display = 'flex';
            var _tzLt = !document.body.classList.contains('r-dark'); // v1492
            tz.innerHTML = rows.map(function(x){
              var txt = x.response_text.trim();
              if(txt.length > 64) txt = txt.slice(0,64)+'…';
              var who = ((x.user_name||'Alguien').split(' ')[0]) || 'Alguien';
              return '<div style="display:flex;align-items:center;gap:8px;background:'+(_tzLt?'rgba(0,0,0,.04)':'rgba(255,255,255,.045)')+';border:1px solid '+(_tzLt?'rgba(140,105,25,.25)':'rgba(200,158,56,.16)')+';border-radius:12px;padding:8px 12px">'
                + '<span style="font-size:15px;flex-shrink:0">'+(x.mood_emoji||'💬')+'</span>'
                + '<span style="flex:1;min-width:0;font-family:Jost,sans-serif;font-size:11.5px;color:'+(_tzLt?'rgba(60,45,10,.85)':'rgba(255,255,255,.80)')+';font-style:italic;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">&ldquo;'+_escHtml(txt)+'&rdquo;</span>'
                + '<span style="flex-shrink:0;font-family:Jost,sans-serif;font-size:10px;color:'+(_tzLt?'rgba(140,105,25,.85)':'rgba(200,158,56,.70)')+';font-weight:700">'+_escHtml(who)+'</span>'
                + '</div>';
            }).join('');
          } else tz.style.display = 'none';
        }catch(_tz){ tz.style.display = 'none'; }
      } else tz.style.display = 'none';
    }
  }catch(e){}
}

function _startDqReactPoll(){
  if(_dqReactPollTmr || !sbClient) return;
  _dqReactPollTmr = setInterval(async function(){
    var ids = _dqAllResponses.map(function(r){ return r.id; });
    if(!ids.length) return;
    await _loadDqReactions(ids);
    ids.forEach(function(id){ _updateDqCardReactions(String(id)); });
  }, 20000);
}
function _stopDqReactPoll(){
  if(_dqReactPollTmr){ clearInterval(_dqReactPollTmr); _dqReactPollTmr = null; }
  if(_dqFeedPollTmr){ clearInterval(_dqFeedPollTmr); _dqFeedPollTmr = null; }
  if(_dqVisHandler){ document.removeEventListener('visibilitychange', _dqVisHandler); _dqVisHandler = null; }
}

async function _fetchDailyFeed(qId){
  if(!sbClient){ _renderDailyFeed([]); return; }
  var today = _dateKey();
  try{
    var res = await sbClient.from('daily_responses_feed').select('*').eq('question_date',today).order('created_at',{ascending:false}).limit(40);
    var responses = res.data || [];
    await _loadDqReactions(responses.map(function(r){ return r.id; }));
    _renderDailyFeed(responses);
    // Batch-fetch usernames for unknown user_ids so @handle shows in each card
    var _unknownUids = responses.filter(function(r){ return r.user_id && !_uLook(r.user_id); }).map(function(r){ return r.user_id; });
    var _uidsUniq = _unknownUids.filter(function(v,i,a){ return a.indexOf(v)===i; });
    if(_uidsUniq.length && sbClient){
      sbClient.from('profiles').select('id,username').in('id',_uidsUniq)
        .then(function(ur){ if(ur.data) ur.data.forEach(function(p){ _uFill(p.id,p.username); }); _renderDailyFeed(_dqAllResponses); })
        .catch(function(){});
    }
  }catch(e){ _renderDailyFeed([]); }
  // Subscribe to real-time new responses.
  // v1450: SIEMPRE re-suscribir (canal viejo/caído dejaba de traer respuestas nuevas en vivo).
  if(_dqRtCh){ _sbUnsub(_dqRtCh); _dqRtCh = null; }
  if(sbClient){
    var _dqToday = today;
    _dqRtCh = _sbSub('velo:dq:'+_dqToday, 'daily_responses', function(payload){
      // Handle INSERT (payload.new), UPDATE (payload.new) and DELETE (payload.old)
      var _evDate = (payload.new && payload.new.question_date) || (payload.old && payload.old.question_date);
      if(_evDate !== _dqToday) return;
      // v1601: la Pregunta del Día vive en el home. Si ya no estás ahí, NO re-fetchear:
      // _fetchDailyFeed re-instala los polls (feed 15s, reacciones 20s) y el listener
      // de visibilidad, resucitando lo que _onPageEnter había frenado al salir (v1515).
      if(_curPage !== 'home') return;
      // Re-fetch feed (renders new card), pulse count, and community pulse bar in parallel
      _fetchDailyFeed(qId);
      try{ _fetchDailyCount(); }catch(e){}
      try{ if(typeof _loadCommunityPulse === 'function') _loadCommunityPulse(); }catch(e){}
    });
  }
  // Subscribe to real-time reaction counts — updates cards surgically, no carousel rebuild
  // v1450: SIEMPRE re-suscribir (canal viejo/caído dejaba de traer reacciones nuevas en vivo).
  if(_dqReactRtCh){ _sbUnsub(_dqReactRtCh); _dqReactRtCh = null; }
  if(sbClient){
    _dqReactRtCh = _sbSub('velo:dq-react', 'dq_reactions', function(payload){
      var myUid = safeLS('get','velo_user_id')||'';
      var ev = payload.eventType; var row = payload.new||{}; var del = payload.old||{};
      var rid, reaction, uid;
      if(ev==='INSERT'){
        rid=row.response_id; reaction=row.reaction; uid=row.user_id;
        if(uid===myUid) return; // already handled optimistically by pToggleDqReaction
        if(!_dqReactMap[rid]) _dqReactMap[rid]={};
        if(!_dqReactMap[rid][reaction]) _dqReactMap[rid][reaction]={count:0,mine:false};
        _dqReactMap[rid][reaction].count++;
      } else if(ev==='DELETE'){
        rid=del.response_id; reaction=del.reaction; uid=del.user_id;
        if(uid===myUid) return;
        if(_dqReactMap[rid]&&_dqReactMap[rid][reaction])
          _dqReactMap[rid][reaction].count=Math.max(0,_dqReactMap[rid][reaction].count-1);
      }
      if(rid) _updateDqCardReactions(String(rid));
    });
  }
  // 15s feed poll — reliable fallback when Supabase RT subscription misses inserts
  if(!_dqFeedPollTmr && sbClient){
    var _pollQId = qId;
    _dqFeedPollTmr = setInterval(function(){
      if(document.hidden) return;
      _fetchDailyFeed(_pollQId);
      try{ _fetchDailyCount(); }catch(e){}
    }, 15000);
  }
  // 20s poll + visibility-change handler: reliable fallback for Supabase RLS gaps
  _startDqReactPoll();
  if(!_dqVisHandler){
    _dqVisHandler = async function(){
      if(document.hidden || !sbClient) return;
      // On return-to-tab, refresh everything: feed, count, and reactions
      try{ _fetchDailyFeed(qId); }catch(e){}
      try{ _fetchDailyCount(); }catch(e){}
      if(_dqAllResponses && _dqAllResponses.length){
        var ids = _dqAllResponses.map(function(r){ return r.id; });
        await _loadDqReactions(ids);
        ids.forEach(function(id){ _updateDqCardReactions(String(id)); });
      }
    };
    document.addEventListener('visibilitychange', _dqVisHandler);
  }
}

// ── DAILY QUESTION REACTIONS ────────────────────────────────────
var _dqReactMap = {}; // {responseId:{identifico:{count,mine},abrazo:{count,mine},entiendo:{count,mine}}}

async function _loadDqReactions(responseIds){
  _dqReactMap = {};
  if(!sbClient || !responseIds.length) return;
  var myUid = safeLS('get','velo_user_id') || '';
  try{
    var res = await sbClient.from('dq_reactions').select('response_id,reaction,user_id').in('response_id', responseIds);
    (res.data||[]).forEach(function(r){
      if(!_dqReactMap[r.response_id]) _dqReactMap[r.response_id] = {};
      var m = _dqReactMap[r.response_id];
      if(!m[r.reaction]) m[r.reaction] = {count:0, mine:false};
      m[r.reaction].count++;
      if(r.user_id === myUid) m[r.reaction].mine = true;
    });
  }catch(e){}
}

var _rxColors = {
  identifico:{activeBg:'rgba(30,160,90,.68)',inactiveBg:'rgba(255,255,255,.05)',border:'rgba(45,185,110,.72)',inactiveBorder:'rgba(255,255,255,.12)',glow:'rgba(30,160,90,.40)',txt:'rgba(130,255,185,.98)',inactiveTxt:'rgba(255,255,255,.45)',circleBg:'rgba(30,160,90,.25)',inactiveCircleBg:'rgba(255,255,255,.08)'},
  abrazo:     {activeBg:'rgba(100,80,225,.62)',inactiveBg:'rgba(255,255,255,.05)',border:'rgba(120,100,240,.70)',inactiveBorder:'rgba(255,255,255,.12)',glow:'rgba(100,80,225,.38)',txt:'rgba(195,185,255,.98)',inactiveTxt:'rgba(255,255,255,.45)',circleBg:'rgba(100,80,225,.22)',inactiveCircleBg:'rgba(255,255,255,.08)'},
  entiendo:   {activeBg:'rgba(45,130,225,.62)',inactiveBg:'rgba(255,255,255,.05)',border:'rgba(65,150,235,.70)',inactiveBorder:'rgba(255,255,255,.12)',glow:'rgba(45,130,225,.38)',txt:'rgba(165,215,255,.98)',inactiveTxt:'rgba(255,255,255,.45)',circleBg:'rgba(45,130,225,.22)',inactiveCircleBg:'rgba(255,255,255,.08)'}
};

function _updateDqCardReactions(rid){
  rid = String(rid);
  var card = document.querySelector('.dq-feed-card[data-response-id="'+rid+'"]');
  if(card){
    var _m = _dqReactMap[rid]||{};
    var metaEl = card.querySelector('.dq-rx-meta');
    if(metaEl){
      // Reconstrueimos las pills por emoji + 'Ver →'
      var r0 = (_dqAllResponses||[]).find(function(x){ return String(x.id)===rid; });
      var col0 = r0 ? (document.body.classList.contains('r-dark')
        ? _userColor(r0.user_id||r0.user_name)
        : _userColorLight(r0.user_id||r0.user_name)) : null;
      var badge = col0 ? col0.badge : 'rgba(116,198,157,.14)';
      var bord  = col0 ? col0.border.replace(/[\d.]+\)$/,'0.32)') : 'rgba(116,198,157,.32)';
      var labl  = col0 ? col0.label : 'rgba(255,255,255,.92)';
      var rxPillsLive = [{k:'identifico',e:'💚'},{k:'abrazo',e:'🫂'},{k:'entiendo',e:'💙'}]
        .filter(function(rx){ return _m[rx.k]&&_m[rx.k].count>0; })
        .map(function(rx){ return '<span style="display:inline-flex;align-items:center;gap:2px;background:'+badge+';border:1px solid '+bord+';border-radius:100px;padding:2px 7px;font-size:11px;font-weight:700">'+rx.e+'<span style="font-size:10px;font-weight:700;color:'+labl+';opacity:.92">'+_m[rx.k].count+'</span></span>'; })
        .join('');
      metaEl.innerHTML = rxPillsLive + '<span style="opacity:.78">Ver →</span>';
    }
  }
  // Update "Tu respuesta" badge
  var myUid = safeLS('get','velo_user_id')||'';
  var myResp = _dqAllResponses.find(function(x){ return String(x.id)===rid && x.user_id===myUid; });
  if(myResp){
    var myBadge = document.getElementById('homeDailyQMyResp');
    if(myBadge){
      var _m2 = _dqReactMap[rid]||{};
      var rxPills2 = [{k:'identifico',e:'💚'},{k:'abrazo',e:'🫂'},{k:'entiendo',e:'💙'}]
        .filter(function(rx){ return _m2[rx.k]&&_m2[rx.k].count>0; })
        .map(function(rx){ return rx.e+' '+_m2[rx.k].count; }).join('  ');
      var myTxt2 = 'Tu respuesta: '+(myResp.mood_emoji||'')+(myResp.response_text?' · '+myResp.response_text.slice(0,30)+(myResp.response_text.length>30?'…':''):'');
      myBadge.textContent = myTxt2;
      var _liveRxEl = document.getElementById('homeDailyQMyRxPills');
      if(_liveRxEl){
        var _liveRxHtml = [{k:'identifico',e:'💚'},{k:'abrazo',e:'🫂'},{k:'entiendo',e:'💙'}]
          .filter(function(rx){ return _m2[rx.k]&&_m2[rx.k].count>0; })
          .map(function(rx){ return '<span style="display:inline-flex;align-items:center;gap:4px;background:rgba(200,158,56,.12);border:1px solid rgba(200,158,56,.28);border-radius:20px;padding:4px 11px;font-size:14px">'+rx.e+'<span style="font-size:12px;font-weight:700;color:rgba(200,155,40,.90);font-family:Jost,sans-serif">'+_m2[rx.k].count+'</span></span>'; })
          .join('');
        _liveRxEl.innerHTML = _liveRxHtml;
        _liveRxEl.style.display = _liveRxHtml ? 'flex' : 'none';
      }
    }
  }
}

function _buildDqReactionBar(responseId){
  var rxDefs = [
    {key:'identifico', label:'Me identifico', emoji:'💚'},
    {key:'abrazo',     label:'Te abrazo',     emoji:'🫂'},
    {key:'entiendo',   label:'Te entiendo',   emoji:'💙'}
  ];
  var m = _dqReactMap[responseId] || {};
  return '<div style="display:flex;gap:5px;margin-top:8px;flex-wrap:wrap">'
    + rxDefs.map(function(rx){
      var rd = m[rx.key] || {count:0, mine:false};
      var cnt = rd.count > 0 ? ' '+rd.count : '';
      return '<button class="dq-reaction-btn" onclick="pToggleDqReaction(\''+responseId+'\',\''+rx.key+'\',this)" '
        +'data-rid="'+responseId+'" data-rtype="'+rx.key+'" data-active="'+rd.mine+'">'
        +rx.emoji+'<span>'+rx.label+cnt+'</span>'
        +'</button>';
    }).join('')
    + '</div>';
}

async function pToggleDqReaction(responseId, reaction, btn){
  var uid = safeLS('get','velo_user_id');
  if(!uid){ pToast('💚','Iniciá sesión para reaccionar'); return; }
  var isActive = btn.dataset.active === 'true';
  if(!_dqReactMap[responseId]) _dqReactMap[responseId] = {};
  var rd = _dqReactMap[responseId][reaction] || {count:0, mine:false};
  var _rxLabel = {identifico:'Me identifico', abrazo:'Te abrazo', entiendo:'Te entiendo'};
  var _rxEmoji = {identifico:'💚', abrazo:'🫂', entiendo:'💙'};
  // Optimistic UI update — CSS class handles colors, just flip data-active
  if(isActive){
    rd.count = Math.max(0, rd.count-1); rd.mine = false;
    btn.dataset.active = 'false';
  } else {
    rd.count++; rd.mine = true;
    btn.dataset.active = 'true';
    pToast(_rxEmoji[reaction], _rxLabel[reaction]);
  }
  _dqReactMap[responseId][reaction] = rd;
  var span = btn.querySelector('.rx-txt');
  if(span) span.textContent = _rxLabel[reaction];
  var cntEl = btn.querySelector('.rx-cnt');
  if(cntEl){ cntEl.textContent = rd.count>0?rd.count:''; cntEl.style.display=rd.count>0?'':'none'; }
  // Update button's inline styles to reflect new active state
  var _rc = _rxColors[reaction];
  if(_rc){
    var _nowActive = btn.dataset.active === 'true';
    btn.style.background = _nowActive ? _rc.activeBg : _rc.inactiveBg;
    btn.style.borderColor = _nowActive ? _rc.border : _rc.inactiveBorder;
    btn.style.boxShadow   = _nowActive ? '0 4px 22px '+_rc.glow : 'none';
    var _circ = btn.querySelector('span:first-child');
    if(_circ){
      _circ.style.background   = _nowActive ? _rc.circleBg : _rc.inactiveCircleBg;
      _circ.style.borderColor  = _nowActive ? _rc.border : 'rgba(255,255,255,.10)';
    }
    var _rxt = btn.querySelector('.rx-txt');
    if(_rxt) _rxt.style.color = _nowActive ? _rc.txt : _rc.inactiveTxt;
    var _rcc = btn.querySelector('.rx-cnt');
    if(_rcc){
      _rcc.style.color       = _nowActive ? _rc.txt : _rc.inactiveTxt;
      _rcc.style.background  = _nowActive ? _rc.circleBg : 'rgba(255,255,255,.08)';
      _rcc.style.borderColor = _nowActive ? _rc.border : 'rgba(255,255,255,.12)';
    }
  }
  // Update feed card pills instantly (optimistic)
  _updateDqCardReactions(String(responseId));
  // Pop animation
  btn.style.animation='none';
  void btn.offsetWidth;
  if(btn.dataset.active==='true') btn.style.animation='velo-rx-pop .22s ease-out both';
  // Sync Supabase
  if(!sbClient) return;
  try{
    if(isActive){
      await sbClient.from('dq_reactions').delete().eq('response_id',responseId).eq('user_id',uid).eq('reaction',reaction);
    } else {
      await sbClient.from('dq_reactions').upsert({response_id:responseId, user_id:uid, reaction:reaction},{onConflict:'response_id,user_id,reaction'});
      // v1448: notificar al autor de la respuesta que alguien reaccionó (actividad)
      try{
        var _dqOwner = _dqAllResponses && _dqAllResponses.find(function(x){ return String(x.id)===String(responseId); });
        if(_dqOwner && _dqOwner.user_id){
          var _rNm = safeLS('get','velo_user_name')||'Alguien';
          _createVeloNotif(_dqOwner.user_id,'dq_reaction',_rNm+' reaccionó '+reaction+' a tu respuesta del día','',responseId);
        }
      }catch(_){}
    }
  }catch(e){}
}

var _DQ_PREVIEW_COUNT = 5; // cards shown before "ver más"
var _dqAllResponses = [];  // full list cached for expand
var _dqThemeObserverSet = false;
// ── MOOD CHIP WIDGET (compact, above greeting) ────────────────
var _moodChipSheetOpen = false;
