function _initMoodChip(){
  if(document.getElementById('homeMoodChip')) return;
  var chip = document.createElement('div');
  chip.id = 'homeMoodChip';
  // v1414: si el día de hoy NO está registrado, ir DIRECTO al selector de
  // emociones (página de ánimo). Solo si ya está completo mostrar el resumen
  // "Mi estado de hoy".
  chip.onclick = function(){
    var _hoy = (typeof _dateKey === 'function') ? _dateKey() : '';
    if(_hoy && !safeLS('get','velo_mood_'+_hoy)){ try{ pGoTo('mood'); return; }catch(_){} }
    pOpenMoodChipSheet();
  };
  chip.style.cssText = 'order:0;width:100%;box-sizing:border-box;margin-bottom:10px;cursor:pointer;flex-shrink:0';
  var greetEl = document.getElementById('homeGreetWrapper');
  if(greetEl && greetEl.parentElement) {
    greetEl.parentElement.insertBefore(chip, greetEl);
  } else {
    var heroLeft = document.querySelector('.r-hero-left');
    if(!heroLeft) return;
    heroLeft.insertAdjacentElement('afterbegin', chip);
  }
  _updateMoodChip();
}

// v1540 — check-in emocional inline en el home: caritas para tocar y registrar
// al toque (más claro y original que el chip ambiguo anterior).
var _HOME_MOODS = [
  {e:'😄',l:'Genial'},{e:'😊',l:'Bien'},{e:'😌',l:'En paz'},
  {e:'😐',l:'Neutro'},{e:'😔',l:'Triste'},{e:'😰',l:'Ansioso/a'}
];
var _homeMoodForcePick = false;
function _homeMoodQuick(emoji, label){
  // v1594: soporte REAL de "recuperar racha". Si hay una fecha objetivo reciente
  // (banner "ayer no registraste"), se guarda en ESA fecha, no en hoy. Antes
  // window._recoveryTargetDate se seteaba pero NUNCA se leía → el botón
  // "Recuperar" no hacía nada. Se auto-expira a los 2 min para no desviar un
  // registro de hoy por accidente.
  var _recov = window._recoveryTargetDate;
  var _recovDate = (_recov && _recov.date && (Date.now() - (_recov.ts||0)) < 120000) ? _recov.date : null;
  window._recoveryTargetDate = null;
  var today = _recovDate || ((typeof _dateKey==='function') ? _dateKey() : '');
  if(!today) return;
  var moodObj = { emoji:emoji, label:label||'', note:'', ts: _recovDate ? new Date(_recovDate+'T12:00:00').getTime() : Date.now() };
  try{ safeLS('set','velo_mood_'+today, JSON.stringify(moodObj)); }catch(_){}
  try{ var log=JSON.parse(safeLS('get','velo_mood_log')||'[]'); log=log.filter(function(m){ return m.dateKey !== today; }); log.unshift(Object.assign({},moodObj,{dateKey:today})); safeLS('set','velo_mood_log', JSON.stringify(log.slice(0,90))); }catch(_){}
  try{ if(typeof sbSaveMoodEntry==='function') sbSaveMoodEntry(today, emoji, label||'', ''); }catch(_){}
  _homeMoodForcePick = false;
  try{ _updateMoodChip(); }catch(_){}
  try{ if(typeof _updateTopbarMoodBadge==='function') _updateTopbarMoodBadge(); }catch(_){}
  try{ if(typeof _loadTodayMoodHome==='function') _loadTodayMoodHome(); }catch(_){}
  try{ if(typeof _renderHomeWeekMoodGraph==='function') _renderHomeWeekMoodGraph().catch(function(){}); }catch(_){}
  try{ pToast(emoji, _recovDate ? 'Ánimo de ayer registrado 💚 ¡racha a salvo! 🔥' : 'Ánimo guardado 💚'); }catch(_){}
  try{ if(typeof _showStreakCelebration==='function') _showStreakCelebration(); }catch(_){}
}
function _updateMoodChip(){
  var chip = document.getElementById('homeMoodChip');
  if(!chip) return;
  var today = _dateKey ? _dateKey() : '';
  var emoji = null; var label = '';
  if(today){ try{ var _cm=JSON.parse(safeLS('get','velo_mood_'+today)||'null'); if(_cm){emoji=_cm.emoji||null;label=_cm.label||'';} }catch(e){} }
  var hasEntry = !!emoji;
  // Pulse ambient si no registró hoy — llama sin gritar
  if(hasEntry) chip.classList.remove('velo-pulse-glow');
  else chip.classList.add('velo-pulse-glow');
  var isDark = document.body.classList.contains('r-dark');
  var wrapBg   = isDark ? 'linear-gradient(145deg,rgba(14,58,32,.92),rgba(8,38,20,.90))' : 'linear-gradient(145deg,rgba(255,255,255,.96),rgba(238,252,244,.94))';
  var wrapBdr  = isDark ? 'rgba(116,198,157,.65)' : 'rgba(74,160,110,.55)';
  var wrapShd  = isDark ? '0 4px 24px rgba(0,0,0,.45),inset 0 1px 0 rgba(116,198,157,.12)' : '0 4px 18px rgba(74,160,110,.16),inset 0 1px 0 rgba(255,255,255,.80)';
  var glowBg   = isDark ? 'radial-gradient(circle,rgba(116,198,157,.25) 0%,transparent 70%)' : 'radial-gradient(circle,rgba(74,160,110,.18) 0%,transparent 70%)';
  var iconBg   = isDark ? 'rgba(116,198,157,.20)' : 'rgba(74,160,110,.12)';
  var iconBdr  = isDark ? 'rgba(116,198,157,.65)' : 'rgba(74,160,110,.55)';
  var iconShd  = isDark ? '0 2px 10px rgba(116,198,157,.22)' : '0 2px 10px rgba(74,160,110,.15)';
  var lblCol   = isDark ? 'rgba(116,198,157,.90)' : 'rgba(38,120,70,.85)';
  var mainCol  = isDark ? 'rgba(230,255,240,.98)' : 'rgba(8,52,24,.92)';
  var arrowCol = isDark ? 'rgba(116,198,157,.90)' : 'rgba(38,120,70,.75)';
  // Streak visible con 🔥 cuando llegás a 2+ días — motiva a mantener el ritual diario
  var streak = 0;
  try{ streak = _getMoodStreak(); }catch(e){}
  var streakBadge = '';
  if(streak >= 2){
    var streakGlow = streak >= 7 ? '0 0 16px rgba(255,150,60,.55)' : streak >= 4 ? '0 0 10px rgba(255,180,80,.42)' : '0 0 6px rgba(255,180,80,.30)';
    var streakBg = isDark ? 'linear-gradient(140deg,rgba(255,140,50,.32),rgba(220,90,20,.24))' : 'linear-gradient(140deg,rgba(255,180,80,.35),rgba(230,110,30,.24))';
    var streakBdr = isDark ? 'rgba(255,170,80,.75)' : 'rgba(230,130,40,.75)';
    var streakTxt = isDark ? 'rgba(255,230,180,.98)' : 'rgba(120,50,0,.94)';
    streakBadge = '<span class="mcc-streak" style="position:absolute;top:8px;right:10px;z-index:2;display:inline-flex;align-items:center;gap:3px;background:'+streakBg+';border:1.5px solid '+streakBdr+';border-radius:100px;padding:3px 9px 3px 7px;font-size:11.5px;font-weight:800;color:'+streakTxt+';font-family:Jost,sans-serif;box-shadow:'+streakGlow+';line-height:1;white-space:nowrap"><span class="velo-flicker-fire" style="font-size:13px;line-height:1;display:inline-block">🔥</span>'+streak+'</span>';
    // Inyectar keyframes si aún no están
    if(!document.getElementById('_mccStreakKf')){
      var _kf = document.createElement('style'); _kf.id='_mccStreakKf';
      _kf.textContent = '@keyframes mccStreakPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}@keyframes mccFlicker{0%,100%{transform:scale(1) rotate(-2deg);filter:drop-shadow(0 0 3px rgba(255,180,60,.6))}50%{transform:scale(1.12) rotate(3deg);filter:drop-shadow(0 0 6px rgba(255,150,40,.9))}}';
      document.head.appendChild(_kf);
    }
  }
  var showPicker = !hasEntry || _homeMoodForcePick;
  // v1545: contenedor PROPIO (sin .mcc-wrap, que en CSS es display:flex y apilaba
  // todo horizontal apretado). Texto en mainCol (legible en claro/oscuro), caritas
  // como botones CON etiqueta (se entiende que son clickeables) + "Ver todas".
  var _card = '<div style="padding:15px 16px;background:'+wrapBg+';border:1.5px solid '+wrapBdr+';border-radius:20px;box-shadow:'+wrapShd+';position:relative;overflow:visible">';
  if(showPicker){
    var facesHtml = _HOME_MOODS.map(function(m){
      var sl = _escHtml((m.l||'').replace('/a',''));
      return '<button type="button" onclick="event.stopPropagation();_homeMoodQuick(\''+m.e+'\',\''+_escHtml(m.l)+'\')" style="flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:3px;background:'+iconBg+';border:1.5px solid '+iconBdr+';border-radius:13px;padding:8px 1px 6px;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .1s" onmousedown="this.style.transform=\'scale(1.1)\'" onmouseup="this.style.transform=\'\'" onmouseleave="this.style.transform=\'\'"><span style="font-size:23px;line-height:1">'+m.e+'</span><span style="font-size:8px;font-weight:700;color:'+mainCol+';opacity:.82;font-family:Jost,sans-serif;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%">'+sl+'</span></button>';
    }).join('');
    chip.innerHTML = _card
      + streakBadge
      + '<div style="font-size:12px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:'+mainCol+';font-family:Jost,sans-serif">✦ ¿Cómo estás ahora?</div>'
      + '<div style="font-size:11.5px;color:'+mainCol+';opacity:.72;font-family:Jost,sans-serif;margin:3px 0 11px">Tocá una carita — se guarda al toque</div>'
      + '<div style="display:flex;gap:5px">'+facesHtml+'</div>'
      + (_homeMoodForcePick
          ? '<div style="display:flex;gap:6px;margin-top:10px"><button onclick="event.stopPropagation();_homeMoodForcePick=false;_updateMoodChip();" style="flex:1;padding:9px;background:none;border:1.5px solid '+iconBdr+';border-radius:12px;color:'+mainCol+';opacity:.85;font-family:Jost,sans-serif;font-size:12px;font-weight:800;cursor:pointer">✕ Cancelar</button><button onclick="event.stopPropagation();try{pGoTo(\'mood\')}catch(_){}" style="flex:1.6;padding:9px;background:'+iconBg+';border:1.5px solid '+iconBdr+';border-radius:12px;color:'+mainCol+';font-family:Jost,sans-serif;font-size:12px;font-weight:800;cursor:pointer">＋ Ver todas las emociones</button></div>'
          : '<button onclick="event.stopPropagation();try{pGoTo(\'mood\')}catch(_){}" style="width:100%;margin-top:10px;padding:9px;background:'+iconBg+';border:1.5px solid '+iconBdr+';border-radius:12px;color:'+mainCol+';font-family:Jost,sans-serif;font-size:12px;font-weight:800;cursor:pointer">＋ Ver todas las emociones</button>')
      + '</div>';
  } else {
    chip.innerHTML = _card
      + streakBadge
      + '<div style="display:flex;align-items:center;gap:14px">'
      +   '<div style="width:46px;height:46px;border-radius:15px;background:'+iconBg+';border:1.5px solid '+iconBdr+';display:flex;align-items:center;justify-content:center;font-size:24px;flex-shrink:0;box-shadow:'+iconShd+'">'+(emoji||'💚')+'</div>'
      +   '<div style="flex:1;min-width:0"><div style="font-size:10px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:'+mainCol+';opacity:.72;font-family:Jost,sans-serif;margin-bottom:3px">Hoy te sentiste</div><div style="font-size:16px;font-weight:800;color:'+mainCol+';font-family:Jost,sans-serif;line-height:1.2">'+_escHtml(label||'Registrado')+'</div></div>'
      +   '<button onclick="event.stopPropagation();_homeMoodForcePick=true;_updateMoodChip()" style="background:'+iconBg+';border:1.5px solid '+iconBdr+';color:'+mainCol+';border-radius:12px;padding:8px 12px;font-family:Jost,sans-serif;font-size:12px;font-weight:800;cursor:pointer;flex-shrink:0">✎ Cambiar</button>'
      + '</div>'
      + '<button onclick="event.stopPropagation();try{pOpenMoodChipSheet()}catch(_){}" style="width:100%;margin-top:11px;padding:9px;background:none;border:1.5px solid '+iconBdr+';border-radius:12px;color:'+mainCol+';opacity:.9;font-family:Jost,sans-serif;font-size:11.5px;font-weight:800;cursor:pointer">Ver más → estado · lema · evolución</button>'
      + '</div>';
  }
}

function pOpenMoodChipSheet(){
  if(_moodChipSheetOpen) return;
  var reg = document.getElementById('homeRegisterOuter');
  if(!reg) return;
  _moodChipOrgParent = reg.parentElement;
  _moodChipOrgNextSibling = reg.nextSibling;
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'moodChipSheetOv';
  ov.style.zIndex = '750';
  ov.onclick = function(e){ if(e.target===ov) pCloseMoodChipSheet(); };
  var sheet = document.createElement('div');
  sheet.className = 'p-sheet p-sheet-dark';
  sheet.style.cssText = 'padding:0;overflow-y:auto;max-height:92vh;border-radius:28px 28px 0 0;border-top:2px solid rgba(116,198,157,.38)';
  sheet.innerHTML = '<div style="padding:14px 20px 10px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:1;background:rgba(6,16,10,.97);backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,255,255,.06)">'
    +'<div class="p-sheet-handle" style="position:absolute;top:8px;left:50%;transform:translateX(-50%);margin:0;background:rgba(116,198,157,.32)"></div>'
    +'<div style="font-size:15px;font-weight:800;color:rgba(200,240,218,.92);font-family:Jost,sans-serif;margin-top:6px">😊 Mi estado de hoy</div>'
    +'<button onclick="pCloseMoodChipSheet()" style="background:none;border:none;color:rgba(255,255,255,.38);font-size:20px;cursor:pointer;padding:4px;line-height:1;margin-top:6px">×</button>'
    +'</div>'
    +'<div id="moodChipSheetBody"></div>';
  ov.appendChild(sheet);
  document.body.appendChild(ov);
  reg.style.display = 'block';
  document.getElementById('moodChipSheetBody').appendChild(reg);
  _moodChipSheetOpen = true;
}

function pCloseMoodChipSheet(){
  var ov = document.getElementById('moodChipSheetOv');
  var reg = document.getElementById('homeRegisterOuter');
  if(reg && _moodChipOrgParent){
    reg.style.display = 'none';
    if(_moodChipOrgNextSibling && _moodChipOrgNextSibling.parentElement === _moodChipOrgParent){
      _moodChipOrgParent.insertBefore(reg, _moodChipOrgNextSibling);
    } else {
      _moodChipOrgParent.appendChild(reg);
    }
  }
  if(ov) ov.remove();
  _moodChipSheetOpen = false;
  _updateMoodChip();
}

function _initDqThemeObserver(){
  if(_dqThemeObserverSet) return;
  _dqThemeObserverSet = true;
  var _dqThemeTimer = null;
  var obs = new MutationObserver(function(){
    clearTimeout(_dqThemeTimer);
    _dqThemeTimer = setTimeout(function(){
      _updateMoodChip();
      if(_dqAllResponses && _dqAllResponses.length) _renderDailyFeed(_dqAllResponses);
    }, 60);
  });
  obs.observe(document.body, {attributes:true, attributeFilter:['class']});
}

function _renderDailyFeed(responses){
  _dqAllResponses = responses;
  var _dqHidden = []; try{ _dqHidden = JSON.parse(safeLS('get','velo_dq_hidden')||'[]'); }catch(e){}
  var myUid2 = safeLS('get','velo_user_id')||'';
  var myResp2 = responses.find(function(r){ return r.user_id === myUid2; });
  // Update "Tu respuesta" badge — pills inline para que sea un solo chip orgánico
  var myBadge2 = document.getElementById('homeDailyQMyResp');
  if(myBadge2 && myResp2){
    var _rxMapInline = _dqReactMap[myResp2.id] || {};
    var _rxInline = [{k:'identifico',e:'💚'},{k:'abrazo',e:'🫂'},{k:'entiendo',e:'💙'}]
      .filter(function(rx){ return _rxMapInline[rx.k]&&_rxMapInline[rx.k].count>0; })
      .map(function(rx){ return '<span style="margin-left:8px;display:inline-flex;align-items:center;gap:3px;font-size:12px;font-weight:700">'+rx.e+'<span style="font-size:11px">'+_rxMapInline[rx.k].count+'</span></span>'; })
      .join('');
    myBadge2.innerHTML = _dqMyRespHtml(myResp2.mood_emoji, myResp2.response_text, _rxInline);
  }
  // Ocultar la fila separada de pills — ahora viven dentro de "Tu respuesta"
  var _rxPillsEl2 = document.getElementById('homeDailyQMyRxPills');
  if(_rxPillsEl2){ _rxPillsEl2.style.display = 'none'; _rxPillsEl2.innerHTML = ''; }
  // Update count from actual data — avoids stale "Sé el primero" text
  var _totalCount = responses.length;
  var _countTxt = _totalCount === 0 ? 'Sé el primero en responder ✨'
    : _totalCount === 1 ? '1 persona compartió hoy'
    : _totalCount+' personas compartieron hoy';
  var _openCount = document.getElementById('homeDailyQOpenCount');
  if(_openCount && _totalCount > 0) _openCount.textContent = _countTxt;
  // Hide emoji summary row — redundant noise
  var summaryEl = document.getElementById('homeDailyQSummary');
  if(summaryEl) summaryEl.style.display = 'none';
  var feedEl    = document.getElementById('homeDailyQFeed');
  var btnEl     = document.getElementById('dqVerTodosBtn');
  if(!feedEl) return;
  // Exclude own response from home feed (already shown in badge above)
  var others = responses.filter(function(r){
    return r.user_id !== myUid2 && _dqHidden.indexOf(String(r.id)) === -1 && !_isBlocked(r.user_id);
  });
  // v1486: si el único que respondió soy yo, todo el bloque de comunidad
  // (pulso + feed + dots) se reemplaza por UN solo mensaje claro — antes
  // convivían "1 persona compartió hoy" (yo) y "la comunidad aún no
  // compartió" + cajas vacías: contradictorio y confuso.
  var _pulseRowEl = document.querySelector('#homeDailyQOpen .dq-pulse-row');
  var _dotsEl = document.getElementById('dqDots');
  if(!others.length){
    if(_pulseRowEl) _pulseRowEl.style.display = 'none';
    if(_dotsEl){ _dotsEl.style.display = 'none'; _dotsEl.innerHTML = ''; }
    // v1494: una sola línea serena — sin caja dentro de caja
    var _fbLt = !document.body.classList.contains('r-dark');
    feedEl.innerHTML = '<div style="display:flex;align-items:flex-start;gap:8px;padding:2px 2px 0;font-family:Jost,sans-serif">'
      + '<span style="font-size:14px;flex-shrink:0;line-height:1.4">🌱</span>'
      + '<span style="font-size:11.5px;font-style:italic;line-height:1.55;color:'+(_fbLt?'rgba(85,70,30,.75)':'rgba(255,255,255,.52)')+'">Fuiste la primera persona en responder hoy — las respuestas de otros van a aparecer acá.</span>'
      + '</div>';
    if(btnEl) btnEl.innerHTML = '';
    return;
  }
  if(_pulseRowEl) _pulseRowEl.style.display = 'flex';
  if(_dotsEl) _dotsEl.style.display = '';
  var _dqPrevL = feedEl.scrollLeft;
  feedEl.innerHTML = _buildDqCards(others.slice(0,3));
  _initCarouselDots('homeDailyQFeed','dqDots');
  if(_dqPrevL>0) requestAnimationFrame(function(){ feedEl.scrollLeft = _dqPrevL; });
  if(btnEl){
    if(others.length > 3){
      btnEl.innerHTML = '<button onclick="pOpenDqAllSheet()" style="width:100%;margin-top:10px;padding:10px 16px;background:rgba(200,158,56,.12);border:1.5px solid rgba(200,158,56,.40);border-radius:14px;color:rgba(220,185,75,.88);font-size:14px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer;letter-spacing:.3px">✦ Ver todas las respuestas ('+others.length+') →</button>';
    } else {
      btnEl.innerHTML = '';
    }
  }
}

function _expandDailyFeed(){
  var feedEl = document.getElementById('homeDailyQFeed');
  if(!feedEl) return;
  var _dqHidden = []; try{ _dqHidden = JSON.parse(safeLS('get','velo_dq_hidden')||'[]'); }catch(e){}
  var _vis = _dqHidden.length ? _dqAllResponses.filter(function(r){ return _dqHidden.indexOf(String(r.id)) === -1; }) : _dqAllResponses;
  feedEl.innerHTML = _buildDqCards(_vis);
}

function pOpenDqAllSheet(){
  var myUid = safeLS('get','velo_user_id')||'';
  var q = _getDailyQuestion();
  var existing = document.getElementById('dqAllSheetOv');
  if(existing) existing.remove();
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'dqAllSheetOv';
  ov.onclick = function(e){ if(e.target===ov) ov.remove(); };
  var _dqHidden = []; try{ _dqHidden = JSON.parse(safeLS('get','velo_dq_hidden')||'[]'); }catch(e){}
  var allVis = _dqHidden.length ? _dqAllResponses.filter(function(r){ return _dqHidden.indexOf(String(r.id))===-1; }) : _dqAllResponses;
  var myResp = allVis.find(function(r){ return r.user_id === myUid; });
  ov.innerHTML =
    '<div class="p-sheet p-sheet-dark" style="max-height:92vh;display:flex;flex-direction:column;overflow:hidden;background:linear-gradient(160deg,rgba(14,10,32,.98),rgba(6,4,20,.99));border-top:2.5px solid rgba(200,158,56,.55)">'
    +'<div class="p-sheet-handle" style="background:rgba(200,158,56,.55)"></div>'
    +'<div style="padding:16px 20px 14px;flex-shrink:0;border-bottom:1px solid rgba(200,158,56,.16)">'
    +'<div style="font-size:11px;font-weight:800;letter-spacing:2.5px;text-transform:uppercase;color:rgba(200,158,56,.75);font-family:\'Jost\',sans-serif;margin-bottom:9px">✨ Pregunta del día</div>'
    +(q ? '<div style="font-family:\'Cormorant Garamond\',serif;font-size:16.5px;font-style:italic;font-weight:600;color:rgba(255,255,255,.92);line-height:1.42;padding-left:13px;border-left:2.5px solid rgba(200,158,56,.50)">'+_escHtml(q.text)+'</div>' : '')
    +'</div>'
    +'<div style="display:flex;gap:0;padding:0 20px;border-bottom:1px solid rgba(200,158,56,.12);flex-shrink:0">'
    +'<button id="dqAllTab1" onclick="pDqAllTabSwitch(1)" style="flex:1;padding:11px 0;font-size:14px;font-weight:700;font-family:\'Jost\',sans-serif;background:none;border:none;border-bottom:2.5px solid rgba(200,158,56,.75);color:rgba(210,170,60,.95);cursor:pointer">Todas ('+allVis.length+')</button>'
    +'<button id="dqAllTab2" onclick="pDqAllTabSwitch(2)" style="flex:1;padding:11px 0;font-size:14px;font-weight:700;font-family:\'Jost\',sans-serif;background:none;border:none;border-bottom:2.5px solid transparent;color:rgba(255,255,255,.38);cursor:pointer">Mi publicación</button>'
    +'</div>'
    +'<div id="dqAllTabContent1" style="flex:1;overflow-y:auto;padding:14px 14px 0">'
    +(allVis.length ? _buildDqCards(allVis) : '<div style="text-align:center;padding:32px;font-size:15px;color:rgba(255,255,255,.30);font-style:italic;font-family:Jost,sans-serif">Nadie ha respondido aún 🌱</div>')
    +'</div>'
    +'<div id="dqAllTabContent2" style="display:none;flex:1;overflow-y:auto;padding:16px">'
    +_buildDqMyPubSection(myResp)
    +'</div>'
    +'<div style="padding:10px 20px 16px;flex-shrink:0;border-top:1px solid rgba(200,158,56,.12)">'
    +'<button onclick="document.getElementById(\'dqAllSheetOv\').remove()" style="width:100%;padding:12px;background:rgba(200,158,56,.08);border:1px solid rgba(200,158,56,.22);border-radius:14px;color:rgba(200,158,56,.65);font-size:15px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer;letter-spacing:.5px">Cerrar</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
}

function pDqAllTabSwitch(tab){
  var t1 = document.getElementById('dqAllTab1');
  var t2 = document.getElementById('dqAllTab2');
  var c1 = document.getElementById('dqAllTabContent1');
  var c2 = document.getElementById('dqAllTabContent2');
  if(!t1||!t2||!c1||!c2) return;
  if(tab === 2){
    t2.style.borderBottomColor = 'rgba(200,158,56,.75)';
    t2.style.color = 'rgba(210,170,60,.95)';
    t1.style.borderBottomColor = 'transparent';
    t1.style.color = 'rgba(255,255,255,.38)';
    c1.style.display = 'none'; c2.style.display = '';
  } else {
    t1.style.borderBottomColor = 'rgba(200,158,56,.75)';
    t1.style.color = 'rgba(210,170,60,.95)';
    t2.style.borderBottomColor = 'transparent';
    t2.style.color = 'rgba(255,255,255,.38)';
    c2.style.display = 'none'; c1.style.display = '';
  }
}

function _buildDqMyPubSection(myResp){
  if(!myResp) return '<div style="text-align:center;padding:48px 24px;font-family:\'Jost\',sans-serif">'
    +'<div style="font-size:38px;margin-bottom:14px">🌱</div>'
    +'<div style="font-size:14px;color:rgba(255,255,255,.42);line-height:1.7">Respondé la pregunta del día<br>para ver tu publicación aquí</div>'
    +'</div>';
  var col = _dqEmojiColor(myResp.mood_emoji||'💭');
  var ca = function(c,a){ return c.replace(/,[\d.]+\)$/,','+a+')'); };
  var _m = _dqReactMap[myResp.id] || {};
  var rxTypes = ['identifico','abrazo','entiendo'];
  var rxEmojis = {identifico:'🙌',abrazo:'🤗',entiendo:'💙'};
  var rxLabels = {identifico:'Me identifico',abrazo:'Te mando un abrazo',entiendo:'Te entiendo'};
  var totalRx = rxTypes.reduce(function(s,k){ return s+((_m[k]&&_m[k].count)||0); },0);
  var rxHtml = rxTypes.map(function(k){
    var cnt = (_m[k]&&_m[k].count)||0;
    if(!cnt) return '';
    return '<div style="display:flex;align-items:center;gap:12px;padding:10px 14px;background:'+ca(col.strip,'.16')+';border:1px solid '+ca(col.border,'.28')+';border-radius:13px;margin-bottom:8px">'
      +'<span style="font-size:24px;line-height:1">'+rxEmojis[k]+'</span>'
      +'<div style="flex:1"><div style="font-size:13px;font-weight:600;color:'+ca(col.label,'.80')+';font-family:\'Jost\',sans-serif">'+rxLabels[k]+'</div>'
      +'<div style="font-size:20px;font-weight:800;color:rgba(255,255,255,.92);font-family:\'Jost\',sans-serif;line-height:1.2">'+cnt+'</div></div>'
      +'</div>';
  }).join('');
  return '<div style="font-size:11px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:'+ca(col.label,'.70')+';font-family:\'Jost\',sans-serif;margin-bottom:13px">✦ Mi publicación</div>'
    +'<div style="background:'+col.bg+';border:1.5px solid '+ca(col.border,'.50')+';border-left:3px solid '+ca(col.border,'.80')+';border-radius:16px;padding:16px 18px;margin-bottom:20px">'
    +'<div style="font-size:17px;font-family:\'Cormorant Garamond\',serif;font-style:italic;font-weight:600;color:rgba(255,255,255,.93);line-height:1.68;margin-bottom:10px">❝ '+_escHtml(myResp.response_text||'')+' ❞</div>'
    +'<div style="font-size:13px;color:'+ca(col.label,'.65')+';font-family:\'Jost\',sans-serif">'+myResp.mood_emoji+' · '+_momentoAgo(myResp.created_at||'')+'</div>'
    +'</div>'
    +'<div style="font-size:12px;font-weight:700;color:rgba(255,255,255,.45);font-family:\'Jost\',sans-serif;margin-bottom:12px;letter-spacing:.3px">Reacciones recibidas</div>'
    +(totalRx > 0 ? rxHtml : '<div style="text-align:center;padding:20px;font-size:14px;color:rgba(255,255,255,.28);font-style:italic;font-family:Jost,sans-serif">Aún no recibiste reacciones 🌙</div>');
}

function _dqEmojiColor(emoji){
  var warm=['😊','😄','😁','😃','🙂','🌟','✨','⭐','💫','🌅','☀️','🎉','🎊','💛','🧡','🌻','🔥','😍','🤩','😀'];
  var calm=['😌','🤍','🌿','💚','🕊️','🌊','💙','🌙','⛅','☁️','🫧','🌾','🍀','🐦','😶','😑'];
  var sad=['😢','😔','😞','😟','😥','💔','🌧️','😓','😪','😮‍💨','😣','😖'];
  if(warm.indexOf(emoji)>=0) return {bg:'rgba(48,32,4,.92)',strip:'rgba(218,160,30,.38)',border:'rgba(218,160,30,.70)',glow:'rgba(218,160,30,.18)',label:'rgba(255,210,70,.95)',badge:'rgba(218,162,40,.24)'};
  if(sad.indexOf(emoji)>=0) return {bg:'rgba(28,8,8,.90)',strip:'rgba(200,80,80,.32)',border:'rgba(200,80,80,.58)',glow:'rgba(200,80,80,.14)',label:'rgba(255,160,160,.90)',badge:'rgba(200,80,80,.22)'};
  if(calm.indexOf(emoji)>=0) return {bg:'rgba(6,28,18,.92)',strip:'rgba(72,185,128,.34)',border:'rgba(72,185,128,.64)',glow:'rgba(72,185,128,.16)',label:'rgba(120,230,175,.95)',badge:'rgba(72,185,128,.24)'};
  return {bg:'rgba(16,16,48,.92)',strip:'rgba(110,128,220,.36)',border:'rgba(110,128,220,.60)',glow:'rgba(110,128,220,.15)',label:'rgba(165,182,255,.95)',badge:'rgba(110,128,220,.24)'};
}

function _dqEmojiColorLight(emoji){
  var warm=['😊','😄','😁','😃','🙂','🌟','✨','⭐','💫','🌅','☀️','🎉','🎊','💛','🧡','🌻','🔥','😍','🤩','😀'];
  var calm=['😌','🤍','🌿','💚','🕊️','🌊','💙','🌙','⛅','☁️','🫧','🌾','🍀','🐦','😶','😑'];
  var sad=['😢','😔','😞','😟','😥','💔','🌧️','😓','😪','😮‍💨','😣','😖'];
  if(warm.indexOf(emoji)>=0) return {bg:'rgba(255,248,215,.97)',strip:'rgba(218,160,30,.22)',border:'rgba(175,118,5,.48)',glow:'rgba(218,160,30,.10)',label:'rgba(85,52,0,.88)',badge:'rgba(200,150,8,.14)'};
  if(sad.indexOf(emoji)>=0) return {bg:'rgba(255,226,226,.97)',strip:'rgba(200,75,75,.18)',border:'rgba(175,50,50,.42)',glow:'rgba(200,75,75,.10)',label:'rgba(105,15,15,.85)',badge:'rgba(200,75,75,.14)'};
  if(calm.indexOf(emoji)>=0) return {bg:'rgba(212,248,228,.97)',strip:'rgba(62,175,118,.20)',border:'rgba(32,130,75,.42)',glow:'rgba(62,175,118,.10)',label:'rgba(12,68,35,.85)',badge:'rgba(62,175,118,.14)'};
  return {bg:'rgba(224,220,252,.97)',strip:'rgba(105,95,215,.18)',border:'rgba(75,65,188,.40)',glow:'rgba(105,95,215,.10)',label:'rgba(32,22,115,.82)',badge:'rgba(105,95,215,.14)'};
}

// Consistent per-user color palette — same user always gets same color
function _userColor(seed){
  var s=String(seed||'');
  var h=0;
  for(var i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0;}
  return [
    {bg:'rgba(34,10,62,.94)',strip:'rgba(155,88,228,.50)',border:'rgba(155,88,228,.85)',glow:'rgba(155,88,228,.30)',label:'rgba(212,172,255,.97)',badge:'rgba(155,88,228,.34)'},
    {bg:'rgba(5,32,18,.94)',strip:'rgba(45,180,120,.50)',border:'rgba(45,180,120,.85)',glow:'rgba(45,180,120,.30)',label:'rgba(112,238,175,.97)',badge:'rgba(45,180,120,.34)'},
    {bg:'rgba(44,22,2,.94)',strip:'rgba(222,162,36,.50)',border:'rgba(222,162,36,.85)',glow:'rgba(222,162,36,.30)',label:'rgba(255,220,75,.97)',badge:'rgba(222,162,36,.34)'},
    {bg:'rgba(6,14,50,.94)',strip:'rgba(82,132,228,.50)',border:'rgba(82,132,228,.85)',glow:'rgba(82,132,228,.30)',label:'rgba(162,195,255,.97)',badge:'rgba(82,132,228,.34)'},
    {bg:'rgba(46,6,22,.94)',strip:'rgba(215,75,135,.50)',border:'rgba(215,75,135,.85)',glow:'rgba(215,75,135,.30)',label:'rgba(255,155,205,.97)',badge:'rgba(215,75,135,.34)'},
    {bg:'rgba(46,16,2,.94)',strip:'rgba(225,110,38,.50)',border:'rgba(225,110,38,.85)',glow:'rgba(225,110,38,.30)',label:'rgba(255,180,85,.97)',badge:'rgba(225,110,38,.34)'},
  ][Math.abs(h)%6];
}
function _userColorLight(seed){
  var s=String(seed||'');
  var h=0;
  for(var i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0;}
  return [
    {bg:'rgba(235,220,255,.96)',strip:'rgba(155,88,228,.22)',border:'rgba(155,88,228,.55)',glow:'rgba(155,88,228,.16)',label:'rgba(75,28,148,.90)',badge:'rgba(155,88,228,.14)'},
    {bg:'rgba(212,248,230,.96)',strip:'rgba(45,180,120,.22)',border:'rgba(45,180,120,.55)',glow:'rgba(45,180,120,.16)',label:'rgba(10,80,45,.90)',badge:'rgba(45,180,120,.14)'},
    {bg:'rgba(255,245,210,.96)',strip:'rgba(222,162,36,.22)',border:'rgba(222,162,36,.55)',glow:'rgba(222,162,36,.16)',label:'rgba(88,55,0,.90)',badge:'rgba(222,162,36,.14)'},
    {bg:'rgba(218,228,255,.96)',strip:'rgba(82,132,228,.22)',border:'rgba(82,132,228,.55)',glow:'rgba(82,132,228,.16)',label:'rgba(22,52,148,.90)',badge:'rgba(82,132,228,.14)'},
    {bg:'rgba(255,220,238,.96)',strip:'rgba(215,75,135,.22)',border:'rgba(215,75,135,.55)',glow:'rgba(215,75,135,.16)',label:'rgba(108,18,62,.90)',badge:'rgba(215,75,135,.14)'},
    {bg:'rgba(255,235,215,.96)',strip:'rgba(225,110,38,.22)',border:'rgba(225,110,38,.55)',glow:'rgba(225,110,38,.16)',label:'rgba(108,42,4,.90)',badge:'rgba(225,110,38,.14)'},
  ][Math.abs(h)%6];
}

function _buildDqCards(list){
  var myUid = safeLS('get','velo_user_id') || '';
  var _dqHid = []; try{ _dqHid = JSON.parse(safeLS('get','velo_dq_hidden')||'[]'); }catch(e){}
  var isDark = document.body.classList.contains('r-dark');
  return list.filter(function(r){ return _dqHid.indexOf(String(r.id)) === -1; }).map(function(r){
    var isOwn = myUid && r.user_id === myUid;
    var _m = _dqReactMap[r.id] || {};
    var _totalRx = ['identifico','abrazo','entiendo'].reduce(function(s,k){ return s+((_m[k]&&_m[k].count)||0); },0);
    var actionBtn = isOwn
      ? '<button type="button" onclick="event.stopPropagation();pDeleteMyDqResponse(\''+r.id+'\')" style="background:none;border:none;color:rgba(220,60,60,.60);font-size:14px;cursor:pointer;padding:2px 4px;line-height:1;flex-shrink:0">🗑️</button>'
      : '<button type="button" onclick="event.stopPropagation();pReportDqResponse(\''+r.id+'\',\''+r.user_id+'\')">🚩</button>';
    // Per-user color palette (consistent hash per user_id)
    var col = isDark ? _userColor(r.user_id || r.user_name) : _userColorLight(r.user_id || r.user_name);
    // Avatar
    var avUrl = r.user_avatar && r.user_avatar.startsWith('http') ? r.user_avatar : '';
    var avEmoji = r.user_avatar && !r.user_avatar.startsWith('http') ? r.user_avatar : '';
    var avLetter = (r.user_name||'A')[0].toUpperCase();
    var avInner = avUrl
      ? '<img src="'+_escHtml(avUrl)+'" style="width:36px;height:36px;border-radius:50%;object-fit:cover;flex-shrink:0;border:1.5px solid '+col.border+'">'
      : '<div style="width:36px;height:36px;border-radius:50%;flex-shrink:0;background:'+col.badge+';border:1.5px solid '+col.border+';display:flex;align-items:center;justify-content:center;font-size:'+(avEmoji?'18':'13')+'px;font-weight:700;color:'+col.label+'">'+(avEmoji||avLetter)+'</div>';
    return '<div class="dq-feed-card home-mc" data-response-id="'+_escHtml(String(r.id))+'" onclick="pOpenDqResponseSheet(\''+_escHtml(String(r.id))+'\')"'
      +' style="display:flex;align-items:flex-start;gap:10px;background:'+col.bg+';border:1.5px solid '+col.border+';border-radius:14px;cursor:pointer;flex-shrink:0;width:100%;box-sizing:border-box;box-shadow:0 2px 12px '+col.glow+'">'
      +avInner
      +'<div style="flex:1;min-width:0;overflow:hidden">'
        +'<div style="display:flex;align-items:center;justify-content:space-between;gap:4px;margin-bottom:4px">'
          +'<span style="font-size:13px;font-weight:700;color:'+col.label+';font-family:Jost,sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(r.user_name||'Alguien')+'</span>'
          +'<span style="font-size:11px;color:'+col.label+';opacity:.50;font-family:Jost,sans-serif;flex-shrink:0;margin-right:4px">'+_momentoAgo(r.created_at||'')+'</span>'
        +'</div>'
        +(r.response_text
          ? '<div style="background:'+col.badge+';border:1px solid '+col.border.replace(/[\d.]+\)$/,'0.25)')+';border-radius:8px 8px 8px 2px;padding:5px 8px;margin-bottom:3px">'
            +'<div style="font-size:13px;font-family:\'Cormorant Garamond\',serif;font-style:italic;color:'+col.label+';line-height:1.40;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">'+_escHtml(r.mood_emoji||'💭')+' '+_escHtml(r.response_text)+'</div>'
            +'</div>'
            +'<div style="font-size:10px;color:'+col.label.replace(/[\d.]+\)$/,'0.38)')+';font-family:Jost,sans-serif;letter-spacing:.1px;margin-bottom:4px">💬 Toca para comentar</div>'
          : '<div style="font-size:20px;margin-bottom:5px">'+_escHtml(r.mood_emoji||'💭')+'</div>')
        +'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px">'
          +'<span class="dq-rx-meta" style="font-size:11px;font-weight:700;color:'+col.border+';font-family:Jost,sans-serif;flex-shrink:0;white-space:nowrap;display:inline-flex;align-items:center;gap:6px">'
            + (function(){
              var rxPillsHome = [{k:'identifico',e:'💚'},{k:'abrazo',e:'🫂'},{k:'entiendo',e:'💙'}]
                .filter(function(rx){ return _m[rx.k]&&_m[rx.k].count>0; })
                .map(function(rx){ return '<span style="display:inline-flex;align-items:center;gap:2px;background:'+col.badge+';border:1px solid '+col.border.replace(/[\d.]+\)$/,'0.32)')+';border-radius:100px;padding:2px 7px;font-size:11px;font-weight:700">'+rx.e+'<span style="font-size:10px;font-weight:700;color:'+col.label+';opacity:.92">'+_m[rx.k].count+'</span></span>'; })
                .join('');
              return (rxPillsHome || '') + '<span style="opacity:.78">Ver →</span>';
            })()
          + '</span>'
          + actionBtn
        +'</div>'
      +'</div>'
    +'</div>';
  }).join('');
}

async function pOpenDqResponseSheet(responseId){
  var r = (_dqAllResponses||[]).find(function(x){ return String(x.id) === String(responseId); });
  if(!r){
    // Fetch directly from Supabase when not in cache (e.g. opened from notification)
    _initSupabase();
    if(sbClient){
      try{
        var _fr = await sbClient.from('daily_responses_feed')
          .select('id,user_id,user_name,user_avatar,response_text,mood_emoji,created_at')
          .eq('id', String(responseId)).single();
        if(!_fr.error && _fr.data) r = _fr.data;
      }catch(e){}
    }
    if(!r){ pToast('⚠️','No se encontró la respuesta'); return; }
  }
  var q = _getDailyQuestion();
  var av = r.user_avatar || '';
  var isImg = av && av.startsWith('http');
  var canSeeProfile = r.user_id && r.user_id !== 'anon';
  var col = _dqEmojiColor(r.mood_emoji||'💭');
  var _stripSolid = col.strip.replace(/[\d.]+\)$/,'0.55)');
  var _stripFaint = col.strip.replace(/[\d.]+\)$/,'0.18)');
  var _labelFull  = col.label;
  var _labelDim   = col.label.replace(/[\d.]+\)$/,'0.48)');
  var avStyle = 'width:44px;height:44px;border-radius:50%;object-fit:cover;border:2.5px solid '+col.border+';flex-shrink:0;'+(canSeeProfile?'cursor:pointer':'');
  var avClick = canSeeProfile ? ' onclick="pQuickProfile('+_jsAttr(r.user_name||'Alguien')+','+_jsAttr(av)+',\'\',\'\','+_jsAttr(r.user_id)+')"' : '';
  var avHtml = isImg
    ? '<img src="'+_escHtml(av)+'" style="'+avStyle+'"'+avClick+'>'
    : '<div style="'+avStyle+';background:'+_stripFaint+';display:flex;align-items:center;justify-content:center;font-size:26px"'+avClick+'>'+(av||'🌿')+'</div>';

  // Reaction buttons — zen row layout: emoji big on top, label below, 3 in a row
  var rxDefs = [{key:'identifico',label:'Me identifico',emoji:'💚'},{key:'abrazo',label:'Te abrazo',emoji:'🫂'},{key:'entiendo',label:'Te entiendo',emoji:'💙'}];
  var _m = _dqReactMap[responseId] || {};
  var rxHtml = rxDefs.map(function(rx){
    var rd = _m[rx.key] || {count:0,mine:false};
    var rc = _rxColors[rx.key];
    var bg = rd.mine ? rc.activeBg : 'rgba(255,255,255,.08)';
    var bdr = rd.mine ? rc.border : col.border.replace(/[\d.]+\)$/,'0.22)');
    var txtCol = rd.mine ? rc.txt : _labelDim;
    var glow = rd.mine ? '0 0 14px '+rc.glow+',0 2px 6px '+rc.glow : 'none';
    var emojiScale = rd.mine ? 'transform:scale(1.12);filter:drop-shadow(0 0 6px '+rc.glow+')' : '';
    return '<button class="dq-reaction-btn" onclick="pToggleDqReaction(\''+responseId+'\',\''+rx.key+'\',this)" '
      +'data-rid="'+responseId+'" data-rtype="'+rx.key+'" data-active="'+rd.mine+'" '
      +'style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:9px 5px 8px;background:'+bg+';border:1px solid '+bdr+';border-radius:14px;cursor:pointer;transition:all .22s;box-shadow:'+glow+';font-family:Jost,sans-serif;box-sizing:border-box">'
      +'<span style="font-size:20px;line-height:1;display:block;transition:all .22s;'+emojiScale+'">'+rx.emoji+'</span>'
      +'<span class="rx-txt" style="font-size:10.5px;font-weight:700;color:'+txtCol+';text-align:center;letter-spacing:.2px;transition:color .22s;line-height:1.25">'+rx.label+'</span>'
      +(rd.count>0
        ? '<span class="rx-cnt" style="font-size:10px;font-weight:800;color:'+txtCol+';opacity:.65;min-height:12px">'+rd.count+'</span>'
        : '<span class="rx-cnt" style="display:none"></span>')
      +'</button>';
  }).join('');

  var existing = document.getElementById('dqResponseSheetOv');
  if(existing) existing.remove();
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'dqResponseSheetOv';
  ov.onclick = function(e){ if(e.target===ov) ov.remove(); };

  // Zen divider helper
  var _zenDiv = '<div style="display:flex;align-items:center;gap:10px;margin:18px 0">'
    +'<div style="flex:1;height:1px;background:linear-gradient(90deg,transparent,'+col.border.replace(/[\d.]+\)$/,'0.22)')+')">'+'</div>'
    +'<span style="font-size:13px;color:'+col.label.replace(/[\d.]+\)$/,'0.30)')+'">✦</span>'
    +'<div style="flex:1;height:1px;background:linear-gradient(270deg,transparent,'+col.border.replace(/[\d.]+\)$/,'0.22)')+')">'+'</div>'
    +'</div>';

  ov.innerHTML = '<div class="p-sheet p-sheet-dark" style="padding:0;overflow-y:auto;max-height:88vh;border-top:3px solid '+col.border+';border-radius:28px 28px 0 0;background:'+col.bg+'">'
    // Header — vibrant gradient using strip color
    +'<div style="background:linear-gradient(150deg,'+_stripSolid+' 0%,'+col.bg+' 55%);padding:18px 20px 16px;position:sticky;top:0;z-index:1;text-align:center;backdrop-filter:blur(12px)">'
    +'<div class="p-sheet-handle" style="background:'+col.border.replace(/[\d.]+\)$/,'0.50)')+';position:absolute;top:8px;left:50%;transform:translateX(-50%);margin:0"></div>'
    +'<button onclick="document.getElementById(\'dqResponseSheetOv\').remove()" style="position:absolute;top:12px;right:14px;background:rgba(255,255,255,.18);border:none;border-radius:50%;width:30px;height:30px;color:rgba(255,255,255,.85);font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;z-index:2">✕</button>'
    +'<div style="display:flex;align-items:center;justify-content:center;gap:9px;margin-bottom:10px;margin-top:6px">'
    +'<span style="font-size:36px;line-height:1;filter:drop-shadow(0 0 14px '+col.glow+')">'+r.mood_emoji+'</span>'
    +'<span style="font-size:11px;font-weight:800;letter-spacing:2.5px;text-transform:uppercase;color:'+_labelFull+';font-family:Jost,sans-serif">✨ Pregunta del día</span>'
    +'</div>'
    +'<div style="font-size:15.5px;font-family:\'Cormorant Garamond\',serif;font-style:italic;color:'+_labelFull+';line-height:1.45;max-width:320px;margin:0 auto 12px;opacity:.92">'+_escHtml(q?q.text:'')+'</div>'
    +'<div style="display:inline-flex;align-items:center;gap:8px;padding:6px 14px 6px 7px;background:'+_stripFaint+';border-radius:100px;border:1px solid '+col.border.replace(/[\d.]+\)$/,'0.35)')+'">'+avHtml
    +'<div style="text-align:left">'
    +'<div style="font-size:14px;font-weight:700;color:'+_labelFull+';font-family:Jost,sans-serif'+(canSeeProfile?';cursor:pointer':'')+'"'+avClick+'>'+_escHtml(r.user_name||'Alguien')+'</div>'
    +'<div style="font-size:11px;color:'+_labelDim+';font-family:Jost,sans-serif">'+_momentoAgo(r.created_at||new Date().toISOString())+'</div>'
    +'</div></div>'
    +'</div>'
    // Body
    +'<div style="padding:18px 18px calc(max(20px, env(safe-area-inset-bottom, 20px)) + 8px);text-align:center">'
    +(r.response_text
      ? '<div style="margin-bottom:16px;padding:18px 18px 20px;background:rgba(255,255,255,.08);border-radius:18px;border:1px solid '+col.border.replace(/[\d.]+\)$/,'0.28)')+';position:relative;overflow:hidden;box-shadow:0 2px 18px rgba(0,0,0,.18)">'
        +'<div style="position:absolute;top:0;left:0;width:3px;height:100%;background:'+col.strip.replace(/[\d.]+\)$/,'0.80)')+'"></div>'
        +'<div style="font-size:48px;font-family:\'Cormorant Garamond\',serif;color:'+col.border.replace(/[\d.]+\)$/,'0.28)')+';line-height:.60;margin-bottom:8px;user-select:none;padding-left:14px;text-align:left">❝</div>'
        +'<div style="font-size:20px;font-family:\'Cormorant Garamond\',serif;font-style:italic;font-weight:600;color:'+_labelFull+';line-height:1.55;padding:0 6px 0 16px;letter-spacing:.2px;text-align:left">'+_escHtml(r.response_text)+'</div>'
        +'</div>'
      : '')
    +_zenDiv
    +'<div style="font-size:11px;font-weight:800;letter-spacing:1.8px;text-transform:uppercase;color:'+_labelDim+';font-family:Jost,sans-serif;margin-bottom:12px">¿Cómo te resonó?</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:16px">'+rxHtml+'</div>'
    +_zenDiv
    +'<div style="text-align:left;margin-bottom:18px">'
    +'<div style="font-size:11px;font-weight:800;letter-spacing:1.8px;text-transform:uppercase;color:rgba(220,240,228,.80);font-family:Jost,sans-serif;margin-bottom:12px">💬 Hilo de comentarios</div>'
    +'<div id="dqCommentFeed" style="margin-bottom:14px;background:rgba(255,251,232,.97);border-radius:16px;padding:12px 10px;min-height:60px"><div style="text-align:center;padding:20px 8px;font-size:14px;color:rgba(80,70,40,.50);font-family:Jost,sans-serif">Cargando…</div></div>'
    +'<label for="dqCommentAnon" style="display:flex;align-items:center;gap:8px;padding:9px 12px;margin-bottom:8px;background:rgba(255,251,232,.18);border:1px solid rgba(255,220,140,.30);border-radius:12px;cursor:pointer;font-family:Jost,sans-serif">'
      +'<input type="checkbox" id="dqCommentAnon" style="width:16px;height:16px;accent-color:'+col.label+';cursor:pointer;flex-shrink:0">'
      +'<span style="font-size:12px;color:rgba(255,250,225,.92);line-height:1.35"><strong>🕊️ Comentar como anónimo/a</strong> <span style="opacity:.62">— sin marcar, mostrás tu perfil.</span></span>'
    +'</label>'
    +'<div style="display:flex;gap:8px;align-items:flex-end">'
    +'<textarea id="dqCommentInput" rows="2" placeholder="Sumar algo al hilo…" style="flex:1;background:rgba(255,252,240,.97);border:1.5px solid rgba(0,0,0,.12);border-radius:14px;color:rgba(20,25,20,.90);font-size:15px;font-family:\'Jost\',sans-serif;padding:10px 12px;resize:none;outline:none;line-height:1.4"></textarea>'
    +'<button id="dqCommentBtn" onclick="pPostDqComment(\''+responseId+'\')" style="background:'+col.strip+';border:none;border-radius:12px;color:rgba(255,255,255,.92);font-size:14px;font-weight:800;font-family:\'Jost\',sans-serif;cursor:pointer;padding:10px 14px;flex-shrink:0;height:44px;min-width:60px;box-shadow:0 2px 10px '+col.glow+'">Enviar</button>'
    +'</div>'
    +'</div>'
    +'<button onclick="document.getElementById(\'dqResponseSheetOv\').remove()" style="width:100%;padding:13px;background:'+_stripFaint+';border:1.5px solid '+col.border.replace(/[\d.]+\)$/,'0.35)')+';border-radius:100px;color:'+_labelFull+';font-size:13px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;letter-spacing:1.5px;text-transform:uppercase">· CERRAR ·</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
  // Load comments asynchronously
  _loadDqComments(responseId).then(function(comments){
    var feed = document.getElementById('dqCommentFeed');
    if(feed) feed.innerHTML = _renderMomentoComments(comments, col, true);
  });
}

async function _loadDqComments(responseId){
  _initSupabase(); if(!sbClient) return [];
  try{
    var _dqSel='id,text,user_name,user_avatar,user_id,created_at';
    var res = await sbClient.from('dq_comments_feed')
      .select(_dqSel).eq('response_id', String(responseId)).order('created_at', {ascending: true}).limit(50);
    if(res.error){
      res = await sbClient.from('dq_comments')
        .select(_dqSel).eq('response_id', String(responseId)).order('created_at', {ascending: true}).limit(50);
    }
    if(res.error) return [];
    var comments = res.data || [];
    // Filtrar comentarios de usuarios bloqueados (excepto anónimos)
    comments = comments.filter(function(c){ return c.user_name === 'Anónimo' || !_isBlocked(c.user_id); });
    // Hidratar username/avatar/nombre desde profiles para usuarios NO anónimos
    var nonAnonUids = comments
      .filter(function(c){ return c.user_id && c.user_name !== 'Anónimo'; })
      .map(function(c){ return c.user_id; });
    var uniqUids = nonAnonUids.filter(function(u,i,a){ return a.indexOf(u) === i; });
    if(uniqUids.length){
      try{
        var pr = await sbClient.from('profiles').select('id,username,nombre,avatar').in('id', uniqUids);
        if(pr && pr.data){
          var pmap = {};
          pr.data.forEach(function(p){ pmap[p.id] = p; });
          comments.forEach(function(c){
            var p = pmap[c.user_id];
            if(p){
              if(p.username) c.username = p.username;
              if(!c.user_avatar && p.avatar) c.user_avatar = p.avatar;
              if((!c.user_name || c.user_name === 'Alguien') && p.nombre) c.user_name = p.nombre;
            }
          });
        }
      }catch(e){}
    }
    return comments;
  }catch(e){ return []; }
}

async function pPostDqComment(responseId){
  var inp = document.getElementById('dqCommentInput');
  if(!inp) return;
  var text = (inp.value || '').trim();
  if(!text) return;
  var btn = document.getElementById('dqCommentBtn');
  if(btn){ btn.disabled = true; btn.textContent = '...'; }
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); if(btn){ btn.disabled = false; btn.textContent = 'Enviar'; } return; }
  var data = { response_id: String(responseId), text: text, user_hash: _momentoUserHash(), created_at: new Date().toISOString() };
  var anonChkC = document.getElementById('dqCommentAnon');
  var _cIsAnon = !!(anonChkC && anonChkC.checked);
  var pn = safeLS('get','velo_user_name'); var pav = safeLS('get','velo_user_av'); var uid = safeLS('get','velo_user_id');
  if(_cIsAnon){
    data.user_name = 'Anónimo';
    // omit avatar so renderer falls back to letter "A" o ícono anónimo
  } else {
    if(pn) data.user_name = pn;
    if(pav) data.user_avatar = pav;
  }
  if(uid) data.user_id = uid;
  var res = await sbClient.from('dq_comments').insert(data);
  if(res.error){
    if(res.error.code === '42P01' || res.error.code === 'PGRST200'){
      pToast('🛠️','La tabla de comentarios aún no está creada en la base de datos');
      if(btn){ btn.disabled = false; btn.textContent = 'Enviar'; } return;
    }
    if(res.error.code === '42703' || res.error.code === 'PGRST204' || (res.error.message && res.error.message.indexOf('user_avatar') >= 0)){
      delete data.user_name; delete data.user_avatar;
      res = await sbClient.from('dq_comments').insert(data);
      if(res.error){ pToast('⚠️','Error al comentar'); if(btn){ btn.disabled = false; btn.textContent = 'Enviar'; } return; }
    } else { pToast('⚠️','Error: '+res.error.message); if(btn){ btn.disabled = false; btn.textContent = 'Enviar'; } return; }
  }
  inp.value = '';
  pToast('💬','Comentario publicado');
  var _dqRespOwner = _dqAllResponses && _dqAllResponses.find(function(x){ return String(x.id)===String(responseId); });
  if(_dqRespOwner && _dqRespOwner.user_id){
    var _notifName = _cIsAnon ? 'Anónimo' : (safeLS('get','velo_user_name')||'Alguien');
    _createVeloNotif(_dqRespOwner.user_id,'dq_comment',_notifName+' comentó tu respuesta del día',text.slice(0,80),responseId);
  }
  var feedEl = document.getElementById('dqCommentFeed');
  if(feedEl){
    var comments = await _loadDqComments(responseId);
    feedEl.innerHTML = _renderMomentoComments(comments, null);
  }
  if(btn){ btn.disabled = false; btn.textContent = 'Enviar'; }
}

