function _createVeloNotif(recipientId,type,title,body,relatedId){
  var myUid=safeLS('get','velo_user_id');
  if(!recipientId||recipientId===myUid) return;
  _initSupabase(); if(!sbClient) return;
  var data={user_id:recipientId,type:type,title:title,body:body||null,related_id:relatedId?String(relatedId):null,is_read:false,created_at:new Date().toISOString()};
  // v1590 (SEGURIDAD): preferimos el RPC security-definer velo_create_notif, que
  // registra el remitente verificado (sender_id) y evita el spoofing por insert
  // directo. Si el RPC todavía no está desplegado (rollout), caemos al insert.
  function _fallbackInsert(){ try{ sbClient.from('velo_notifications').insert(data).then(function(){}).catch(function(){}); }catch(_){} }
  try{
    sbClient.rpc('velo_create_notif',{
      p_recipient:recipientId, p_type:type, p_title:title,
      p_body:body||null, p_related:relatedId?String(relatedId):null
    }).then(function(r){ if(r && r.error) _fallbackInsert(); }).catch(_fallbackInsert);
  }catch(_){ _fallbackInsert(); }
}

async function _loadVeloNotifs(){
  _initSupabase(); if(!sbClient) return [];
  var uid=safeLS('get','velo_user_id'); if(!uid) return [];
  try{
    var res=await sbClient.from('velo_notifications')
      .select('id,type,title,body,related_id,is_read,created_at')
      .eq('user_id',uid)
      .order('created_at',{ascending:false})
      .limit(40);
    if(res.error) return [];
    return res.data||[];
  }catch(e){ return []; }
}

// v1375: la campana de Actividad sumaba los DMs no leídos al contador
// (_updateVeloNotifBadge incluye _dmUnreadTotal()) pero la hoja solo
// listaba velo_notifications (comentarios/reacciones) — el badge decía
// "2" y adentro no había nada. Ahora los DMs no leídos aparecen como
// items propios arriba de la lista.
async function _loadDmActivityItems(){
  var m = {}; try{ m = JSON.parse(safeLS('get','velo_dm_unread')||'{}'); }catch(e){}
  // v1395: respetar la marca "leído hasta" — si ya abriste el chat de ese peer
  // después de que llegó su último mensaje, NO mostrarlo como no-leído en la
  // campana (aunque el contador velo_dm_unread haya quedado desincronizado).
  var readUntil = {}; try{ readUntil = JSON.parse(safeLS('get','velo_dm_read_until')||'{}'); }catch(_){}
  var cache0 = _dmCacheGet();
  var ids = Object.keys(m).filter(function(id){
    if((Number(m[id])||0) <= 0) return false;
    var lastTs = (cache0[id] && cache0[id].ts) || 0;
    if(readUntil[id] && lastTs && lastTs <= readUntil[id] + 2000) return false;
    return true;
  });
  if(!ids.length) return [];
  _initSupabase(); if(!sbClient) return [];
  var cache = _dmCacheGet();
  var profs = {};
  try{
    var r = await sbClient.from('profiles').select('id,nombre,avatar').in('id', ids);
    (r.data||[]).forEach(function(p){ profs[p.id] = p; });
  }catch(e){}
  return ids.map(function(id){
    var p = profs[id] || {};
    var c = cache[id] || {};
    return {
      id: id,
      name: p.nombre || 'Usuario',
      av: p.avatar || '🧑',
      text: c.text || 'Nuevo mensaje',
      ts: c.ts || Date.now()
    };
  }).sort(function(a,b){ return b.ts - a.ts; });
}
function _renderDmActivityItems(items){
  if(!items || !items.length) return '';
  return items.map(function(it){
    return '<div onclick="_navToDmActivity('+_jsAttr(it.id)+','+_jsAttr(it.name)+','+_jsAttr(it.av)+')" style="display:flex;gap:10px;align-items:flex-start;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.06);cursor:pointer;border-radius:12px;background:rgba(116,198,157,.05)">'
      +'<span style="width:8px;height:8px;border-radius:50%;background:rgba(116,198,157,.90);flex-shrink:0;margin-top:5px;box-shadow:0 0 6px rgba(116,198,157,.50)"></span>'
      +'<span style="font-size:22px;flex-shrink:0;line-height:1.25">'+_avInline(it.av,22)+'</span>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:15px;font-weight:700;color:rgba(255,255,255,.90);font-family:Jost,sans-serif;line-height:1.35;margin-bottom:3px">'+_escHtml(it.name)+' te escribió</div>'
      +'<div style="font-size:14px;color:rgba(255,255,255,.40);font-family:\'Cormorant Garamond\',serif;font-style:italic;line-height:1.45;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+_escHtml('"'+it.text+'"')+'</div>'
      +'<div style="font-size:12px;color:rgba(255,255,255,.25);font-family:Jost,sans-serif;margin-top:4px">'+_momentoAgo(it.ts)+'<span style="margin-left:8px;color:rgba(116,198,157,.55);font-size:11px">Ver →</span></div>'
      +'</div>'
      +'</div>';
  }).join('');
}
function _navToDmActivity(id, name, av){
  var shOv = document.getElementById('veloNotifsSheetOv');
  if(shOv) shOv.remove();
  pOpenDM(id, name, av);
}

async function _markVeloNotifsRead(){
  _initSupabase(); if(!sbClient) return;
  var uid=safeLS('get','velo_user_id'); if(!uid) return;
  try{ await sbClient.from('velo_notifications').update({is_read:true}).eq('user_id',uid).eq('is_read',false); }catch(e){}
}

// Suma de DMs no leídos (excluye peer con el que estoy chateando ahora)
function _dmUnreadTotal(){
  var m = {}; try{ m = JSON.parse(safeLS('get','velo_dm_unread')||'{}'); }catch(e){}
  var currentPeer = (_dmPeer && _dmPeer.id) || null;
  var curPage = document.querySelector('.p-page.active');
  var isInDm = curPage && curPage.id === 'pg-dm-chat' && currentPeer;
  return Object.keys(m).reduce(function(acc, k){
    if(isInDm && k === currentPeer) return acc; // no cuento el chat en el que estoy
    return acc + (Number(m[k])||0);
  }, 0);
}
function _updateVeloNotifBadge(count){
  var b=document.getElementById('veloNotifBadge');
  var dmSum = _dmUnreadTotal();
  var total = (Number(count)||0) + dmSum;
  if(b){
    b.textContent=total>9?'9+':String(total);
    b.style.display=total>0?'inline-block':'none';
  }
  // Badge en el ⭐ del bottom nav (Contactos Favoritos)
  var cb = document.getElementById('contactsDMBadge');
  if(cb){
    cb.textContent = dmSum > 9 ? '9+' : String(dmSum);
    cb.style.display = dmSum > 0 ? 'inline-block' : 'none';
  }
}
// Recalcula badges leyendo el count actual de velo_notifications (o 0 si no está cacheado)
function _refreshChatBadges(){
  var cached = parseInt(safeLS('get','velo_notif_unread_cached')||'0', 10);
  _updateVeloNotifBadge(isNaN(cached)?0:cached);
}

async function _checkVeloNotifs(){
  _initSupabase(); if(!sbClient) return;
  var uid=safeLS('get','velo_user_id'); if(!uid) return;
  try{
    var res=await sbClient.from('velo_notifications')
      .select('id',{count:'exact',head:true})
      .eq('user_id',uid)
      .eq('is_read',false);
    if(res.error) return;
    try{ safeLS('set','velo_notif_unread_cached', String(res.count||0)); }catch(_){}
    _updateVeloNotifBadge(res.count||0);
  }catch(e){}
}

function _navToNotif(type, relatedId){
  var shOv = document.getElementById('veloNotifsSheetOv');
  if(shOv) shOv.remove();
  // Los tipos de buddy no llevan relatedId (van al modal, no a un post puntual)
  if(type === 'buddy_request' || type === 'buddy_matched'){
    pOpenBuddyModal();
    return;
  }
  if(!relatedId) return;
  if(type === 'dq_comment' || type === 'dq_reaction'){
    pOpenDqResponseSheet(relatedId);
  } else if(type === 'momento_comment'){
    // Navigate home so cache is populated, then open the sheet
    pGoTo('home');
    setTimeout(function(){ pOpenMomentoSheet(relatedId); }, 900);
  } else if(type === 'vibe_comment' || type === 'vibe_reaction' || type === 'vibe_comment_like'){
    _openVibeFromNotif(relatedId);
  } else if(type === 'bt_comment' || type === 'bt_reaction'){
    // Abrir el post de Bitácora — navegar primero para que cargue la página
    pGoTo('bitacora');
    setTimeout(function(){ try{ if(typeof _btOpenDetail === 'function') _btOpenDetail(relatedId); }catch(_){} }, 700);
  }
}
// Abre el momento correspondiente desde una notificación de Actividad —
// distingue si es instantáneo o de un grupo. v1375
async function _openVibeFromNotif(vibeId){
  _initSupabase(); if(!sbClient) return;
  try{
    var r = await sbClient.from('vibes').select('id,group_id').eq('id', vibeId).maybeSingle();
    if(!r || !r.data){ pToast('🌱','Ese momento ya no está disponible'); return; }
    if(r.data.group_id) pPlayVibeGroup(r.data.group_id);
    else pPlayInstant(vibeId);
  }catch(e){ console.warn('[open-vibe-from-notif]', e); }
}

function _veloNotifsEmptyState(){
  return '<div style="text-align:center;padding:40px 16px">'
    +'<div style="font-size:44px;margin-bottom:14px;opacity:.40">💬</div>'
    +'<div style="font-size:17px;font-weight:700;color:rgba(255,255,255,.45);font-family:Jost,sans-serif">Todo al día</div>'
    +'<div style="font-size:14px;color:rgba(255,255,255,.25);margin-top:8px;line-height:1.55;font-family:Jost,sans-serif">Cuando alguien te escriba, comente o reaccione a tus publicaciones aparecerá acá</div>'
    +'</div>';
}
function _renderVeloNotifs(notifs){
  var typeIcon={dq_comment:'💬',dq_reaction:'💚',momento_comment:'💬',reaction:'💚',vibe_comment:'💬',vibe_reaction:'🌊',vibe_comment_like:'❤️',buddy_request:'🌱',buddy_matched:'🤝',bt_comment:'📓',bt_reaction:'💚'};
  var typeNavigable={dq_comment:true, dq_reaction:true, momento_comment:true, vibe_comment:true, vibe_reaction:true, vibe_comment_like:true, buddy_request:true, buddy_matched:true, bt_comment:true, bt_reaction:true};
  if(!notifs||!notifs.length) return '';
  return notifs.map(function(n){
    var icon=typeIcon[n.type]||'🔔';
    var unread=!n.is_read;
    var _buddyType = (n.type === 'buddy_request' || n.type === 'buddy_matched');
    var canNav=typeNavigable[n.type]&&(n.related_id||_buddyType);
    var dot=unread
      ?'<span style="width:8px;height:8px;border-radius:50%;background:rgba(116,198,157,.90);flex-shrink:0;margin-top:5px;box-shadow:0 0 6px rgba(116,198,157,.50)"></span>'
      :'<span style="width:8px;flex-shrink:0"></span>';
    var clickAttr=canNav
      ?' onclick="_navToNotif(\''+_escHtml(n.type)+'\',\''+_escHtml(String(n.related_id||''))+'\')" style="cursor:pointer"'
      :'';
    var navBg = canNav ? (unread ? ';background:rgba(116,198,157,.05)' : '') : '';
    return '<div'+clickAttr+' style="display:flex;gap:10px;align-items:flex-start;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.06)'+(canNav?';border-radius:12px;transition:background .18s'+navBg:'')+'">'+''
      +dot
      +'<span style="font-size:22px;flex-shrink:0;line-height:1.25">'+icon+'</span>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:15px;font-weight:'+(unread?'700':'500')+';color:rgba(255,255,255,'+(unread?'.90':'.50')+');font-family:Jost,sans-serif;line-height:1.35;margin-bottom:3px">'+_escHtml(n.title||'')+'</div>'
      +(n.body?'<div style="font-size:14px;color:rgba(255,255,255,.40);font-family:\'Cormorant Garamond\',serif;font-style:italic;line-height:1.45;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+_escHtml('"'+n.body+'"')+'</div>':'')
      +'<div style="font-size:12px;color:rgba(255,255,255,.25);font-family:Jost,sans-serif;margin-top:4px">'+_momentoAgo(n.created_at||'')+(canNav?'<span style="margin-left:8px;color:rgba(116,198,157,.55);font-size:11px">Ver →</span>':'')+'</div>'
      +'</div>'
      +'</div>';
  }).join('');
}

async function pOpenVeloNotifsSheet(){
  var existing=document.getElementById('veloNotifsSheetOv');
  if(existing) existing.remove();
  var ov=document.createElement('div');
  ov.className='p-modal-ov show';
  ov.id='veloNotifsSheetOv';
  ov.onclick=function(e){if(e.target===ov)ov.remove();};
  ov.innerHTML='<div class="p-sheet p-sheet-dark" style="padding:0;overflow-y:auto;max-height:86vh;border-top:2px solid rgba(116,198,157,.40);border-radius:28px 28px 0 0">'
    +'<div style="padding:16px 20px 12px;border-bottom:1px solid rgba(255,255,255,.07);display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:1;background:rgba(6,16,10,.97);backdrop-filter:blur(12px)">'
    +'<div class="p-sheet-handle" style="position:absolute;top:8px;left:50%;transform:translateX(-50%);margin:0;background:rgba(116,198,157,.30)"></div>'
    +'<div style="font-size:15px;font-weight:800;color:rgba(200,240,218,.92);font-family:Jost,sans-serif;letter-spacing:.2px;margin-top:6px">🔔 Actividad</div>'
    +'<button onclick="document.getElementById(\'veloNotifsSheetOv\').remove()" style="background:none;border:none;color:rgba(255,255,255,.35);font-size:20px;cursor:pointer;padding:4px;line-height:1;margin-top:6px">×</button>'
    +'</div>'
    +'<div id="veloNotifsBody" style="padding:0 18px 4px"><div style="text-align:center;padding:32px 8px;font-size:14px;color:rgba(255,255,255,.28);font-family:Jost,sans-serif">Cargando…</div></div>'
    +'<div style="padding:12px 18px calc(max(16px,env(safe-area-inset-bottom,16px)) + 4px);border-top:1px solid rgba(255,255,255,.06)">'
    +'<button onclick="pGoTo(\'inbox\');document.getElementById(\'veloNotifsSheetOv\').remove()" style="width:100%;padding:12px;background:rgba(116,198,157,.12);border:1.5px solid rgba(116,198,157,.32);border-radius:100px;color:rgba(160,235,195,.85);font-size:14px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;letter-spacing:.6px">📥 Ver Buzón Velo →</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
  var _dmItems=[], notifs=[];
  try{ _dmItems = await _loadDmActivityItems(); }catch(_){}
  try{ notifs = await _loadVeloNotifs(); }catch(_){}
  var body=document.getElementById('veloNotifsBody');
  var combinedHtml = _renderDmActivityItems(_dmItems) + _renderVeloNotifs(notifs);
  if(body) body.innerHTML = combinedHtml || _veloNotifsEmptyState();
  _markVeloNotifsRead().then(function(){ _updateVeloNotifBadge(0); });
}

