async function pSubmitDailyResponse(){
  if(!_dailySelectedEmoji){ pToast('✨','Elegí cómo te sentís'); return; }
  var txEl  = document.getElementById('dailyResponseText');
  var text  = txEl ? txEl.value.trim().slice(0,120) : '';
  if(!text){ pToast('✏️','Escribí algo sobre cómo te sentís con esta pregunta'); if(txEl) txEl.focus(); return; }

  // ── Feedback inmediato: bloquear botón + mostrar 'Publicando…' antes de los awaits ──
  var submitBtn = document.querySelector('#dailyResponseOv button[onclick*="pSubmitDailyResponse"]');
  var origBtnHtml = null;
  if(submitBtn && !submitBtn.disabled){
    origBtnHtml = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.style.opacity = '.78';
    submitBtn.style.cursor = 'wait';
    submitBtn.innerHTML = '<span style="display:inline-block;width:14px;height:14px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:dqSpin .8s linear infinite;vertical-align:middle;margin-right:8px"></span>Publicando…';
    if(!document.getElementById('_dqSpinKf')){
      var _kf = document.createElement('style'); _kf.id='_dqSpinKf';
      _kf.textContent = '@keyframes dqSpin{to{transform:rotate(360deg)}}';
      document.head.appendChild(_kf);
    }
  }

  function _restoreBtn(){
    if(submitBtn && origBtnHtml !== null){
      submitBtn.disabled = false;
      submitBtn.style.opacity = '';
      submitBtn.style.cursor = '';
      submitBtn.innerHTML = origBtnHtml;
    }
  }

  var q     = _getDailyQuestion();
  var dateKey = _dateKey();
  var anonChk = document.getElementById('dqAnonChk');
  var isAnon = !!(anonChk && anonChk.checked);
  // Always use auth.getUser() so the stored user_id matches what RLS checks (auth.uid())
  var uid = safeLS('get','velo_user_id');
  var name = isAnon ? 'Anónimo' : (safeLS('get','velo_user_name') || '');
  var av   = isAnon ? '' : (safeLS('get','velo_user_av') || '');
  if(sbClient){
    try{
      var {data:_authSub} = await sbClient.auth.getUser();
      if(_authSub && _authSub.user) uid = _authSub.user.id;
    }catch(e){}
    // Si no es anónimo y el nombre local está vacío o quedó como "Anónimo" de un envío
    // previo, traer el nombre real desde profiles para no terminar publicando como Anónimo
    if(!isAnon && (!name || name === 'Anónimo') && uid){
      try{
        var _pr = await sbClient.from('profiles').select('nombre,avatar').eq('id', uid).maybeSingle();
        if(_pr && _pr.data){
          if(_pr.data.nombre) { name = _pr.data.nombre; safeLS('set','velo_user_name', _pr.data.nombre); }
          if(!av && _pr.data.avatar) av = _pr.data.avatar;
        }
      }catch(e){}
    }
  }
  if(!name) name = 'Alguien';
  var avSafe = (av && !av.startsWith('data:')) ? av : '';
  if(!uid){ _restoreBtn(); return; }
  safeLS('set','velo_daily_resp_'+dateKey, JSON.stringify({emoji:_dailySelectedEmoji,text:text,uid:uid,anon:isAnon}));
  if(sbClient){
    try{
      await sbClient.from('daily_responses').upsert({
        user_id:uid, question_date:dateKey, question_id:q.id,
        mood_emoji:_dailySelectedEmoji, response_text:text,
        user_name:name, user_avatar:avSafe
      },{onConflict:'user_id,question_date'});
    }catch(e){ console.warn('[dailyQ save]',e); }
  }
  closeModal('dailyResponseOv');
  _restoreBtn();
  pToast('💚','¡Gracias por compartir!');
  try{ _fetchDqStreak(true); }catch(_){} // v1485: actualizar racha + toast 🔥
  var lockedEl = document.getElementById('homeDailyQLocked');
  var openEl   = document.getElementById('homeDailyQOpen');
  if(lockedEl) lockedEl.style.display = 'none';
  if(openEl)   openEl.style.display   = 'block';
  var openQEl = document.getElementById('homeDailyQOpenText');
  if(openQEl) openQEl.textContent = q.text;
  var myBadge = document.getElementById('homeDailyQMyResp');
  if(myBadge) myBadge.textContent = 'Tu respuesta: '+_dailySelectedEmoji+(text?' · '+text.slice(0,35)+(text.length>35?'…':''):'');
  _fetchDailyFeed(q.id);
}

function pOpenMyDqResponseFromHome(){
  var uid = safeLS('get','velo_user_id');
  if(!uid || !_dqAllResponses) return;
  var myResp = _dqAllResponses.find(function(x){ return x.user_id === uid; });
  if(!myResp){ pToast('💭','Aún no respondiste hoy'); return; }
  pOpenDqResponseSheet(String(myResp.id));
}

// ── COMMUNITY PULSE ────────────────────────────────────────────
async function _loadCommunityPulse(){
  var today = _dateKey();
  var countEl   = document.getElementById('homeDailyQCount');
  var subEl     = document.getElementById('homeDailyQPulseSub');
  var emEl      = document.getElementById('homeDailyQPulseEmoji');
  var barEl     = document.getElementById('homeDailyQPulseBar');
  var openCountEl = document.getElementById('homeDailyQOpenCount');
  var openEmEl    = document.getElementById('homeDailyQOpenPulseEmoji');
  var openBarEl   = document.getElementById('homeDailyQOpenPulseBar');
  if(!sbClient){
    if(countEl) countEl.textContent = 'Cargando comunidad...';
    return;
  }
  try{
    // v1594: leer la vista enmascarada (la tabla cruda quedó owner-only por RLS;
    // si leyéramos la cruda, el conteo comunitario mostraría solo la propia fila).
    var res = await sbClient.from('daily_responses_feed').select('mood_emoji').eq('question_date',today);
    var rows = res.data || [];
    var total = rows.length;
    var counts = {};
    rows.forEach(function(r){ counts[r.mood_emoji]=(counts[r.mood_emoji]||0)+1; });
    var sorted = Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];});
    var topEmoji = sorted[0] || '🌿';
    var topCount = counts[topEmoji] || 0;
    var isTopUnique = sorted.length <= 1 || counts[sorted[1]] < topCount;
    var _labels = {'😊':'bien','😄':'genial','😌':'en paz','🥺':'sensibles','😔':'tristes','😰':'ansiosos','😤':'frustrados','💪':'con fuerza'};
    var topStr = isTopUnique ? topEmoji : sorted.slice(0,2).join(' ');
    if(emEl)    emEl.textContent = topStr;
    if(openEmEl) openEmEl.textContent = topStr;
    var countTxt, subTxt;
    if(total === 0){
      countTxt = 'Sé el primero en responder hoy ✨';
      subTxt   = 'La comunidad está esperando';
    } else {
      var pct = Math.round((topCount/total)*100);
      countTxt = total+(total===1?' persona respondió hoy':' personas respondieron hoy');
      subTxt   = isTopUnique && pct > 50
        ? 'El '+pct+'% se siente '+(_labels[topEmoji]||'bien')+' · '+topEmoji
        : '¡Hoy hay de todo! '+sorted.slice(0,3).join(' ');
    }
    if(countEl)     countEl.textContent = countTxt;
    if(openCountEl) openCountEl.textContent = countTxt;
    if(subEl)       subEl.textContent = subTxt;
    var barHTML = sorted.slice(0,4).map(function(e){
      var h = total > 0 ? Math.max(4, Math.round((counts[e]/total)*28)) : 4;
      return '<div style="display:flex;flex-direction:column;align-items:center;gap:2px">'
        +'<div style="width:6px;border-radius:3px;background:rgba(200,158,56,.55);height:'+h+'px;transition:height .4s"></div>'
        +'<span style="font-size:10px">'+e+'</span>'
        +'</div>';
    }).join('');
    if(barEl)    barEl.innerHTML = barHTML;
    if(openBarEl) openBarEl.innerHTML = barHTML;
  }catch(e){}
}

function _closePulseDetail(){
  var ov = document.getElementById('pulseDetailOv');
  if(ov) ov.style.display = 'none';
}

async function _showPulseDetail(){
  var ov = document.getElementById('pulseDetailOv');
  var cont = document.getElementById('pulseDetailContent');
  if(!ov || !cont) return;
  ov.style.display = 'flex';
  cont.innerHTML = '<div style="text-align:center;padding:24px;color:rgba(180,230,210,.60);font-family:Jost,sans-serif;font-size:15px">Cargando…</div>';
  if(!sbClient){
    cont.innerHTML = '<div style="text-align:center;padding:24px;color:rgba(180,230,210,.60);font-family:Jost,sans-serif;font-size:15px">Sin conexión</div>';
    return;
  }
  try{
    var today = _dateKey();
    // v1594: vista enmascarada (ver nota en _loadCommunityPulse)
    var res = await sbClient.from('daily_responses_feed').select('mood_emoji').eq('question_date', today);
    var rows = res.data || [];
    var total = rows.length;
    var counts = {};
    rows.forEach(function(r){ if(r.mood_emoji) counts[r.mood_emoji]=(counts[r.mood_emoji]||0)+1; });
    var sorted = Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];});
    var _lbl = {'😊':'Bien','😄':'Genial','😌':'En paz','🥺':'Sensible','😔':'Triste','😰':'Ansioso/a','😤':'Frustrado/a','💪':'Con fuerza'};
    var maxCount = sorted.length ? counts[sorted[0]] : 0;
    var isUniqueDominant = sorted.length === 1 || (sorted.length > 1 && counts[sorted[1]] < maxCount);
    if(total === 0){
      cont.innerHTML = '<div style="text-align:center;padding:24px"><div style="font-size:36px;margin-bottom:10px">🌿</div>'
        +'<div style="font-size:15px;color:rgba(180,230,210,.70);font-family:Jost,sans-serif">Nadie respondió todavía.<br>¡Sé el primero!</div></div>';
      return;
    }
    var html = '<div style="text-align:center;font-size:15px;font-weight:600;color:rgba(255,255,255,.75);font-family:Jost,sans-serif;margin-bottom:20px">'
      +total+(total===1?' persona respondió hoy':' personas respondieron hoy')
      +'</div>';
    sorted.forEach(function(emoji){
      var cnt = counts[emoji];
      var pct = Math.round((cnt/total)*100);
      var isDom = isUniqueDominant && emoji === sorted[0];
      var barColor = isDom ? 'rgba(116,198,157,.80)' : 'rgba(116,198,157,.30)';
      var nameColor = isDom ? 'rgba(200,255,230,.95)' : 'rgba(255,255,255,.78)';
      html += '<div style="display:flex;align-items:center;gap:14px;margin-bottom:16px">'
        +'<div style="font-size:32px;width:40px;text-align:center;flex-shrink:0">'+emoji+'</div>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">'
        +'<span style="font-size:15px;font-weight:'+(isDom?'800':'600')+';color:'+nameColor+';font-family:Jost,sans-serif">'+(_lbl[emoji]||emoji)+(isDom?' ✦':'')+'</span>'
        +'<span style="font-size:13px;color:rgba(180,230,210,.60);font-family:Jost,sans-serif">'+cnt+(cnt===1?' persona':' personas')+' · '+pct+'%</span>'
        +'</div>'
        +'<div style="height:6px;background:rgba(255,255,255,.08);border-radius:4px;overflow:hidden">'
        +'<div style="height:6px;background:'+barColor+';border-radius:4px;width:'+pct+'%;transition:width .4s"></div>'
        +'</div>'
        +'</div>'
        +'</div>';
    });
    cont.innerHTML = html;
  }catch(e){
    cont.innerHTML = '<div style="text-align:center;padding:24px;color:rgba(180,230,210,.60);font-family:Jost,sans-serif;font-size:15px">No se pudo cargar</div>';
  }
}

// ── GUARDIAN ACTIVITY CHIP ─────────────────────────────────────
async function _loadGuardianActivity(){
  var el = document.getElementById('homeGuardianChip');
  if(!el) return;
  el.style.display = 'block'; // always visible
  var inner = el.querySelector('[data-guardian-inner]');
  if(!inner){ inner = el.querySelector('div'); }
  var txtEl = document.getElementById('homeGuardianChipTxt');
  var dotEl = el.querySelector('[data-guardian-dot]');
  if(!sbClient){
    if(txtEl) txtEl.textContent = '🛡️ Guardianes — tu red de apoyo';
    return;
  }
  try{
    var cutoff = new Date(Date.now() - 10*60*1000).toISOString();
    var res = await sbClient.from('guardian_presence')
      .select('user_id',{count:'exact',head:true})
      .eq('is_guardian', true)
      .eq('status','disponible')
      .gte('last_seen', cutoff);
    var n = res.count || 0;
    if(n < 1){
      // No active guardians — show a softer CTA
      if(inner){
        inner.style.background = 'rgba(116,198,157,.05)';
        inner.style.borderColor = 'rgba(116,198,157,.14)';
      }
      if(dotEl){ dotEl.style.background='rgba(116,198,157,.3)'; dotEl.style.boxShadow='none'; dotEl.style.animation='none'; }
      if(txtEl){ txtEl.style.color='rgba(116,198,157,.55)'; txtEl.textContent='🛡️ Sin guardianes activos ahora — ¿te animas?'; }
    } else {
      if(inner){
        inner.style.background = 'linear-gradient(135deg,rgba(116,198,157,.16),rgba(74,160,110,.10))';
        inner.style.borderColor = 'rgba(116,198,157,.35)';
      }
      if(dotEl){ dotEl.style.background='rgba(116,198,157,.9)'; dotEl.style.boxShadow='0 0 0 3px rgba(116,198,157,.22)'; dotEl.style.animation='guardianPulse 2s ease-in-out infinite'; }
      if(txtEl){ txtEl.style.color='rgba(116,198,157,.9)'; txtEl.textContent='🛡️ '+n+(n===1?' guardián disponible ahora':' guardianes disponibles ahora'); }
    }
  }catch(e){
    if(txtEl) txtEl.textContent='🛡️ Guardianes — tu red de apoyo';
  }
}

