var _shareCardAIPhrase = '';
function _closeShareCard(){
  var ov = document.getElementById('shareCardOv');
  if(ov) ov.style.display = 'none';
}

async function pOpenShareCard(){
  var ov = document.getElementById('shareCardOv');
  if(ov){ ov.style.display = 'flex'; }
  // Sync this week's moods from Supabase if localStorage is empty (e.g. after clearing cache)
  var _hasMoods = false;
  for(var _mi=0;_mi<7;_mi++){
    var _md=new Date(); _md.setDate(_md.getDate()-_mi);
    if(safeLS('get','velo_mood_'+_md.toISOString().slice(0,10))){ _hasMoods=true; break; }
  }
  if(!_hasMoods){
    _initSupabase();
    var _uid = safeLS('get','velo_user_id');
    if(sbClient && _uid){
      try{
        var _now=new Date(), _months={};
        for(var _si=0;_si<7;_si++){
          var _sd=new Date(_now.getFullYear(),_now.getMonth(),_now.getDate()-_si);
          var _mk=_sd.getFullYear()+'-'+String(_sd.getMonth()+1).padStart(2,'0');
          if(!_months[_mk]) _months[_mk]={year:_sd.getFullYear(),month:_sd.getMonth()+1};
        }
        await Promise.all(Object.values(_months).map(async function(m){
          var sb=await sbLoadAllMoods(m.year,m.month);
          if(sb) sb.forEach(function(e){
            if(!safeLS('get','velo_mood_'+e.date_key)){
              safeLS('set','velo_mood_'+e.date_key, JSON.stringify({emoji:e.emoji,label:e.label||'',note:e.note||'',ts:0}));
            }
          });
        }));
        // Also restore lema if missing
        if(!safeLS('get','velo_user_motto')){
          try{
            var ok2 = await _ensureSbSession();
            if(ok2){
              var {data:ud2} = await sbClient.auth.getUser();
              if(ud2 && ud2.user){
                var pr = await sbClient.from('profiles').select('motto,nombre').eq('id',ud2.user.id).limit(1);
                if(pr.data && pr.data[0]){
                  if(pr.data[0].motto) safeLS('set','velo_user_motto', pr.data[0].motto);
                  if(pr.data[0].nombre && !safeLS('get','velo_user_name')) safeLS('set','velo_user_name', pr.data[0].nombre);
                }
              }
            }
          }catch(e2){}
        }
      }catch(e){}
    }
  }
  // Generate AI phrase from this week's mood balance
  _shareCardAIPhrase = '';
  try{
    var _mc={};
    for(var _mi3=0;_mi3<7;_mi3++){
      var _md3=new Date(); _md3.setDate(_md3.getDate()-_mi3);
      var _raw3=safeLS('get','velo_mood_'+_md3.toISOString().slice(0,10));
      if(_raw3){ try{ var _obj3=JSON.parse(_raw3); var _e3=_obj3.emoji||_obj3||''; if(_e3) _mc[_e3]=(_mc[_e3]||0)+1; }catch(e3){} }
    }
    var _moodLbl2={'😄':'Excelente','😊':'Bien','😐':'Regular','😔':'Melancólico/a','😰':'Ansioso/a','😤':'Frustrado/a','😌':'En paz','🥺':'Sensible','💪':'Con fuerza','😢':'Angustiado/a','😞':'Desanimado/a','🤩':'Emocionado/a','🙂':'Tranquilo/a','😃':'Con energía','😍':'Enamorado/a','🥰':'Agradecido/a','💔':'Desamorado/a','😬':'Nervioso/a','😨':'Con miedo','😡':'Con bronca','😴':'Agotado/a','🤒':'Enfermo/a','🤔':'Confundido/a'};
    var _sortedE2=Object.keys(_mc).sort(function(a,b){return _mc[b]-_mc[a];});
    var _domL=_sortedE2.length>0?(_moodLbl2[_sortedE2[0]]||'variado'):'sin registros';
    var _dRec=_sortedE2.reduce(function(s,k){return s+_mc[k];},0);
    var _mSum=_sortedE2.map(function(e){return (_moodLbl2[e]||e)+' x'+_mc[e];}).join(', ');
    if(_dRec>0){
      var _aiP='Genera UNA frase inspiradora muy breve (máximo 10 palabras) en español neutro (usa "tú", nunca "vos" ni "Che") '
        +'para alguien que esta semana tuvo: '+_mSum+'. Estado predominante: '+_domL+'. '
        +'Días registrados: '+_dRec+'/7. Que sea cálida, directa y poética. Sin vocativos ni saludos. '
        +'Solo devuelve la frase, sin comillas ni explicaciones.';
      var _aiResp=await _geminiCall(_aiP,{temperature:0.92,maxOutputTokens:50});
      if(_aiResp) _shareCardAIPhrase=_aiResp.replace(/^["'""„]|["'""„]$/g,'').trim();
    }
  }catch(e){}
  _drawShareCard();
}

function _drawShareCard(){
  var canvas = document.getElementById('shareCanvas');
  if(!canvas) return;
  var _logoUrls = [
    'assets/logo.png',
    'https://yuravtnjvvztsxdtggod.supabase.co/storage/v1/object/public/velo-assets/IMG_2624.png'
  ];
  (function _nextLogo(i){
    if(i >= _logoUrls.length){ _renderShareCard(canvas, null); return; }
    var img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload  = function(){ _renderShareCard(canvas, img); };
    img.onerror = function(){ _nextLogo(i+1); };
    img.src = _logoUrls[i];
  })(0);
}

function _renderShareCard(canvas, logoImg){
  var ctx = canvas.getContext('2d');
  var W = 1080, H = 1080;
  ctx.clearRect(0,0,W,H);

  // ── Background ─────────────────────────────────────────────────
  var bg = ctx.createLinearGradient(0,0,W,H);
  bg.addColorStop(0,'#091c0e');
  bg.addColorStop(0.45,'#071409');
  bg.addColorStop(1,'#030c05');
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.roundRect(0,0,W,H,48);
  ctx.fill();

  // Glows
  var g1 = ctx.createRadialGradient(W*.15,H*.1,0,W*.15,H*.1,480);
  g1.addColorStop(0,'rgba(116,198,157,.09)'); g1.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g1; ctx.fillRect(0,0,W,H);
  var g2 = ctx.createRadialGradient(W*.85,H*.85,0,W*.85,H*.85,400);
  g2.addColorStop(0,'rgba(200,158,56,.07)'); g2.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g2; ctx.fillRect(0,0,W,H);

  // Decorative dots (constellation feel)
  var dots = [[120,200],[W-130,160],[80,H-180],[W-100,H-220],[W/2+180,320],[W/2-200,780],
              [W*.3,H*.55],[W*.72,H*.42],[W*.18,H*.38],[W*.88,H*.65],[W*.5,H*.82]];
  dots.forEach(function(p,i){
    var sz = i%4===0?5:i%3===0?3:2;
    ctx.fillStyle = i%3===0 ? 'rgba(116,198,157,.20)' : i%2===0 ? 'rgba(200,158,56,.14)' : 'rgba(255,255,255,.08)';
    ctx.beginPath(); ctx.arc(p[0],p[1],sz,0,Math.PI*2); ctx.fill();
  });
  // Subtle corner accents
  [[0,0],[W,0],[0,H],[W,H]].forEach(function(p,i){
    var cg=ctx.createRadialGradient(p[0],p[1],0,p[0],p[1],220);
    cg.addColorStop(0,i%2===0?'rgba(116,198,157,.06)':'rgba(200,158,56,.05)');
    cg.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=cg; ctx.fillRect(0,0,W,H);
  });

  // ── Logo / header ───────────────────────────────────────────────
  var headerEnd; // y where header area ends
  if(logoImg){
    var lH = 260, lW = 260;
    var lX = (W - lW) / 2, lY = 28;
    ctx.save();
    ctx.shadowColor = 'rgba(116,198,157,.55)'; ctx.shadowBlur = 50;
    ctx.drawImage(logoImg, 0, 0, logoImg.naturalWidth, logoImg.naturalHeight, lX, lY, lW, lH);
    ctx.restore();
    headerEnd = lY + lH + 16;
  } else {
    ctx.textAlign='center';
    ctx.font='800 68px Arial,sans-serif';
    ctx.fillStyle='rgba(116,198,157,.92)';
    ctx.fillText('VELO', W/2, 72);
    headerEnd = 104;
  }

  // Gold separator line — well below logo
  var topLine = ctx.createLinearGradient(60,0,W-60,0);
  topLine.addColorStop(0,'rgba(200,158,56,0)');
  topLine.addColorStop(0.25,'rgba(200,158,56,.75)');
  topLine.addColorStop(0.75,'rgba(200,158,56,.75)');
  topLine.addColorStop(1,'rgba(200,158,56,0)');
  ctx.strokeStyle=topLine; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(60,headerEnd); ctx.lineTo(W-60,headerEnd); ctx.stroke();

  var D = headerEnd - 68; // vertical offset applied to all content below

  // ── Header subtitle ─────────────────────────────────────────────
  var monthNames=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  var now = new Date();
  var weekNum = Math.ceil((((now-new Date(now.getFullYear(),0,1))/86400000)+new Date(now.getFullYear(),0,1).getDay()+1)/7);
  ctx.font='300 26px Arial,sans-serif';
  ctx.fillStyle='rgba(255,255,255,.38)';
  ctx.textAlign='center';
  ctx.fillText('Semana '+weekNum+' · '+monthNames[now.getMonth()]+' '+now.getFullYear(), W/2, 108+D);

  // ── User name ───────────────────────────────────────────────────
  var name = safeLS('get','velo_user_name') || '';
  var motto = (safeLS('get','velo_user_motto') || '').trim();
  ctx.font='700 62px Arial,sans-serif';
  ctx.fillStyle='rgba(200,158,56,.90)';
  ctx.fillText(name || 'Mi semana', W/2, 185+D);

  ctx.textAlign='center';
  if(motto){
    ctx.font='italic 400 26px Georgia,serif';
    ctx.fillStyle='rgba(255,255,255,.58)';
    var mt = '"' + motto + '"';
    var maxMW = W - 200;
    while(ctx.measureText(mt).width > maxMW && mt.length > 3){ mt = mt.slice(0,-2) + '…"'; }
    ctx.fillText(mt, W/2, 218+D);
  } else {
    ctx.font='400 24px Arial,sans-serif';
    ctx.fillStyle='rgba(255,255,255,.28)';
    ctx.fillText('mi semana emocional en Velo', W/2, 218+D);
  }

  // ── Collect mood data ───────────────────────────────────────────
  var days7=[], dayLabels=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'], moodCounts={};
  for(var i=6;i>=0;i--){
    var d=new Date(); d.setDate(d.getDate()-i);
    var k=d.toISOString().slice(0,10);
    var raw=safeLS('get','velo_mood_'+k), emoji='';
    if(raw){ try{ var obj=JSON.parse(raw); emoji=obj.emoji||obj||''; }catch(e){ emoji=raw; } }
    days7.push({day:dayLabels[d.getDay()===0?6:d.getDay()-1],emoji:emoji});
    if(emoji) moodCounts[emoji]=(moodCounts[emoji]||0)+1;
  }
  var daysRecorded=days7.filter(function(d){return d.emoji;}).length;
  var _sortedMoods=Object.keys(moodCounts).sort(function(a,b){return moodCounts[b]-moodCounts[a];});
  // Only call it "dominant" if one emoji strictly leads (no tie)
  var dominantEmoji=(_sortedMoods.length>0 && (_sortedMoods.length===1 || moodCounts[_sortedMoods[1]]<moodCounts[_sortedMoods[0]])) ? _sortedMoods[0] : '';
  var _moodLabel={'😄':'Excelente','😊':'Bien','😐':'Regular','😔':'Melancólico/a','😰':'Ansioso/a','😤':'Frustrado/a','😌':'En paz','🥺':'Sensible','💪':'Con fuerza','😢':'Angustiado/a','😞':'Desanimado/a','🤩':'Emocionado/a','🙂':'Tranquilo/a','😃':'Con energía','😍':'Enamorado/a','🥰':'Agradecido/a','💔':'Desamorado/a','😬':'Nervioso/a','😨':'Con miedo','😡':'Con bronca','😴':'Agotado/a','🤒':'Enfermo/a','🤔':'Confundido/a'};
  var _moodColor={'😄':'rgba(218,160,30,.32)','😊':'rgba(218,160,30,.28)','😌':'rgba(72,185,128,.28)','😐':'rgba(200,160,80,.22)','😔':'rgba(140,100,210,.28)','😰':'rgba(200,140,70,.26)','😤':'rgba(200,80,80,.26)','🥺':'rgba(180,120,200,.26)','💪':'rgba(100,150,220,.26)','😢':'rgba(140,100,210,.28)','😞':'rgba(140,100,210,.24)','🤩':'rgba(218,160,30,.32)','🙂':'rgba(72,185,128,.24)','😃':'rgba(218,160,30,.30)'};
  var _moodBorder={'😄':'rgba(218,160,30,.65)','😊':'rgba(218,160,30,.55)','😌':'rgba(72,185,128,.60)','😐':'rgba(200,160,80,.45)','😔':'rgba(140,100,210,.60)','😰':'rgba(200,140,70,.55)','😤':'rgba(200,80,80,.60)','🥺':'rgba(180,120,200,.55)','💪':'rgba(100,150,220,.60)','😢':'rgba(140,100,210,.60)','😞':'rgba(140,100,210,.50)','🤩':'rgba(218,160,30,.65)','🙂':'rgba(72,185,128,.50)','😃':'rgba(218,160,30,.60)'};
  var _moodCellBg={'😄':'rgba(218,160,30,.13)','😊':'rgba(218,160,30,.10)','😌':'rgba(72,185,128,.12)','😐':'rgba(200,160,80,.09)','😔':'rgba(140,100,210,.12)','😰':'rgba(200,140,70,.11)','😤':'rgba(200,80,80,.12)','🥺':'rgba(180,120,200,.11)','💪':'rgba(100,150,220,.12)','😢':'rgba(140,100,210,.12)','😞':'rgba(140,100,210,.10)','🤩':'rgba(218,160,30,.13)','🙂':'rgba(72,185,128,.10)','😃':'rgba(218,160,30,.11)'};

  // ── Reflexión semanal personalizada ────────────────────────────
  var _rfxY = 248+D;
  var _reflexion = '';
  if(daysRecorded===7) _reflexion='✦ Registraste los 7 días esta semana ✦';
  else if(daysRecorded>=4) _reflexion='✦ '+daysRecorded+' de 7 días registrados esta semana ✦';
  else if(daysRecorded>0) _reflexion='✦ Registraste '+daysRecorded+' día'+(daysRecorded>1?'s':'')+' · seguí así ✦';
  else _reflexion='✦ Empieza a registrar tu semana emocional ✦';
  if(_reflexion){
    ctx.font='500 22px Arial,sans-serif'; ctx.textAlign='center';
    ctx.fillStyle='rgba(116,198,157,.48)'; ctx.fillText(_reflexion,W/2,_rfxY);
  }

  // ── Separator ───────────────────────────────────────────────────
  var sep = function(y){
    var sl=ctx.createLinearGradient(80,0,W-80,0);
    sl.addColorStop(0,'rgba(116,198,157,0)'); sl.addColorStop(.5,'rgba(116,198,157,.22)'); sl.addColorStop(1,'rgba(116,198,157,0)');
    ctx.strokeStyle=sl; ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(80,y); ctx.lineTo(W-80,y); ctx.stroke();
  };
  sep(274+D);

  // ── Mood grid ───────────────────────────────────────────────────
  var gX=54,gY=310+D,gW=W-108,colW=gW/7;
  days7.forEach(function(d,i){
    var x=gX+colW*i+colW/2;
    var cellBg=d.emoji?(_moodCellBg[d.emoji]||'rgba(116,198,157,.10)'):'rgba(255,255,255,.04)';
    var cellBorder=d.emoji?(_moodBorder[d.emoji]||'rgba(116,198,157,.35)'):'rgba(255,255,255,.10)';
    // Cell background pill
    ctx.fillStyle=cellBg;
    ctx.beginPath(); ctx.roundRect(x-colW/2+6,gY-18,colW-12,114,20); ctx.fill();
    // Cell border glow for filled days
    if(d.emoji){
      ctx.strokeStyle=cellBorder; ctx.lineWidth=1.5;
      ctx.beginPath(); ctx.roundRect(x-colW/2+6,gY-18,colW-12,114,20); ctx.stroke();
    }
    // Day label
    ctx.font='700 19px Arial,sans-serif';
    ctx.fillStyle=d.emoji?'rgba(255,255,255,.60)':'rgba(255,255,255,.22)';
    ctx.textAlign='center';
    ctx.fillText(d.day,x,gY+5);
    // Emoji or empty dot
    if(d.emoji){
      ctx.font='64px Arial,sans-serif';
      ctx.fillText(d.emoji,x,gY+83);
    } else {
      ctx.fillStyle='rgba(255,255,255,.12)';
      ctx.beginPath(); ctx.arc(x,gY+52,14,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle='rgba(255,255,255,.08)'; ctx.lineWidth=1;
      ctx.beginPath(); ctx.arc(x,gY+52,14,0,Math.PI*2); ctx.stroke();
    }
  });

  var afterGrid = gY+132;
  sep(afterGrid);

  // ── Dominant mood pill (always visible) ────────────────────────
  var _showDominant = _sortedMoods.length > 0 ? _sortedMoods[0] : '';
  var pillY=afterGrid+22, pillH=94, pillX=80, pillW=W-160;
  if(_showDominant){
    var _pillFill=_moodColor[_showDominant]||'rgba(116,198,157,.22)';
    var _pillBorder=_moodBorder[_showDominant]||'rgba(116,198,157,.45)';
    ctx.fillStyle=_pillFill;
    ctx.beginPath(); ctx.roundRect(pillX,pillY,pillW,pillH,24); ctx.fill();
    ctx.strokeStyle=_pillBorder; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.roundRect(pillX,pillY,pillW,pillH,24); ctx.stroke();
    // Inner glow strip
    var _pg=ctx.createLinearGradient(pillX,pillY,pillX+pillW,pillY+pillH);
    _pg.addColorStop(0,'rgba(255,255,255,.06)'); _pg.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle=_pg; ctx.beginPath(); ctx.roundRect(pillX,pillY,pillW,pillH,24); ctx.fill();
    ctx.font='54px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif';
    ctx.textBaseline='middle'; ctx.textAlign='left';
    ctx.fillText(_showDominant,pillX+22,pillY+pillH/2);
    ctx.textBaseline='alphabetic';
    ctx.font='800 28px Arial,sans-serif'; ctx.fillStyle='rgba(255,255,255,.92)';
    ctx.fillText('Estado predominante: '+(_moodLabel[_showDominant]||_showDominant).toUpperCase(),pillX+102,pillY+38);
    ctx.font='400 21px Arial,sans-serif'; ctx.fillStyle='rgba(255,255,255,.50)';
    var _isDominant=_sortedMoods.length===1||moodCounts[_sortedMoods[1]]<moodCounts[_sortedMoods[0]];
    ctx.fillText((_isDominant?'Predominante ·':'')+' '+(moodCounts[_showDominant]||0)+' veces · '+daysRecorded+'/7 días registrados',pillX+102,pillY+68);
  } else {
    // No moods — show invitation pill
    ctx.fillStyle='rgba(116,198,157,.08)';
    ctx.beginPath(); ctx.roundRect(pillX,pillY,pillW,pillH,24); ctx.fill();
    ctx.strokeStyle='rgba(116,198,157,.22)'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.roundRect(pillX,pillY,pillW,pillH,24); ctx.stroke();
    ctx.font='56px Arial,sans-serif'; ctx.textAlign='left';
    ctx.fillText('🌱',pillX+22,pillY+68);
    ctx.font='700 28px Arial,sans-serif'; ctx.fillStyle='rgba(255,255,255,.65)';
    ctx.fillText('Empieza a registrar tus emociones',pillX+102,pillY+38);
    ctx.font='italic 400 21px Arial,sans-serif'; ctx.fillStyle='rgba(255,255,255,.35)';
    ctx.fillText('Cada emoción registrada es un paso hacia ti',pillX+102,pillY+68);
  }

  // ── AI phrase row ───────────────────────────────────────────────
  var statsY = afterGrid+150;
  var _aiPhrase = _shareCardAIPhrase || '';
  var _apFinalY = statsY + 48; // tracks where phrase ends; used to position next section
  if(_aiPhrase){
    ctx.font='italic 600 34px Georgia,”Times New Roman”,serif';
    ctx.textAlign='center'; ctx.fillStyle='rgba(116,198,157,.82)';
    var _aw=W-200, _apWords=('”'+_aiPhrase+'”').split(' '), _aLine='', _apY=statsY+44;
    _apWords.forEach(function(w){
      var _t=_aLine+(_aLine?' ':'')+w;
      if(ctx.measureText(_t).width>_aw&&_aLine){ ctx.fillText(_aLine,W/2,_apY); _apY+=50; _aLine=w; }
      else _aLine=_t;
    });
    if(_aLine) ctx.fillText(_aLine,W/2,_apY);
    _apFinalY = _apY;
  }

  // ── Emoji breakdown row ─────────────────────────────────────────
  var brkY = _apFinalY + 58; // dynamic gap below AI phrase (no overlap)
  ctx.font='700 22px Arial,sans-serif'; ctx.textAlign='center';
  ctx.fillStyle='rgba(255,255,255,.42)';
  ctx.fillText('Emociones de la semana',W/2,brkY);
  var brkEmojis=Object.keys(moodCounts).sort(function(a,b){return moodCounts[b]-moodCounts[a];});
  var brkN=Math.min(brkEmojis.length,6), brkStep=Math.min(120, Math.floor((W-120)/Math.max(brkN,1)));
  var brkStartX=W/2 - (brkN-1)*brkStep/2;
  brkEmojis.slice(0,brkN).forEach(function(e,i){
    var bx=brkStartX+i*brkStep;
    ctx.font='52px “Apple Color Emoji”,”Segoe UI Emoji”,”Noto Color Emoji”,sans-serif';
    ctx.textAlign='center';
    ctx.fillText(e,bx,brkY+70);
    ctx.font='700 20px Arial,sans-serif';
    ctx.fillStyle='rgba(255,255,255,.50)';
    ctx.fillText('×'+moodCounts[e],bx,brkY+96);
    ctx.fillStyle='rgba(255,255,255,.42)'; // reset for next iteration label
  });

  sep(brkY+120);

  // ── Poetic phrase ───────────────────────────────────────────────
  var phrases=['Estuviste aquí. Eso importa.','Cuidarte es un acto de valentía.','Cada día que registras es tuyo.','Tu historia merece ser contada.','Lo que sientes es real y válido.','Cada emoción tiene su lugar.','Hoy estuviste presente para ti.'];
  var weekIdx=Math.floor(Date.now()/(86400000*7))%phrases.length;
  var phrase='"'+phrases[weekIdx]+'"'; // AI phrase already shown above; use static phrase here
  ctx.font='italic 600 44px Georgia,serif';
  ctx.fillStyle='rgba(255,255,255,.72)';
  ctx.textAlign='center';
  // Wrap long phrases — tighter gap when logo image is present to avoid canvas overflow
  var maxW=W-160, words=phrase.split(' '), line='', phrY=brkY+148;
  words.forEach(function(w){
    var test=line+(line?' ':'')+w;
    if(ctx.measureText(test).width>maxW && line){ ctx.fillText(line,W/2,phrY); phrY+=58; line=w; }
    else line=test;
  });
  if(line) ctx.fillText(line,W/2,phrY);
  phrY+=42;

  // ── Bottom branding ─────────────────────────────────────────────
  var brandY=Math.max(phrY+40, H-110);
  sep(brandY-20);
  ctx.font='500 32px Arial,sans-serif'; ctx.fillStyle='rgba(116,198,157,.65)'; ctx.textAlign='center';
  ctx.fillText('heyvelo.app', W/2, brandY+20);
  if(!logoImg){
    // Logo image already contains "Acompañamos emociones." — skip to save space
    ctx.font='italic 300 24px Georgia,serif'; ctx.fillStyle='rgba(255,255,255,.28)';
    ctx.fillText('Acompañamos emociones', W/2, brandY+54);
  }

  // Gold bottom line
  var btmLine=ctx.createLinearGradient(60,0,W-60,0);
  btmLine.addColorStop(0,'rgba(200,158,56,0)'); btmLine.addColorStop(.25,'rgba(200,158,56,.5)');
  btmLine.addColorStop(.75,'rgba(200,158,56,.5)'); btmLine.addColorStop(1,'rgba(200,158,56,0)');
  ctx.strokeStyle=btmLine; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(60,H-30); ctx.lineTo(W-60,H-30); ctx.stroke();
}

async function pShareCard(){
  var canvas = document.getElementById('shareCanvas');
  if(!canvas) return;
  try{
    canvas.toBlob(async function(blob){
      if(!blob) return;
      var file = new File([blob],'mi-semana-velo.png',{type:'image/png'});
      if(navigator.share && navigator.canShare && navigator.canShare({files:[file]})){
        try{
          await navigator.share({
            files:[file],
            title:'Mi semana emocional en Velo',
            text:'Registré cómo me sentí esta semana · heyvelo.app'
          });
        }catch(e){ if(e.name!=='AbortError') _downloadShareCard(canvas); }
      } else {
        _downloadShareCard(canvas);
      }
    },'image/png');
  }catch(e){ _downloadShareCard(canvas); }
}

function _downloadShareCard(canvas){
  var link = document.createElement('a');
  link.download = 'mi-semana-velo.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
  pToast('📥','Imagen guardada — compartila donde quieras 💚');
}

// ── GUARDIAN DATA ─────────────────────────────────────────────
// Guardianes = usuarios de la comunidad que se ofrecen a acompañar a otros.
// Nivel Bronce: 5 días distintos de uso de la app.
// Niveles superiores: número de conversaciones completadas.
function _getBadge(convs, visitDaysOverride){
  var visitDays = (visitDaysOverride !== undefined) ? visitDaysOverride : _getVisitDayCount();
  if(convs >= 100) return { icon:'💎', name:'Diamante', color:'#7B68EE', next:null,        needed:0,           visitBased:false };
  if(convs >= 40)  return { icon:'🥇', name:'Oro',      color:'#C8A200', next:'Diamante',  needed:100-convs,   visitBased:false };
  if(convs >= 20)  return { icon:'🥈', name:'Plata',    color:'#8892A4', next:'Oro',        needed:40-convs,    visitBased:false };
  if(visitDays >= 5) return { icon:'🥉', name:'Bronce', color:'#C07840', next:'Plata',      needed:20-convs,    visitBased:false };
  return { icon:'🌱', name:'Novato', color:'var(--sage4)', next:'Bronce', needed:5-visitDays, visitBased:true, visitDays:visitDays };
}

function _checkAndNotifyBadge(){
  var convs = parseInt(safeLS('get','velo_guardian_convs')||'0',10);
  var badge = _getBadge(convs);
  var lastNotified = safeLS('get','velo_badge_last_notified');
  if(!lastNotified){
    safeLS('set','velo_badge_last_notified', badge.name);
    return;
  }
  if(badge.name === lastNotified) return;
  safeLS('set','velo_badge_last_notified', badge.name);
  // Only notify for Plata, Oro, Diamante — Bronce is silently awarded for basic app usage
  if(badge.name !== 'Bronce') _sendBadgeInboxMsg(badge);
  if(badge.name === 'Diamante') _grantDiamanteReward();
}

async function _grantDiamanteReward(){
  if(safeLS('get','velo_diamante_plus_granted')) return; // prevent double-grant
  _initSupabase();
  if(!sbClient) return;
  try{
    var ok = await _ensureSbSession();
    if(!ok) return;
    // Otorgo 100% server-side: el RPC valida ≥100 conversaciones REALES
    // (guardian_requests) antes de activar Plus. El cliente ya no escribe role
    // ni plus_expires_at (el trigger velo_protect_role lo bloquearía igual).
    var res = await sbClient.rpc('grant_diamante_plus');
    if(res && !res.error && res.data && res.data.ok){
      safeLS('set','velo_plan','plus');
      safeLS('set','velo_diamante_plus_granted','1');
      if(typeof _updatePlanUI==='function') _updatePlanUI();
    }
  }catch(e){}
}

function _sendBadgeInboxMsg(badge){
  if(badge.name === 'Bronce') return; // Bronce is silently awarded — never creates an inbox message
  var catalog = {
    Plata:    { asunto:'¡Insignia Plata desbloqueada! 🥈', cuerpo:'¡Increíble! Completaste 20 conversaciones de acompañamiento. Tu perfil ahora muestra el badge de guardián verificado, visible en toda la comunidad. ¡Seguí así!' },
    Oro:      { asunto:'¡Sos Guardián Oro! 🥇', cuerpo:'¡Felicitaciones! Completaste 40 conversaciones. Ahora podés crear Círculos de Paz y tenés prioridad en el listado de guardianes. ¡Sos un pilar de Velo!' },
    Diamante: { asunto:'¡Insignia Diamante — Leyenda de Velo! 💎🎁', cuerpo:'¡Extraordinario! Completaste 100 conversaciones y alcanzaste el nivel máximo de Velo.\n\nComo reconocimiento especial, te regalamos 3 meses de Velo Plus completamente gratis 🎁 — ya está activado en tu cuenta.\n\nCon Velo Plus tenés acceso ilimitado al acompañante IA Calma, sin restricciones en la Sala de Ayuda, Al Mar y Círculos de Paz, y muchas funciones exclusivas más.\n\n¡Gracias por tu dedicación. Sos una leyenda de nuestra comunidad! 💎' }
  };
  var info = catalog[badge.name];
  if(!info) return;
  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  // Prevent duplicate badge inbox messages for the same level
  var badgePrefix = 'badge_'+badge.name.toLowerCase()+'_';
  if(inbox.some(function(m){ return m.id && m.id.indexOf(badgePrefix) === 0; })) return;
  var msgId = badgePrefix+Date.now();
  inbox.unshift({
    id: msgId,
    tipo: 'sistema',
    icon: badge.icon,
    remitente: 'Velo',
    asunto: info.asunto,
    extracto: info.cuerpo.slice(0, 80) + '…',
    cuerpo: info.cuerpo,
    leido: false,
    fecha: new Date().toLocaleDateString('es', { day:'2-digit', month:'short' })
  });
  safeLS('set','velo_inbox', JSON.stringify(inbox));
  _updateHomeBell();
  // Persist badge level to Supabase so new browsers see the badge notification too
  _initSupabase();
  var _bnUid = safeLS('get','velo_user_id');
  if(sbClient && _bnUid){
    sbClient.from('profiles').update({ badge_notified: badge.name }).eq('id', _bnUid).then(function(){}).catch(function(){});
  }
}

