async function _checkDailyGreeting(){
  var today = new Date().toISOString().slice(0,10);
  if(safeLS('get','velo_greeting_shown_'+today)) return;

  var d        = new Date();
  var h        = d.getHours();
  var momento  = (h < 6 || h >= 20) ? 'noche' : h < 12 ? 'mañana' : 'tarde';
  var saludoMap = { 'mañana':'¡Buenos días', 'tarde':'¡Buenas tardes', 'noche':'¡Buenas noches' };
  var name     = (safeLS('get','velo_user_name')||'').split(' ')[0];
  var saludo   = saludoMap[momento] + (name ? ', '+name : '') + '!';

  // Show card immediately with saludo + loading dots — no waiting
  _showDailyGreeting(saludo, null);

  // Now fetch Gemini message in background with 5s timeout
  var cached = safeLS('get','velo_greeting_'+today);
  var msg;
  if(cached){
    msg = cached;
  } else {
    var dias     = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
    var dia      = dias[d.getDay()];
    var meses    = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
    var fechaFull = d.getDate()+' de '+meses[d.getMonth()]+' de '+d.getFullYear();
    var startOfYear = new Date(d.getFullYear(), 0, 0);
    var dayOfYear   = Math.floor((d - startOfYear) / 86400000);
    var tema        = _greetingTemas[dayOfYear % _greetingTemas.length];

    var prompt = 'Sos el acompañante de bienestar de Velo, una app de bienestar emocional entre pares.\n'
      +'Generá un mensaje de bienvenida breve y muy cálido. '
      +'Hoy es '+fechaFull+', '+momento+' del '+dia+'.\n'
      +'El mensaje de HOY debe girar alrededor del tema: "'+tema+'".\n'
      +'Reglas: 1-2 oraciones cortas. Genuino, empático, no exagerado. '
      +'Español rioplatense (vos, te). Terminá con un emoji suave (🌿 💚 ✨ 🌱 🌸 💙 🫂). '
      +'NO incluyas saludo ni nombre — solo el mensaje. Sin comillas ni explicaciones.';

    var timeoutP = new Promise(function(res){ setTimeout(function(){ res(null); }, 5000); });
    msg = await Promise.race([_geminiCall(prompt, { temperature:0.92, maxOutputTokens:80 }), timeoutP]);
    if(!msg || msg.length > 220){
      msg = _greetingFallbacks[d.getDate() % _greetingFallbacks.length];
    }
    safeLS('set','velo_greeting_'+today, msg);
  }

  // Inject message into already-visible card
  var msgEl = document.getElementById('veloGreetingGemini');
  if(msgEl){
    msgEl.style.transition = 'opacity .4s';
    msgEl.style.opacity = '0';
    setTimeout(function(){
      msgEl.textContent = msg;
      msgEl.style.opacity = '1';
    }, 150);
  }
}

function _showDailyGreeting(saludo, msg){
  var today = new Date().toISOString().slice(0,10);
  safeLS('set','velo_greeting_shown_'+today, '1');

  var card = document.createElement('div');
  card.id  = 'veloGreetingCard';
  card.style.cssText = [
    'position:fixed',
    'bottom:0',
    'left:50%',
    'transform:translateX(-50%) translateY(110%)',
    'width:min(400px,calc(100vw - 24px))',
    'z-index:9800',
    'transition:transform .45s cubic-bezier(.34,1.56,.64,1)'
  ].join(';');

  card.innerHTML = ''
    +'<div style="'
      +'background:linear-gradient(150deg,rgba(248,253,250,.97),rgba(238,250,244,.95));'
      +'backdrop-filter:blur(28px) saturate(1.5);'
      +'-webkit-backdrop-filter:blur(28px) saturate(1.5);'
      +'border:1.5px solid rgba(116,198,157,.32);'
      +'border-bottom:none;'
      +'border-radius:26px 26px 0 0;'
      +'padding:10px 20px 26px;'
      +'box-shadow:0 -10px 48px rgba(45,106,79,.14),0 -2px 12px rgba(45,106,79,.07),'
        +'inset 0 1px 0 rgba(255,255,255,.7);'
      +'position:relative'
    +'">'

    // drag handle
    +'<div style="'
      +'width:38px;height:4px;background:rgba(116,198,157,.35);border-radius:2px;'
      +'margin:0 auto 16px'
    +'"></div>'

    // content row
    +'<div style="display:flex;align-items:flex-start;gap:14px">'

      // avatar
      +'<div style="'
        +'width:54px;height:54px;border-radius:18px;flex-shrink:0;'
        +'background:linear-gradient(135deg,rgba(116,198,157,.25),rgba(168,212,232,.2));'
        +'border:2px solid rgba(116,198,157,.3);'
        +'box-shadow:0 4px 18px rgba(116,198,157,.2);'
        +'display:flex;align-items:center;justify-content:center;'
        +'font-size:30px;'
        +'animation:p-float 3.2s ease-in-out infinite'
      +'">🌿</div>'

      // text
      +'<div style="flex:1;min-width:0;padding-top:2px">'
        +'<div style="'
          +'font-size:12px;font-weight:700;letter-spacing:1.3px;text-transform:uppercase;'
          +'color:rgba(116,198,157,.75);margin-bottom:6px'
        +'">Acompañante Velo</div>'
        // Fixed greeting line (Buenos días / tardes / noches)
        +'<div style="'
          +'font-family:\'Cormorant Garamond\',serif;font-size:19px;'
          +'color:var(--sage);line-height:1.3;font-weight:600;letter-spacing:-.2px;margin-bottom:6px'
        +'">'+_escHtml(saludo)+'</div>'
        // Gemini message line — shows loading dots until ready
        +'<div id="veloGreetingGemini" style="'
          +'font-family:\'Cormorant Garamond\',serif;'
          +'color:rgba(255,255,255,.95);font-size:17px;line-height:1.52;font-weight:500;letter-spacing:-.1px;text-shadow:0 1px 12px rgba(0,0,0,.65)'
        +'">'+( msg ? _escHtml(msg) : '…')+'</div>'
      +'</div>'

      // close
      +'<button onclick="pDismissGreeting()" style="'
        +'flex-shrink:0;width:30px;height:30px;border-radius:50%;'
        +'background:rgba(116,198,157,.1);border:1px solid rgba(116,198,157,.2);'
        +'color:var(--sage3);font-size:15px;cursor:pointer;'
        +'display:flex;align-items:center;justify-content:center;'
        +'font-family:\'Jost\',sans-serif;transition:all .15s;align-self:flex-start;margin-top:1px'
      +'">✕</button>'
    +'</div>'

    // progress bar
    +'<div style="margin-top:16px;height:3px;background:rgba(116,198,157,.12);border-radius:2px;overflow:hidden">'
      +'<div id="veloGreetingBar" style="'
        +'height:100%;width:100%;'
        +'background:linear-gradient(90deg,rgba(116,198,157,.5),rgba(116,198,157,.8));'
        +'border-radius:2px;transition:none'
      +'"></div>'
    +'</div>'
    +'</div>';

  document.body.appendChild(card);

  // Content already injected inline; veloGreetingGemini updated async by caller

  // Slide up into view
  requestAnimationFrame(function(){
    setTimeout(function(){
      card.style.transform = 'translateX(-50%) translateY(0)';
      // Start countdown bar after card settles
      setTimeout(function(){
        var bar = document.getElementById('veloGreetingBar');
        if(bar){
          bar.style.transition = 'width 7s linear';
          bar.style.width = '0%';
        }
      }, 500);
    }, 60);
  });

  // Auto-dismiss at 7.8s
  var _autoTimer = setTimeout(pDismissGreeting, 7800);
  card.dataset.timer = _autoTimer;

  // Drag to dismiss
  var startY = null;
  card.addEventListener('touchstart', function(e){ startY = e.touches[0].clientY; }, {passive:true});
  card.addEventListener('touchmove', function(e){
    if(startY === null) return;
    var dy = e.touches[0].clientY - startY;
    if(dy > 0) card.style.transform = 'translateX(-50%) translateY('+dy+'px)';
  }, {passive:true});
  card.addEventListener('touchend', function(e){
    var dy = e.changedTouches[0].clientY - (startY||0);
    if(dy > 60){ pDismissGreeting(); } else { card.style.transform = 'translateX(-50%) translateY(0)'; }
    startY = null;
  }, {passive:true});
}

function pDismissGreeting(){
  var card = document.getElementById('veloGreetingCard');
  if(!card) return;
  clearTimeout(parseInt(card.dataset.timer));
  card.style.transition = 'transform .32s cubic-bezier(.4,0,.6,1)';
  card.style.transform  = 'translateX(-50%) translateY(110%)';
  setTimeout(function(){ if(card.parentNode) card.parentNode.removeChild(card); }, 340);
}

function pForceRefreshNews(){
  var today = new Date().toISOString().slice(0,10);
  safeLS('del', 'velo_goodnews_'+today);
  var newsEl = document.getElementById('newsContainer');
  if(newsEl) newsEl.innerHTML = '<div style="text-align:center;padding:40px;color:var(--ink4)">🔄 Actualizando noticias...</div>';
  pRenderNews(true);
}

async function pRenderNews(forceRefresh){
  var newsEl = document.getElementById('newsContainer');
  if(!newsEl) return;
  var _tok = _navToken;
  var today = new Date().toISOString().slice(0,10);
  var cacheKey = 'velo_goodnews_'+today;
  var _nd = new Date();
  var _cy = _nd.getFullYear();

  // Static pool — shown immediately when no cache (no spinner)
  var _pool = [
    { emoji:'🌱', titulo:'Reforestación récord: millones de árboles plantados en '+_cy, cuerpo:'Coaliciones de países y organizaciones siguen batiendo récords de reforestación, contribuyendo a absorber millones de toneladas de CO₂ y restaurar ecosistemas degradados en distintos continentes.', reflexion:'Cada árbol es un acto de fe en el futuro. La humanidad puede regenerarse cuando actúa unida. 🌿', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('reforestacion record arboles')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'💊', titulo:'Avances en tratamientos sin opioides para el dolor crónico', cuerpo:'Investigadores continúan desarrollando terapias basadas en neuromodulación y biomedicina que reducen el dolor crónico sin generar dependencia, mejorando la calidad de vida de millones de personas.', reflexion:'El alivio del sufrimiento humano sigue avanzando. La ciencia trabaja para que vivir bien sea posible para todos. 💙', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('tratamiento dolor cronico sin opioides')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'☀️', titulo:'Energía solar bate récords de producción en '+_cy, cuerpo:'La energía solar alcanzó nuevos máximos de producción global en '+_cy+', con cientos de comunidades rurales accediendo por primera vez a electricidad limpia gracias a micro-redes comunitarias.', reflexion:'La energía limpia no es solo tecnología — es dignidad y oportunidad. ✨', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('record energia solar renovable')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'🐋', titulo:'Especies marinas en recuperación gracias a áreas protegidas', cuerpo:'Ballenas, tortugas y delfines muestran señales de recuperación poblacional en zonas donde se establecieron reservas marinas, demostrando que la protección sostenida revierte el daño ambiental.', reflexion:'La naturaleza sana cuando le damos tiempo y espacio. El daño puede revertirse. 🌊', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('conservacion marina especies recuperacion')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'📚', titulo:'Programas de inclusión digital reducen el aislamiento en adultos mayores', cuerpo:'Iniciativas en toda América Latina capacitan a personas mayores en el uso de internet y videollamadas, reduciendo el aislamiento social y conectando a miles con sus familias y comunidades.', reflexion:'Aprender no tiene edad. Cada persona conectada es una vida más acompañada. 🌻', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('inclusion digital adultos mayores america latina')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'🧬', titulo:'Terapias génicas CRISPR abren nuevas esperanzas para enfermedades raras', cuerpo:'Los avances en edición genética continúan transformando el tratamiento de enfermedades hereditarias, con nuevas terapias aprobadas y ensayos clínicos que muestran resultados prometedores en pacientes de todo el mundo.', reflexion:'La ciencia convierte el sufrimiento de hoy en el alivio de mañana. Cada avance es una vida cambiada. 💙', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('CRISPR terapia genica aprobacion')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'🌊', titulo:'Corales tropicales muestran resiliencia ante el cambio climático', cuerpo:'Científicos identificaron colonias de coral con mayor tolerancia al calor y trabajan en programas de restauración activa que replican estas variedades en arrecifes degradados de todo el mundo.', reflexion:'La resiliencia de la naturaleza nos enseña que siempre hay posibilidad de regeneración. 🌏', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('restauracion corales resiliencia')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'🤲', titulo:'Redes de voluntariado baten récords de impacto social en '+_cy, cuerpo:'Organizaciones de voluntarios en todo el mundo registran un crecimiento sin precedentes en '+_cy+', con millones de personas dedicando tiempo a causas comunitarias, bancos de alimentos y apoyo a personas vulnerables.', reflexion:'La solidaridad transforma vecindarios en comunidades. Compartir es un acto de amor. ❤️', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('voluntariado record solidaridad')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'♻️', titulo:'Ciudades líderes en reciclaje y economía circular en '+_cy, cuerpo:'Varias ciudades europeas y latinoamericanas alcanzan tasas de reciclaje históricas en '+_cy+', inspirando nuevos modelos de economía circular que reducen residuos y generan empleos verdes.', reflexion:'Un futuro limpio se construye con pequeñas decisiones diarias y mucha voluntad colectiva. 🌍', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('ciudades reciclaje economia circular')+'+'+_cy+'&hl=es-419', _src:'static' },
    { emoji:'🧠', titulo:'Investigaciones en salud mental reducen el estigma en jóvenes', cuerpo:'Nuevos programas de salud mental en escuelas y universidades de América Latina están logrando que más jóvenes busquen ayuda sin miedo al juicio, cambiando la cultura del bienestar emocional.', reflexion:'Hablar de lo que sentimos es el primer paso hacia sanar. La salud mental es salud. 💚', sourceName:'Buscar noticia', sourceUrl:'https://news.google.com/search?q='+encodeURIComponent('salud mental jovenes programa')+'+'+_cy+'&hl=es-419', _src:'static' }
  ];

  // Cache hit → instant render and done
  if(!forceRefresh){
    var cached = safeLS('get', cacheKey);
    if(cached){
      try{
        var cachedItems = JSON.parse(cached);
        if(cachedItems && cachedItems.length){ _renderNewsList(newsEl, cachedItems); return; }
      }catch(e){}
    }
  }

  // Always show static items immediately (no spinner) — replaced when API returns
  var _pOff = _nd.getDate() % _pool.length;
  var _staticItems = [];
  for(var _psi=0;_psi<5;_psi++) _staticItems.push(_pool[(_pOff+_psi)%_pool.length]);
  _renderNewsList(newsEl, _staticItems);
  if(forceRefresh){
    // Subtle top banner while fetching fresh news in background
    var _ub=document.createElement('div');
    _ub.id='newsUpdBanner';
    _ub.style.cssText='text-align:center;padding:8px 12px;margin-bottom:10px;border-radius:10px;background:rgba(116,198,157,.10);border:1px solid rgba(116,198,157,.20);color:var(--ink4);font-size:14px;opacity:.75';
    _ub.textContent='🔄 Buscando noticias frescas del día…';
    if(newsEl) newsEl.insertBefore(_ub, newsEl.firstChild);
  }

  // Admin-published news
  _initSupabase();
  var adminNews = (await sbLoadAdminNews()).map(function(n){
    return { emoji:n.emoji||'📰', titulo:n.titulo, cuerpo:n.cuerpo, reflexion:'',
      sourceUrl:n.source_url||'', sourceName:n.source_name||'Velo', _src:'admin' };
  });
  if(safeLS('get','velo_admin_news_only') === '1' && adminNews.length){
    newsEl = document.getElementById('newsContainer');
    if(_navToken !== _tok || !newsEl) return;
    safeLS('set', cacheKey, JSON.stringify(adminNews));
    _renderNewsList(newsEl, adminNews);
    return;
  }

  var monthYear = ['enero','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'][_nd.getMonth()]+' '+_nd.getFullYear();
  var todayFull = _nd.getDate()+' de '+['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][_nd.getMonth()]+' de '+_nd.getFullYear();
  var _topicSets = [
    'avances médicos, nuevos tratamientos, bienestar emocional positivo',
    'naturaleza, conservación animal, reforestación, océanos limpios',
    'solidaridad humana, voluntariado, comunidades que se ayudan',
    'ciencia y tecnología para el bien, energía renovable, accesibilidad',
    'educación, arte, cultura, deportes inspiradores'
  ];
  var _topicFocus = _topicSets[(_nd.getDate() + (forceRefresh ? Math.floor(Math.random()*5) : 0)) % _topicSets.length];
  var _seed = forceRefresh ? ' Session:'+Date.now() : '';

  // Attempt 1: Grounded search — Gemini with Google Search finds real articles with verified URLs
  var gPrompt = 'Today is '+todayFull+' ('+_nd.getFullYear()+').'+_seed+' Use Google Search to find 5 DIFFERENT real positive news stories published in '+_nd.getFullYear()+' (current year). '
    +'Focus on: '+_topicFocus+'. '
    +'PRIORITY: articles from '+_nd.getFullYear()+'. Only use older articles (max 1 year old) if absolutely nothing recent is found. NEVER use articles older than 12 months. '
    +'For EACH story you MUST include: the real article URL (sourceUrl — must be a direct link to the article page), the news outlet name (sourceName), '
    +'the article title, a 2-3 sentence summary in Argentine Spanish (rioplatense, vos/vosotros), and a short wellbeing reflection. '
    +'ONLY include stories actually found via Google Search — do NOT use training data, do NOT invent URLs. '
    +'Respond ONLY with valid JSON array, no markdown fences: '
    +'[{"emoji":"...","titulo":"...","cuerpo":"...","reflexion":"...","sourceName":"...","sourceUrl":"https://..."}]';

  var result = await _geminiCallGrounded(gPrompt, { maxOutputTokens:2000 });
  if(_navToken !== _tok) return;
  var items = [];

  if(result.text){
    try{
      var raw = result.text.replace(/```json\n?|```/g,'').trim();
      var m = raw.match(/\[[\s\S]*\]/);
      if(m) items = JSON.parse(m[0]);
    }catch(e){}
    // For any item missing a URL, try to fill from grounding chunks
    var chunkPool = (result.urls || []).slice();
    items.forEach(function(item){
      var hasUrl = item.sourceUrl && item.sourceUrl.startsWith('http');
      if(!hasUrl && chunkPool.length){
        var chunk = chunkPool.shift();
        item.sourceUrl = chunk.uri;
        if(!item.sourceName || item.sourceName.length < 2) item.sourceName = chunk.title || 'Fuente';
      }
      if(!item.sourceUrl || !item.sourceUrl.startsWith('http')) item.sourceUrl = '';
    });
    items.forEach(function(it){ it._src = 'g'; });
  }

  // Attempt 2: Regular Gemini fallback (no fake URLs)
  if(!items.length){
    var aiPrompt = 'Generá 5 noticias reales, positivas e inspiradoras de '+_nd.getFullYear()+' (año actual) sobre bienestar, ciencia, naturaleza o solidaridad humana. '
      +'Priorizá noticias del año '+_nd.getFullYear()+'. Si no tenés información de ese año, usá noticias de los últimos 12 meses. NUNCA uses noticias de más de 2 años atrás. '
      +'Sé específico: incluí nombres reales, países, datos concretos. No inventes URLs. '
      +'SOLO JSON: [{"emoji":"...","titulo":"...","cuerpo":"...","reflexion":"...","sourceName":"nombre del medio real"}]';
    var aiText = await _geminiCall(aiPrompt, { temperature:0.85, maxOutputTokens:1200 });
    if(_navToken !== _tok) return;
    if(aiText){
      try{
        var am = aiText.replace(/```json\n?|```/g,'').trim().match(/\[[\s\S]*\]/);
        if(am){ items = JSON.parse(am[0]); items.forEach(function(it){ it._src='ai'; }); }
      }catch(e){}
    }
  }

  newsEl = document.getElementById('newsContainer');
  if(_navToken !== _tok || !newsEl) return;
  var _removeBanner=function(){ var b=document.getElementById('newsUpdBanner'); if(b&&b.parentNode) b.parentNode.removeChild(b); };
  if(items.length){
    var finalItems = adminNews.concat(items);
    safeLS('set', cacheKey, JSON.stringify(finalItems));
    _renderNewsList(newsEl, finalItems);
  } else if(adminNews.length && forceRefresh){
    safeLS('set', cacheKey, JSON.stringify(adminNews));
    _renderNewsList(newsEl, adminNews);
  } else {
    // Gemini failed but static items already visible — just remove the banner
    _removeBanner();
  }
}

// ── Feature 4: reading tracker ──────────────────────────────────────
function _trackNewsRead(){
  var today = new Date().toISOString().slice(0,10);
  var reads = []; try{ reads = JSON.parse(safeLS('get','velo_news_reads')||'[]'); }catch(e){}
  reads.push(today);
  // keep last 90 days
  safeLS('set','velo_news_reads', JSON.stringify(reads.slice(-200)));
}
function _getNewsWeekCount(){
  var reads = []; try{ reads = JSON.parse(safeLS('get','velo_news_reads')||'[]'); }catch(e){}
  var cutoff = new Date(Date.now() - 7*24*3600*1000).toISOString().slice(0,10);
  return reads.filter(function(d){ return d >= cutoff; }).length;
}
function _getNewsStreak(){
  var reads = []; try{ reads = JSON.parse(safeLS('get','velo_news_reads')||'[]'); }catch(e){}
  var days = {}; reads.forEach(function(d){ days[d]=1; });
  var streak = 0;
  var d = new Date();
  for(var i=0;i<60;i++){
    var k = d.toISOString().slice(0,10);
    if(days[k]) streak++;
    else if(i>0) break;
    d.setDate(d.getDate()-1);
  }
  return streak;
}
function _newsReadingBadgeHtml(){
  var count = _getNewsWeekCount();
  var streak = _getNewsStreak();
  if(!count) return '';
  var streakTxt = streak >= 2 ? ' · <strong>'+streak+' días seguidos 🔥</strong>' : '';
  return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;padding:11px 14px;background:linear-gradient(90deg,rgba(116,198,157,.10),rgba(116,198,157,.05));border:1px solid rgba(116,198,157,.22);border-radius:14px">'
    +'<span style="font-size:22px">🌞</span>'
    +'<div style="font-size:14px;color:var(--ink3);line-height:1.5">Leíste <strong style="color:var(--sage2)">'+count+' noticia'+(count!==1?'s':'')+' buena'+(count!==1?'s':'')+'</strong> esta semana'+streakTxt+'</div>'
    +'</div>';
}

// ── Feature 5: share helper ─────────────────────────────────────────
function pShareNewsItem(titulo, cuerpo, sourceUrl){
  var text = '🌞 '+titulo+'\n\n'+cuerpo+(sourceUrl ? '\n\n🔗 '+sourceUrl : '')+'\n\n— Compartido desde Velo (heyvelo.app)';
  if(navigator.share){
    navigator.share({ title: titulo, text: text, url: sourceUrl || 'https://heyvelo.app' }).catch(function(){});
    return;
  }
  // WhatsApp fallback
  var wa = 'https://api.whatsapp.com/send?text='+encodeURIComponent(text);
  window.open(wa, '_blank');
}
function pCopyNewsItem(titulo, cuerpo, sourceUrl, btnEl){
  var text = '🌞 '+titulo+'\n\n'+cuerpo+(sourceUrl ? '\n\n🔗 '+sourceUrl : '')+'\n\n— Compartido desde Velo (heyvelo.app)';
  try{
    navigator.clipboard.writeText(text).then(function(){
      if(btnEl){ var orig=btnEl.textContent; btnEl.textContent='✅ Copiado'; setTimeout(function(){ btnEl.textContent=orig; },1800); }
    }).catch(function(){ pToast('📋','Copiado al portapapeles'); });
  }catch(e){ pToast('⚠️','Tu navegador no soporta copiar'); }
}

function _renderNewsList(el, items){
  var _b=document.getElementById('newsUpdBanner'); if(_b&&_b.parentNode) _b.parentNode.removeChild(_b);
  _newsListCache = items;
  var _cy = new Date().getFullYear();
  // v1521: cada noticia toma un color según su emoji (cálido/esperanza/calma)
  // en vez del verde uniforme — el muro se siente vivo, no aburrido.
  var isDark = document.body.classList.contains('r-dark');
  var _sourceTag = function(item){
    var _newsSearch = 'https://news.google.com/search?q='+encodeURIComponent((item.titulo||'')+' '+_cy)+'&hl=es-419';
    var tagBg = isDark ? 'rgba(255,255,255,.10)' : 'rgba(0,0,0,.055)';
    var tagCol = isDark ? 'rgba(255,255,255,.82)' : 'rgba(45,40,25,.82)';
    var tagBd = isDark ? 'rgba(255,255,255,.18)' : 'rgba(0,0,0,.12)';
    return item.titulo
      ? '<a href="'+_escHtml(_newsSearch)+'" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation()" style="display:inline-flex;align-items:center;gap:3px;color:'+tagCol+';font-weight:700;text-decoration:none;background:'+tagBg+';padding:3px 8px;border-radius:100px;border:1px solid '+tagBd+'">🔗 Buscar en Google News</a>'
      : '<span style="color:var(--ink5);font-style:italic">✨ Velo IA</span>';
  };

  var heroHtml = '';
  var restHtml = '';

  items.forEach(function(item, i){
    var col = isDark ? _dqEmojiColor(item.emoji||'📰') : _dqEmojiColorLight(item.emoji||'📰');
    var bodyCol = isDark ? 'rgba(255,255,255,.80)' : 'rgba(38,30,14,.82)';
    var stripSolid = col.strip.replace(/[\d.]+\)$/,'0.9)');
    var isHero = i === 0;
    if(isHero){
      // "Noticia del día" — hero con color propio según el emoji de la noticia
      heroHtml = '<div onclick="pOpenNewsDetail(0)" style="cursor:pointer;margin-bottom:18px;border-radius:22px;overflow:hidden;background:'+col.bg+';border:1.5px solid '+col.border+';box-shadow:0 6px 26px '+col.glow+'">'
        +'<div style="height:4px;background:'+stripSolid+'"></div>'
        +'<div style="padding:14px 16px 6px;display:flex;align-items:center;gap:6px">'
        +'<span style="font-size:11px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:'+col.label+';background:'+col.badge+';padding:3px 10px;border-radius:100px;border:1px solid '+col.border+'">🗞️ Noticia del día</span>'
        +'</div>'
        +'<div style="padding:8px 18px 6px;text-align:center">'
        +'<div style="font-size:56px;line-height:1;margin-bottom:10px">'+_escHtml(item.emoji||'📰')+'</div>'
        +'<h3 style="font-family:\'Cormorant Garamond\',serif;font-size:23px;font-weight:700;color:'+col.label+';line-height:1.3;margin-bottom:10px">'+_escHtml(item.titulo)+'</h3>'
        +'<p style="font-size:15px;color:'+bodyCol+';line-height:1.7;margin-bottom:6px">'+_escHtml(item.cuerpo)+'</p>'
        +'<div style="display:flex;justify-content:center">'+_newsRxRowHtml(0)+'</div>'
        +'</div>'
        +'<div style="padding:10px 18px 14px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;border-top:1px solid '+col.border+';margin-top:8px">'
        +_sourceTag(item)
        +'<button onclick="event.stopPropagation();pShareNewsItem('+_jsAttr(item.titulo)+','+_jsAttr(item.cuerpo)+','+_jsAttr(item.sourceUrl||'')+');" style="display:inline-flex;align-items:center;gap:5px;padding:5px 12px;background:'+col.badge+';border:1px solid '+col.border+';border-radius:100px;font-size:13px;font-weight:700;color:'+col.label+';cursor:pointer;font-family:\'Jost\',sans-serif">📤 Compartir</button>'
        +'</div>'
        +'</div>';
    } else {
      restHtml += '<div style="margin-bottom:12px;cursor:pointer;border-radius:16px;overflow:hidden;background:'+col.bg+';border:1px solid '+col.border+';box-shadow:0 2px 12px '+col.glow+'" onclick="pOpenNewsDetail('+i+')">'
        +'<div style="display:flex;align-items:stretch">'
        +'<div style="width:5px;flex-shrink:0;background:'+stripSolid+'"></div>'
        +'<div style="display:flex;align-items:flex-start;gap:13px;padding:14px 15px;flex:1;min-width:0">'
        +'<div style="font-size:30px;line-height:1;flex-shrink:0">'+_escHtml(item.emoji||'📰')+'</div>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:16.5px;color:'+col.label+';margin-bottom:5px;font-weight:700;line-height:1.3">'+_escHtml(item.titulo)+'</div>'
        +'<div style="font-size:14px;color:'+bodyCol+';line-height:1.6">'+_escHtml(item.cuerpo)+'</div>'
        +_newsRxRowHtml(i)
        +'<div style="margin-top:9px;font-size:13px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">'
        +_sourceTag(item)
        +'</div>'
        +'</div>'
        +'</div>'
        +'</div>'
        +'</div>';
    }
  });

  el.innerHTML = _newsReadingBadgeHtml() + '<div id="newsTopOfDay"></div>' + heroHtml + (items.length > 1 ? '<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--ink4);margin-bottom:10px;margin-top:4px">MÁS NOTICIAS</div>' : '') + restHtml;
  // v1501: reacciones comunitarias — cargar contadores y top del día (no bloquea)
  try{ setTimeout(function(){ _loadNewsReactions(); }, 250); }catch(_){}
}

// ── v1501: REACCIONES A BUENAS NOTICIAS ─────────────────────────────
// 🌞 me alegró · 💛 me encantó · 🌱 me dio esperanza — contadores en vivo
// + "La que más alegró hoy" (tabla news_reactions; si falta, se oculta sola).
var _NEWS_RX = [
  { k:'alegro',    e:'🌞', lbl:'Me alegró' },
  { k:'amor',      e:'💛', lbl:'Me encantó' },
  { k:'esperanza', e:'🌱', lbl:'Esperanza' }
];
function _newsKey(titulo){
  return (titulo||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80);
}
var _newsRxData = {}; // news_key → { counts:{alegro,amor,esperanza}, mine:{} }
function _newsRxRowHtml(i){
  var item = _newsListCache[i]; if(!item) return '';
  var key = _newsKey(item.titulo);
  var d = _newsRxData[key] || { counts:{}, mine:{} };
  var lt = !document.body.classList.contains('r-dark');
  return '<div class="news-rx-row" data-nkey="'+_escHtml(key)+'" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">'
    + _NEWS_RX.map(function(rx){
        var on = !!d.mine[rx.k];
        var n = d.counts[rx.k]||0;
        var css = on
          ? (lt ? 'background:rgba(190,145,35,.20);border:1.5px solid rgba(190,145,35,.65);color:rgba(110,80,10,.95)' : 'background:rgba(255,215,110,.22);border:1.5px solid rgba(255,215,110,.6);color:rgba(255,235,170,.98)')
          : (lt ? 'background:rgba(0,0,0,.045);border:1px solid rgba(60,110,80,.28);color:rgba(45,85,60,.85)' : 'background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.15);color:rgba(255,255,255,.72)');
        return '<button onclick="event.stopPropagation();pReactNews('+i+',\''+rx.k+'\')" style="display:inline-flex;align-items:center;gap:4px;padding:5px 10px;border-radius:20px;cursor:pointer;font-family:Jost,sans-serif;font-size:10.5px;font-weight:700;-webkit-tap-highlight-color:transparent;'+css+'">'+rx.e+' '+rx.lbl+(n>0?' · '+n:'')+'</button>';
      }).join('')
    + '</div>';
}
function _paintNewsRxRows(){
  document.querySelectorAll('.news-rx-row').forEach(function(row){
    var key = row.getAttribute('data-nkey');
    var idx = -1;
    _newsListCache.forEach(function(it,i){ if(_newsKey(it.titulo)===key) idx = i; });
    if(idx >= 0){ var tmp = document.createElement('div'); tmp.innerHTML = _newsRxRowHtml(idx); row.replaceWith(tmp.firstChild); }
  });
}
async function _loadNewsReactions(){
  _initSupabase(); if(!sbClient || !_newsListCache.length) return;
  var uid = safeLS('get','velo_user_id')||'';
  var keys = _newsListCache.map(function(it){ return _newsKey(it.titulo); }).filter(Boolean);
  try{
    var r = await sbClient.from('news_reactions').select('news_key,reaction,user_id').in('news_key', keys);
    if(r.error) return; // tabla aún no creada → sin reacciones
    _newsRxData = {};
    (r.data||[]).forEach(function(x){
      var d = _newsRxData[x.news_key] = _newsRxData[x.news_key] || { counts:{}, mine:{} };
      d.counts[x.reaction] = (d.counts[x.reaction]||0)+1;
      if(uid && x.user_id === uid) d.mine[x.reaction] = true;
    });
    _paintNewsRxRows();
    // ── Top del día: la noticia con más reacciones HOY (mínimo 2) ──
    var today = new Date().toISOString().slice(0,10);
    var t = await sbClient.from('news_reactions').select('news_key,titulo,emoji_news').eq('date_key', today);
    var box = document.getElementById('newsTopOfDay');
    if(!t.error && t.data && t.data.length && box){
      var agg = {};
      t.data.forEach(function(x){
        var a = agg[x.news_key] = agg[x.news_key] || { n:0, titulo:x.titulo, emoji:x.emoji_news };
        a.n++;
        if(!a.titulo && x.titulo) a.titulo = x.titulo;
      });
      var top = Object.keys(agg).map(function(k){ return agg[k]; }).sort(function(a,b){ return b.n-a.n; })[0];
      if(top && top.n >= 2 && top.titulo){
        var lt2 = !document.body.classList.contains('r-dark');
        box.innerHTML = '<div style="margin-bottom:14px;padding:12px 15px;border-radius:16px;background:linear-gradient(140deg,rgba(196,152,52,'+(lt2?'.14':'.16')+'),rgba(196,152,52,.06));border:1.5px solid rgba(196,152,52,'+(lt2?'.45':'.38')+')">'
          + '<div style="font-size:10px;font-weight:800;letter-spacing:1.8px;text-transform:uppercase;color:'+(lt2?'rgba(140,100,20,.9)':'rgba(240,200,90,.9)')+';font-family:Jost,sans-serif;margin-bottom:5px">🌞 La que más alegró hoy</div>'
          + '<div style="display:flex;align-items:center;gap:9px">'
          + '<span style="font-size:24px;flex-shrink:0">'+_escHtml(top.emoji||'📰')+'</span>'
          + '<span style="flex:1;min-width:0;font-family:\'Cormorant Garamond\',serif;font-size:15.5px;font-weight:700;line-height:1.35;color:'+(lt2?'rgba(55,40,10,.94)':'rgba(255,245,215,.95)')+'">'+_escHtml(top.titulo)+'</span>'
          + '<span style="flex-shrink:0;font-size:11px;font-weight:800;color:'+(lt2?'rgba(140,100,20,.85)':'rgba(240,200,90,.85)')+';font-family:Jost,sans-serif">'+top.n+' 💛</span>'
          + '</div></div>';
      }
    }
  }catch(e){}
}
async function pReactNews(i, rxKey){
  var item = _newsListCache[i]; if(!item) return;
  _initSupabase();
  var uid = safeLS('get','velo_user_id')||'';
  if(!sbClient || !uid){ pToast('🌿','Iniciá sesión para reaccionar'); return; }
  var key = _newsKey(item.titulo);
  var d = _newsRxData[key] = _newsRxData[key] || { counts:{}, mine:{} };
  var today = new Date().toISOString().slice(0,10);
  if(d.mine[rxKey]){
    d.mine[rxKey] = false; d.counts[rxKey] = Math.max(0,(d.counts[rxKey]||1)-1);
    _paintNewsRxRows();
    try{ await sbClient.from('news_reactions').delete().eq('news_key',key).eq('user_id',uid).eq('reaction',rxKey); }catch(e){}
  } else {
    d.mine[rxKey] = true; d.counts[rxKey] = (d.counts[rxKey]||0)+1;
    _paintNewsRxRows();
    try{
      var r = await sbClient.from('news_reactions').insert({ news_key:key, titulo:(item.titulo||'').slice(0,200), emoji_news:item.emoji||'', reaction:rxKey, user_id:uid, date_key:today });
      if(r && r.error && String(r.error.code) !== '23505'){
        d.mine[rxKey] = false; d.counts[rxKey] = Math.max(0,(d.counts[rxKey]||1)-1);
        _paintNewsRxRows();
      }
    }catch(e){}
  }
}

var _newsListCache = [];
function pOpenNewsDetail(i){
  var item = _newsListCache[i];
  if(!item) return;
  _trackNewsRead(); // Feature 4: count this read
  var hasLink = item.sourceUrl && item.sourceUrl.startsWith('http');
  var _nd = new Date();
  var _cy2 = _nd.getFullYear();
  var _months = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  var _dateStr = _nd.getDate()+' de '+_months[_nd.getMonth()]+' de '+_cy2;
  var _detailNewsSearch = 'https://news.google.com/search?q='+encodeURIComponent((item.titulo||'')+' '+_cy2)+'&hl=es-419';
  var sourceRef = item.titulo
    ? '<a href="'+_escHtml(_detailNewsSearch)+'" target="_blank" rel="noopener noreferrer" style="font-size:14px;color:var(--sage2);font-weight:600;text-decoration:none;display:inline-flex;align-items:center;gap:4px">🔗 Buscar en Google News</a>'
    : '<span style="font-size:14px;color:var(--ink4);font-style:italic">✨ Historia de bienestar · Velo IA</span>';
  var sourceBlock = '<div style="display:flex;align-items:center;flex-wrap:wrap;gap:8px 12px;margin-bottom:18px;padding:10px 14px;background:rgba(116,198,157,.07);border-radius:10px;border:1px solid rgba(116,198,157,.18)">'
    +'<span style="font-size:14px;color:var(--ink4)">📅 '+_dateStr+'</span>'
    +'<span style="color:var(--ink5);font-size:14px">·</span>'
    +sourceRef
    +'</div>';
  // Feature 5: share buttons row
  var shareRow = '<div style="display:flex;gap:8px;margin-bottom:14px">'
    +'<button onclick="pShareNewsItem('+_jsAttr(item.titulo)+','+_jsAttr(item.cuerpo)+','+_jsAttr(item.sourceUrl||'')+')" style="flex:1;display:flex;align-items:center;justify-content:center;gap:6px;padding:11px;background:rgba(20,110,70,.78);border:1.5px solid rgba(116,198,157,.45);border-radius:14px;font-size:15px;font-weight:700;color:#fff;cursor:pointer;font-family:\'Jost\',sans-serif">📤 Compartir</button>'
    +'<button id="newsCopyBtn" onclick="pCopyNewsItem('+_jsAttr(item.titulo)+','+_jsAttr(item.cuerpo)+','+_jsAttr(item.sourceUrl||'')+',this)" style="flex:1;display:flex;align-items:center;justify-content:center;gap:6px;padding:11px;background:rgba(116,198,157,.08);border:1.5px solid rgba(116,198,157,.22);border-radius:14px;font-size:15px;font-weight:700;color:var(--ink3);cursor:pointer;font-family:\'Jost\',sans-serif">📋 Copiar</button>'
    +'</div>';
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'newsDetailOv';
  ov.innerHTML = '<div class="p-sheet" style="max-height:85vh;overflow-y:auto">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="font-size:52px;text-align:center;margin-bottom:12px">'+_escHtml(item.emoji||'📰')+'</div>'
    +'<h2 style="font-family:\'Cormorant Garamond\',serif;font-size:22px;font-weight:700;color:var(--ink);margin-bottom:14px;line-height:1.3;text-align:center">'+_escHtml(item.titulo)+'</h2>'
    +sourceBlock
    +'<p style="font-size:14px;color:var(--ink2);line-height:1.75;margin-bottom:20px">'+_escHtml(item.cuerpo)+'</p>'
    +'<div style="background:var(--sage7);border-radius:12px;padding:12px 14px;margin-bottom:20px">'
    +'<div style="font-size:13px;font-weight:700;color:var(--sage3);letter-spacing:.5px;margin-bottom:6px">✨ REFLEXIÓN VELO IA</div>'
    +'<p style="font-size:15px;color:var(--ink3);line-height:1.65;margin:0;font-style:italic">'+_escHtml(item.reflexion||'Cada buena noticia nos recuerda que el mundo avanza con esperanza.')+'</p>'
    +'</div>'
    +'<a href="'+_escHtml(_detailNewsSearch)+'" target="_blank" rel="noopener noreferrer" class="p-btn p-btn--secondary p-btn--lg p-btn--full" style="display:block;text-align:center;text-decoration:none;margin-bottom:12px;background:var(--sage7);border-color:rgba(116,198,157,.4);color:var(--sage2)">🔍 Buscar en Google News</a>'
    +shareRow
    +'<button class="p-btn p-btn--primary p-btn--lg p-btn--full" onclick="document.getElementById(\'newsDetailOv\').remove()">Cerrar</button>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
}

// ── ACOMPAÑANTE VELO IA ──────────────────────────────────────────
var _calmAIMsgs = [];
var _calmChipsShown = false;

// ── Calm AI: session memory (localStorage per day) ───────────────────
function _calmTodayKey(){
  var d = new Date();
  return 'velo_calm_'+d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function _saveCalmSession(){
  if(!_calmAIMsgs.some(function(m){ return m.user; })) return;
  safeLS('set', _calmTodayKey(), JSON.stringify(_calmAIMsgs.slice(-30)));
}
function _loadCalmSession(){
  try{ return JSON.parse(safeLS('get', _calmTodayKey())||'[]'); }catch(e){ return []; }
}

// ── Calm AI: mood context from today's mood log ───────────────────────
function _calmMoodContext(){
  var d = new Date();
  var dk = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  var stored = safeLS('get','velo_mood_'+dk);
  if(!stored) return null;
  try{ return JSON.parse(stored); }catch(e){ return null; }
}

// ── Calm AI: personalized greeting ───────────────────────────────────
function _calmGreeting(mood){
  var hour = new Date().getHours();
  var tg = hour < 12 ? 'Buenos días' : hour < 20 ? 'Buenas tardes' : 'Buenas noches';
  if(mood && mood.emoji){
    var desc = {'😄':'muy bien hoy','😊':'bien hoy','😐':'más o menos hoy','😞':'no tan bien hoy','😢':'bastante mal hoy'}[mood.emoji]||'de cierta manera hoy';
    var noteSnip = mood.note ? ' Me comentaste: "'+mood.note.slice(0,55)+(mood.note.length>55?'…':'')+'". ' : ' ';
    return tg+' 🌿 Vi que registraste que te sentís '+desc+'.'+noteSnip+'Estoy acá si querés contarme más, sin ningún apuro.';
  }
  var opts = [
    'Hola, estoy acá para acompañarte 🌿 ¿Cómo te sentís en este momento? Podés contarme lo que quieras, sin apuros.',
    tg+' 🌿 Me alegra que estés acá. ¿Cómo andás hoy?',
    'Hola 🌿 Este es tu espacio, sin juicios. ¿Qué te trajo por acá hoy?'
  ];
  var d = new Date();
  return opts[(d.getDate()+d.getHours())%opts.length];
}

// ── Calm AI: quick-start chips ────────────────────────────────────────
function _showCalmChips(){
  var msgEl = document.getElementById('calmAIMessages');
  if(!msgEl || _calmChipsShown) return;
  _calmChipsShown = true;
  var chips = [
    { label:'😰 Estoy ansioso/a',       text:'Estoy sintiendo mucha ansiedad' },
    { label:'😔 Me siento solo/a',       text:'Me siento muy solo/a últimamente' },
    { label:'😤 Tuve un día difícil',    text:'Tuve un día muy difícil' },
    { label:'😴 No puedo dormir',        text:'Tengo problemas para dormir' },
    { label:'💭 Solo quiero hablar',      text:'Quiero hablar y que alguien me escuche' }
  ];
  var wrap = document.createElement('div');
  wrap.id = 'calmChips';
  wrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;padding:6px 0 10px';
  wrap.innerHTML = chips.map(function(c){
    return '<button class="calm-chip" onclick="pCalmChipSend('+_jsAttr(c.text)+')">'+c.label+'</button>';
  }).join('');
  msgEl.appendChild(wrap);
  msgEl.scrollTop = msgEl.scrollHeight;
}
function pCalmChipSend(text){
  var chips = document.getElementById('calmChips');
  if(chips) chips.remove();
  var ta = document.getElementById('calmAIInput');
  if(ta){ ta.value = text; }
  pSendCalmAIMsg();
}

function _initCalmAIPage(){
  _calmChipsShown = false;
  var msgEl = document.getElementById('calmAIMessages');
  if(msgEl) msgEl.innerHTML = '';
  var ta = document.getElementById('calmAIInput');
  if(ta){ ta.value = ''; ta.style.height = ''; }

  var prevMsgs = _loadCalmSession();
  var hasUser = prevMsgs.some(function(m){ return m.user; });

  if(hasUser){
    // Offer to resume today's conversation
    var lastUser = prevMsgs.slice().reverse().find(function(m){ return m.user; });
    var _lt = lastUser ? (lastUser.text||'') : '';
    var snippet = _lt ? _escHtml(_lt.slice(0,65))+(_lt.length>65?'…':'') : '';
    var resumeDiv = document.createElement('div');
    resumeDiv.style.cssText = 'margin:16px 0 8px;padding:14px;background:rgba(116,198,157,.08);border:1px solid rgba(116,198,157,.22);border-radius:16px;text-align:center';
    resumeDiv.innerHTML = '<div style="font-size:13px;color:rgba(255,255,255,.45);margin-bottom:6px;letter-spacing:.3px">CONVERSACIÓN DE HOY</div>'
      +'<div style="font-size:14px;color:rgba(255,255,255,.6);font-style:italic;margin-bottom:12px;line-height:1.5">"'+snippet+'"</div>'
      +'<div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">'
      +'<button onclick="_calmResumeSession()" style="padding:9px 18px;background:rgba(116,198,157,.18);border:1.5px solid rgba(116,198,157,.38);border-radius:100px;font-size:14px;font-weight:700;color:rgba(116,198,157,.9);cursor:pointer;font-family:\'Jost\',sans-serif">↩️ Retomar conversación</button>'
      +'<button onclick="_calmStartFresh()" style="padding:9px 18px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:100px;font-size:14px;color:rgba(255,255,255,.45);cursor:pointer;font-family:\'Jost\',sans-serif">Empezar de nuevo</button>'
      +'</div>';
    if(msgEl) msgEl.appendChild(resumeDiv);
  } else {
    _calmStartFresh();
  }
}

function _calmStartFresh(){
  _calmAIMsgs = [];
  _calmChipsShown = false;
  var msgEl = document.getElementById('calmAIMessages');
  if(msgEl) msgEl.innerHTML = '';
  var mood = _calmMoodContext();
  var greeting = _calmGreeting(mood);
  setTimeout(function(){
    _calmAIAddMsg(greeting, false);
    setTimeout(_showCalmChips, 700);
  }, 400);
}

function _calmResumeSession(){
  var prevMsgs = _loadCalmSession();
  _calmAIMsgs = prevMsgs;
  _calmChipsShown = true;
  var msgEl = document.getElementById('calmAIMessages');
  if(msgEl) msgEl.innerHTML = '';
  prevMsgs.forEach(function(m){
    var div = document.createElement('div');
    div.innerHTML = _buildMsgBubble(m.text, m.user, '🌿', 'Acompañante Velo', 'calmAIInput', 'calmAIReplyBar', '');
    if(!m.user){
      var bubble = div.querySelector('.feed-bubble');
      if(bubble) bubble.innerHTML = bubble.innerHTML.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    }
    var child = div.firstElementChild;
    if(child && msgEl) msgEl.appendChild(child);
  });
  if(msgEl) msgEl.scrollTop = msgEl.scrollHeight;
  setTimeout(function(){
    _calmAIAddMsg('Seguimos donde lo dejamos 🌿 ¿Cómo te sentís ahora?', false);
  }, 350);
}

function _calmAIAddMsg(text, isUser){
  _calmAIMsgs.push({text:text, user:isUser});
  var msgEl = document.getElementById('calmAIMessages');
  if(!msgEl) return;
  var div = document.createElement('div');
  div.innerHTML = _buildMsgBubble(text, isUser, '🌿', 'Acompañante Velo', 'calmAIInput', 'calmAIReplyBar', '');
  if(!isUser){
    var bubble = div.querySelector('.feed-bubble');
    if(bubble) bubble.innerHTML = bubble.innerHTML.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  }
  var child = div.firstElementChild;
  if(child) msgEl.appendChild(child);
  msgEl.scrollTop = msgEl.scrollHeight;
}

async function _geminiChat(systemPrompt, msgs, cfg){
  // 1. Gemini proxy — primary (multi-turn chat)
  try{
    var pr = await fetch(GEMINI_PROXY, { method:'POST', headers:_aiHeaders(),
      body: JSON.stringify({ type:'chat', systemPrompt:systemPrompt, msgs:msgs, cfg:cfg||{} }) });
    if(pr.ok){ var t1 = _gText(await pr.json()); if(t1) return t1; }
    else { var e1={}; try{e1=await pr.json();}catch(x){} console.warn('[Velo] Gemini chat',pr.status,e1.error||''); }
  }catch(e){ console.warn('[Velo] Gemini chat error:',e.message); }
  // 2. Groq proxy — fallback multi-turn chat (llama-3.3-70b)
  try{
    var gr = await fetch(GROQ_PROXY, { method:'POST', headers:_aiHeaders(),
      body: JSON.stringify({ type:'chat', systemPrompt:systemPrompt, msgs:msgs, cfg:cfg||{} }) });
    if(gr.ok){ var t2 = _gText(await gr.json()); if(t2) return t2; }
  }catch(e){}
  // 3. Last resort: embed conversation as single generate prompt
  var convLines = msgs.slice(-8).map(function(m){
    return (m.user ? 'Usuario' : 'Acompañante Velo') + ': ' + m.text;
  });
  var fallbackPrompt = systemPrompt
    + '\n\nConversación hasta ahora:\n' + convLines.join('\n')
    + '\n\nAcompañante Velo (respondé en 2-3 oraciones, cálido y específico a lo que el usuario dijo):';
  return _geminiCall(fallbackPrompt, Object.assign({ temperature:0.88, maxOutputTokens:220 }, cfg||{}));
}

