var _sosCountry = null;

function _renderSOSResources(){
  var el = document.getElementById('sosResources');
  if(!el) return;

  var countries = Object.keys(_sosData);
  var selectedCountry = _sosCountry || countries[0];

  var selectorHtml = '<div style="margin-bottom:14px">'
    +'<label style="font-size:13px;font-weight:700;color:rgba(255,255,255,.45);letter-spacing:1px;display:block;margin-bottom:6px">SELECCIONÁ TU PAÍS</label>'
    +'<select id="sosCountrySel" onchange="pSosCountry(this.value)" tabindex="-1" style="width:100%;padding:10px 14px;background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.15);border-radius:12px;color:#fff;font-size:15px;font-weight:600;font-family:\'Jost\',sans-serif;cursor:pointer">'
    +countries.map(function(c){
      return '<option value="'+c+'" style="background:#0B1810;color:#fff"'+(c===selectedCountry?' selected':'')+'>'+c+'</option>';
    }).join('')
    +'</select>'
    +'</div>';

  var lines = _sosData[selectedCountry] || [];
  var linesHtml = lines.map(function(r){
    var isUrl = r.url.startsWith('http');
    return '<a href="'+r.url+'" '+(isUrl?'target="_blank" rel="noopener"':'')+' style="display:flex;align-items:center;justify-content:space-between;padding:12px 14px;background:rgba(192,48,40,.08);border:1px solid rgba(192,48,40,.18);border-radius:14px;margin-bottom:8px;text-decoration:none">'
      +'<div><div style="font-size:13px;font-weight:700;color:rgba(255,255,255,.45);margin-bottom:2px">'+r.label+'</div><div style="font-size:15px;color:#fff;font-weight:700">'+r.num+'</div></div>'
      +'<span style="font-size:20px">'+(isUrl?'🌐':'📞')+'</span>'
      +'</a>';
  }).join('');

  el.innerHTML = selectorHtml + linesHtml
    +'<div style="margin-top:14px;padding:12px;background:rgba(116,198,157,.06);border:1px solid rgba(116,198,157,.12);border-radius:12px;text-align:center">'
    +'<p style="font-size:13px;color:rgba(255,255,255,.4);line-height:1.5;margin:0">Esta información es de carácter informativo y se actualiza periódicamente. En caso de emergencia, contactá siempre al número de emergencias de tu país.</p>'
    +'</div>';
  // iOS Safari scrolls the sheet to the first focusable element (<select>) when it's injected.
  // Reset scrollTop immediately and again after the next paint so the header stays visible.
  var _sheet = document.querySelector('#sosOv .p-sheet');
  if(_sheet){
    _sheet.scrollTop = 0;
    requestAnimationFrame(function(){ _sheet.scrollTop = 0; });
    setTimeout(function(){ _sheet.scrollTop = 0; }, 80);
  }
}

function pSosCountry(country){
  _sosCountry = country;
  _renderSOSResources();
}

// ── BOTTLE WALL ────────────────────────────────────────────────
var _bottleMoods = ['😰','😢','😤','😔','🤗','💭','😊','🌊'];

function pBottleTab(tab, btn){
  document.querySelectorAll('.bottle-tab').forEach(function(b){ b.classList.remove('active'); });
  if(btn) btn.classList.add('active');
  var listEl = document.getElementById('bottleList');
  var respEl = document.getElementById('bottleRespList');
  if(tab === 'mar'){
    if(listEl) listEl.style.display = '';
    if(respEl) respEl.style.display = 'none';
  } else {
    if(listEl) listEl.style.display = 'none';
    if(respEl){
      respEl.style.display = '';
      pRenderBottleResponses();
    }
  }
}

async function pRenderBottleResponses(){
  var el = document.getElementById('bottleRespList');
  if(!el) return;

  // Only show bottles YOU replied to — responses to your own go to Buzón Velo
  var cutoff24h = Date.now() - 24*3600*1000;
  var replied = []; try{ replied = JSON.parse(safeLS('get','velo_bottles_replied')||'[]'); }catch(e){}
  // Remove expired entries (> 24h) and persist
  replied = replied.filter(function(r){ return r.ts && r.ts > cutoff24h; });
  safeLS('set','velo_bottles_replied', JSON.stringify(replied));

  if(!replied.length){
    el.innerHTML = '<div class="p-empty"><span class="p-empty-emoji">💬</span>'
      +'<div class="p-empty-title" style="color:var(--ink2)">Aún no respondiste mensajes</div>'
      +'<div class="p-empty-sub">Cuando respondas un mensaje del mar, aparecerá aquí 🌊</div></div>';
    return;
  }

  el.innerHTML = replied.map(function(r){
    var relTime = (function(){
      var d = Date.now()-r.ts;
      if(d<3600000) return 'hace '+Math.floor(d/60000)+'min';
      return 'hace '+Math.floor(d/3600000)+'h';
    })();
    var expireMin = Math.round((r.ts + 24*3600*1000 - Date.now()) / 60000);
    var expireLabel = expireMin > 60 ? Math.floor(expireMin/60)+'h' : expireMin+'min';
    var authorName = r.authorName || 'Anónimo';
    var avHtml = _avInline(r.authorAv||'🌊', 28);
    var authorClick = r.authorId ? 'onclick="pQuickProfile('+_jsAttr(r.authorName)+','+_jsAttr(r.authorAv||'🧑')+',\'\',\'\','+_jsAttr(r.authorId||'')+')" style="cursor:pointer"' : '';
    var myName = safeLS('get','velo_user_name')||'Vos';
    var myAv = safeLS('get','velo_user_av')||'🌿';
    return '<div class="dark-bottle bottle-replied-card" style="border-left:3px solid rgba(80,150,200,.35);padding:14px 14px 12px">'
      // Header
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
      +'<span style="font-size:12px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:rgba(80,150,200,.75);font-family:\'Jost\',sans-serif">💬 Conversación</span>'
      +'<span class="bottle-replied-meta">'+relTime+' · expira en '+expireLabel+'</span>'
      +'</div>'
      // Their message — left bubble
      +'<div style="display:flex;gap:9px;align-items:flex-start;margin-bottom:10px">'
      +'<div '+authorClick+'>'+avHtml+'</div>'
      +'<div style="flex:1;background:rgba(80,150,200,.09);border:1px solid rgba(80,150,200,.20);border-radius:0 14px 14px 14px;padding:10px 13px">'
      +'<div style="font-size:12px;font-weight:700;color:rgba(80,150,200,.80);font-family:\'Jost\',sans-serif;margin-bottom:5px">🌊 '+_escHtml(authorName)+'</div>'
      +'<div style="font-size:15px;font-family:\'Cormorant Garamond\',serif;font-style:italic;color:var(--ink);line-height:1.55">"'+(r.preview?_escHtml(r.preview.slice(0,160)+(r.preview.length>160?'…':'')):'')+'"</div>'
      +'</div>'
      +'</div>'
      // My reply — right bubble
      +'<div style="display:flex;gap:9px;align-items:flex-start;flex-direction:row-reverse">'
      +_avInline(myAv, 28)
      +'<div style="flex:1;background:rgba(116,198,157,.12);border:1px solid rgba(116,198,157,.25);border-radius:14px 0 14px 14px;padding:10px 13px;text-align:right">'
      +'<div style="font-size:12px;font-weight:700;color:rgba(116,198,157,.80);font-family:\'Jost\',sans-serif;margin-bottom:5px">'+_escHtml(myName)+' (vos) 💚</div>'
      +'<div style="font-size:15px;color:var(--ink);line-height:1.55">'+_escHtml(r.reply||'')+'</div>'
      +'</div>'
      +'</div>'
      +'</div>';
  }).join('');
}

function pDeleteBottleResponse(broadcastId, cardEl){
  _pConfirm('¿Eliminar esta respuesta?', async function(){
    if(cardEl){ cardEl.style.transition='opacity .3s'; cardEl.style.opacity='0'; setTimeout(function(){ if(cardEl.parentNode) cardEl.parentNode.removeChild(cardEl); },350); }
    _initSupabase();
    if(sbClient && broadcastId){
      try{ await sbClient.from('broadcasts').delete().eq('id', broadcastId); }catch(e){}
    }
    var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
    inbox = inbox.filter(function(m){ return m.id !== broadcastId; });
    safeLS('set','velo_inbox', JSON.stringify(inbox));
    pToast('🗑️','Respuesta eliminada');
  });
}

async function _loadGuardianStats(){
  var el = document.getElementById('guardianStatsBar');
  if(!el || !sbClient) return;
  try{
    var [r1, r2] = await Promise.all([
      sbClient.from('help_posts').select('id', {count:'exact',head:true}),
      sbClient.from('help_posts').select('id', {count:'exact',head:true}).eq('taken',true)
    ]);
    var total  = (r1 && r1.count != null) ? r1.count : '—';
    var helped = (r2 && r2.count != null) ? r2.count : '—';
    el.textContent = '🕊️ '+total+' ayudas solicitadas · 💚 '+helped+' personas acompañadas';
    el.style.display = 'block';
  }catch(e){}
}

async function _loadBottleStats(){
  var el = document.getElementById('bottleStatsBar');
  if(!el || !sbClient) return;
  try{
    var since = new Date(Date.now() - 24*3600*1000).toISOString();
    var results = await Promise.all([
      sbClient.from('bottles').select('id', {count:'exact',head:true}).gte('created_at', since),
      sbClient.from('bottle_replies').select('id', {count:'exact',head:true}).gte('created_at', since),
      sbClient.from('bottle_reactions').select('id', {count:'exact',head:true}).gte('created_at', since),
    ]);
    var bottles = (results[0] && results[0].count != null) ? results[0].count : 0;
    var replies = (results[1] && !results[1].error && results[1].count != null) ? results[1].count : 0;
    var reacts  = (results[2] && !results[2].error && results[2].count != null) ? results[2].count : 0;
    var isLight = !document.body.classList.contains('r-dark');
    // Fondos sólidos para leer bien sobre imagen de fondo (light mode) o dark
    var pillBg  = isLight ? 'rgba(255,255,255,.92)' : 'rgba(20,45,72,.90)';
    var pillBrd = isLight ? 'rgba(65,155,222,.55)'  : 'rgba(140,205,255,.55)';
    var textCol = isLight ? 'rgba(12,58,138,.94)'   : 'rgba(220,240,255,.96)';
    var strongCol = isLight ? 'rgba(8,32,88,1)'     : 'rgba(255,255,255,1)';
    var sepCol  = isLight ? 'rgba(30,90,128,.35)'   : 'rgba(220,240,255,.30)';
    el.innerHTML = '<span style="display:inline-flex;gap:14px;padding:9px 18px;background:'+pillBg+';border:1.5px solid '+pillBrd+';border-radius:100px;font-weight:800;font-family:Jost,sans-serif;font-size:12.5px;color:'+textCol+';align-items:center;box-shadow:0 4px 16px rgba(65,155,222,.20);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)">'
      + '<span>🌊 <strong style="color:'+strongCol+'">'+bottles+'</strong> hoy</span>'
      + '<span style="color:'+sepCol+'">·</span>'
      + '<span>💌 <strong style="color:'+strongCol+'">'+replies+'</strong> respuestas</span>'
      + '<span style="color:'+sepCol+'">·</span>'
      + '<span>💛 <strong style="color:'+strongCol+'">'+reacts+'</strong> abrazos</span>'
      + '</span>';
    el.style.display = 'block';
    el.style.textAlign = 'center';
    el.style.padding = '0 0 12px';
  }catch(e){}
}

function _bottleEmojiColor(mood){
  var warm=['🤗','😊','🥰','😄','🎉','💛','☀️','🌻'];
  var sad=['😢','😔','😰','😤','😞','😖','💔','🫂'];
  var anx=['😬','😨','😥','😣','🤯','😓'];
  if(warm.indexOf(mood)>=0) return {bg:'rgba(52,28,4,.94)',border:'rgba(222,162,36,.85)',glow:'rgba(222,162,36,.30)',strip:'rgba(222,162,36,.45)',label:'rgba(255,220,75,.97)'};
  if(sad.indexOf(mood)>=0)  return {bg:'rgba(8,12,52,.94)',border:'rgba(110,128,228,.82)',glow:'rgba(110,128,228,.28)',strip:'rgba(110,128,228,.45)',label:'rgba(168,182,255,.97)'};
  if(anx.indexOf(mood)>=0)  return {bg:'rgba(38,8,38,.94)',border:'rgba(192,80,200,.80)',glow:'rgba(192,80,200,.26)',strip:'rgba(192,80,200,.42)',label:'rgba(245,168,255,.97)'};
  if(mood==='🌊')           return {bg:'rgba(4,24,52,.94)',border:'rgba(65,158,222,.82)',glow:'rgba(65,158,222,.28)',strip:'rgba(65,158,222,.45)',label:'rgba(140,210,255,.97)'};
  return                           {bg:'rgba(8,28,20,.94)',border:'rgba(72,185,128,.80)',glow:'rgba(72,185,128,.26)',strip:'rgba(72,185,128,.42)',label:'rgba(120,240,185,.97)'};
}
function _bottleEmojiColorLight(mood){
  var warm=['🤗','😊','🥰','😄','🎉','💛','☀️','🌻'];
  var sad=['😢','😔','😰','😤','😞','😖','💔','🫂'];
  var anx=['😬','😨','😥','😣','🤯','😓'];
  if(warm.indexOf(mood)>=0) return {bg:'rgba(255,246,210,.97)',border:'rgba(200,148,28,.55)',glow:'rgba(200,148,28,.16)',strip:'rgba(200,148,28,.22)',label:'rgba(85,52,0,.90)'};
  if(sad.indexOf(mood)>=0)  return {bg:'rgba(218,225,255,.97)',border:'rgba(90,112,220,.55)',glow:'rgba(90,112,220,.16)',strip:'rgba(90,112,220,.22)',label:'rgba(28,42,148,.90)'};
  if(anx.indexOf(mood)>=0)  return {bg:'rgba(248,220,255,.97)',border:'rgba(170,65,185,.55)',glow:'rgba(170,65,185,.16)',strip:'rgba(170,65,185,.22)',label:'rgba(88,18,108,.90)'};
  if(mood==='🌊')           return {bg:'rgba(218,238,255,.97)',border:'rgba(48,142,215,.55)',glow:'rgba(48,142,215,.16)',strip:'rgba(48,142,215,.22)',label:'rgba(12,58,138,.90)'};
  return                          {bg:'rgba(212,248,232,.97)',border:'rgba(50,168,112,.55)',glow:'rgba(50,168,112,.16)',strip:'rgba(50,168,112,.22)',label:'rgba(8,72,40,.90)'};
}

// Filtro activo del feed de Al Mar
var _bottleFilter = '';
var _BOTTLE_REACTIONS = [
  {k:'heart', e:'💛', lbl:'abrazo'},
  {k:'olive', e:'🌿', lbl:'con vos'},
  {k:'dove',  e:'🕊️', lbl:'paz'},
];
function pFilterBottleFeed(emoji, btn){
  _bottleFilter = (emoji===_bottleFilter) ? '' : emoji; // toggle
  pRenderBottle(); // re-render aplica el estilo activo con colores adaptados
}
// Modal para ver todas las respuestas recibidas en una botella mía
async function pViewMyBottleReplies(bottleId){
  _initSupabase();
  var uid = safeLS('get','velo_user_id') || '';
  if(!uid || !sbClient){ pToast('⚠️','Sin conexión'); return; }
  var ex = document.getElementById('bottleRepliesOv'); if(ex) ex.remove();
  var ov = document.createElement('div');
  ov.id = 'bottleRepliesOv';
  ov.style.cssText = 'position:fixed;inset:0;z-index:10001;background:rgba(0,0,0,.82);display:flex;align-items:flex-end;justify-content:center;padding:0';
  ov.onclick = function(e){ if(e.target===ov) ov.remove(); };
  ov.innerHTML = '<div style="background:linear-gradient(155deg,rgba(10,28,48,.98),rgba(6,18,32,.98));border-radius:28px 28px 0 0;width:100%;max-width:560px;max-height:88vh;overflow-y:auto;padding:14px 18px max(20px,env(safe-area-inset-bottom));border-top:2px solid rgba(65,155,222,.42)">'
    + '<div style="display:flex;justify-content:center;padding:0 0 12px"><div style="width:40px;height:4px;background:rgba(140,205,255,.32);border-radius:2px"></div></div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">'
      + '<div><div style="font-size:11px;font-weight:800;letter-spacing:2.5px;text-transform:uppercase;color:rgba(140,205,255,.72);font-family:Jost,sans-serif">🌊 RESPUESTAS AL MAR</div>'
      + '<div style="font-family:\'Cormorant Garamond\',serif;font-size:22px;color:rgba(230,245,255,.98);margin-top:2px">Palabras para vos</div></div>'
      + '<button onclick="document.getElementById(\'bottleRepliesOv\').remove()" style="background:none;border:none;color:rgba(255,255,255,.50);font-size:22px;cursor:pointer;padding:4px 10px">✕</button>'
    + '</div>'
    + '<div id="bottleRepliesList" style="min-height:120px"><p style="text-align:center;color:rgba(180,220,240,.55);font-family:Jost,sans-serif;padding:24px 0">Cargando respuestas…</p></div>'
    + '</div>';
  document.body.appendChild(ov);
  try{
    // Buscar broadcasts con el marker [bid:XXX] de esta botella
    var res = await sbClient.from('broadcasts')
      .select('id,body,sender,sent_at,created_at,read_at')
      .eq('target', 'user:'+uid)
      .ilike('body', '%[bid:'+bottleId+']%')
      .order('created_at', {ascending: false})
      .limit(100);
    var listEl = document.getElementById('bottleRepliesList');
    if(!listEl) return;
    if(res.error || !res.data || !res.data.length){
      listEl.innerHTML = '<div style="text-align:center;padding:36px 20px"><div style="font-size:42px;margin-bottom:10px">🌿</div><div style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:rgba(230,245,255,.85);margin-bottom:6px">Todavía sin respuestas</div><div style="font-size:12.5px;color:rgba(180,220,240,.55);font-family:Jost,sans-serif;line-height:1.5">Las respuestas aparecen acá cuando alguien te escribe.<br>Las viejas respuestas quedan en tu buzón 💌</div></div>';
      return;
    }
    listEl.innerHTML = res.data.map(function(r){
      // Extraer texto de respuesta del body: entre '💬 Respuesta:\n"..."'
      var replyText = '';
      var m = String(r.body||'').match(/💬 Respuesta:\s*\n?"([^"]+)"/);
      if(m) replyText = m[1];
      else replyText = String(r.body||'').replace(/\[bid:[^\]]+\]/,'').trim();
      // Extraer sender info
      var senderName = 'Anónimo', senderAv = '🌊';
      try{
        if(r.sender && r.sender.startsWith('{')){
          var s = JSON.parse(r.sender);
          senderName = s.n || 'Anónimo';
          senderAv = s.a || '🌊';
        }
      }catch(e){}
      var ts = r.sent_at || r.created_at;
      var relTime = '';
      if(ts){
        var diff = Date.now() - new Date(ts).getTime();
        var m2 = Math.floor(diff/60000);
        if(m2 < 60) relTime = 'hace '+m2+' min';
        else if(m2 < 1440) relTime = 'hace '+Math.floor(m2/60)+'h';
        else relTime = 'hace '+Math.floor(m2/1440)+'d';
      }
      var avHtml = senderAv.startsWith('http') || senderAv.startsWith('data:')
        ? '<img src="'+_escHtml(senderAv)+'" style="width:34px;height:34px;border-radius:50%;object-fit:cover;flex-shrink:0;border:1.5px solid rgba(65,155,222,.45)">'
        : '<div style="width:34px;height:34px;border-radius:50%;background:rgba(65,155,222,.18);border:1.5px solid rgba(65,155,222,.45);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0">'+_escHtml(senderAv)+'</div>';
      return '<div style="background:rgba(65,155,222,.10);border:1px solid rgba(65,155,222,.24);border-left:3px solid rgba(140,205,255,.65);border-radius:14px;padding:12px 14px;margin-bottom:10px">'
        + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">'
          + avHtml
          + '<div style="flex:1;min-width:0">'
            + '<div style="font-size:13px;font-weight:800;color:rgba(220,240,255,.94);font-family:Jost,sans-serif">'+_escHtml(senderName)+'</div>'
            + '<div style="font-size:11px;color:rgba(180,220,240,.55);font-family:Jost,sans-serif">'+relTime+'</div>'
          + '</div>'
        + '</div>'
        + '<p style="font-size:14px;color:rgba(220,240,255,.90);line-height:1.55;margin:0;font-family:\'Cormorant Garamond\',serif;font-style:italic">"'+_escHtml(replyText)+'"</p>'
      + '</div>';
    }).join('');
  }catch(e){
    var lel = document.getElementById('bottleRepliesList');
    if(lel) lel.innerHTML = '<p style="text-align:center;color:rgba(255,180,180,.85);font-family:Jost,sans-serif;padding:24px 0">Error cargando las respuestas</p>';
  }
}

async function pReactBottle(bottleId, reaction){
  _initSupabase();
  var uid = safeLS('get','velo_user_id') || '';
  if(!uid){ pToast('⚠️','Iniciá sesión para reaccionar'); return; }
  if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  // Feedback visual inmediato (antes del server round-trip)
  try{
    var _srcBtn = event && event.currentTarget;
    if(_srcBtn){
      _srcBtn.classList.remove('velo-bounce-tap');
      void _srcBtn.offsetWidth; // reflow
      _srcBtn.classList.add('velo-bounce-tap');
      var em = _BOTTLE_REACTIONS.find(function(r){ return r.k===reaction; });
      if(em) veloHeartFloat(_srcBtn, em.e);
    }
  }catch(e){}
  try{
    var ex = await sbClient.from('bottle_reactions')
      .select('id').eq('bottle_id', bottleId).eq('user_id', uid).eq('reaction', reaction).maybeSingle();
    if(ex && ex.data){
      await sbClient.from('bottle_reactions').delete().eq('id', ex.data.id);
    } else {
      var ins = await sbClient.from('bottle_reactions').insert({ bottle_id: bottleId, user_id: uid, reaction: reaction });
      if(ins.error){ pToast('⚠️','Falta la tabla bottle_reactions — correr el SQL'); return; }
      var em2 = _BOTTLE_REACTIONS.find(function(r){ return r.k===reaction; });
      pToast(em2 ? em2.e : '💚', '¡'+(em2?em2.lbl:'reacción')+' enviado!');
    }
    pRenderBottle();
  }catch(e){ console.warn('[bottle-react]', e); }
}

async function pRenderBottle(){
  var _tok = _navToken;
  _renderFavWidget('bottleFavWidget');
  var moodRow = document.getElementById('bottleMoodRow');
  if(moodRow) moodRow.innerHTML = _bottleMoods.map(function(m){
    return '<button style="font-size:22px;padding:7px;border:2px solid transparent;border-radius:10px;background:none;cursor:pointer;transition:all .15s" onclick="pSelBottleMood(this,\''+m+'\')" data-mood="'+m+'">'+m+'</button>';
  }).join('');

  var list = document.getElementById('bottleList');
  if(!list) return;

  var allBottles, usingSB = false;
  var myId = safeLS('get','velo_user_id')||safeLS('get','velo_user_email')||'';
  // Load stats
  _loadBottleStats();
  // Show all bottles — stay visible after reply so multiple people can respond
  var cutoff24h = new Date(Date.now() - 24*3600*1000).toISOString();
  var sbRows = await _sbLoad('bottles', function(q){
    return q.gte('created_at', cutoff24h).order('created_at',{ascending:false}).limit(60);
  });
  if(_navToken !== _tok) return;
  if(sbRows !== null){
    usingSB = true;
    allBottles = sbRows.map(_sbBottleRow);
    // Purge LS bottles that: (a) are older than 24h, or (b) belong to a different userId (old sessions)
    var myBottlesLS = []; try{ myBottlesLS = JSON.parse(safeLS('get','velo_my_bottles')||'[]'); }catch(e){}
    var cutoff24hMs = Date.now() - 24*3600*1000;
    var cleanedLS = myBottlesLS.filter(function(b){ return b.ts > cutoff24hMs && (!b.userId || b.userId === myId); });
    if(cleanedLS.length !== myBottlesLS.length) safeLS('set','velo_my_bottles', JSON.stringify(cleanedLS));
    myBottlesLS = cleanedLS;
    var sbIds = allBottles.reduce(function(s,b){ s[b.id]=1; return s; }, {});
    myBottlesLS.forEach(function(b){ if(!sbIds[b.id] && b.ts > Date.now()-24*3600*1000) allBottles.unshift(b); });
  } else {
    // Fallback: localStorage + mock data
    var mockBottles = [
      { id:'mb1', mood:'😔', text:'A veces el silencio duele más que las palabras.',            color:'rgba(116,198,157,.12)',   ts: Date.now()-3*60000   },
      { id:'mb2', mood:'💭', text:'¿Alguien más siente que no encaja en ningún lado?',           color:'rgba(200,165,100,.08)',   ts: Date.now()-8*60000   },
      { id:'mb3', mood:'😢', text:'Hoy recordé a alguien que ya no está. Lo extraño tanto.',     color:'rgba(196,181,232,.12)',   ts: Date.now()-15*60000  },
      { id:'mb4', mood:'🤗', text:'Para quien lo necesite: no estás solo/a. Esto también pasa.', color:'rgba(116,198,157,.1)',    ts: Date.now()-22*60000  }
    ];
    var responded = []; try{ responded = JSON.parse(safeLS('get','velo_bottles_replied')||'[]'); }catch(e){}
    var filteredMock = mockBottles.filter(function(b){ return responded.indexOf(b.id) < 0; });
    var myBottles = []; try{ myBottles = JSON.parse(safeLS('get','velo_my_bottles')||'[]'); }catch(e){}
    allBottles = myBottles.concat(filteredMock);
  }

  // Mark (but do NOT hide) already-replied bottles — they stay visible, styled differently
  // Replied bottles remain so multiple users can respond; user just can't reply again

  // Batch-fetch usernames for non-anon bottle authors not yet cached
  if(sbClient){ var _bUnknown = allBottles.filter(function(b){ return !b.anon && b.userId && !_uLook(b.userId); }).map(function(b){ return b.userId; }); if(_bUnknown.length){ try{ var _br = await sbClient.from('profiles').select('id,username').in('id',_bUnknown); if(_br.data) _br.data.forEach(function(p){ _uFill(p.id,p.username); }); }catch(e){} } }

  // ── FILTROS por emoción — colores adaptados al tema ──
  var isLightBottle = !document.body.classList.contains('r-dark');
  // Fondos sólidos con blur para leer bien sobre imagen de fondo
  var _chipActiveBg    = isLightBottle ? 'rgba(65,155,222,.92)'  : 'rgba(140,205,255,.85)';
  var _chipActiveBrd   = isLightBottle ? 'rgba(30,90,138,1)'     : 'rgba(220,240,255,1)';
  var _chipActiveCol   = isLightBottle ? 'rgba(255,255,255,1)'   : 'rgba(12,42,88,1)';
  var _chipInactiveBg  = isLightBottle ? 'rgba(255,255,255,.85)' : 'rgba(20,45,72,.75)';
  var _chipInactiveBrd = isLightBottle ? 'rgba(65,155,222,.55)'  : 'rgba(180,220,255,.55)';
  var _chipInactiveCol = isLightBottle ? 'rgba(12,58,138,.94)'   : 'rgba(220,240,255,.94)';
  // Detectar emojis presentes para armar chips dinámicos
  var moodSet = {};
  allBottles.forEach(function(b){ if(b.mood) moodSet[b.mood] = (moodSet[b.mood]||0)+1; });
  var topMoods = Object.keys(moodSet).sort(function(a,b){ return moodSet[b] - moodSet[a]; }).slice(0,7);
  function _chipStyle(active){
    return 'flex-shrink:0;padding:7px 14px;background:'+(active?_chipActiveBg:_chipInactiveBg)+';border:1.5px solid '+(active?_chipActiveBrd:_chipInactiveBrd)+';border-radius:100px;color:'+(active?_chipActiveCol:_chipInactiveCol)+';font-size:13px;font-weight:800;cursor:pointer;font-family:Jost,sans-serif;letter-spacing:.2px;box-shadow:0 2px 8px rgba(65,155,222,'+(active?'.25':'.15')+');backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)';
  }
  var filterChipsHtml = '<div id="bottleFilterChips" style="display:flex;gap:6px;overflow-x:auto;padding:2px 0 12px;-webkit-overflow-scrolling:touch;scrollbar-width:none">'
    + '<button data-filter="" onclick="pFilterBottleFeed(\'\',this)" style="'+_chipStyle(_bottleFilter==='')+'">Todos</button>'
    + topMoods.map(function(em){
        var active = _bottleFilter === em;
        return '<button data-filter="'+em+'" onclick="pFilterBottleFeed(\''+em+'\',this)" style="'+_chipStyle(active)+'">'+em+' <span style="font-size:11.5px;opacity:.72;font-weight:700">'+moodSet[em]+'</span></button>';
      }).join('')
    + '</div>';

  // Aplicar filtro (después de armar los chips para que muestren todos los emojis, no solo los filtrados)
  var filteredBottles = _bottleFilter ? allBottles.filter(function(b){ return b.mood === _bottleFilter; }) : allBottles;

  if(!filteredBottles.length){
    var emptyMsg = _bottleFilter
      ? '<div class="p-empty"><span class="p-empty-emoji">'+_bottleFilter+'</span><div class="p-empty-title">Nada acá todavía</div><div class="p-empty-sub">Probá otro filtro o dejalo en Todos</div></div>'
      : '<div class="p-empty"><span class="p-empty-emoji">🌊</span><div class="p-empty-title">El mar está tranquilo</div><div class="p-empty-sub">Sé el primero en lanzar un mensaje</div></div>';
    list.innerHTML = filterChipsHtml + emptyMsg;
    return;
  }

  // ── REACCIONES y RESPUESTAS: batch fetch para todas las botellas visibles ─
  var reactionsByBottle = {}; // { bottleId: { heart:{count:N,mine:bool}, olive:{...}, dove:{...} } }
  var repliesByBottle = {}; // { bottleId: count }
  if(sbClient && filteredBottles.length){
    try{
      var bIds = filteredBottles.map(function(b){ return b.id; }).filter(Boolean);
      var myUid = safeLS('get','velo_user_id') || '';
      var [reactRes, replyRes] = await Promise.all([
        sbClient.from('bottle_reactions').select('bottle_id,reaction,user_id').in('bottle_id', bIds),
        sbClient.from('bottle_replies').select('bottle_id').in('bottle_id', bIds),
      ]);
      if(reactRes && !reactRes.error && reactRes.data){
        reactRes.data.forEach(function(r){
          if(!reactionsByBottle[r.bottle_id]) reactionsByBottle[r.bottle_id] = {};
          if(!reactionsByBottle[r.bottle_id][r.reaction]) reactionsByBottle[r.bottle_id][r.reaction] = {count:0, mine:false};
          reactionsByBottle[r.bottle_id][r.reaction].count++;
          if(r.user_id === myUid) reactionsByBottle[r.bottle_id][r.reaction].mine = true;
        });
      }
      if(replyRes && !replyRes.error && replyRes.data){
        replyRes.data.forEach(function(r){ repliesByBottle[r.bottle_id] = (repliesByBottle[r.bottle_id]||0) + 1; });
      }
    }catch(e){ console.warn('[bottle-reactions-fetch]', e); }
  }

  list.innerHTML = filterChipsHtml + filteredBottles.map(function(b, i){
    var relTime = b.ts ? (function(){
      var tl = b.ts + 24*3600*1000 - Date.now();
      if(tl <= 0) return 'expirado';
      var mins = Math.floor(tl/60000);
      if(mins < 60) return '⏳ '+mins+'min restantes';
      var hrs = Math.floor(mins/60); var rem = mins%60;
      return '⏳ '+(rem ? hrs+'h '+rem+'min' : hrs+'h')+' restantes';
    })() : '⏳ 24h restantes';
    var isOwn = myId && (b.userId||'') === myId;
    var alreadyReplied = safeLS('get','velo_bottle_replied_'+b.id) === '1';
    var actions;
    var _isLightBottle=!document.body.classList.contains('r-dark');
    var _ownMsgColor=_isLightBottle?'rgba(0,0,0,.45)':'rgba(255,255,255,.45)';
    var _delBtnColor=_isLightBottle?'rgba(180,20,20,.85)':'rgba(255,140,140,.90)';
    var _replyTextColor=_isLightBottle?'rgba(12,58,138,.90)':'rgba(160,215,255,.96)';
    if(isOwn){
      var _myReplyCount = repliesByBottle[b.id] || 0;
      var _seeReplyBtn = _myReplyCount > 0
        ? '<button style="padding:5px 12px;background:rgba(65,155,222,.20);border:1.5px solid rgba(65,155,222,.55);border-radius:100px;color:'+_replyTextColor+';font-size:13px;font-weight:800;cursor:pointer;font-family:\'Jost\',sans-serif;box-shadow:0 2px 10px rgba(65,155,222,.20)" onclick="pViewMyBottleReplies(\''+b.id+'\')">💬 Ver '+_myReplyCount+' respuesta'+(_myReplyCount===1?'':'s')+'</button>'
        : '';
      actions = '<div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap;justify-content:flex-end">'
        +'<span style="font-size:13px;color:'+_ownMsgColor+';font-style:italic;font-family:\'Jost\',sans-serif">Tu mensaje 🌊</span>'
        +_seeReplyBtn
        +'<button data-del-btn="1" style="padding:4px 10px;background:rgba(220,50,50,.14);border:1.5px solid rgba(220,50,50,.32);border-radius:100px;color:'+_delBtnColor+';font-size:13px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif" onclick="pDeleteBottle(\''+b.id+'\')">🗑️</button>'
        +'</div>';
    } else {
      actions = '<div style="display:flex;gap:7px;align-items:center">'
        +'<button style="padding:5px 11px;background:rgba(200,50,50,.14);border:1.5px solid rgba(200,50,50,.32);border-radius:100px;color:rgba(190,30,30,.88);font-size:13px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif" onclick="pReportBottle(\''+b.id+'\')">🚩 Reportar</button>'
        +(alreadyReplied
          ? '<span style="font-size:13px;color:rgba(116,198,157,.85);font-weight:700;font-family:\'Jost\',sans-serif">💛 Ya respondiste</span>'
          : '<button style="padding:5px 14px;background:rgba(65,155,222,.22);border:1.5px solid rgba(65,155,222,.55);border-radius:100px;color:'+_replyTextColor+';font-size:13px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif;box-shadow:0 2px 10px rgba(65,155,222,.20)" onclick="pOpenBottleReply('+_jsAttr(b.id)+','+_jsAttr(b.text.substring(0,120))+','+_jsAttr(b.userId||b.user_id||'')+','+_jsAttr(b.anon?'':''+( b.userName||''))+','+_jsAttr(b.anon?'':''+( b.userAv||''))+')">💌 Responder</button>')
        +'</div>';
    }
    var isLight=!document.body.classList.contains('r-dark');
    var showAuthor = !b.anon && b.userName && !isOwn;
    var bCol = isLight ? _bottleEmojiColorLight(b.mood||'🌊') : _bottleEmojiColor(b.mood||'🌊');
    var _bav = b.userAv || '';
    var bAvHasImg = _bav && (_bav.startsWith('http')||_bav.startsWith('data:'));
    var bAvIsEmoji = _bav && !bAvHasImg;
    var myName = safeLS('get','velo_user_name') || '';
    var anonColor = isLight?'rgba(0,0,0,.42)':'rgba(255,255,255,.38)';
    var bodyTextColor = isLight?bCol.label:'rgba(255,255,255,.93)';
    var avCircleBg = isLight?'rgba(0,0,0,.06)':'rgba(255,255,255,.10)';
    var cardBorder = isLight?bCol.border.replace(/[\d.]+\)$/,'.30)'):'rgba(255,255,255,.07)';
    var authorNameHtml;
    if(isOwn){
      if(b.anon){
        // Publiqué anónimo → mismo texto que otros ven ('Anónimo/a').
        // La ownership ya está clara por el 'Tu mensaje 🌊' y el 🗑️ abajo.
        authorNameHtml = '<span style="font-size:13px;font-weight:800;color:'+anonColor+';letter-spacing:.2px">Anónimo/a</span>';
      } else {
        authorNameHtml = '<span style="font-size:13px;font-weight:700;color:'+bCol.label+'">'+(myName||'Tú')+'</span>';
      }
    } else if(showAuthor){
      authorNameHtml = (bAvHasImg
        ? '<img src="'+_escHtml(_bav)+'" style="width:15px;height:15px;border-radius:50%;object-fit:cover;vertical-align:middle;margin-right:3px;border:1px solid '+bCol.border+'">'
        : (bAvIsEmoji ? '<span style="font-size:14px;vertical-align:middle;margin-right:3px">'+_escHtml(_bav)+'</span>' : ''))
        + '<span style="font-size:13px;font-weight:700;color:'+bCol.label+';cursor:pointer" onclick="pQuickProfile('+_jsAttr(b.userName||'Usuario')+','+_jsAttr(b.userAv||'🧑')+',\'\',\'\','+_jsAttr(b.userId||'')+')">'
        + _escHtml(b.userName)+'</span>'
        + (_uAt(b.userId||''));
    } else {
      authorNameHtml = '<span style="font-size:13px;font-weight:700;color:'+anonColor+';letter-spacing:.2px">Anónimo/a</span>';
    }
    var stripInnerB = bAvHasImg
      ? '<img src="'+_escHtml(_bav)+'" style="width:40px;height:40px;border-radius:50%;object-fit:cover;border:2.5px solid '+bCol.border+';display:block;box-shadow:0 2px 12px '+bCol.glow+'">'
      : bAvIsEmoji
        ? '<div style="width:40px;height:40px;border-radius:50%;background:'+avCircleBg+';border:2px solid '+bCol.border+';display:flex;align-items:center;justify-content:center;font-size:22px;box-shadow:0 2px 12px '+bCol.glow+'">'+_escHtml(_bav)+'</div>'
        : '<span style="font-size:30px;line-height:1;filter:drop-shadow(0 0 8px '+bCol.glow+')">'+_escHtml(b.mood||'🌊')+'</span>';
    // Reacciones de esta botella
    var bReacts = reactionsByBottle[b.id] || {};
    var reactionsBar = _BOTTLE_REACTIONS.map(function(rDef){
      var d = bReacts[rDef.k] || {count:0, mine:false};
      // Colores adaptados al fondo de la card (que ya es dark en dark-mode y warm en light)
      var pillBg, pillBrd, pillCol;
      if(d.mine){
        pillBg  = 'rgba(255,215,110,.28)';
        pillBrd = 'rgba(255,205,80,.75)';
        pillCol = isLight ? 'rgba(120,80,0,.95)' : 'rgba(255,230,140,.98)';
      } else {
        pillBg  = isLight ? 'rgba(0,0,0,.05)'       : 'rgba(255,255,255,.10)';
        pillBrd = isLight ? 'rgba(0,0,0,.14)'       : 'rgba(255,255,255,.22)';
        pillCol = isLight ? 'rgba(0,0,0,.72)'       : 'rgba(255,255,255,.88)';
      }
      return '<button onclick="pReactBottle(\''+b.id+'\',\''+rDef.k+'\')" style="display:inline-flex;align-items:center;gap:5px;padding:5px 11px;background:'+pillBg+';border:1.5px solid '+pillBrd+';border-radius:100px;font-family:Jost,sans-serif;font-size:12.5px;font-weight:800;color:'+pillCol+';cursor:pointer;transition:all .18s;-webkit-tap-highlight-color:transparent" onmousedown="this.style.transform=\'scale(.92)\'" onmouseup="this.style.transform=\'\'" onmouseleave="this.style.transform=\'\'" ontouchstart="this.style.transform=\'scale(.92)\'" ontouchend="this.style.transform=\'\'"><span style="font-size:14px;line-height:1">'+rDef.e+'</span>'+(d.count>0?'<span>'+d.count+'</span>':'')+'</button>';
    }).join(' ');
    var replyCount = repliesByBottle[b.id] || 0;
    var replyCountHtml = replyCount > 0
      ? '<span style="display:inline-flex;align-items:center;gap:4px;font-size:11.5px;font-weight:700;color:'+(isLight?'rgba(30,90,128,.62)':'rgba(180,220,240,.72)')+';font-family:Jost,sans-serif;letter-spacing:.2px;margin-left:6px">💌 '+replyCount+(replyCount===1?' persona respondió':' personas respondieron')+'</span>'
      : '';
    return '<div class="dark-bottle'+(alreadyReplied?' bottle-already-replied':'')+'" id="bottle-'+b.id+'"'
      +' style="animation-delay:'+i*.08+'s;position:relative;background:'+bCol.bg+';border:1.5px solid '+cardBorder+';border-radius:18px;box-shadow:0 4px 22px '+bCol.glow+',inset 0 0 0 1px '+bCol.border.replace(/[\d.]+\)$/,'0.18)')+';overflow:hidden;margin:0 0 10px;padding:0">'
      +'<div class="velo-wave-strip" style="position:absolute;left:0;top:0;bottom:0;width:64px;background-color:'+bCol.strip+';border-right:1.5px solid '+bCol.border.replace(/[\d.]+\)$/,'0.45)')+';display:flex;align-items:center;justify-content:center;'+((isOwn && !b.anon)||showAuthor?'cursor:pointer;':'')+'" '
      +((isOwn && !b.anon) ? 'onclick="pQuickProfile('+_jsAttr(myName||b.userName||'Tú')+','+_jsAttr(b.userAv||'🧑')+',\'\',\'\','+_jsAttr(myId)+')"'
        : showAuthor ? 'onclick="pQuickProfile('+_jsAttr(b.userName||'Usuario')+','+_jsAttr(b.userAv||'🧑')+',\'\',\'\','+_jsAttr(b.userId||'')+')"'
        : '')
      +'>'
      +stripInnerB
      +'</div>'
      +'<div style="margin-left:64px;min-height:76px;padding:10px 12px">'
      +'<div style="display:flex;align-items:center;gap:5px;margin-bottom:5px;flex-wrap:wrap">'
      +authorNameHtml
      +(alreadyReplied?'<span style="font-size:11px;font-weight:700;color:rgba(116,198,157,.80);background:rgba(116,198,157,.14);border:1px solid rgba(116,198,157,.28);border-radius:100px;padding:1px 7px;margin-left:auto">💌 Respondiste</span>'
        :'<span style="margin-left:auto;font-size:11px;font-weight:700;color:'+bCol.label.replace(/[\d.]+\)$/,'0.60)')+';font-family:\'Jost\',sans-serif">'+relTime+'</span>')
      +'</div>'
      +'<p style="font-size:15px;color:'+bodyTextColor+';line-height:1.55;margin:0 0 9px;font-family:\'Cormorant Garamond\',serif;font-style:italic;font-weight:500;letter-spacing:.01em">"'+_escHtml(b.text)+'"</p>'
      // Barra de reacciones rápidas + contador de respuestas
      +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap">'+reactionsBar+replyCountHtml+'</div>'
      +'<div style="display:flex;align-items:center;justify-content:flex-end">'+actions+'</div>'
      +'</div></div>';
  }).join('');
}

var _selectedBottleMood = '';
function pSelBottleMood(el, mood){
  _selectedBottleMood = mood;
  var parent = document.getElementById('bottleMoodRow');
  if(parent) parent.querySelectorAll('button').forEach(function(b){
    b.style.borderColor = b.dataset.mood === mood ? 'rgba(200,165,100,.5)' : 'transparent';
    b.style.background = b.dataset.mood === mood ? 'rgba(200,165,100,.1)' : 'none';
  });
}

function pToggleBottleProfile(tog){
  tog.classList.toggle('on');
  var isVisible = tog.classList.contains('on');
  document.getElementById('bottleShowProfile').checked = isVisible;
  // Hide emoji picker when profile is visible (avatar is used instead)
  var emojiSec = document.getElementById('bottleEmojiSection');
  if(emojiSec) emojiSec.style.display = isVisible ? 'none' : '';
}

function pOpenBottleForm(){
  // Reset emoji selection so the user must pick one each time (when anonymous)
  _selectedBottleMood = '';
  var parent = document.getElementById('bottleMoodRow');
  if(parent) parent.querySelectorAll('button').forEach(function(b){
    b.style.borderColor = 'transparent';
    b.style.background = 'none';
  });
  // Reset profile toggle to default (anonymous)
  var tog = document.getElementById('bottleProfileTog');
  if(tog) tog.classList.remove('on');
  var cb = document.getElementById('bottleShowProfile');
  if(cb) cb.checked = false;
  var emojiSec = document.getElementById('bottleEmojiSection');
  if(emojiSec) emojiSec.style.display = '';
  openModal('bottleFormOv');
}

async function pSendBottle(){
  var ta = document.getElementById('bottleMsgTa');
  if(!ta || !ta.value.trim()){ pToast('✍️','Escribí algo antes de lanzar'); return; }
  var showProfile = document.getElementById('bottleShowProfile') && document.getElementById('bottleShowProfile').checked;
  // Require an emoji when posting anonymously — it's the only identifier shown
  if(!showProfile && !_selectedBottleMood){
    pToast('😊','Elegí un emoji para tu mensaje anónimo'); return;
  }
  // Nudge suave si detecta crisis — antes del rate limit para no perder el texto
  if(_detectCrisisContent(ta.value) && !window._crisisNudgeSkipped_bottle){
    closeModal('bottleFormOv');
    _openCrisisNudge(function(){
      window._crisisNudgeSkipped_bottle = true;
      openModal('bottleFormOv');
      // el textarea sigue con su contenido
      setTimeout(function(){ pSendBottle(); }, 250);
    });
    return;
  }
  if(!_checkDailyLimit('bottle')){
    closeModal('bottleFormOv');
    pShowDailyLimitModal('bottle');
    return;
  }
  var text = ta.value.trim();
  var isAnon = !showProfile || safeLS('get','velo_incognito')==='true'; // incógnito global gana
  var myName = isAnon ? null : _myDisplayName();
  var myAv   = isAnon ? null : (safeLS('get','velo_user_av')||'🧑');
  var myId   = safeLS('get','velo_user_id')||safeLS('get','velo_user_email')||'';
  ta.value = '';
  closeModal('bottleFormOv');
  _incDailyLimit('bottle');
  var bottles = []; try{ bottles = JSON.parse(safeLS('get','velo_my_bottles')||'[]'); }catch(e){}
  var id = 'ub'+Date.now();
  bottles.unshift({ id:id, mood:_selectedBottleMood, text:text, responses:0, color:'rgba(116,198,157,.12)', ts:Date.now(),
    userId:myId, userName:myName, userAv:myAv, anon:isAnon });
  safeLS('set','velo_my_bottles', JSON.stringify(bottles.slice(0,50)));
  pToast('🌊','¡Mensaje lanzado al mar! 🌿');
  _geminiModerateContent(text, 'mensajes-al-mar');
  _initSupabase();
  if(sbClient){
    // Always store user_id so delete button and reply notifications work for anon posts too
    try{
      await sbClient.from('bottles').insert({ id:id,
        user_id: myId||null,
        user_name: myName||null, user_av: myAv||null, anon: isAnon,
        mood:_selectedBottleMood, text:text, color:'rgba(116,198,157,.12)', replied:false
      });
    }catch(e){ console.error('[pSendBottle insert]', e); }
  }
  pRenderBottle();
}

var _curBottleReplyId   = null;
var _curBottleReplyText = '';
var _curBottleUserId    = null;
var _curBottleAuthorName = '';
var _curBottleAuthorAv   = '';

function pOpenBottleReply(bottleId, bottlePreview, bottleUserId, authorName, authorAv){
  _curBottleReplyId    = bottleId;
  _curBottleReplyText  = bottlePreview;
  _curBottleUserId     = bottleUserId || null;
  _curBottleAuthorName = authorName || '';
  _curBottleAuthorAv   = authorAv   || '';
  var preview = document.getElementById('bottleReplyPreview');
  if(preview) preview.textContent = '"'+bottlePreview+'"';
  var ta = document.getElementById('bottleReplyTa');
  if(ta) ta.value = '';
  openModal('bottleReplyOv');
}

function pSendBottleReply(){
  var ta = document.getElementById('bottleReplyTa');
  if(!ta || !ta.value.trim()){ pToast('✍️','Escribí tu respuesta antes de enviar'); return; }
  if(ta.value.trim().length < 10){ pToast('✍️','Escribí al menos 10 caracteres'); return; }
  var replyText = ta.value.trim();
  _geminiModerateContent(replyText, 'mensajes-al-mar-reply');
  closeModal('bottleReplyOv');

  // 1. Record that THIS user replied and optimistically hide the bottle from their view
  if(_curBottleReplyId){
    safeLS('set','velo_bottle_replied_'+_curBottleReplyId,'1');
    // Save replied bottle details so it appears in "Mis respuestas" tab
    var _rBottles = []; try{ _rBottles = JSON.parse(safeLS('get','velo_bottles_replied')||'[]'); }catch(e){}
    _rBottles.unshift({ id:_curBottleReplyId, preview:_curBottleReplyText||'', reply:replyText, ts:Date.now(), authorName:_curBottleAuthorName||'', authorAv:_curBottleAuthorAv||'', authorId:_curBottleUserId||'' });
    safeLS('set','velo_bottles_replied', JSON.stringify(_rBottles.slice(0,30)));
    // Optimistically fade out the bottle card immediately
    var card = document.getElementById('bottle-'+_curBottleReplyId);
    if(card){ card.style.transition='opacity .4s'; card.style.opacity='0'; setTimeout(function(){ if(card.parentNode) card.parentNode.removeChild(card); }, 450); }
  }
  _initSupabase();
  if(sbClient && _curBottleReplyId){
    sbClient.from('bottles').update({ replied:true, replied_by: safeLS('get','velo_user_id')||'' })
      .eq('id', _curBottleReplyId).then(function(){}).catch(function(){});
    // Registrar en bottle_replies para el contador público "X personas respondieron"
    var _myUid = safeLS('get','velo_user_id')||'';
    if(_myUid){
      sbClient.from('bottle_replies').insert({ bottle_id: _curBottleReplyId, user_id: _myUid })
        .then(function(){}).catch(function(){});
    }
  }

  // 2. Deliver to the bottle author's inbox via Supabase broadcasts
  if(sbClient && _curBottleUserId){
    var _rid = safeLS('get','velo_user_id')||'';
    var _rName = safeLS('get','velo_user_name')||'';
    var _rAv = safeLS('get','velo_user_av')||'🧑';
    sbClient.from('broadcasts').insert({
      target: 'user:'+_curBottleUserId,
      subject: '¡Tu mensaje en el mar recibió una respuesta!',
      // Marker [bid:XXX] al final del body → sirve para agrupar respuestas por botella
      body: (_curBottleReplyText ? '🌊 Tu mensaje:\n"'+_curBottleReplyText+'"\n\n' : '')+'💬 Respuesta:\n"'+replyText+'"\n\n[bid:'+_curBottleReplyId+']',
      icon: '🌊',
      sender: _rid ? JSON.stringify({ n:_rName, i:_rid, a:_rAv, u:safeLS('get','velo_username')||'' }) : 'Velo — Al Mar',
      sent_at: new Date().toISOString()
    }).then(function(){}).catch(function(){});
  }

  pToast('💌','¡Respuesta enviada! 🌊');
  setTimeout(function(){ pToast('📬','El autor recibió tu respuesta en su buzón Velo'); }, 1200);
}

function pDeleteBottle(bottleId){
  // Two-tap confirm: first tap shows "¿Seguro?" state; second tap deletes
  var btn = document.querySelector('#bottle-'+bottleId+' [data-del-btn]');
  if(btn && btn.dataset.confirmPending === '1'){
    _doDeleteBottle(bottleId);
  } else {
    if(btn){
      btn.dataset.confirmPending = '1';
      btn.textContent = '¿Seguro? 🗑️';
      btn.style.background = 'rgba(255,80,80,.18)';
      btn.style.borderColor = 'rgba(255,80,80,.4)';
      btn.style.color = 'rgba(255,120,120,.95)';
      setTimeout(function(){
        if(btn && btn.dataset.confirmPending === '1'){
          btn.dataset.confirmPending = '0';
          btn.textContent = '🗑️';
          btn.style.background = 'rgba(255,80,80,.08)';
          btn.style.borderColor = 'rgba(255,80,80,.2)';
          btn.style.color = 'rgba(255,120,120,.75)';
        }
      }, 3000);
    } else {
      _doDeleteBottle(bottleId); // fallback if button not found
    }
  }
}
async function _doDeleteBottle(bottleId){
  _initSupabase();
  if(sbClient){
    try{ await sbClient.from('bottles').delete().eq('id', bottleId); }catch(e){}
  }
  var myBottles = []; try{ myBottles = JSON.parse(safeLS('get','velo_my_bottles')||'[]'); }catch(e){}
  safeLS('set','velo_my_bottles', JSON.stringify(myBottles.filter(function(b){ return b.id !== bottleId; })));
  var card = document.getElementById('bottle-'+bottleId);
  if(card){ card.style.transition='opacity .3s'; card.style.opacity='0'; setTimeout(function(){ pRenderBottle(); },350); }
  else { pRenderBottle(); }
  pToast('🌊','Mensaje eliminado del mar');
}

function pReportBottle(bottleId){
  var bottle = _sbBottles && _sbBottles.find(function(b){ return String(b.id) === String(bottleId); });
  var preview = bottle && bottle.text ? bottle.text : '';
  pReportContent('bottle', bottleId, preview);
}

// ── DIARY ──────────────────────────────────────────────────────
var _diaryEmojis = ['😊','😢','😰','😤','😴','🤔','💪','🌿','✨','💔'];
var _diaryPrivacyShown = false;

function pInitDiary(){
  var _now = new Date();
  var _dias = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  var _meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  var _diaStr = _dias[_now.getDay()]+', '+_now.getDate()+' de '+_meses[_now.getMonth()];
  // Hero header date
  var heroDate = document.getElementById('diaryHeroDate');
  if(heroDate) heroDate.textContent = _diaStr;
  // Write panel date
  var dateEl = document.getElementById('diaryDateLbl');
  if(dateEl) dateEl.textContent = _now.getDate()+' de '+_meses[_now.getMonth()]+' '+_now.getFullYear();
  var dateSubEl = document.getElementById('diaryDateSub');
  if(dateSubEl) dateSubEl.textContent = '— '+_dias[_now.getDay()].toLowerCase();
  // Reset form state on each visit
  _selectedDiaryEmoji = '';
  var chosenEl = document.getElementById('diaryEmojiChosen');
  if(chosenEl) chosenEl.textContent = '';
  var titleEl = document.getElementById('diaryTitleInput');
  if(titleEl) titleEl.value = '';
  // Clear active mood pills
  document.querySelectorAll('.diary-mood-pill').forEach(function(b){ b.classList.remove('active'); });
  _loadDiaryEntries();
  _initDiaryPromptPreview();
  var _diaryTA = document.getElementById('diaryTa');
  var _diaryCC = document.getElementById('diaryCharCount');
  if(_diaryTA && _diaryCC){
    _diaryTA.oninput = function(){ _diaryCC.textContent = this.value.length; };
    _diaryCC.textContent = _diaryTA.value.length;
  }
}

