async function pSaveDiary(){
  var ta = document.getElementById('diaryTa');
  var hasText = !!(ta && ta.value.trim());
  var hasAudio = !!_veloRecordedBlob;
  var hasImage = !!_veloDiaryImageBase64;
  // Aceptar la entrada si tiene AL MENOS UNA de las 3 cosas
  if(!hasText && !hasAudio && !hasImage){
    pToast('✍️','Agregá texto, audio o foto antes de guardar');
    return;
  }
  var titleEl = document.getElementById('diaryTitleInput');
  var title = titleEl ? titleEl.value.trim() : '';
  var emoji = _selectedDiaryEmoji || '';
  var rawText = (ta && ta.value) ? ta.value.trim() : '';
  // Legacy combined text for sbSaveDiaryEntry compatibility
  var text = (emoji ? emoji+' ' : '') + rawText;
  var ts = Date.now();
  var dateLabel = _fmtDate(ts);
  // Local storage
  var entries = []; try{ entries = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  var newEntry = { title:title, emoji:emoji, text:rawText, dateLabel:dateLabel, ts:ts };
  // Adjuntar audio y/o imagen si hay adjuntos pendientes
  newEntry = await _attachVoiceToEntry(newEntry);
  newEntry = await _attachImageToEntry(newEntry);
  // Enviar a Supabase PRIMERO (con audio/imagen completos)
  sbSaveDiaryEntry(text, dateLabel, ts, title, newEntry.audio, newEntry.image);
  // En memoria: la entry queda COMPLETA (con audio/imagen)
  entries.unshift(newEntry);
  _diaryEntries = entries.slice();  // actualizar módulo state para la lista
  // Para localStorage: comprimir si el total serializado supera cap iOS
  var LS_BLOB_LIMIT = 2 * 1024 * 1024;
  var lsOk = false;
  try{
    var serialized = JSON.stringify(entries.slice(0,200));
    if(serialized.length > 4 * 1024 * 1024){ throw new Error('too big for LS'); }
    // setItem DIRECTO (no safeLS): safeLS traga el QuotaExceededError y devuelve
    // null, así que el fallback de compactación de abajo nunca se disparaba en el
    // caso de quota REAL (LS lleno pero serializado < 4MB). Directo, el throw propaga.
    localStorage.setItem('velo_diary', serialized);
    lsOk = true;
  }catch(e){
    console.warn('[diary] LS quota — guardando versión compacta sin blobs:', e && e.message);
    // Fallback: guardar SIN blobs en LS (Supabase los tiene)
    var compactEntries = entries.slice(0,200).map(function(en){
      var c = Object.assign({}, en);
      if(c.audio){ c.audioInSupabase = true; delete c.audio; }
      if(c.image){ c.imageInSupabase = true; delete c.image; }
      return c;
    });
    try{ safeLS('set','velo_diary', JSON.stringify(compactEntries)); lsOk = true; }catch(e2){ console.error('[diary] LS falló totalmente:', e2); }
  }
  ta.value = '';
  if(titleEl) titleEl.value = '';
  _selectedDiaryEmoji = '';
  var chosenEl = document.getElementById('diaryEmojiChosen');
  if(chosenEl) chosenEl.textContent = '';
  pToast('📔','Entrada guardada 💚');
  // Re-render con _diaryEntries en memoria (que TIENE los blobs completos)
  // NO llamar _loadDiaryEntries porque resetearía desde LS (que puede estar compactado)
  var elList = document.getElementById('diaryEntries');
  if(elList) _renderDiaryEntryList(elList, _diaryEntries);
  _updateDiaryStats(_diaryEntries);
}

function _renderDiaryEntryList(el, entries){
  // Actualizar stats SIEMPRE (aún cuando la lista queda vacía tras borrar)
  _updateDiaryStats(entries || []);
  if(!entries || !entries.length){
    el.innerHTML = '<div class="p-empty"><span class="p-empty-emoji">📔</span><div class="p-empty-title">Aún no tenés entradas</div><div class="p-empty-sub">Empezá hoy — es tu espacio seguro 🌙</div></div>';
    return;
  }
  var sorted = entries.slice().sort(function(a,b){ return (b.ts||0) - (a.ts||0); });
  el.innerHTML = sorted.map(function(e, i){
    var rawLabel = e.dateLabel || '';
    var dateOnly = rawLabel ? rawLabel.split('·')[0].trim() : new Date(Number(e.ts)).toLocaleDateString('es-AR',{day:'numeric',month:'long',year:'numeric'});
    var emo = e.emoji || '📜';
    var hasAudio = !!e.audio;
    var hasImage = !!e.image;
    var hasText = !!(e.text && e.text.trim());
    // Preview: si es solo audio, decir "Nota de voz"; si es solo imagen, "Imagen"; si tiene texto, mostrar preview
    var preview;
    if(hasText){ preview = e.title ? e.title : e.text.replace(/\n/g,' ').slice(0,72); }
    else if(hasAudio && hasImage){ preview = '🎙️ Audio + 📷 Imagen'; }
    else if(hasAudio){ preview = '🎙️ Nota de voz'; }
    else if(hasImage){ preview = '📷 Imagen'; }
    else { preview = ''; }
    var previewHtml = preview ? '<div class="diary-row-preview">'+_escHtml(preview)+'</div>' : '';
    // Badges de tipo: audio + imagen (theme-aware para modo claro y oscuro)
    var isDarkList = document.body.classList.contains('r-dark');
    var badges = '';
    if(hasAudio){
      // Alto contraste sobre cream/dark: ámbar sólido oscuro (light) / ámbar claro (dark)
      var audioColor = isDarkList ? '#ffe28a' : '#5c3d10';
      var audioBg    = isDarkList ? 'rgba(220,180,80,.28)' : 'rgba(220,180,80,.45)';
      var audioBrd   = isDarkList ? 'rgba(255,220,120,.60)' : 'rgba(140,90,10,.75)';
      badges += '<span title="Tiene audio" style="display:inline-flex;align-items:center;gap:3px;background:'+audioBg+';border:1.5px solid '+audioBrd+';border-radius:100px;padding:3px 9px;font-size:11px;font-weight:800;color:'+audioColor+';font-family:Jost,sans-serif;letter-spacing:.3px">🎙️ Audio</span>';
    }
    if(hasImage){
      // Violeta sólido oscuro (light) / violeta claro (dark) — más saturado
      var imageColor = isDarkList ? '#e8dcff' : '#3d1f7a';
      var imageBg    = isDarkList ? 'rgba(180,155,240,.28)' : 'rgba(180,155,240,.42)';
      var imageBrd   = isDarkList ? 'rgba(200,180,255,.60)' : 'rgba(90,60,180,.75)';
      badges += (badges?'<span style="width:6px;display:inline-block"></span>':'')+'<span title="Tiene foto" style="display:inline-flex;align-items:center;gap:3px;background:'+imageBg+';border:1.5px solid '+imageBrd+';border-radius:100px;padding:3px 9px;font-size:11px;font-weight:800;color:'+imageColor+';font-family:Jost,sans-serif;letter-spacing:.3px">📷 Foto</span>';
    }
    // Border-left color según tipo predominante: audio → dorado, imagen → violeta, texto → default
    var leftBorder = '';
    if(hasAudio && !hasText && !hasImage) leftBorder = 'border-left:3px solid rgba(220,180,80,.65);padding-left:12px';
    else if(hasImage && !hasText && !hasAudio) leftBorder = 'border-left:3px solid rgba(180,155,240,.65);padding-left:12px';
    else if(hasAudio || hasImage) leftBorder = 'border-left:3px solid rgba(180,220,240,.42);padding-left:12px';
    // Thumbnail de imagen: renderizar si hay y hacer fallback en onerror
    var thumbHtml = hasImage
      ? '<img src="'+e.image+'" onerror="this.outerHTML=\'<span style=&quot;font-size:22px;line-height:1;width:44px;text-align:center;display:inline-block&quot;>'+emo+'</span>\'" style="width:44px;height:44px;object-fit:cover;border-radius:10px;flex-shrink:0;border:1.5px solid rgba(180,155,240,.35)">'
      : '<span style="font-size:22px;flex-shrink:0;line-height:1;width:44px;text-align:center">'+emo+'</span>';
    return '<div class="diary-row" onclick="pOpenDiaryEntry('+e.ts+')" style="animation-delay:'+i*.04+'s;cursor:pointer;'+leftBorder+'">'
      +'<div style="display:flex;align-items:center;gap:10px">'
      + thumbHtml
      +'<div style="flex:1;min-width:0">'
      +'<div class="diary-row-date">'+_escHtml(dateOnly)+'</div>'
      +previewHtml
      + (badges ? '<div style="margin-top:4px;display:flex;align-items:center">'+badges+'</div>' : '')
      +'</div>'
      +'<button onclick="event.stopPropagation();pDeleteDiary('+e.ts+')" style="background:none;border:none;cursor:pointer;font-size:14px;color:var(--ink4);opacity:.5;padding:4px 6px;flex-shrink:0">🗑️</button>'
      +'</div>'
      +'</div>';
  }).join('');
}

async function _loadDiaryEntries(){
  var el = document.getElementById('diaryEntries');
  if(!el) return;
  // Local storage has full metadata (title, emoji) — prefer it
  var local = []; try{ local = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  var localMap = {};
  local.forEach(function(e){ if(e.ts != null) localMap[String(e.ts)] = e; });
  // Render from localStorage immediately — instant, no Supabase wait
  _diaryEntries = local.slice();
  _renderDiaryEntryList(el, _diaryEntries);
  // Supabase for cross-device sync — merge blobs faltantes + entries nuevas
  var sbEntries = await sbLoadDiaryEntries();
  if(!document.getElementById('diaryEntries')) return;
  var entries = local.slice();
  if(sbEntries && sbEntries.length){
    var sbMap = {};
    sbEntries.forEach(function(se){ sbMap[String(se.ts)] = se; });
    // Merge: si la LS entry tiene flag inSupabase pero no el blob, traerlo de SB
    entries = entries.map(function(le){
      var se = sbMap[String(le.ts)];
      if(!se) return le;
      var merged = Object.assign({}, le);
      if(le.audioInSupabase && !le.audio && se.audio){ merged.audio = se.audio; delete merged.audioInSupabase; }
      if(le.imageInSupabase && !le.image && se.image){ merged.image = se.image; delete merged.imageInSupabase; }
      // También traer si LS no tiene el campo audio/image
      if(!le.audio && se.audio) merged.audio = se.audio;
      if(!le.image && se.image) merged.image = se.image;
      return merged;
    });
    // Agregar entries de SB que no están en LS
    sbEntries.forEach(function(se){
      var k = String(se.ts);
      if(!localMap[k]){
        entries.push(Object.assign({}, se, { ts: Number(se.ts)||se.ts, dateLabel: se.date_label||se.dateLabel||'' }));
      }
    });
  }
  // Normalize any remaining field name differences
  entries = entries.map(function(e){ return e.dateLabel != null ? e : Object.assign({}, e, { dateLabel: e.date_label || '' }); });
  _diaryEntries = entries;
  _renderDiaryEntryList(el, _diaryEntries);
}

var _diaryEntries = [];
var _diarySearchTimer = null;

function pExportDiary(){
  var entries=[]; try{entries=JSON.parse(safeLS('get','velo_diary')||'[]');}catch(e){}
  if(!entries.length){ pToast('📔','No hay entradas para exportar'); return; }
  var sorted=entries.slice().sort(function(a,b){return (a.ts||0)-(b.ts||0);});
  var lines=['VELO — Mi Diario Emocional','Exportado el '+new Date().toLocaleDateString('es',{day:'numeric',month:'long',year:'numeric'}),'═'.repeat(40),''];
  sorted.forEach(function(e){
    lines.push('📅 '+(e.dateLabel||new Date(Number(e.ts)).toLocaleDateString('es')));
    if(e.emoji||e.title) lines.push((e.emoji?e.emoji+' ':'')+_escHtml(e.title||'').replace(/&[a-z]+;/g,''));
    if(e.text) lines.push('',''+e.text);
    lines.push('','─'.repeat(32),'');
  });
  var blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a'); a.href=url; a.download='velo-diario.txt';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(function(){URL.revokeObjectURL(url);},2000);
  pToast('📤','Diario exportado');
}

function pDiarySearch(val){
  clearTimeout(_diarySearchTimer);
  _diarySearchTimer = setTimeout(function(){
    var el = document.getElementById('diaryEntries');
    if(!el) return;
    var q = (val||'').toLowerCase().trim();
    var clr = document.getElementById('diarySearchClear');
    if(clr) clr.style.opacity = q ? '1' : '0';
    if(!q){ _renderDiaryEntryList(el, _diaryEntries); return; }
    var filtered = _diaryEntries.filter(function(e){
      return ((e.title||'')+' '+(e.text||'')).toLowerCase().indexOf(q) >= 0;
    });
    if(!filtered.length){
      el.innerHTML = '<div class="p-empty"><span class="p-empty-emoji">🔍</span>'
        +'<div class="p-empty-title">Sin resultados</div>'
        +'<div class="p-empty-sub">Intenta con otras palabras</div></div>';
    } else {
      _renderDiaryEntryList(el, filtered);
    }
  }, 280);
}

function pDiaryClear(){
  var inp = document.getElementById('diarySearchInput');
  if(inp){ inp.value = ''; }
  pDiarySearch('');
}

function _getDiaryStreak(entries){
  if(!entries || !entries.length) return 0;
  var msDay = 86400000;
  var today = new Date(); today.setHours(0,0,0,0);
  var uniqueDays = {};
  entries.forEach(function(e){
    if(!e.ts) return;
    var d = new Date(Number(e.ts)); d.setHours(0,0,0,0);
    uniqueDays[d.getTime()] = true;
  });
  var streak = 0;
  var check = today.getTime();
  if(!uniqueDays[check]) check -= msDay;
  while(uniqueDays[check]){ streak++; check -= msDay; }
  return streak;
}

function _updateDiaryStats(entries){
  var streak = _getDiaryStreak(entries);
  var sv = document.getElementById('diaryStreakVal');
  var ec = document.getElementById('diaryEntryCountEl');
  if(sv) sv.textContent = streak;
  if(ec) ec.textContent = entries ? entries.length : 0;
}

