function veloI18n(key){
  var lang = safeLS('get','velo_lang') || 'es';
  if(lang === 'es' || !VELO_I18N[lang]) return key;
  return VELO_I18N[lang][key] || key;
}
// Detección al boot
(function _veloDetectLang(){
  try{
    var browserLang = (navigator.language || navigator.userLanguage || '').toLowerCase();
    var ptBrowserMatch = browserLang.indexOf('pt') === 0;
    var tzStr = '';
    try{ tzStr = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; }catch(e){}
    var ptTzMatch = /Lisbon|Portugal|Azores|Madeira|Sao_Paulo|Bahia|Fortaleza|Manaus|Recife|Belem|Rio_Branco|Maceio|Araguaina|Cuiaba|Campo_Grande|Boa_Vista|Porto_Velho|Noronha|Santarem/i.test(tzStr);
    var isPtCandidate = ptBrowserMatch || ptTzMatch;
    safeLS('set','velo_lang_available', isPtCandidate ? 'pt' : '');
  }catch(e){}
})();
// Cambiar idioma — hard reload inmediato para que TODA la app se pinte en el nuevo idioma
// (los feeds/modales dinámicos NO se re-renderizan sin reload)
function pSetVeloLang(lang){
  try{ safeLS('set','velo_lang', lang); }catch(e){}
  var ov = document.getElementById('prefsOv'); if(ov) ov.remove();
  // Reload inmediato — el toast lo ve después del reload (no perder tiempo)
  try{
    var url = window.location.pathname + (window.location.search ? window.location.search + '&' : '?') + '_i18n=' + Date.now();
    window.location.replace(url);
  }catch(e){
    try{ window.location.reload(); }catch(e2){}
  }
}
// Aplicar traducciones al DOM — scan agresivo de nodos texto
// NOTA: NO usar flag "i18nDone" en padres — el contenido de los hijos se
// reemplaza dinámicamente al navegar y el flag congelaría el español para siempre.
// En su lugar guardamos el traducido en el propio text node.
var _veloI18nSortedKeysCache = null;
var _veloI18nDictHash = '';
function _veloGetSortedKeys(dict){
  var hash = Object.keys(dict).length + '_' + (dict.__firstKey || Object.keys(dict)[0] || '');
  if(_veloI18nSortedKeysCache && _veloI18nDictHash === hash) return _veloI18nSortedKeysCache;
  _veloI18nSortedKeysCache = Object.keys(dict).sort(function(a,b){ return b.length - a.length; });
  _veloI18nDictHash = hash;
  return _veloI18nSortedKeysCache;
}
function _veloApplyI18n(){
  var lang = safeLS('get','velo_lang') || 'es';
  if(lang === 'es' || !VELO_I18N[lang]) return;
  var dict = VELO_I18N[lang];
  var sortedKeys = _veloGetSortedKeys(dict);
  // 1) Elementos con data-i18n
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var key = el.getAttribute('data-i18n');
    if(dict[key]) el.textContent = dict[key];
  });
  // 2) Scan de text nodes — cada nodo lleva su "última versión traducida" en __veloI18nAppliedTo
  //    para poder detectar reemplazos y no re-traducir un texto que ya está traducido.
  try{
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode: function(node){
        var p = node.parentElement;
        if(!p) return NodeFilter.FILTER_REJECT;
        var tag = p.tagName;
        if(tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || tag === 'INPUT' || tag === 'CODE') return NodeFilter.FILTER_REJECT;
        var v = String(node.nodeValue||'').trim();
        if(v.length < 2) return NodeFilter.FILTER_REJECT;
        // Si el nodo ya fue traducido a este valor exacto, saltar
        if(node.__veloI18nAppliedTo === node.nodeValue) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    var nodes = [];
    var n;
    while((n = walker.nextNode())) nodes.push(n);
    nodes.forEach(function(node){
      var original = node.nodeValue;
      var translated = original;
      var changed = false;
      sortedKeys.forEach(function(k){
        if(translated.indexOf(k) >= 0){
          translated = translated.split(k).join(dict[k]);
          changed = true;
        }
      });
      if(changed){
        node.nodeValue = translated;
        node.__veloI18nAppliedTo = translated;
      } else {
        // Marcar como scaneado para no re-escanear estático que no matchea
        node.__veloI18nAppliedTo = original;
      }
    });
  }catch(e){ console.warn('[i18n] walker error:', e); }
  // 3) Placeholders de inputs / textareas
  document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(function(el){
    var ph = el.getAttribute('placeholder') || '';
    if(el.__veloI18nPh === ph) return;
    var newPh = ph;
    sortedKeys.forEach(function(k){ if(newPh.indexOf(k) >= 0) newPh = newPh.split(k).join(dict[k]); });
    if(newPh !== ph){ el.setAttribute('placeholder', newPh); el.__veloI18nPh = newPh; }
    else { el.__veloI18nPh = ph; }
  });
  // 4) Titles / aria-labels
  document.querySelectorAll('[title], [aria-label]').forEach(function(el){
    ['title','aria-label'].forEach(function(attr){
      var v = el.getAttribute(attr);
      if(!v) return;
      var newV = v;
      sortedKeys.forEach(function(k){ if(newV.indexOf(k) >= 0) newV = newV.split(k).join(dict[k]); });
      if(newV !== v) el.setAttribute(attr, newV);
    });
  });
}
// Re-aplicar i18n periódicamente + observer para contenido dinámico
var _veloI18nObserver = null;
var _veloI18nApplyPending = false;
function _veloRequestI18nApply(){
  if(_veloI18nApplyPending) return;
  _veloI18nApplyPending = true;
  setTimeout(function(){ _veloI18nApplyPending = false; _veloApplyI18n(); }, 60);
}
function _veloScheduleI18n(){
  var lang = safeLS('get','velo_lang') || 'es';
  if(lang === 'es' || !VELO_I18N[lang]) return;
  setTimeout(function(){ _veloApplyI18n(); }, 40);
  setTimeout(function(){ _veloApplyI18n(); }, 400);
  setTimeout(function(){ _veloApplyI18n(); }, 1200);
  setTimeout(function(){ _veloApplyI18n(); }, 3000);
  // MutationObserver — re-aplica en cualquier inserción de nodos (páginas, modales, feeds)
  if(!_veloI18nObserver && typeof MutationObserver === 'function'){
    _veloI18nObserver = new MutationObserver(function(mutations){
      for(var i=0; i<mutations.length; i++){
        if(mutations[i].addedNodes && mutations[i].addedNodes.length > 0){
          _veloRequestI18nApply();
          return;
        }
      }
    });
    try{ _veloI18nObserver.observe(document.body, { childList:true, subtree:true }); }catch(e){}
  }
  // Auto-traducir strings desconocidas via Gemini (async, cachea en LS)
  setTimeout(function(){ if(typeof _veloAutoTranslateDOM === 'function') _veloAutoTranslateDOM(); }, 2500);
}

// Auto-traducción con Gemini + caché en LS
async function _veloAutoTranslateDOM(){
  var lang = safeLS('get','velo_lang') || 'es';
  if(lang === 'es' || typeof _geminiCall !== 'function') return;
  var dict = VELO_I18N[lang] || {};
  var cacheKey = 'velo_i18n_ai_cache_' + lang;
  var cache = {};
  try{ cache = JSON.parse(safeLS('get', cacheKey) || '{}'); }catch(e){}
  // Cargar caché en dict combinado (efectivo)
  var effDict = Object.assign({}, cache, dict);
  // Recorrer text nodes y encontrar strings NO cubiertas
  var untranslated = {};
  try{
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode: function(node){
        var p = node.parentElement;
        if(!p) return NodeFilter.FILTER_REJECT;
        var tag = p.tagName;
        if(tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || tag === 'INPUT' || tag === 'CODE') return NodeFilter.FILTER_REJECT;
        var v = String(node.nodeValue||'').trim();
        // Solo texto sustancial en español (min 5 chars, con letras)
        if(v.length < 5 || v.length > 400) return NodeFilter.FILTER_REJECT;
        if(!/[a-záéíóúñü]/i.test(v)) return NodeFilter.FILTER_REJECT;
        if(effDict[v]) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    var n;
    while((n = walker.nextNode())){
      var v = String(n.nodeValue||'').trim();
      untranslated[v] = true;
    }
  }catch(e){ console.warn('[i18n-auto]', e); return; }
  var texts = Object.keys(untranslated).slice(0, 30); // max 30 por batch
  if(!texts.length) return;
  var langLabel = lang === 'pt' ? 'português (Portugal)' : lang;
  var prompt = 'Traduce estos textos de UI de una app de bienestar emocional al '+langLabel+'. '
    + 'Mantén el tono cálido, empático y natural. NO traduzcas nombres propios (Velo, Bitácora si es marca). '
    + 'Responde EXCLUSIVAMENTE con JSON válido: {"1":"tradução","2":"tradução",...}\n\n'
    + texts.map(function(t,i){ return (i+1)+'. '+t; }).join('\n');
  try{
    var result = await _geminiCall(prompt, { temperature:0.2, maxOutputTokens:2000 });
    if(!result) return;
    var m = result.match(/\{[\s\S]*\}/);
    if(!m) return;
    var parsed = JSON.parse(m[0]);
    Object.keys(parsed).forEach(function(k){
      var idx = parseInt(k)-1;
      if(texts[idx] && parsed[k] && typeof parsed[k] === 'string'){
        cache[texts[idx]] = parsed[k];
        dict[texts[idx]] = parsed[k];
      }
    });
    try{ safeLS('set', cacheKey, JSON.stringify(cache)); }catch(e){}
    // Re-aplicar con nuevas traducciones
    _veloApplyI18n();
    console.log('[i18n-auto] traducidos', Object.keys(parsed).length, 'strings via IA');
  }catch(e){ console.warn('[i18n-auto]', e); }
}

// Cargar caché IA en el diccionario al bootear
(function _veloLoadI18nCache(){
  try{
    var lang = safeLS('get','velo_lang') || 'es';
    if(lang === 'es' || !VELO_I18N[lang]) return;
    var cache = JSON.parse(safeLS('get','velo_i18n_ai_cache_' + lang) || '{}');
    VELO_I18N[lang] = Object.assign({}, cache, VELO_I18N[lang]);
  }catch(e){}
})();

// ── TRANSLATE ON DEMAND — botón "Traduzir" para contenido de usuarios ─
// Cache: velo_content_translations_<lang> = { 'texto original': 'traducción' }
async function pTranslateUserContent(elementId, originalText){
  var el = document.getElementById(elementId);
  if(!el) return;
  var lang = safeLS('get','velo_lang') || 'es';
  var cacheKey = 'velo_content_translations_' + lang;
  var cache = {};
  try{ cache = JSON.parse(safeLS('get', cacheKey) || '{}'); }catch(e){}
  var cached = cache[originalText];
  var showTranslation = function(txt){
    var wrap = document.createElement('div');
    wrap.style.cssText = 'margin-top:8px;padding:10px 12px;background:rgba(80,150,220,.10);border:1px solid rgba(80,150,220,.25);border-left:3px solid rgba(80,150,220,.85);border-radius:0 10px 10px 0;font-family:Jost,sans-serif';
    var flag = lang==='pt'?'🇵🇹':'🇪🇸';
    wrap.innerHTML = '<div style="font-size:10px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:rgba(80,150,220,.75);margin-bottom:4px">'+flag+' TRADUÇÃO</div>'
      + '<div style="font-size:14px;color:rgba(220,240,255,.94);line-height:1.55;font-family:\'Cormorant Garamond\',serif;font-style:italic">'+_escHtml(txt)+'</div>';
    el.parentNode.insertBefore(wrap, el.nextSibling);
  };
  if(cached){ showTranslation(cached); return; }
  pToast('🌐', lang==='pt' ? 'Traduzindo…' : 'Traduciendo…');
  var langLabel = lang === 'pt' ? 'português (Portugal)' : 'espanhol';
  var prompt = 'Traduz este texto ao '+langLabel+' mantendo o tom original (empático, cálido). '
    + 'Responde APENAS com a tradução, sem aspas nem explicações:\n\n' + originalText;
  try{
    var translated = await _geminiCall(prompt, { temperature:0.3, maxOutputTokens:800 });
    if(!translated){ pToast('⚠️','No pude traducir'); return; }
    translated = translated.replace(/^["']|["']$/g,'').trim();
    cache[originalText] = translated;
    try{ safeLS('set', cacheKey, JSON.stringify(cache)); }catch(e){}
    showTranslation(translated);
  }catch(e){ pToast('⚠️','Error al traducir'); }
}
// Función global para renderizar el botón traducir con datos dinámicos
function _veloTranslateBtnHtml(originalText, targetElementId){
  var lang = safeLS('get','velo_lang') || 'es';
  if(lang === 'es') return ''; // solo mostrar cuando el user tiene otra lang
  if(!originalText || originalText.length < 10) return '';
  var safeTs = 'tx' + Math.random().toString(36).slice(2,8);
  var escaped = String(originalText).replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,'\\n');
  return '<button onclick="pTranslateUserContent(\''+targetElementId+'\',\''+escaped+'\')" style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;background:rgba(80,150,220,.10);border:1px solid rgba(80,150,220,.32);border-radius:100px;color:rgba(140,190,240,.92);font-size:11px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;letter-spacing:.3px;margin-left:6px" title="Traduzir">🌐 '+ (lang==='pt'?'Traduzir':'Traducir') +'</button>';
}

// ── BACKUP / EXPORT — descargar todos mis datos como JSON ──────────
async function pBackupMyData(){
  pToast('📦','Preparando tu backup…');
  var uid = safeLS('get','velo_user_id') || '';
  var userName = safeLS('get','velo_user_name') || 'Usuario';
  var payload = { velo_backup_version: 1, exported_at: new Date().toISOString(), user_id: uid, user_name: userName };
  // Del LS
  try{
    payload.local_storage = {};
    Object.keys(localStorage).forEach(function(k){
      if(k.indexOf('velo_') === 0){
        payload.local_storage[k] = localStorage.getItem(k);
      }
    });
  }catch(e){}
  // De Supabase
  _initSupabase();
  if(sbClient && uid){
    payload.supabase = {};
    try{
      var pr = await sbClient.from('profiles_full').select('*').eq('id', uid).maybeSingle();
      if(pr && pr.data) payload.supabase.profile = pr.data;
    }catch(e){}
    try{
      var mr = await sbClient.from('mood_entries').select('*').eq('user_id', uid).order('date_key',{ascending:false}).limit(2000);
      if(mr && !mr.error) payload.supabase.mood_entries = mr.data;
    }catch(e){}
    try{
      var br = await sbClient.from('bitacora_posts').select('*').eq('user_id', uid).order('created_at',{ascending:false}).limit(500);
      if(br && !br.error) payload.supabase.bitacora_posts = br.data;
    }catch(e){}
    try{
      var dr = await sbClient.from('diary_entries').select('*').eq('user_id', uid).order('ts',{ascending:false}).limit(2000);
      if(dr && !dr.error) payload.supabase.diary_entries = dr.data;
    }catch(e){}
    try{
      var refR = await sbClient.from('referrals').select('*').or('referrer_id.eq.'+uid+',referred_id.eq.'+uid);
      if(refR && !refR.error) payload.supabase.referrals = refR.data;
    }catch(e){}
  }
  var json = JSON.stringify(payload, null, 2);
  var blob = new Blob([json], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'velo-backup-'+userName.split(' ')[0].toLowerCase()+'-'+new Date().toISOString().slice(0,10)+'.json';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
  pToast('✓','Backup descargado — guardalo en un lugar seguro 🌿');
}

// ── REFERRAL LEADERBOARD — top usuarios que más invitaron ──────────
