var _lastMoodMsgIdx = -1;

async function pSaveMood(){
  if(!_selMood){ pToast('🌈','Seleccioná cómo te sentís'); return; }
  var note = document.getElementById('moodNote');
  var noteVal = note ? note.value.trim() : '';
  var today = _dateKey();
  var data = { emoji:_selMood.emoji, label:_selMood.label, note:noteVal, ts:Date.now() };
  safeLS('set','velo_mood_'+today, JSON.stringify(data));
  // Also append to mood_log so monthly summary can see it
  var _mLog = []; try{ _mLog = JSON.parse(safeLS('get','velo_mood_log')||'[]'); }catch(e){}
  _mLog = _mLog.filter(function(m){ return m.dateKey !== today; }); // dedupe today
  _mLog.unshift(Object.assign({},data,{dateKey:today}));
  safeLS('set','velo_mood_log', JSON.stringify(_mLog.slice(0,90)));
  sbSaveMoodEntry(today, _selMood.emoji, _selMood.label, noteVal);
  _updateTopbarMoodBadge();
  pToast(_selMood.emoji, 'Estado de ánimo registrado 💚');
  _showStreakCelebration();
  if(note) note.value = '';

  // Show personalized message
  var msgs = _moodMessages[_selMood.emoji] || _moodMessages['😐'];
  var idx;
  do { idx = Math.floor(Math.random()*msgs.length); } while(idx === _lastMoodMsgIdx && msgs.length > 1);
  _lastMoodMsgIdx = idx;
  var msgEl = document.getElementById('moodSaveMsg');
  if(!msgEl){
    msgEl = document.createElement('div');
    msgEl.id = 'moodSaveMsg';
    msgEl.className = 'mood-save-msg';
    var card = document.querySelector('#pg-mood .p-card');
    if(card) card.appendChild(msgEl);
  }
  msgEl.textContent = msgs[idx];
  msgEl.style.display = 'block';
  setTimeout(function(){ if(msgEl) msgEl.style.display = 'none'; }, 6000);

  _loadMoodCalendar();
  _loadTodayMoodHome();
  _renderHomeWeekMoodGraph().catch(function(){});
  _updateHomeStreak();
  // v1416: tras registrar, abrir el resumen "Mi estado de hoy" DIRECTO encima
  // (es un overlay que funciona desde cualquier página, incluida la de ánimo)
  // — NO navegar al inicio primero, que causaba un parpadeo del home en el
  // medio. Delay corto para que se vea el toast/celebración de racha.
  // v1503: la primera vez del día, ofrecer la sugerencia contextual según el
  // ánimo (triste → compañía · feliz → compartir); si ya se mostró, el resumen.
  setTimeout(function(){
    var _fuShown = false;
    try{ _fuShown = _showMoodFollowUp(_selMood && _selMood.emoji); }catch(_){}
    if(!_fuShown){ try{ pOpenMoodChipSheet(); }catch(_){} }
  }, 1200);
  // v1228: mensual NO se auto-envía. Solo desde admin (pAdminSendMonthlyReport).
  // _checkMonthlyMoodReport();
}

// ── MOOD QUICK VIEW MODAL ─────────────────────────────────────
var _moodQVYear = 0, _moodQVMonth = 0;

async function _moodQVNav(delta){
  var now = new Date();
  var ny = _moodQVYear, nm = _moodQVMonth + delta;
  if(nm < 0){ nm = 11; ny--; }
  if(nm > 11){ nm = 0; ny++; }
  if(ny > now.getFullYear() || (ny === now.getFullYear() && nm > now.getMonth())) return;
  _moodQVYear = ny; _moodQVMonth = nm;
  var monthNames = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  var titleEl = document.getElementById('moodQVTitle');
  if(titleEl) titleEl.textContent = monthNames[nm] + ' ' + ny;
  var calEl = document.getElementById('moodQVCal');
  if(!calEl) return;
  var daysInMonth = new Date(ny, nm+1, 0).getDate();

  function _buildNavCal(mMap){
    var h='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px;margin:0 auto 16px;max-width:330px">';
    ['L','M','M','J','V','S','D'].forEach(function(dd){h+='<div style="text-align:center;font-size:11px;font-weight:700;color:var(--ink5);padding:2px 0">'+dd+'</div>';});
    var fd=new Date(ny,nm,1).getDay(); fd=fd===0?6:fd-1;
    for(var i=0;i<fd;i++)h+='<div></div>';
    for(var d2=1;d2<=daysInMonth;d2++){
      var dk2=''+ny+'-'+String(nm+1).padStart(2,'0')+'-'+String(d2).padStart(2,'0');
      var ent=mMap[dk2];
      var isT=ny===now.getFullYear()&&nm===now.getMonth()&&d2===now.getDate();
      h+='<div style="aspect-ratio:1;border-radius:8px;background:'+(ent?'rgba(116,198,157,.2)':'var(--cream2)')+';display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;'+(isT?'outline:2px solid var(--sage);outline-offset:1px':'')+'">'
        +'<span style="font-size:11px;color:'+(ent?'var(--sage3)':'var(--ink5)')+';font-weight:700;line-height:1">'+d2+'</span>'
        +(ent?'<span style="font-size:15px;line-height:1">'+ent.emoji+'</span>':'')+'</div>';
    }
    return h+'</div>';
  }

  // Show from localStorage immediately
  var moodMap = {};
  for(var d=1;d<=daysInMonth;d++){
    var dk=''+ny+'-'+String(nm+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    var st=safeLS('get','velo_mood_'+dk);
    if(st){try{var ms=JSON.parse(st);if(ms.emoji)moodMap[dk]=ms;}catch(e){}}
  }
  calEl.innerHTML = _buildNavCal(moodMap);

  // Update silently from Supabase in background
  try{
    var sbM=await sbLoadAllMoods(ny,nm+1);
    if(sbM && sbM.length){
      var ch=false;
      sbM.forEach(function(e){if(e.emoji&&!moodMap[e.date_key]){moodMap[e.date_key]=e;ch=true;}});
      if(ch && document.getElementById('moodQVCal')) calEl.innerHTML=_buildNavCal(moodMap);
    }
  }catch(e){}
}

async function pOpenMoodQuickView(){
  var existing = document.getElementById('moodQuickOv');
  if(existing) existing.remove();

  // Build calendar grid for current month (merge localStorage + Supabase)
  var now = new Date();
  var year = now.getFullYear();
  var month = now.getMonth();
  _moodQVYear = year; _moodQVMonth = month;
  var daysInMonth = new Date(year, month+1, 0).getDate();
  var monthNames = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

  // Build moodMap from localStorage first (instant)
  var moodMap = {};
  for(var _d=1; _d<=daysInMonth; _d++){
    var _dk = year+'-'+String(month+1).padStart(2,'0')+'-'+String(_d).padStart(2,'0');
    var _st = safeLS('get','velo_mood_'+_dk);
    if(_st){ try{ var _ms=JSON.parse(_st); if(_ms.emoji) moodMap[_dk]=_ms; }catch(e){} }
  }

  function _buildCalHtml(mMap){
    var html = '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px;margin:0 auto 16px;max-width:330px">';
    ['L','M','M','J','V','S','D'].forEach(function(d){
      html += '<div style="text-align:center;font-size:11px;font-weight:700;color:var(--ink5);padding:2px 0">'+d+'</div>';
    });
    var firstDay = new Date(year, month, 1).getDay();
    firstDay = firstDay === 0 ? 6 : firstDay - 1;
    for(var i=0; i<firstDay; i++) html += '<div></div>';
    for(var d=1; d<=daysInMonth; d++){
      var dk = year+'-'+String(month+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
      var entry = mMap[dk];
      var isToday = d === now.getDate();
      html += '<div style="aspect-ratio:1;border-radius:8px;background:'+(entry?'rgba(116,198,157,.2)':'var(--cream2)')+';display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;'+(isToday?'outline:2px solid var(--sage);outline-offset:1px':'')+'">'
        +'<span style="font-size:11px;color:'+(entry?'var(--sage3)':'var(--ink5)')+';font-weight:700;line-height:1">'+d+'</span>'
        +(entry?'<span style="font-size:15px;line-height:1">'+entry.emoji+'</span>':'')
        +'</div>';
    }
    return html + '</div>';
  }

  // Last 5 mood reports from inbox
  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  var reports = inbox.filter(function(m){ return m.tipo==='reporte' && m.icon==='📊'; }).slice(0,5);
  var reportsHtml = '';
  if(reports.length){
    reportsHtml = '<div style="margin-top:4px"><div style="font-size:12px;font-weight:700;letter-spacing:1.5px;color:var(--ink5);text-transform:uppercase;margin-bottom:10px">Últimos reportes</div>'
      + reports.map(function(r){
        return '<div style="background:var(--cream2);border-radius:12px;padding:12px 14px;margin-bottom:8px;cursor:pointer" onclick="document.getElementById(\'moodQuickOv\').remove();pOpenInboxMsg(\''+r.id+'\',null)">'
          +'<div style="font-size:14px;font-weight:700;color:var(--ink);margin-bottom:3px">'+_escHtml(r.asunto||'Reporte mensual')+'</div>'
          +'<div style="font-size:13px;color:var(--ink4);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.5">'+_escHtml(r.extracto||'')+'</div>'
          +'<div style="font-size:12px;color:var(--ink5);margin-top:4px">'+_escHtml(r.fecha||'')+'</div>'
          +'</div>';
      }).join('')
      + '</div>';
  }

  // Show modal IMMEDIATELY from localStorage — no waiting for Supabase
  var ov = document.createElement('div');
  ov.className = 'p-modal-ov show';
  ov.id = 'moodQuickOv';
  ov.innerHTML = '<div class="p-sheet" style="max-height:88vh;overflow-y:auto">'
    +'<div class="p-sheet-handle"></div>'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">'
    +'<button onclick="_moodQVNav(-1)" style="width:32px;height:32px;border-radius:50%;background:var(--cream2);border:none;font-size:18px;cursor:pointer;color:var(--ink3);flex-shrink:0;line-height:1">‹</button>'
    +'<div style="text-align:center"><div style="font-size:12px;font-weight:700;letter-spacing:1.5px;color:var(--sage3);text-transform:uppercase">Seguimiento</div>'
    +'<div id="moodQVTitle" style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:var(--ink)">'+monthNames[month]+' '+year+'</div></div>'
    +'<button onclick="document.getElementById(\'moodQuickOv\').remove()" style="width:32px;height:32px;border-radius:50%;background:var(--cream2);border:none;font-size:16px;cursor:pointer;color:var(--ink4);flex-shrink:0">✕</button>'
    +'</div>'
    +'<div style="background:rgba(116,198,157,.07);border:1px solid rgba(116,198,157,.18);border-radius:10px;padding:8px 12px;margin-bottom:10px;font-size:13px;color:var(--sage2)">🔒 Solo vos podés ver estos registros</div>'
    +'<div style="background:rgba(221,212,245,.15);border:1px solid rgba(196,181,232,.3);border-radius:10px;padding:9px 12px;margin-bottom:14px;font-size:13px;color:var(--ink3);line-height:1.55">✨ La IA genera un reporte mensual con análisis de tus ánimos registrados. Lo recibirás en tu <strong>Buzón Velo</strong> el día 1 de cada mes 💌</div>'
    +'<div id="moodQVCal">'+_buildCalHtml(moodMap)+'</div>'
    + reportsHtml
    +'<div style="height:8px"></div>'
    +'<button class="p-btn p-btn--primary p-btn--md p-btn--full" onclick="document.getElementById(\'moodQuickOv\').remove();pGoTo(\'mood\')">Registrar ánimo de hoy ✨</button>'
    +'<div style="height:8px"></div>'
    +'<button class="p-btn p-btn--secondary p-btn--md p-btn--full" onclick="document.getElementById(\'moodQuickOv\').remove()">Cerrar</button>'
    +'</div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });

  // Now fetch from Supabase in background and silently update calendar if more data found
  try{
    var sbMoods = await sbLoadAllMoods(year, month+1);
    if(sbMoods && sbMoods.length){
      var changed = false;
      sbMoods.forEach(function(e){ if(e.emoji && !moodMap[e.date_key]){ moodMap[e.date_key]=e; changed=true; } });
      if(changed){
        var calEl = document.getElementById('moodQVCal');
        if(calEl) calEl.innerHTML = _buildCalHtml(moodMap);
      }
    }
  }catch(e){}
}

// ── SATISFACTION SURVEY (every 90 days) ──────────────────────
var SURVEY_INTERVAL = 90 * 24 * 60 * 60 * 1000; // 90 days in ms
var _surveyScores   = { general: 0, utilidad: 0, recomendaria: 0 };
var _surveyFuncion  = '';

// Stable id per calendar quarter so read-tracking survives re-renders/reloads
function _surveyQuarterId(){
  var n = new Date();
  return 'survey-' + n.getFullYear() + 'Q' + (Math.floor(n.getMonth()/3)+1);
}

function _checkSurveyDue(){
  // Only for regular users (not admin, not pro)
  if(safeLS('get','velo_user_type') === 'admin') return;
  if(safeLS('get','velo_user_type') === 'pro') return;
  // Require at least 7 distinct days of usage before showing first survey
  try{
    var _vd = JSON.parse(safeLS('get','velo_visit_days')||'[]');
    if(!Array.isArray(_vd) || _vd.length < 7) return;
  }catch(e){ return; }
  var sid = _surveyQuarterId();
  // Already opened/completed this quarter's survey → never re-add
  if(safeLS('get','velo_read_'+sid) === '1') return;
  if(_syncedReadIds[sid]) return; // deleted on another device
  var last = parseInt(safeLS('get','velo_last_survey')||'0', 10);
  if(Date.now() - last < SURVEY_INTERVAL) return;
  // Don't send twice in the same session
  if(safeLS('get','velo_survey_sent_session') === '1') return;
  safeLS('set','velo_survey_sent_session','1');
  // Add inbox notification
  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  // Skip if ANY survey already exists (read or unread) — avoids duplicate unread copies
  if(inbox.some(function(m){ return m.tipo === 'encuesta'; })) return;
  inbox.unshift({
    id: sid,
    tipo: 'encuesta',
    icon: '📊',
    remitente: 'Velo — Encuesta trimestral',
    asunto: '¿Cómo ves a Velo? Tu opinión nos importa 🌿',
    extracto: 'Tomá 2 minutos para contarnos qué tal te parece la app. Tu feedback es clave para mejorar.',
    cuerpo: '',
    accion: 'pOpenSurvey()',
    leido: false,
    fecha: new Date().toLocaleDateString('es',{day:'2-digit',month:'short'})
  });
  safeLS('set','velo_inbox', JSON.stringify(inbox.slice(0,100)));
  _updateInboxDot();
  setTimeout(function(){
    pToast('📊','¡Tenemos una encuesta para vos! Revisá tu buzón 🌿');
  }, 4000);
}

function pOpenSurvey(){
  _surveyScores = { general: 0, utilidad: 0, recomendaria: 0 };
  _surveyFuncion = '';
  var ov = document.getElementById('surveyOv');
  if(!ov) return;
  // Reset UI
  ov.querySelectorAll('.survey-btn').forEach(function(b){ b.classList.remove('selected'); });
  var ta = ov.querySelector('#surveyTa');
  if(ta) ta.value = '';
  ov.querySelectorAll('.survey-func-btn').forEach(function(b){ b.classList.remove('selected'); });
  ov.classList.add('show');
  // Mark survey as read immediately when opened (don't require submit to clear badge)
  try{
    var inbx = JSON.parse(safeLS('get','velo_inbox')||'[]');
    var changed = false;
    inbx = inbx.map(function(m){ if(m.tipo==='encuesta' && !m.leido){ changed=true; return Object.assign({},m,{leido:true}); } return m; });
    if(changed){ safeLS('set','velo_inbox', JSON.stringify(inbx)); _updateHomeBell(); }
  }catch(e){}
}

function pSurveyRate(q, val, el){
  _surveyScores[q] = val;
  var group = el.closest('.survey-score-group');
  if(group) group.querySelectorAll('.survey-btn').forEach(function(b){ b.classList.remove('selected'); });
  el.classList.add('selected');
}

function pSurveyFuncion(val, el){
  _surveyFuncion = val;
  var group = el.closest('.survey-func-row');
  if(group) group.querySelectorAll('.survey-func-btn').forEach(function(b){ b.classList.remove('selected'); });
  el.classList.add('selected');
}

function pSubmitSurvey(){
  if(!_surveyScores.general){ pToast('⚠️','Calificá tu experiencia general (1-10)'); return; }
  if(!_surveyScores.utilidad){ pToast('⚠️','Calificá qué tan útil te parece (1-10)'); return; }
  if(!_surveyScores.recomendaria){ pToast('⚠️','¿Con qué probabilidad la recomendarías? (1-10)'); return; }
  var ta = document.getElementById('surveyTa');
  var sugerencia = ta ? ta.value.trim() : '';
  var response = {
    ts: Date.now(),
    scores: { general: _surveyScores.general, utilidad: _surveyScores.utilidad, recomendaria: _surveyScores.recomendaria },
    funcion: _surveyFuncion || 'No indicado',
    sugerencia: sugerencia // stored generically, shown without attribution
  };
  var responses = []; try{ responses = JSON.parse(safeLS('get','velo_survey_responses')||'[]'); }catch(e){}
  responses.unshift(response);
  safeLS('set','velo_survey_responses', JSON.stringify(responses.slice(0,500)));
  safeLS('set','velo_last_survey', String(Date.now()));
  // Persist to Supabase so admin sees aggregated results
  _initSupabase();
  if(sbClient){
    try{
      sbClient.from('surveys').insert({ user_id: safeLS('get','velo_user_id')||safeLS('get','velo_user_email')||'anon',
        general:_surveyScores.general, utilidad:_surveyScores.utilidad, recomendaria:_surveyScores.recomendaria,
        funcion:_surveyFuncion||'', sugerencia:sugerencia }).then(function(){}).catch(function(){});
    }catch(e){}
  }
  safeLS('set','velo_survey_sent_session','1');
  // Mark inbox message as read
  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  inbox = inbox.map(function(m){ return m.tipo==='encuesta' ? Object.assign({},m,{leido:true}) : m; });
  safeLS('set','velo_inbox', JSON.stringify(inbox));
  _updateHomeBell();
  closeModal('surveyOv');
  pToast('💚','¡Gracias por tu opinión! Nos ayudás a mejorar Velo 🌿');
  setTimeout(function(){ if(document.getElementById('inboxList')) pRenderInbox(); }, 300);
}

async function _adminLoadSurveys(){
  var el = document.getElementById('adminSurveyResults');
  if(!el) return;
  var responses = [];
  _initSupabase();
  if(sbClient){
    try{
      var r = await sbClient.from('surveys').select('general,utilidad,recomendaria,funcion,sugerencia,created_at').order('created_at',{ascending:false}).limit(500);
      if(!r.error && r.data && r.data.length){
        // Supabase rows have flat shape: { general, utilidad, recomendaria, funcion, sugerencia }
        responses = r.data.map(function(row){
          return { scores:{ general:row.general||0, utilidad:row.utilidad||0, recomendaria:row.recomendaria||0 }, funcion:row.funcion||'', sugerencia:row.sugerencia||'' };
        });
      }
    }catch(e){}
  }
  // Fallback to localStorage (own device responses)
  if(!responses.length){
    try{ responses = JSON.parse(safeLS('get','velo_survey_responses')||'[]'); }catch(e){}
  }
  el.innerHTML = _renderSurveyResults(responses);
}

function _renderSurveyResults(responses){
  if(!responses || !responses.length){
    return '<p style="font-size:14px;color:rgba(255,255,255,.3);padding:12px 0">Sin respuestas aún.</p>';
  }
  var total = responses.length;
  var avgGeneral    = (responses.reduce(function(s,r){ return s + ((r.scores&&r.scores.general)||r.general||0); }, 0) / total).toFixed(1);
  var avgUtilidad   = (responses.reduce(function(s,r){ return s + ((r.scores&&r.scores.utilidad)||r.utilidad||0); }, 0) / total).toFixed(1);
  var avgRecomend   = (responses.reduce(function(s,r){ return s + ((r.scores&&r.scores.recomendaria)||r.recomendaria||0); }, 0) / total).toFixed(1);
  // Most used feature
  var funcCount = {};
  responses.forEach(function(r){ if(r.funcion) funcCount[r.funcion] = (funcCount[r.funcion]||0)+1; });
  var topFunc = Object.keys(funcCount).sort(function(a,b){ return funcCount[b]-funcCount[a]; })[0] || '—';
  // Suggestions (generic, no attribution)
  var sugs = responses.filter(function(r){ return r.sugerencia && r.sugerencia.length > 3; }).slice(0,10);

  function scoreBar(val){
    var pct = Math.round((parseFloat(val)/10)*100);
    var color = pct >= 70 ? 'rgba(116,198,157,.8)' : pct >= 40 ? 'rgba(200,162,0,.8)' : 'rgba(220,80,80,.8)';
    return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">'
      +'<div style="flex:1;height:7px;background:rgba(255,255,255,.08);border-radius:99px;overflow:hidden">'
      +'<div style="height:100%;width:'+pct+'%;background:'+color+';border-radius:99px;transition:width .5s"></div></div>'
      +'<span style="font-size:15px;font-weight:800;color:'+color+';min-width:28px;text-align:right">'+val+'</span>'
      +'</div>';
  }

  return '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px">'
    +'<div style="background:rgba(116,198,157,.07);border:1px solid rgba(116,198,157,.15);border-radius:12px;padding:12px;text-align:center">'
    +'<div style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:6px">Satisfacción general</div>'
    +scoreBar(avgGeneral)+'</div>'
    +'<div style="background:rgba(116,198,157,.07);border:1px solid rgba(116,198,157,.15);border-radius:12px;padding:12px;text-align:center">'
    +'<div style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:6px">Utilidad</div>'
    +scoreBar(avgUtilidad)+'</div>'
    +'<div style="background:rgba(116,198,157,.07);border:1px solid rgba(116,198,157,.15);border-radius:12px;padding:12px;text-align:center">'
    +'<div style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:6px">Recomendaría (NPS)</div>'
    +scoreBar(avgRecomend)+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:10px;margin-bottom:14px">'
    +'<div style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:10px 14px;flex:1">'
    +'<span style="font-size:12px;color:rgba(255,255,255,.35);letter-spacing:1px">FUNCIÓN MÁS USADA</span>'
    +'<div style="font-size:15px;font-weight:700;color:rgba(255,255,255,.8);margin-top:4px">'+_escHtml(topFunc)+'</div></div>'
    +'<div style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:10px 14px;flex:1">'
    +'<span style="font-size:12px;color:rgba(255,255,255,.35);letter-spacing:1px">RESPUESTAS TOTALES</span>'
    +'<div style="font-size:15px;font-weight:700;color:rgba(255,255,255,.8);margin-top:4px">'+total+'</div></div>'
    +'</div>'
    +(sugs.length ? '<div style="font-size:12px;font-weight:700;color:rgba(255,255,255,.3);letter-spacing:1px;margin-bottom:8px">SUGERENCIAS (anónimas)</div>'
      + sugs.map(function(r){
          return '<div style="background:rgba(255,255,255,.04);border-left:3px solid rgba(116,198,157,.4);border-radius:0 8px 8px 0;padding:8px 10px;margin-bottom:6px;font-size:14px;color:rgba(255,255,255,.6);line-height:1.5">'+_escHtml(r.sugerencia)+'</div>';
        }).join('')
    : '');
}

async function _checkMonthlyMoodReport(){
  var today = new Date();
  if(today.getDate() !== 1) return;
  var reportKey = 'velo_mood_report_'+today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0');
  if(safeLS('get',reportKey) === '1') return;
  safeLS('set', reportKey, '1');

  var prev = new Date(today.getFullYear(), today.getMonth()-1, 1);
  var prevYear = prev.getFullYear();
  var prevMonth = prev.getMonth()+1;
  var daysInPrev = new Date(prevYear, prevMonth, 0).getDate();
  var moodCounts = {}; var totalDays = 0;
  var firstHalf = {}; var secondHalf = {};
  for(var d = 1; d <= daysInPrev; d++){
    var k = prevYear+'-'+String(prevMonth).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    var stored = safeLS('get','velo_mood_'+k);
    if(stored){ try{ var ms = JSON.parse(stored); if(ms.emoji){
      moodCounts[ms.emoji]=(moodCounts[ms.emoji]||0)+1; totalDays++;
      if(d <= 15){ firstHalf[ms.emoji]=(firstHalf[ms.emoji]||0)+1; }
      else { secondHalf[ms.emoji]=(secondHalf[ms.emoji]||0)+1; }
    }}catch(e){} }
  }

  var monthNames = ['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  var monthName = monthNames[prevMonth];
  var positives = (moodCounts['😄']||0) + (moodCounts['😊']||0);
  var topEmoji = totalDays ? Object.keys(moodCounts).sort(function(a,b){ return moodCounts[b]-moodCounts[a]; })[0] : null;
  var summary = totalDays ? 'Registraste '+totalDays+' días en '+monthName+'. Tu ánimo más frecuente: '+topEmoji : 'Sin registros en '+monthName;

  // Happy wall stats
  var happyStats = _happyStatsGet(prev);
  var happyLine = '';
  if(happyStats.posts || happyStats.reactionsReceived || happyStats.commentsReceived){
    var parts = [];
    if(happyStats.posts) parts.push((happyStats.posts===1?'1 momento de alegría compartido':happyStats.posts+' momentos de alegría compartidos')+' 🌻');
    if(happyStats.reactionsReceived) parts.push(happyStats.reactionsReceived+(happyStats.reactionsReceived===1?' reacción':' reacciones')+' recibidas 💛');
    if(happyStats.commentsReceived) parts.push(happyStats.commentsReceived+(happyStats.commentsReceived===1?' comentario':' comentarios')+' en tus publicaciones 💬');
    if(parts.length) happyLine = '\n\nEn la comunidad: '+parts.join(', ')+'.';
  }

  // Community activity stats
  var helpedOthers  = parseInt(safeLS('get','velo_guardian_convs')||'0',10);
  var helpReceived  = parseInt(safeLS('get','velo_help_received')||'0',10);
  var myBottles = []; try{ myBottles = JSON.parse(safeLS('get','velo_my_bottles')||'[]'); }catch(e){}
  var bottleCount = myBottles.filter(function(b){ var bd=new Date(b.ts); return b.ts && bd.getFullYear()===prevYear && (bd.getMonth()+1)===prevMonth; }).length;

  // Diary activity for the month
  var diaryArr = []; try{ diaryArr = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  var monthPrefix = prevYear+'-'+String(prevMonth).padStart(2,'0');
  var diaryCount = diaryArr.filter(function(e){ return e.dateLabel && e.dateLabel.indexOf(monthPrefix) > -1 || (e.ts && new Date(e.ts).getFullYear()===prevYear && (new Date(e.ts).getMonth()+1)===prevMonth); }).length;

  // Reviews received from Supabase
  var reviewsReceived = 0; var reviewStars = 0;
  _initSupabase();
  var myUid = safeLS('get','velo_user_id')||'';
  if(sbClient && myUid){
    try{
      await _ensureSbSession();
      var cutoffStart = new Date(prevYear, prevMonth-1, 1).toISOString();
      var cutoffEnd   = new Date(prevYear, prevMonth, 0, 23, 59, 59).toISOString();
      var rvRes = await sbClient.from('reviews').select('stars')
        .eq('pro_id', myUid).gte('created_at', cutoffStart).lte('created_at', cutoffEnd);
      if(rvRes.data && rvRes.data.length){
        reviewsReceived = rvRes.data.length;
        reviewStars = Math.round(rvRes.data.reduce(function(s,r){ return s+(r.stars||5); },0) / reviewsReceived * 10) / 10;
      }
    }catch(e){}
  }

  // Detect unused sections for invitation
  var happyArr = []; try{ happyArr = JSON.parse(safeLS('get','velo_happy')||'[]'); }catch(e){}
  // v1487: sugerir solo secciones ACTIVAS (Muro Feliz y Al Mar están ocultas).
  // Usa los conteos reales de velo_badge_counts (Supabase) cuando existen.
  var unusedSections = [];
  var _bcCounts = null; try{ _bcCounts = JSON.parse(safeLS('get','velo_badge_counts')||'null'); }catch(e){}
  if(!diaryArr.length) unusedSections.push('el Diario Íntimo 📔');
  if(_bcCounts){
    if(!(_bcCounts.vibes>0))    unusedSections.push('las Vibes de hoy ✨');
    if(!(_bcCounts.bitacora>0)) unusedSections.push('la Bitácora 📖');
    if(!(_bcCounts.dq>0))       unusedSections.push('la Pregunta del Día 💭');
  }
  unusedSections = unusedSections.slice(0,2); // máx 2 sugerencias, sin abrumar

  var MIN_DAYS_FOR_ANALYSIS = 5;
  var analysis;
  if(!totalDays){
    analysis = 'No registraste tu ánimo en '+monthName+'. Recordá que el seguimiento diario te ayuda a conocerte mejor. ¡Este mes es una nueva oportunidad! 🌱';
  } else if(totalDays < MIN_DAYS_FOR_ANALYSIS){
    // Not enough data for a meaningful AI analysis
    var communityLines = [];
    if(helpedOthers > 0) communityLines.push('acompañaste a '+helpedOthers+' persona'+(helpedOthers>1?'s':'')+' como guardián/a 💙');
    if(helpReceived > 0) communityLines.push('recibiste apoyo '+helpReceived+' vez'+(helpReceived>1?'es':'')+' 🌿');
    if(bottleCount > 0) communityLines.push('lanzaste '+bottleCount+' mensaje'+(bottleCount>1?'s':'')+' al Mar 🌊');
    if(happyStats.posts > 0) communityLines.push('compartiste '+happyStats.posts+' momento'+(happyStats.posts>1?'s':'')+' con la comunidad 🌻');
    if(diaryCount > 0) communityLines.push('escribiste '+diaryCount+' entrada'+(diaryCount>1?'s':'')+' en tu diario 📔');
    var communityText = communityLines.length
      ? ' Eso sí, este mes '+communityLines.join(', ')+'. ¡Eso también cuenta!'
      : ' Animate a explorar más espacios de Velo: la Bitácora, el Diario o las Vibes de hoy te esperan. 🌿';
    analysis = 'En '+monthName+' registraste solo '+totalDays+' día'+(totalDays>1?'s':'')+' de ánimo — necesitamos al menos '+MIN_DAYS_FOR_ANALYSIS+' para hacer un análisis emocional personalizado. No alcanzó esta vez, pero ¡ya sabés cómo funciona! Registrá a diario este mes y el 1° de '+monthNames[today.getMonth()+1 > 12 ? 1 : today.getMonth()+1]+' vas a recibir tu análisis completo. 📊'+communityText;
  } else {
    var moodList = Object.entries(moodCounts).map(function(e){ return e[0]+' ('+e[1]+' días)'; }).join(', ');
    var topFirst  = Object.keys(firstHalf).sort(function(a,b){ return (firstHalf[b]||0)-(firstHalf[a]||0); })[0]||'variado';
    var topSecond = Object.keys(secondHalf).sort(function(a,b){ return (secondHalf[b]||0)-(secondHalf[a]||0); })[0]||'variado';
    var pct = Math.round(positives/totalDays*100);
    var prompt = 'Sos un asistente empático de bienestar emocional de la app Velo.\n'
      +'Analizá los datos del usuario en '+monthName+' y escribí un mensaje personalizado, cálido y esperanzador en español rioplatense (usá "vos/te").\n\n'
      +'Datos reales del mes:\n'
      +'- Días registrados: '+totalDays+' de '+daysInPrev+' posibles\n'
      +'- Distribución de ánimo: '+moodList+'\n'
      +'- Primera quincena predominó: '+topFirst+'\n'
      +'- Segunda quincena predominó: '+topSecond+'\n'
      +'- Días con ánimo positivo: '+pct+'%\n'
      +(diaryCount?'- Entradas en el Diario: '+diaryCount+'\n':'')
      +(happyStats.posts?'- Momentos compartidos con la comunidad: '+happyStats.posts+'\n':'')
      +(happyStats.reactionsReceived?'- Reacciones recibidas en sus momentos: '+happyStats.reactionsReceived+'\n':'')
      +(helpedOthers?'- Conversaciones como guardián/acompañante: '+helpedOthers+'\n':'')
      +(helpReceived?'- Veces que recibió apoyo/acompañamiento: '+helpReceived+'\n':'')
      +(bottleCount?'- Mensajes enviados al Mar: '+bottleCount+'\n':'')
      +(reviewsReceived?'- Reseñas recibidas este mes: '+reviewsReceived+' (promedio '+reviewStars+'⭐)\n':'')
      +'\nEscribí 3-4 oraciones que:\n'
      +'1. Reconozcan cómo fue el mes con honestidad\n'
      +'2. Destaquen algún patrón real de los datos (ánimo, conexión con otros, escritura)\n'
      +'3. Terminen con un mensaje motivador sin ser cursi\n'
      +'Sin asteriscos, sin markdown, sin listas. Solo texto corrido. Máximo 100 palabras.';

    var aiText = await _geminiCall(prompt);
    analysis = aiText || (pct >= 60
      ? '¡'+monthName+' fue un mes mayormente positivo para vos! '+pct+'% de tus días registraste bienestar. Seguí construyendo ese espacio de cuidado. 🌻'
      : pct >= 35
        ? monthName+' tuvo sus altibajos. Lo importante es que seguís registrando y avanzando. 💙'
        : 'Parece que '+monthName+' fue un mes desafiante. Gracias por seguir registrando incluso en los días difíciles. 🌿');
  }

  // Build rich message body
  var extraLines = '';
  if(helpedOthers > 0) extraLines += '\n\n💙 Acompañaste a '+helpedOthers+' persona'+(helpedOthers>1?'s':'')+' como guardián/a en '+monthName+'. Eso importa más de lo que imaginás.';
  if(helpReceived > 0) extraLines += '\n\n🌿 Recibiste acompañamiento '+helpReceived+' vez'+(helpReceived>1?'es':'')+'. Pedir apoyo también es valentía.';
  if(bottleCount > 0) extraLines += '\n\n🌊 Lanzaste '+bottleCount+' mensaje'+(bottleCount>1?'s':'')+' al Mar. Esas palabras llegaron a alguien que las necesitaba.';
  if(reviewsReceived > 0) extraLines += '\n\n⭐ Recibiste '+reviewsReceived+' reseña'+(reviewsReceived>1?'s':'')+' este mes con un promedio de '+reviewStars+' estrellas. ¡La comunidad te valora!';
  if(diaryCount > 0) extraLines += '\n\n📔 Escribiste '+diaryCount+' entrada'+(diaryCount>1?'s':'')+' en tu diario. Cada página es un paso hacia conocerte mejor.';
  if(unusedSections.length > 0) extraLines += '\n\n✨ ¿Todavía no exploraste '+unusedSections.join(' ni ')+'? Este mes es un buen momento para descubrirlos.';
  extraLines += '\n\n🌻 Si Velo te está siendo útil, considerá apoyar con una donación. Cada aporte ayuda a mantener este espacio gratuito para más personas.';

  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  inbox.unshift({
    id: 'mood-report-'+Date.now(), tipo:'reporte', icon:'📊',
    remitente:'Velo — Análisis de Bienestar ✨',
    asunto:'Tu resumen de '+monthName+' 🌿',
    extracto: summary,
    cuerpo: analysis + happyLine + extraLines,
    leido:false,
    fecha: new Date().toLocaleDateString('es',{day:'2-digit',month:'short'})
  });
  safeLS('set','velo_inbox', JSON.stringify(inbox.slice(0,100)));
  _updateInboxDot();
  setTimeout(function(){ pToast('📊','Recibiste tu resumen de '+monthName+' en el buzón 💚'); }, 3000);
}

// v1406: mes que se está viendo en el calendario (para navegar a meses
// anteriores y completar días viejos). null = mes actual.
var _moodCalYear = null, _moodCalMonth = null;
function pMoodCalNav(delta){
  var now = new Date();
  var y = _moodCalYear || now.getFullYear();
  var m = (_moodCalMonth || (now.getMonth()+1)) + delta;
  if(m < 1){ m = 12; y--; }
  else if(m > 12){ m = 1; y++; }
  // No permitir navegar al futuro más allá del mes actual
  if(y > now.getFullYear() || (y === now.getFullYear() && m > now.getMonth()+1)) return;
  _moodCalYear = y; _moodCalMonth = m;
  _loadMoodCalendar();
}
async function _loadMoodCalendar(){
  var cal = document.getElementById('moodCalendar');
  var hist = document.getElementById('moodHistory');
  if(!cal) return;
  var _tok = _navToken;
  var now = new Date();
  var year = _moodCalYear || now.getFullYear();
  var month = _moodCalMonth || (now.getMonth() + 1);
  var isCurrentMonth = (year === now.getFullYear() && month === now.getMonth()+1);
  // Título del mes + deshabilitar "siguiente" si ya estamos en el mes actual
  var _calTitle = document.getElementById('moodCalTitle');
  if(_calTitle){ _calTitle.textContent = new Date(year, month-1, 1).toLocaleDateString('es-AR',{month:'long',year:'numeric'}); }
  var _nextBtn = document.getElementById('moodCalNextBtn');
  if(_nextBtn){ _nextBtn.style.visibility = isCurrentMonth ? 'hidden' : 'visible'; }
  var daysInMonth = new Date(year, month, 0).getDate();
  var sbData = await sbLoadAllMoods(year, month);
  if(_navToken !== _tok || !document.getElementById('moodCalendar')) return;
  var moodMap = {};
  if(sbData){ sbData.forEach(function(e){ moodMap[e.date_key] = e; }); }
  // Fill from local too
  for(var d = 1; d <= daysInMonth; d++){
    var key = year+'-'+String(month).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    var local = safeLS('get','velo_mood_'+key);
    if(local && !moodMap[key]){ try{ var lo = JSON.parse(local); moodMap[key] = lo; }catch(e){} }
  }
  var html = '';
  // v1406: encabezados de días + offset del 1er día para que cada fecha caiga
  // bajo su día de la semana real (antes se amontonaban sin alinear).
  ['L','M','M','J','V','S','D'].forEach(function(wd){
    html += '<div style="text-align:center;font-size:11px;font-weight:800;color:var(--ink5);padding:2px 0 4px;letter-spacing:.5px">'+wd+'</div>';
  });
  var _firstDow = new Date(year, month-1, 1).getDay(); // 0=Dom
  _firstDow = _firstDow === 0 ? 6 : _firstDow - 1;     // semana arranca en Lun
  for(var _o=0; _o<_firstDow; _o++) html += '<div></div>';
  // En meses pasados TODOS los días son "pasados" y completables; en el mes
  // actual, solo hasta hoy.
  var todayDay = isCurrentMonth ? now.getDate() : (daysInMonth + 1);
  var missingPast = 0; // días pasados sin registro en el mes visible
  for(var dd = 1; dd <= daysInMonth; dd++){
    var k = year+'-'+String(month).padStart(2,'0')+'-'+String(dd).padStart(2,'0');
    var entry = moodMap[k];
    var isToday2 = isCurrentMonth && dd === todayDay;
    var isPast = dd < todayDay; // días anteriores clickeables para backfill
    var isFuture = dd > todayDay;
    if(isPast && !entry) missingPast++;
    var clickable = (isPast && !entry) || isToday2;
    var cursor = clickable ? 'cursor:pointer;' : '';
    var onClick = clickable ? ' onclick="pOpenBackfillMood(\''+k+'\')"' : '';
    var titleTxt = entry
      ? k+' · '+(entry.label||entry.emoji)+(entry.note?' — '+String(entry.note).replace(/"/g,'&quot;'):'')
      : (isFuture ? k+' · aún no llegó' : (isToday2 ? k+' · Registrá tu ánimo de hoy' : k+' · Registrar ánimo de este día'));
    // Fondo legible por estado: registrado (verde tenue), completable
    // (punteado verde), futuro (muy tenue).
    var _bg = entry ? 'rgba(116,198,157,.22)' : (clickable ? 'rgba(116,198,157,.06)' : 'rgba(255,255,255,.03)');
    var _numCol = entry ? 'var(--sage3)' : (isFuture ? 'rgba(150,160,150,.45)' : 'var(--ink3)');
    html += '<div'+onClick+' style="aspect-ratio:1;background:'+_bg+';border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;'+cursor+(isToday2?'outline:2px solid var(--sage);outline-offset:1px;':'')+(clickable && !entry?'border:1.5px dashed rgba(116,198,157,.55);':'')+'" title="'+titleTxt+'">'
      +'<span style="font-size:12.5px;color:'+_numCol+';font-weight:800;line-height:1">'+dd+'</span>'
      +(entry
          ? '<span style="font-size:17px;line-height:1">'+entry.emoji+'</span>'
          : (clickable ? '<span style="font-size:13px;line-height:1;color:rgba(116,198,157,.85);font-weight:800">＋</span>' : ''));
    html += '</div>';
  }
  cal.innerHTML = html;
  // Aviso proactivo si hay 2+ días atrás sin registrar en el mes vigente
  var missBanner = document.getElementById('moodMissBanner');
  if(missingPast >= 2){
    if(!missBanner){
      missBanner = document.createElement('div');
      missBanner.id = 'moodMissBanner';
      missBanner.style.cssText = 'margin:10px 0 14px;padding:12px 14px;background:rgba(116,198,157,.18);border:1.5px solid rgba(116,198,157,.5);border-radius:14px;display:flex;align-items:center;gap:10px;font-family:Jost,sans-serif;font-size:13px;color:var(--ink);cursor:pointer';
      missBanner.onclick = function(){ pOpenMonthlyMissed(year, month); };
      if(cal.parentNode) cal.parentNode.insertBefore(missBanner, cal);
    }
    missBanner.onclick = function(){ pOpenMonthlyMissed(year, month); };
    missBanner.innerHTML = '<span style="font-size:22px;flex-shrink:0">🌿</span>'
      +'<div style="flex:1;min-width:0"><div style="font-weight:800;color:var(--ink);margin-bottom:2px">Tenés '+missingPast+' día'+(missingPast===1?'':'s')+' sin registrar '+(isCurrentMonth?'este mes':'en '+new Date(year,month-1,1).toLocaleDateString('es-AR',{month:'long'}))+'</div>'
      +'<div style="font-size:11.5px;color:var(--ink2);line-height:1.4">Tocá un día del calendario o acá para recuperar cómo te sentiste</div></div>'
      +'<span style="font-size:16px;color:var(--ink2);flex-shrink:0">›</span>';
  } else if(missBanner){
    missBanner.remove();
  }
  // History list
  if(hist){
    var entries = Object.keys(moodMap).sort().reverse().slice(0,10);
    if(!entries.length){ hist.innerHTML = '<p class="p-sm p-muted">Sin registros este mes.</p>'; }
    else {
      hist.innerHTML = '<div class="p-label" style="margin-bottom:10px">Últimos registros</div>'+entries.map(function(k){
        var e = moodMap[k];
        return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)">'
          +'<span style="font-size:20px">'+e.emoji+'</span>'
          +'<div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:600;color:var(--ink)">'+e.label+'</div>'
          +'<div style="font-size:13px;color:var(--ink5)">'+k+(e.note?' · '+e.note:'')+'</div></div>'
          +'<button onclick="pDeleteMood(\''+k+'\')" style="font-size:14px;background:none;border:none;cursor:pointer;color:var(--ink5);padding:4px 6px;border-radius:6px;flex-shrink:0" title="Eliminar registro">🗑️</button>'
          +'</div>';
      }).join('');
    }
  }
}

async function pClearAllMoods(){
  _pConfirm('¿Borrar todo el historial de ánimo? Esta acción no se puede deshacer.', async function(){
    _initSupabase();
    _moodResetPending = true;
    _moodSyncDone = true;
    var _authCl; try{ _authCl = await sbClient.auth.getUser(); }catch(e){}
    var _clUid = (_authCl && _authCl.data && _authCl.data.user) ? _authCl.data.user.id : null;
    if(sbClient && _clUid){
      try{
        var _delCl = await sbClient.from('mood_entries').delete().eq('user_id', _clUid).select('date_key');
        if(_delCl && _delCl.error){
          pToast('⚠️','Error al borrar ánimos. Agregá política DELETE en Supabase.');
          _moodResetPending = false; _moodSyncDone = false; return;
        }
      }catch(e){ pToast('⚠️','Error al conectar'); _moodResetPending = false; _moodSyncDone = false; return; }
    }
    var toRemove = [];
    for(var i = 0; i < localStorage.length; i++){
      var k = localStorage.key(i);
      if(k && (k.startsWith('velo_mood_') || k.startsWith('velo_daily_status_'))) toRemove.push(k);
    }
    toRemove.forEach(function(k){ localStorage.removeItem(k); });
    safeLS('del','velo_mood_log');
    _sbVerifiedMoodCount = 0;
    safeLS('set','velo_mood_cleared_at', String(Date.now())); // blocks _pushMissingMoodsToSb from re-uploading
    _setEl('profileDays', 0);
    pToast('🗑️','Historial de ánimo eliminado');
    pInitMood();
    _renderHomeWeekMoodGraph().catch(function(){});
    _updateHomeStreak();
  });
}

