// ── RESPIRA (Breathing) ────────────────────────────────────────
var _respiraRunning = false;
var _respiraTimer = null;
var _respiraAudio = null;
var _respiraMuted = false;
var _respiraPhases = [
  { name:'Inhala…',  dur:4,  colorA:'rgba(116,198,157,.95)', colorB:'rgba(60,160,110,.6)' },
  { name:'Sostén…',  dur:7,  colorA:'rgba(168,212,232,.90)', colorB:'rgba(80,160,200,.5)' },
  { name:'Exhala…',  dur:8,  colorA:'rgba(196,181,232,.88)', colorB:'rgba(140,100,200,.45)' }
];
var _respiraPhaseIdx = 0;
var _respiraCount    = 0;
var _respiraRaf      = null;
var _respiraAmbientItems = [];

function pInitRespira(){
  var canvas = document.getElementById('respiraCanvas');
  if(!canvas) return;
  _drawRespiraCircleSmooth('rgba(116,198,157,.35)', 0.18);
  _setEl('respiraPhase','Prepárate');
  _setEl('respiraCount','');
  _setEl('respiraBtn','Comenzar');
  _respiraRunning = false;
}

function pStartRespira(){
  if(_respiraRunning){ _stopRespira(); return; }
  _respiraRunning = true;
  _setEl('respiraBtn','Detener');
  _respiraPhaseIdx = 0;
  _startRespiraAmbient();
  _startRespiraMusic();
  _runRespiraPhase();
}

function _startRespiraMusic(){
  _stopRespiraMusic();
  _respiraMuted = false;
  try{
    _respiraAudio = new Audio('sounds/meditacion.mp3?v=1036');
    _respiraAudio.loop = true;
    _respiraAudio.volume = 0.55;
    _respiraAudio.setAttribute('playsinline','');
    _respiraAudio.play().catch(function(){});
    var wrap = document.getElementById('respiraSoundWrap');
    var btn  = document.getElementById('respiraSoundBtn');
    if(wrap) wrap.style.display = 'flex';
    if(btn)  btn.textContent = '🔉';
  }catch(e){}
}

function _stopRespiraMusic(){
  if(_respiraAudio){
    try{ _respiraAudio.pause(); _respiraAudio.currentTime = 0; }catch(e){}
    _respiraAudio = null;
  }
  var wrap = document.getElementById('respiraSoundWrap');
  if(wrap) wrap.style.display = 'none';
  _respiraMuted = false;
}

function pTogRespiraMusic(){
  if(!_respiraAudio) return;
  _respiraMuted = !_respiraMuted;
  _respiraAudio.muted = _respiraMuted;
  var btn = document.getElementById('respiraSoundBtn');
  if(btn) btn.textContent = _respiraMuted ? '🔇' : '🔉';
}

function _runRespiraPhase(){
  if(!_respiraRunning) return;
  var ph = _respiraPhases[_respiraPhaseIdx];
  _setEl('respiraPhase', ph.name);
  _setEl('respiraCount', ph.dur);
  _pulseRespiraRing(_respiraPhaseIdx, ph);
  var startTime = null;
  var lastTick = ph.dur;
  cancelAnimationFrame(_respiraRaf);
  function tick(now){
    if(!_respiraRunning) return;
    if(!startTime) startTime = now;
    var elapsed = (now - startTime) / 1000;
    var progress = Math.min(elapsed / ph.dur, 1);
    var remaining = Math.ceil(ph.dur - elapsed);
    if(remaining !== lastTick){ _setEl('respiraCount', remaining > 0 ? remaining : ''); lastTick = remaining; }
    // Scale: inhale 0→1, hold stays at 1, exhale 1→0
    var scale = (_respiraPhaseIdx === 0) ? progress
              : (_respiraPhaseIdx === 1) ? 1
              : (1 - progress);
    // Smooth easing
    var eased = _easeInOut(scale);
    _drawRespiraCircleSmooth(ph.colorA, eased);
    if(progress < 1){
      _respiraRaf = requestAnimationFrame(tick);
    } else {
      _respiraPhaseIdx = (_respiraPhaseIdx + 1) % _respiraPhases.length;
      if(_respiraRunning) _runRespiraPhase();
    }
  }
  _respiraRaf = requestAnimationFrame(tick);
}

function _easeInOut(t){ return t < 0.5 ? 2*t*t : -1+(4-2*t)*t; }

function _drawRespiraCircleSmooth(colorA, scale){
  var canvas = document.getElementById('respiraCanvas');
  if(!canvas) return;
  var ctx = canvas.getContext('2d');
  ctx.clearRect(0,0,260,260);
  // Dark outer ring
  ctx.fillStyle = 'rgba(8,20,14,0.92)';
  ctx.beginPath(); ctx.arc(130,130,128,0,Math.PI*2); ctx.fill();
  var r = 28 + scale * 90; // radius 28→118
  // Outer glow halo
  var grd = ctx.createRadialGradient(130,130, r*0.1, 130,130, r*1.6);
  grd.addColorStop(0, colorA);
  grd.addColorStop(0.5, colorA.replace(/[\d.]+\)$/, '0.25)'));
  grd.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = grd;
  ctx.beginPath(); ctx.arc(130,130, r*1.6, 0, Math.PI*2); ctx.fill();
  // Solid bright core
  ctx.fillStyle = colorA;
  ctx.beginPath(); ctx.arc(130,130, r, 0, Math.PI*2); ctx.fill();
  // Bright specular highlight
  var highlight = ctx.createRadialGradient(115,115, 2, 130,130, r*0.7);
  highlight.addColorStop(0, 'rgba(255,255,255,0.28)');
  highlight.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = highlight;
  ctx.beginPath(); ctx.arc(130,130, r, 0, Math.PI*2); ctx.fill();
}

function _pulseRespiraRing(phaseIdx, ph){
  var canvas = document.getElementById('respiraCanvas');
  if(!canvas) return;
  var rect = canvas.getBoundingClientRect();
  // Use actual CSS-rendered size (not the HTML attribute)
  var size = Math.round(rect.width);
  var cx = rect.left + size / 2;
  var cy = rect.top  + size / 2;
  var dur = ph ? ph.dur : 4;
  var ring = document.createElement('div');
  // Position centered on the canvas using left/top — NO translate in keyframe
  ring.style.cssText = 'position:fixed;pointer-events:none;border-radius:50%;z-index:9998;'
    +'width:'+size+'px;height:'+size+'px;'
    +'left:'+(cx - size/2)+'px;top:'+(cy - size/2)+'px;'
    +'transform-origin:center center;'
    +'border:2px solid '+(ph ? ph.colorA : 'rgba(116,198,157,.7)')+';'
    +'animation:respiraRingExpand '+dur+'s ease-out forwards;';
  document.body.appendChild(ring);
  setTimeout(function(){ ring.remove(); }, dur*1000 + 200);
}

function _startRespiraAmbient(){
  _stopRespiraAmbient();
  var page = document.getElementById('pg-respira');
  if(!page) return;
  var inner = page.firstElementChild;
  if(!inner) return;
  var layer = document.createElement('div');
  layer.id = 'respiraAmbient';
  layer.style.cssText = 'position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:0';
  if(!inner.style.position) inner.style.position = 'relative';
  inner.insertBefore(layer, inner.firstChild);
  requestAnimationFrame(function(){ requestAnimationFrame(function(){
    var canvas = document.getElementById('respiraCanvas');
    if(!canvas || !layer.isConnected) return;
    var lr = layer.getBoundingClientRect();
    var cr = canvas.getBoundingClientRect();
    var cx  = cr.left - lr.left + cr.width  / 2;
    var cy  = cr.top  - lr.top  + cr.height / 2;
    var canR = cr.width / 2; // actual canvas radius
    var petals = ['🌸','🌼','🌺','✨','🍃','💫','🌿','🌸','✨','🍃','🌼','🌺','🌱','💫'];
    var n = petals.length;
    for(var i = 0; i < n; i++){
      var sz        = 14 + (i * 2.1) % 18;              // emoji size 14–32px
      var dur       = (10 + (i * 2.3) % 10) * 1000;    // 10–20s per expansion cycle
      var startAng  = (i / n) * Math.PI * 2;            // evenly distributed start angles
      var driftAng  = (0.18 + (i * 0.06) % 0.25);      // small angular drift while expanding
      var r0        = canR + sz * 0.4;                  // start just outside circle edge
      var r1        = canR * 2.7 + (i * 12) % 70;      // expand to ~2.7× radius (matches ring)
      var wrapDel   = -(i / n) * dur;                   // negative: distributes rotation angles
      var spanDel   = i * 550;                           // positive: staggered gentle fade-in

      // Wrapper at canvas center sets the radial direction
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;left:'+cx+'px;top:'+cy+'px;'
        +'width:0;height:0;transform-origin:0 0;will-change:transform';

      // Petal sits at left:0 and is moved via translateX in animation
      var span = document.createElement('span');
      span.textContent = petals[i];
      span.style.cssText = 'position:absolute;font-size:'+sz+'px;display:block;opacity:0;'
        +'left:0px;top:'+(-sz/2)+'px;will-change:transform,opacity;transform-origin:center center';

      wrap.appendChild(span);
      layer.appendChild(wrap);

      // Wrapper slowly rotates from start angle + small drift (gives circular spread)
      wrap.animate([
        { transform:'rotate('+startAng+'rad)' },
        { transform:'rotate('+(startAng + driftAng * Math.PI * 2)+'rad)' }
      ], { duration:dur, delay:wrapDel, iterations:Infinity, easing:'linear' });

      // Petal expands outward — fades in gently over first 18% then slowly fades out
      span.animate([
        { transform:'translateX('+r0+'px) rotate(0deg)',   opacity:0 },
        { transform:'translateX('+r0+'px) rotate(15deg)',  opacity:0.65, offset:0.12 },
        { transform:'translateX('+((r0+r1)/2)+'px) rotate(120deg)', opacity:0.6, offset:0.5 },
        { transform:'translateX('+r1+'px) rotate(300deg)', opacity:0.25, offset:0.88 },
        { transform:'translateX('+r1+'px) rotate(360deg)', opacity:0 }
      ], { duration:dur, delay:spanDel, iterations:Infinity, easing:'ease-out' });
    }
  }); });
}

function _stopRespiraAmbient(){
  var layer = document.getElementById('respiraAmbient');
  if(layer) layer.remove();
}

function _stopRespira(){
  _respiraRunning = false;
  cancelAnimationFrame(_respiraRaf); _respiraRaf = null;
  clearInterval(_respiraTimer);      _respiraTimer = null;
  _stopRespiraAmbient();
  _stopRespiraMusic();
  pInitRespira();
}

// ── VELA ───────────────────────────────────────────────────────
// Vela por ti — programa solidario que conecta usuarios con profesionales licenciados
// en sesiones gratuitas o subsidiadas, financiado por donaciones de la comunidad.
function pInitVela(){
  // Nothing to init — static form
}

async function pSendVela(){
  var tipo = document.getElementById('velaTipo');
  var espec = document.getElementById('velaEspec');
  var urgencia = document.querySelector('input[name="velaUrgencia"]:checked');
  var desc = document.getElementById('velaDesc');
  if(!tipo || !tipo.value){ pToast('⚠️','Elegí el tipo de profesional'); return; }
  if(!espec || !espec.value){ pToast('⚠️','Elegí la especialización'); return; }
  if(!urgencia){ pToast('⚠️','Indicá el nivel de urgencia'); return; }
  var horarios = [];
  document.querySelectorAll('input[name="velaHorario"]:checked').forEach(function(h){ horarios.push(h.value); });
  var userName  = safeLS('get','velo_user_name')  || safeLS('get','velo_username') || '';
  var userEmail = safeLS('get','velo_user_email') || '';
  var userId    = safeLS('get','velo_user_id')    || '';
  _initSupabase();
  if(sbClient){
    try{
      await sbClient.from('solidarity_requests').insert({
        user_id: userId || null, email: userEmail, user_name: userName,
        tipo: tipo.value, espec: espec.value, urgencia: urgencia.value,
        horarios: horarios, description: desc ? desc.value.trim() : '',
        status: 'pending', created_at: new Date().toISOString()
      });
    }catch(e){ console.error('[pSendVela]', e); }
  }
  pToast('🕯️','Solicitud enviada. Te contactaremos en 7-14 días 💚');
  if(tipo) tipo.value = '';
  if(espec) espec.value = '';
  if(desc) desc.value = '';
  document.querySelectorAll('input[name="velaUrgencia"]').forEach(function(r){ r.checked = false; });
  document.querySelectorAll('input[name="velaHorario"]').forEach(function(r){ r.checked = false; });
  setTimeout(function(){ pGoTo('home'); }, 1800);
}

// ── CIRCLES ────────────────────────────────────────────────────
var _circlesData = [
  { id:'c1', name:'Manejo de Ansiedad', emoji:'🌊', members:0, maxMembers:30, desc:'Estrategias y apoyo para el día a día con ansiedad.', active:true, official:true },
  { id:'c2', name:'Duelo y Pérdida', emoji:'🌙', members:0, maxMembers:30, desc:'Acompañamiento en procesos de duelo. Sin prisas.', active:false, official:true },
  { id:'c3', name:'Crianza Consciente', emoji:'🌱', members:0, maxMembers:30, desc:'Madres, padres y familias que crían con presencia.', active:false, official:true },
  { id:'c4', name:'Trastornos del Sueño', emoji:'😴', members:0, maxMembers:30, desc:'Cuando la noche no descansa. Juntos buscamos calma.', active:false, official:true },
  { id:'c5', name:'Autoestima', emoji:'✨', members:0, maxMembers:30, desc:'Reconstruir la confianza desde la raíz.', active:false, official:true }
];

var _curCircle = null;
var _circleAutoMsgTimer = null;
var _allCirclesCache = [];
var _circleJoinedSession = {}; // tracks circles joined this session (for join/leave system messages)
var _circleRenderPending = false; // prevents concurrent _renderCircleMessages calls
var _circleRenderQueued  = false; // a render was requested while one was in-flight
var _circleLastDbMsgId   = null;  // last DB message id rendered — avoids unnecessary full re-renders
var _circleMembersCh  = null;  // realtime channel circle_members
var _circleMemberUpsertP = null; // promesa del upsert de membresía (para leer mensajes DESPUÉS de ser miembro)
var _selectedCircleFoto = '';  // base64 photo for new circle

function pRenderCircles(){
  var list = document.getElementById('circlesList');
  if(!list) return;

  var userConvs = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
  var canCreate = userConvs >= 40 || _isPremium();

  var createBtn = document.getElementById('circleCreateBtn');
  if(createBtn){
    if(canCreate){
      createBtn.disabled = false;
      createBtn.textContent = '+ Crear círculo';
      createBtn.title = '';
    } else {
      createBtn.disabled = true;
      createBtn.textContent = '🔒 Crear círculo';
      createBtn.title = 'Necesitás ser Guardián Oro (40 conversaciones) o Velo Plus';
    }
  }

  var notice = document.getElementById('circleCreateNotice');
  if(notice){
    if(!canCreate){
      var convsFalta = 40 - userConvs;
      notice.innerHTML = '<div style="font-size:14px;color:var(--ink4);background:var(--sage7);border:1px solid var(--border);border-radius:12px;padding:10px 14px;margin-bottom:14px;line-height:1.5">'
        +'🛡️ Los Círculos los crean <strong>Guardianes Oro</strong> (40+ conversaciones). '
        +'Te faltan <strong>'+convsFalta+' conversaciones</strong> para llegar a Oro, o podés activar <strong>Velo Plus</strong> para crearlo ahora.'
        +'</div>';
    } else {
      notice.innerHTML = '';
    }
  }

  var lsCircles = []; try{ lsCircles = JSON.parse(safeLS('get','velo_circles')||'[]'); }catch(e){}
  var allCircles = lsCircles.concat(_circlesData);
  _renderCircleCards(list, allCircles, {});

  _initSupabase();
  if(!sbClient) return;

  // Subscribe to circle_members for live count updates.
  // v1450: SIEMPRE re-suscribir (canal viejo/caído dejaba de traer altas/bajas en vivo).
  if(_circleMembersCh){ _sbUnsub(_circleMembersCh); _circleMembersCh = null; }
  _circleMembersCh = _sbSub('velo:circle_members', 'circle_members', function(){
    _refreshCircleMemberCounts();
  });

  // Load user-created circles from Supabase (non-official)
  sbClient.from('circles').select('*').eq('official', false).order('created_at',{ascending:false}).limit(50)
    .then(function(res){
      var sbCircles = (res.data||[]).map(function(r){
        return { id:r.id, name:r.name, desc:r.descripcion||'', emoji:r.emoji||'⭕', foto:r.foto||'',
          members:0, maxMembers:r.cap_max||30, active:true, official:false, creator_id:r.creator_id||'' };
      });
      // Merge: Supabase circles take precedence over same-id localStorage ones
      var merged = sbCircles.slice();
      lsCircles.forEach(function(lc){
        if(!merged.find(function(sc){ return sc.id === lc.id; })) merged.push(lc);
      });
      allCircles = merged.concat(_circlesData);
      _renderCircleCards(list, allCircles, {});
      _refreshCircleMemberCounts(allCircles);
    }).catch(function(){
      _refreshCircleMemberCounts(allCircles);
    });
}

function _circleCardHtml(c, memberCounts){
  var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_circle_'+c.id)||'[]'); }catch(e){}
  var lastMsg = msgs.length ? msgs[msgs.length-1] : null;
  var maxM = c.maxMembers || 30;
  var memberCount = memberCounts && memberCounts[c.id] !== undefined ? memberCounts[c.id] : (c.members||0);
  var capPct = Math.min(100, Math.round(memberCount/maxM*100));
  var isFull = memberCount >= maxM;
  // v1521: cada círculo toma el color de su tema (emoji) en el tile y la barra
  // de cupo — el listado deja de ser verde uniforme y se siente vivo.
  var col = document.body.classList.contains('r-dark') ? _dqEmojiColor(c.emoji||'☮️') : _dqEmojiColorLight(c.emoji||'☮️');
  var imgHtml = c.foto
    ? '<img src="'+_escHtml(c.foto)+'" alt="" style="width:52px;height:52px;border-radius:18px;object-fit:cover;flex-shrink:0">'
    : '<div style="font-size:34px;width:52px;height:52px;border-radius:18px;background:'+col.badge+';border:1.5px solid '+col.border+';box-shadow:0 2px 12px '+col.glow+';display:flex;align-items:center;justify-content:center;flex-shrink:0;position:relative">'
      +c.emoji
      +(c.official ? '<span style="position:absolute;bottom:-4px;right:-4px;font-size:14px;background:#fff;border-radius:50%;width:18px;height:18px;display:flex;align-items:center;justify-content:center;box-shadow:0 1px 4px rgba(0,0,0,.15)" title="Sala oficial Velo">🛡️</span>' : '')
      +'</div>';
  return '<div class="circle-card'+(c.official?' circle-card--official':'')+'" id="circlecard-'+c.id+'" onclick="pOpenCircle(\''+c.id+'\')">'
    +'<div style="display:flex;align-items:center;gap:13px">'
    +imgHtml
    +'<div style="flex:1;min-width:0">'
    +'<div style="font-size:15px;font-weight:700;color:var(--ink);margin-bottom:2px">'+c.name+'</div>'
    +'<div style="font-size:14px;color:var(--ink2);margin-bottom:5px">'+c.desc+'</div>'
    +'<div style="height:5px"></div>'
    +'<div style="display:flex;align-items:center;gap:6px">'
    +'<div style="flex:1;height:4px;background:var(--cream2);border-radius:100px;overflow:hidden"><div style="height:100%;width:'+capPct+'%;background:'+(isFull?'var(--sos)':col.strip.replace(/[\d.]+\)$/,'0.85)'))+';border-radius:100px"></div></div>'
    +'<span class="circle-member-count-'+c.id+'" style="font-size:12px;color:var(--ink3);font-weight:600">'+memberCount+'/'+maxM+'</span>'
    +(isFull ? '<span style="font-size:12px;color:var(--sos);font-weight:700">Lleno</span>' : '')
    +'</div>'
    +'</div>'
    +'<div style="text-align:right;flex-shrink:0;margin-left:6px">'
    +(c.active ? '<span class="p-pill p-pill--live" style="font-size:12px"><span class="p-ldot p-ldot--on"></span> Activo</span><br>' : '')
    +(c.official ? '<span style="font-size:12px;color:var(--sage);font-weight:700">Oficial</span>' : '')
    +'</div>'
    +'</div>'
    +'</div>';
}

function _renderCircleCards(list, circles, memberCounts){
  _allCirclesCache = circles.slice();
  list.innerHTML = circles.map(function(c){ return _circleCardHtml(c, memberCounts); }).join('');
}

function _refreshCircleMemberCounts(circles){
  _initSupabase();
  if(!sbClient) return;
  var since = new Date(Date.now() - 10*60*1000).toISOString();
  sbClient.from('circle_members').select('circle_id,user_id').gte('last_seen', since)
    .then(function(res){
      if(res.error||!res.data) return;
      var counts = {};
      res.data.forEach(function(r){ counts[r.circle_id] = (counts[r.circle_id]||0)+1; });
      // Update all visible circle count spans
      Object.keys(counts).forEach(function(cid){
        var span = document.querySelector('.circle-member-count-'+cid);
        if(span){
          var maxM = 30;
          var card = document.getElementById('circlecard-'+cid);
          if(card){ var existing = span.textContent.split('/'); maxM = parseInt(existing[1])||30; }
          span.textContent = counts[cid]+'/'+maxM;
        }
      });
      // Update open circle header
      if(_curCircle){
        var n = counts[_curCircle.id] || 0;
        _setEl('feedCircleMembers', n + (n===1?' persona activa':' personas activas'));
      }
    }).catch(function(){});
}

function pOpenCircle(id, circleData){
  _curCircle = typeof circleData === 'string' ? JSON.parse(circleData) : circleData;
  if(!_curCircle){ _curCircle = _circlesData.find(function(c){ return c.id===id; }) || _allCirclesCache.find(function(c){ return c.id===id; }); }

  // Save join timestamp — messages from before this moment won't be shown on render
  safeLS('set', 'velo_circle_joined_'+id, new Date().toISOString());
  _setEl('feedCircleName',  _curCircle ? _escHtml(_curCircle.name||'')  : 'Círculo');
  _setEl('feedCircleEmoji', _curCircle ? _curCircle.emoji : '⭕');
  _setEl('feedCircleMembers', _curCircle ? _curCircle.members+' personas' : '');
  // Show rename button only for the creator
  var _myId = safeLS('get','velo_user_id')||safeLS('get','velo_user_email')||'';
  var _renameBtn = document.getElementById('feedCircleRenameBtn');
  if(_renameBtn){
    var _isCreator = _curCircle && _curCircle.creator_id && _curCircle.creator_id===_myId && !_curCircle.official;
    _renameBtn.style.display = _isCreator ? '' : 'none';
    if(_isCreator) _renameBtn.onclick = function(){ pRenameCircle(id); };
  }
  var rulesEl = document.getElementById('feedCircleRules');
  if(rulesEl) rulesEl.innerHTML = '🤝 Sin juicios · Sin agresión · Sin consejo no solicitado';

  // Subscribe to real-time messages for this circle
  _initSupabase();
  _sbUnsub(_circleRtCh);
  _circleRtCh = null;
  if(sbClient){
    var _circleMyId = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || '';
    _circleRtCh = _sbSub('velo:circle:'+id, 'circle_messages', function(payload){
      if(!payload.new || payload.new.circle_id !== id) return;
      // Skip own INSERT events only — pSendCircleMsg already called _renderCircleMessages().
      // Do NOT skip UPDATE events (reactions) even if the message belongs to the current user.
      var isInsert = payload.eventType === 'INSERT' || !payload.eventType;
      if(isInsert && payload.new.user_id && payload.new.user_id === _circleMyId && payload.new.type !== 'system') return;
      // v1601: si ya no estás en el círculo, no re-renderizar. El canal seguía vivo
      // toda la sesión y cada mensaje del círculo disparaba una consulta de 100 filas
      // + rebuild del feed desde cualquier otra pantalla (datos/batería/scroll).
      if(_curPage !== 'feed') return;
      _circleLastDbMsgId = null; // force re-render to pick up reaction changes
      _renderCircleMessages();
    });
    // Upsert user into circle_members for real-time presence counting
    var _cmId = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || '';
    if(_cmId){
      // Guardar la promesa: la RLS member-only de circle_messages requiere que esta
      // membresía esté commiteada antes de leer los mensajes (si no, la 1ª lectura
      // vuelve vacía). _renderCircleMessagesInner la espera.
      _circleMemberUpsertP = sbClient.from('circle_members').upsert({circle_id:id, user_id:_cmId, last_seen:new Date().toISOString()},
        {onConflict:'circle_id,user_id'}).then(function(){}).catch(function(){});
    }
    // Announce join once per session per circle
    if(!_circleJoinedSession[id]){
      _circleJoinedSession[id] = true;
      var jName = safeLS('get','velo_user_name') || 'Alguien';
      var jId   = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || 'anon';
      sbClient.from('circle_messages').insert({ circle_id:id, user_id:jId, user_name:jName,
        user_av:'', text:jName+' se unió al chat', type:'system' }).then(function(){}).catch(function(){});
    }
  }

  // Clear the message container immediately so stale messages from any previous
  // circle don't remain visible while the new circle's DB query is in flight.
  var _feedMsgEl = document.getElementById('feedMessages');
  if(_feedMsgEl) _feedMsgEl.innerHTML = '';
  _circleLastDbMsgId = null;
  _circleRenderPending = false;
  _circleRenderQueued  = false;

  pGoTo('feed');
  setTimeout(function(){ _renderCircleMessages(); _startCircleAutoMsg(); }, 100);
  // Polling fallback every 5s — catches messages if real-time drops
  if(_circleRtPollTmr){ clearInterval(_circleRtPollTmr); _circleRtPollTmr = null; }
  _circleRtPollTmr = setInterval(function(){
    if(_curPage !== 'feed'){ clearInterval(_circleRtPollTmr); _circleRtPollTmr = null; return; }
    _renderCircleMessages();
  }, 5000);
}

async function _renderCircleMessages(){
  // Guard: if a render is in-flight, queue one more and return — the in-flight render will
  // check the queue flag when it finishes and re-run if needed.
  if(_circleRenderPending){ _circleRenderQueued = true; return; }
  _circleRenderPending = true;
  _circleRenderQueued  = false;
  try{
    await _renderCircleMessagesInner();
  }catch(e){}
  _circleRenderPending = false;
  // If a render was queued while we were in-flight, run it now
  if(_circleRenderQueued){ _circleRenderQueued = false; _renderCircleMessages(); }
}

async function _renderCircleMessagesInner(){
  var _tok = _navToken;
  var el = document.getElementById('feedMessages');
  if(!el || !_curCircle) return;

  // Read local cache — used for instant render before Supabase arrives
  var localMsgs = [];
  try{ localMsgs = JSON.parse(safeLS('get','velo_circle_'+_curCircle.id)||'[]'); }catch(e){}

  // localStorage instant render — only on first load (empty container) and only messages
  // Show all cached local messages for instant render before Supabase responds
  if(localMsgs.length && !el.querySelector('.feed-msg')){
    el.innerHTML = localMsgs.map(function(m){
      if(m.type === 'system') return '<div style="text-align:center;margin:10px 0"><span style="font-size:13px;color:var(--ink5);font-style:italic;background:var(--cream2);padding:4px 12px;border-radius:100px">'+_escHtml(m.text)+'</span></div>';
      return _buildMsgBubble(m.text, !!m.own, m.av||'', m.name||'', 'feedInput', 'feedReplyBar', '', m.reactions||{}, '', m.userId||'');
    }).join('');
    el.scrollTop = el.scrollHeight;
  }

  // Esperar a que la membresía commitee (la RLS member-only lo exige para leer).
  try{ if(_circleMemberUpsertP) await _circleMemberUpsertP; }catch(_){}
  // Load newest 100 messages from Supabase (descending → reverse for chronological display)
  var sbRows = await _sbLoad('circle_messages', function(q){
    return q.eq('circle_id', _curCircle.id).order('created_at',{ascending:false}).limit(100);
  });
  if(_navToken !== _tok) return;
  if(sbRows) sbRows = sbRows.reverse(); // oldest-first for correct display order

  var msgs;
  if(sbRows !== null){
    msgs = sbRows.map(_sbCircleMsgRow);
    // Merge local pending messages (own msgs that haven't reached Supabase yet).
    // Dedup: exact UUID match first; fuzzy fallback tracks which sbRow was already claimed
    // so that two identical texts sent close together don't collapse into one bubble.
    var _cutMs = Date.now() - 30000;
    var _claimedSbIds = {}; // sbRow.id already matched by a previous local msg
    localMsgs.filter(function(lm){ return lm.own && lm.ts > _cutMs; }).forEach(function(lm){
      var matchedSbId = null;
      var inSb = msgs.some(function(m){
        if(lm.sbId && m.sbId){ if(lm.sbId === m.sbId){ matchedSbId = m.sbId; return true; } return false; }
        // Fuzzy: same text, within 5 s, and this sbRow not yet claimed by another local msg
        if(m.own && m.text === lm.text && Math.abs(m.ts - lm.ts) < 5000 && !_claimedSbIds[m.sbId]){
          matchedSbId = m.sbId; return true;
        }
        return false;
      });
      if(inSb && matchedSbId) _claimedSbIds[matchedSbId] = true;
      if(!inSb) msgs.push({ id:lm.id, userId:lm.userId||'', av:lm.av||'', name:lm.name||'', text:lm.text, ts:lm.ts, own:true, type:lm.type||'text', reactions:{} });
    });
    msgs.sort(function(a, b){ return a.ts - b.ts; });
    _sbCircleMsgs = msgs;
    if(sbRows.length && _circleAutoMsgTimer){ clearInterval(_circleAutoMsgTimer); _circleAutoMsgTimer = null; }
  } else {
    // Supabase unavailable — use only real localStorage messages
    msgs = localMsgs;
  }

  // Skip full re-render if DB content hasn't changed (prevents flicker on repeated calls)
  var _newLastId = sbRows && sbRows.length ? sbRows[sbRows.length-1].id : null;
  var _hasPending = localMsgs.some(function(lm){
    if(!lm.own || lm.ts <= Date.now() - 30000) return false;
    return !msgs.some(function(m){
      if(lm.sbId && m.sbId) return lm.sbId === m.sbId;
      return m.own && m.text === lm.text && Math.abs(m.ts - lm.ts) < 5000;
    });
  });
  if(_newLastId && _newLastId === _circleLastDbMsgId && !_hasPending) return;
  _circleLastDbMsgId = _newLastId;

  var wasAtBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
  if(!msgs.length){
    el.innerHTML = '<div class="p-empty" style="padding:40px 20px"><span class="p-empty-emoji">💬</span><div class="p-empty-title">Este círculo está vacío</div><div class="p-empty-sub">Sé el primero en compartir algo 💚</div></div>';
    return;
  }
  el.innerHTML = msgs.map(function(m){
    if(m.type === 'system'){
      return '<div style="text-align:center;margin:10px 0"><span style="font-size:13px;color:var(--ink5);font-style:italic;background:var(--cream2);padding:4px 12px;border-radius:100px">'+_escHtml(m.text)+'</span></div>';
    }
    return _buildMsgBubble(m.text, !!m.own, m.av, m.name, 'feedInput', 'feedReplyBar', '', m.reactions, m.sbId, m.userId);
  }).join('');
  if(wasAtBottom) el.scrollTop = el.scrollHeight;

  // Count active members: users who sent a message in the last 2 hours (not all-time)
  if(sbRows !== null){
    var twoHoursAgo = Date.now() - 2*60*60*1000;
    var uids = {};
    sbRows.forEach(function(r){
      if(r.user_id && r.type !== 'system' && new Date(r.created_at).getTime() > twoHoursAgo){
        uids[r.user_id] = 1;
      }
    });
    var memberCount = Object.keys(uids).length;
    _setEl('feedCircleMembers', memberCount + (memberCount===1?' persona activa':' personas activas'));
  }
}

async function pSendCircleMsg(){
  var ta = document.getElementById('feedInput');
  if(!_curCircle) return;
  var text = ta ? ta.value.trim() : '';
  var _cSt = _chatSt('circle');
  var hasAttach = !!(_cSt.blob || _cSt.image);
  if(!text && !hasAttach) return;
  if(text.length > 2000){ pToast('⚠️','Mensaje demasiado largo (máx 2000 caracteres)'); return; }
  // Adjuntos van a la LS del círculo + optimistic bubble; sync a Supabase después
  async function _circleInsertOne(bodyText){
    var msgs2 = []; try{ msgs2 = JSON.parse(safeLS('get','velo_circle_'+_curCircle.id)||'[]'); }catch(e){}
    var name2 = safeLS('get','velo_user_name') || 'Vos';
    var av2   = safeLS('get','velo_user_av')   || '🧑';
    var _uc2 = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
    var badge2 = _getBadge(_uc2);
    var _myId2 = safeLS('get','velo_user_id')||safeLS('get','velo_user_email')||'anon';
    var _ts2 = Date.now();
    msgs2.push({ id:'m'+_ts2, av:av2, name:name2+' '+badge2.icon, text:bodyText, ts:_ts2, own:true, userId:_myId2 });
    safeLS('set','velo_circle_'+_curCircle.id, JSON.stringify(msgs2.slice(-100)));
    var el4 = document.getElementById('feedMessages');
    if(el4){
      var em4 = el4.querySelector('.p-empty'); if(em4) em4.remove();
      var d4 = document.createElement('div');
      d4.innerHTML = _buildMsgBubble(bodyText, true, av2, name2+' '+badge2.icon, 'feedInput', 'feedReplyBar', '');
      var ch4 = d4.firstElementChild; if(ch4){ el4.appendChild(ch4); el4.scrollTop = el4.scrollHeight; }
    }
    _initSupabase();
    if(sbClient){
      try{
        await sbClient.from('circle_messages').insert({
          circle_id:_curCircle.id, user_id:_myId2, user_name:name2+' '+badge2.icon, user_av:av2, text:bodyText
        });
      }catch(e){}
    }
  }
  await _chatConsumeAttachments('circle', _circleInsertOne);
  if(!text) return;
  ta.value = '';
  ta.style.height = '';
  var emojiPanel = document.getElementById('feedEmojiPanel');
  if(emojiPanel) emojiPanel.style.display = 'none';
  var circleQuote = _getReplyQuote('feedReplyBar');
  pClearReplyBar('feedReplyBar');
  var fullText = circleQuote ? '↩ "'+circleQuote.slice(0,60)+(circleQuote.length>60?'…':'')+'"  \n'+text : text;

  var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_circle_'+_curCircle.id)||'[]'); }catch(e){}
  var name = safeLS('get','velo_user_name') || 'Vos';
  var av   = safeLS('get','velo_user_av')   || '🧑';
  var userConvs = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
  var badge = _getBadge(userConvs);
  var myId = safeLS('get','velo_user_id')||safeLS('get','velo_user_email')||'anon';
  var _circleSendTs = Date.now();
  msgs.push({ id:'m'+_circleSendTs, av:av, name:name+' '+badge.icon, text:fullText, ts:_circleSendTs, own:true, userId:myId });
  safeLS('set','velo_circle_'+_curCircle.id, JSON.stringify(msgs.slice(-100)));
  _geminiModerateContent(fullText, 'circulo-'+_curCircle.id);
  // Optimistic DOM append for instant feedback (same pattern as DM/guardian chat)
  var _cMsgEl = document.getElementById('feedMessages');
  var _cLastBubble = null;
  if(_cMsgEl){
    var _emptyState = _cMsgEl.querySelector('.p-empty');
    if(_emptyState) _emptyState.remove();
    var _cTmp = document.createElement('div');
    _cTmp.innerHTML = _buildMsgBubble(fullText, true, av, name+' '+badge.icon, 'feedInput', 'feedReplyBar', circleQuote);
    var _cChild = _cTmp.firstElementChild;
    if(_cChild){ _cMsgEl.appendChild(_cChild); _cMsgEl.scrollTop = _cMsgEl.scrollHeight; _cLastBubble = _cChild; }
  }
  // Insert to Supabase so all circle members see the message in real-time
  _initSupabase();
  if(sbClient){
    var _circleSendId = 'm'+_circleSendTs; // local id used to find this entry later
    sbClient.from('circle_messages').insert({ circle_id:_curCircle.id,
      user_id: myId, user_name: name+' '+badge.icon, user_av: av||'🌿', text:fullText, type:'text'
    }).select('id').single().then(function(res){
      if(res && res.data && res.data.id){
        var _dbUuid = res.data.id;
        // Stamp data-sb-id so reactions can target this row
        if(_cLastBubble) _cLastBubble.setAttribute('data-sb-id', 'circle_messages:'+_dbUuid);
        _circleLastDbMsgId = _dbUuid; // prevent next render from re-appending
        // Save DB UUID in localStorage entry so future dedup uses exact matching instead of fuzzy
        if(_curCircle){
          var _lsMsgs2 = []; try{ _lsMsgs2 = JSON.parse(safeLS('get','velo_circle_'+_curCircle.id)||'[]'); }catch(e){}
          _lsMsgs2 = _lsMsgs2.map(function(m){ return m.id === _circleSendId ? Object.assign({},m,{sbId:_dbUuid}) : m; });
          safeLS('set','velo_circle_'+_curCircle.id, JSON.stringify(_lsMsgs2.slice(-100)));
        }
      }
    }).catch(function(){});
  }
  _renderCircleMessages();
}

var _circleMsgEmojis = ['😊','😢','❤️','🙏','💪','🌿','✨','🤗','🌸','😌','🥺','💙','🌈','☀️','🦋','🕊️','🌊','💚','😔','🫂'];
function pInsertChatEmoji(e, inputId){
  var ta = document.getElementById(inputId || 'feedInput');
  if(!ta) return;
  // Append at cursor position when possible, fall back to end (iOS-safe)
  try{
    var s = (typeof ta.selectionStart === 'number') ? ta.selectionStart : ta.value.length;
    var en = (typeof ta.selectionEnd === 'number') ? ta.selectionEnd : s;
    ta.value = ta.value.slice(0,s) + e + ta.value.slice(en);
  }catch(_){ ta.value = (ta.value||'') + e; }
  ta.focus();
}
function pToggleChatEmojis(panelId, inputId){
  var panel = document.getElementById(panelId);
  if(!panel) return;
  if(panel.style.display === 'flex'){ panel.style.display = 'none'; return; }
  if(!panel.innerHTML){
    panel.innerHTML = _circleMsgEmojis.map(function(e){
      return '<button type="button" onclick="pInsertChatEmoji(\''+e+'\',\''+inputId+'\')" style="font-size:22px;background:none;border:none;cursor:pointer;padding:4px;border-radius:8px">'+e+'</button>';
    }).join('');
  }
  panel.style.display = 'flex';
}
function pToggleCircleEmojis(){
  pToggleChatEmojis('feedEmojiPanel', 'feedInput');
}
function pInsertCircleEmoji(e){
  pInsertChatEmoji(e, 'feedInput');
}

function _startCircleAutoMsg(){ /* disabled — no fake auto-messages */ }

function pLeaveCircle(){
  if(_circleAutoMsgTimer){ clearInterval(_circleAutoMsgTimer); _circleAutoMsgTimer = null; }
  var leftCircle = _curCircle;
  _initSupabase();
  if(sbClient && leftCircle && _circleJoinedSession[leftCircle.id]){
    delete _circleJoinedSession[leftCircle.id];
    var lName = safeLS('get','velo_user_name') || 'Alguien';
    var lId   = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || 'anon';
    sbClient.from('circle_messages').insert({ circle_id:leftCircle.id, user_id:lId, user_name:lName,
      user_av:'', text:lName+' salió del chat', type:'system' }).then(function(){}).catch(function(){});
  }
  // Remove from circle_members
  var _cmId = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || '';
  if(sbClient && leftCircle && _cmId){
    sbClient.from('circle_members').delete().eq('circle_id', leftCircle.id).eq('user_id', _cmId)
      .then(function(){}).catch(function(){});
  }
  _curCircle = null;
  _circleLastDbMsgId  = null;
  _circleRenderPending = false;
  _circleRenderQueued  = false;
  pGoTo('circles');
  // Refresh member counts after leaving so the list reflects current state
  setTimeout(pRenderCircles, 300);
}

function pOpenCreateCircle(){
  var userConvs = parseInt(safeLS('get','velo_guardian_convs')||'0', 10);
  var canCreate = userConvs >= 40 || _isPremium();
  if(!canCreate){
    var falta = 40 - userConvs;
    pToast('🔒','Necesitás Guardián Oro (te faltan '+falta+' conversaciones) o Velo Plus');
    return;
  }
  var ov = document.getElementById('createCircleOv');
  if(ov) ov.classList.add('show');
}

async function pSubmitCreateCircle(){
  var nameEl  = document.getElementById('newCircleName');
  var descEl  = document.getElementById('newCircleDesc');
  var capMinEl = document.getElementById('newCircleCapMin');
  var capMaxEl = document.getElementById('newCircleCapMax');
  var emoji   = _selectedCircleEmoji || '⭕';
  if(!nameEl || !nameEl.value.trim()){ pToast('⚠️','Poné un nombre al círculo'); return; }
  if(pSubmitCreateCircle._busy) return; pSubmitCreateCircle._busy = true; // anti doble-submit (evita saltarse el máximo de 2)
  var capMin = Math.max(5, Math.min(30, parseInt((capMinEl&&capMinEl.value)||'5', 10)));
  var capMax = Math.max(capMin, Math.min(30, parseInt((capMaxEl&&capMaxEl.value)||'30', 10)));
  var myId = safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || 'anon';
  // Enforce max 2 user-created circles
  _initSupabase();
  if(sbClient){
    try{
      var existRes = await sbClient.from('circles').select('id',{count:'exact',head:true}).eq('creator_id',myId).eq('official',false);
      if(!existRes.error && (existRes.count||0)>=2){
        pToast('⚠️','Tenés 2 salas activas (el máximo permitido). Eliminá una para crear una nueva.');
        pSubmitCreateCircle._busy = false;
        return;
      }
    }catch(e){}
  }
  var c = {
    id: 'uc'+Date.now(),
    name: nameEl.value.trim(),
    desc: descEl ? descEl.value.trim() : '',
    emoji: emoji,
    foto: _selectedCircleFoto || '',
    members: 1,
    active: true,
    maxMembers: capMax
  };
  // Save to localStorage as fallback
  var circles = []; try{ circles = JSON.parse(safeLS('get','velo_circles')||'[]'); }catch(e){}
  circles.unshift(c);
  safeLS('set','velo_circles', JSON.stringify(circles.slice(0,20)));
  // Save to Supabase for multiuser
  _initSupabase();
  if(sbClient){
    sbClient.from('circles').insert({
      id: c.id, name: c.name, descripcion: c.desc, emoji: c.emoji, foto: c.foto,
      cap_min: capMin, cap_max: capMax, creator_id: myId, official: false
    }).then(function(){}).catch(function(){});
  }
  _selectedCircleFoto = '';
  var prevEl = document.getElementById('newCirclePhotoPreview');
  if(prevEl) prevEl.style.display = 'none';
  closeModal('createCircleOv');
  pToast('⭕','¡Círculo "'+c.name+'" creado! 🌿');
  pRenderCircles();
  pSubmitCreateCircle._busy = false;
}

