var HAPPY_MAX       = 50;                   // máximo de posts en el muro global
var _happyEmojis    = ['☀️','🌻','🎉','🌈','💚','🌸','✨','🌱','🎵','🙌','🦋','💛'];
var _happyReactEmojis = ['💛','🌸','🤗','🌿','✨'];
