function _myUserId(){
  return safeLS('get','velo_user_id') || safeLS('get','velo_user_email') || 'guest-'+(safeLS('get','velo_user_name')||'user');
}

// Reliable display name — never empty, falls back to email prefix
function _myDisplayName(){
  return safeLS('get','velo_user_name') || (safeLS('get','velo_user_email')||'').split('@')[0] || 'Usuario';
}

// Produces a JS string literal safe to embed inside a double-quoted HTML
// onclick="" attribute. Using JSON.stringify directly emits double quotes
// that prematurely close the attribute — this wraps in single quotes and
// escapes them, turning any inner double quote into &quot;.
function _jsAttr(v){
  return "'" + String(v == null ? '' : v)
    .replace(/\\/g,'\\\\').replace(/'/g,"\\'")
    .replace(/"/g,'&quot;').replace(/[\r\n]+/g,' ') + "'";
}

// Loads reviews written ABOUT a given user (most recent first)
async function _loadUserReviews(userId){
  _initSupabase();
  if(!sbClient || !userId) return [];
  try{
    await _ensureSbSession();
    var res = await sbClient.from('reviews').select('*').eq('pro_id', userId)
      .order('created_at',{ascending:false}).limit(50);
    if(res.error) console.error('[reviews load]', res.error.message);
    return res.data || [];
  }catch(e){ console.error('[reviews load catch]', e); return []; }
}

function _reviewCardHtml(r, myId, proId){
  // Only the reviewer (author) can delete their own review; the recipient cannot delete it
  var canDel = myId && r.user_id === myId;
  // The recipient (proId) can respond to reviews they received
  var canReply = myId && myId === proId && !r.reply;
  var delBtn = canDel
    ? '<button onclick="pDeleteReview(\''+_escHtml(String(r.id||''))+'\',this.closest(\'.p-review-card\'))" style="background:none;border:none;cursor:pointer;font-size:14px;color:var(--ink5);padding:0 0 0 8px;line-height:1;flex-shrink:0" title="Eliminar reseña">🗑️</button>'
    : '';
  var replyBtn = canReply
    ? '<button class="review-reply-btn" onclick="pOpenReviewReply(\''+_escHtml(String(r.id||''))+'\',\''+_escHtml(String(r.user_id||''))+'\',this.closest(\'.p-review-card\'))" style="background:rgba(116,198,157,.20);border:1.5px solid rgba(116,198,157,.65);cursor:pointer;font-size:12.5px;color:var(--sage2);padding:6px 12px;line-height:1;flex-shrink:0;font-family:\'Jost\',sans-serif;font-weight:800;border-radius:100px;letter-spacing:.2px;display:inline-flex;align-items:center;gap:4px" title="Responder a esta reseña">💬 Responder</button>'
    : '';
  var replyHtml = r.reply
    ? '<div class="rv-reply-block">'
      +'<div class="rv-reply-label">Respuesta del guardián</div>'
      +'<div class="rv-reply-text">'+_escHtml(r.reply)+'</div>'
      +'</div>'
    : '';
  return '<div class="p-review-card" style="margin-bottom:10px">'
    +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">'
    +'<span style="font-size:15px">'+'⭐'.repeat(Math.min(5,r.stars||5))+'</span>'
    +'<div style="display:flex;align-items:center">'+replyBtn+delBtn+'</div>'
    +'</div>'
    +(r.texto ? '<p class="p-rv-txt" style="margin:0 0 4px">&#8220;'+_escHtml(r.texto)+'&#8221;</p>' : '')
    +'<div style="font-size:13px;color:var(--ink5)">— '+_escHtml(r.reviewer_name||'Anónimo')+'</div>'
    +replyHtml
    +'</div>';
}

function pOpenReviewReply(reviewId, reviewerUserId, cardEl){
  if(!reviewId) return;
  var isDark = document.body.classList.contains('r-dark');
  var ov = document.createElement('div');
  ov.id = 'reviewReplyOv';
  ov.style.cssText = 'position:fixed;inset:0;z-index:9100;background:rgba(0,0,0,.65);display:flex;flex-direction:column;justify-content:flex-end';
  ov.innerHTML = '<div style="background:'+(isDark?'rgba(8,22,14,.97)':'rgba(255,255,255,.98)')+';border-radius:22px 22px 0 0;padding:20px 18px max(20px,env(safe-area-inset-bottom));border-top:2px solid rgba(116,198,157,.45)">'
    +'<div style="width:36px;height:4px;background:rgba(128,128,128,.25);border-radius:2px;margin:0 auto 16px"></div>'
    +'<div style="font-size:14px;font-weight:700;color:var(--sage);letter-spacing:1px;text-transform:uppercase;margin-bottom:12px">💬 Responder a la reseña</div>'
    +'<textarea id="reviewReplyTA" placeholder="Escribí tu respuesta (gracias, aclaración...)" maxlength="400" style="width:100%;box-sizing:border-box;background:'+(isDark?'rgba(255,255,255,.07)':'rgba(0,0,0,.04)')+';border:1.5px solid rgba(116,198,157,.35);border-radius:14px;padding:10px 12px;color:var(--ink);font-size:15px;font-family:\'Jost\',sans-serif;resize:none;min-height:88px;outline:none;line-height:1.5" rows="4"></textarea>'
    +'<div style="display:flex;gap:10px;margin-top:12px">'
    +'<button onclick="document.getElementById(\'reviewReplyOv\').remove()" style="flex:1;padding:12px;border-radius:14px;border:1.5px solid var(--border);background:transparent;color:var(--ink3);font-size:15px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif">Cancelar</button>'
    +'<button onclick="pSubmitReviewReply(\''+_escHtml(String(reviewId))+'\',\''+_escHtml(String(reviewerUserId||''))+'\')" style="flex:2;padding:12px;border-radius:14px;border:1.5px solid rgba(116,198,157,.55);background:rgba(116,198,157,.18);color:var(--sage);font-size:15px;font-weight:800;cursor:pointer;font-family:\'Jost\',sans-serif">Enviar respuesta 💚</button>'
    +'</div>'
    +'</div>';
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
  document.body.appendChild(ov);
  setTimeout(function(){ var ta=document.getElementById('reviewReplyTA'); if(ta) ta.focus(); }, 100);
}

async function pSubmitReviewReply(reviewId, reviewerUserId){
  var ta = document.getElementById('reviewReplyTA');
  if(!ta) return;
  var replyText = ta.value.trim();
  if(!replyText){ pToast('⚠️','Escribí una respuesta primero'); return; }
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  var myId   = safeLS('get','velo_user_id')||'';
  var myName = _myDisplayName();
  try{
    var _upd = await sbClient.from('reviews').update({ reply: replyText, reply_name: myName }).eq('id', reviewId);
    if(_upd.error){ pToast('⚠️','Error al guardar'); console.error('[reviewReply]',_upd.error); return; }
    // Notify the reviewer
    if(reviewerUserId && reviewerUserId !== myId){
      sbSaveBroadcast('user:'+reviewerUserId,
        '💬 Recibiste una respuesta en tu reseña',
        myName+' respondió a tu reseña: "'+replyText.slice(0,100)+(replyText.length>100?'…':'')+'"',
        '💬', JSON.stringify({n:myName,i:myId,a:safeLS('get','velo_user_av')||'🌿'})
      );
    }
    // Notify self (the guardian who replied)
    pToast('💚','Respuesta enviada');
    var _rrOv=document.getElementById('reviewReplyOv'); if(_rrOv) _rrOv.remove();
    // Refresh reviews
    var myProfileId = safeLS('get','velo_user_id')||'';
    var rvEl = document.getElementById('profileReviews');
    if(rvEl && myProfileId){
      _loadUserReviews(myProfileId).then(function(revs){
        rvEl.innerHTML = revs.length
          ? _renderReviewsList(revs, myProfileId, myProfileId)
          : '<div class="p-empty"><span class="p-empty-emoji">⭐</span><div class="p-empty-title">Aún no hay reseñas</div><div class="p-empty-sub">Cuando acompañes a alguien como Guardián, sus reseñas van a aparecer acá 🌿</div></div>';
      });
    }
  }catch(e){ pToast('⚠️','Error al enviar'); console.error('[reviewReply catch]',e); }
}

function _renderReviewsList(revs, myId, proId){
  var LIMIT = 5;
  var visible = revs.slice(0, LIMIT);
  var rest = revs.slice(LIMIT);
  var html = visible.map(function(r){ return _reviewCardHtml(r, myId, proId); }).join('');
  if(rest.length){
    var moreId = 'rvMore'+Math.random().toString(36).slice(2,7);
    html += '<div id="'+moreId+'" style="display:none">'
      + rest.map(function(r){ return _reviewCardHtml(r, myId, proId); }).join('')
      +'</div>'
      +'<button onclick="var m=document.getElementById(\''+moreId+'\');if(!m)return;var open=m.style.display!==\'none\';m.style.display=open?\'none\':\'block\';this.textContent=open?\'Ver más ('+(rest.length)+') ↓\':\'Ver menos ↑\';" style="background:none;border:none;color:var(--sage);font-size:14px;font-weight:600;cursor:pointer;padding:4px 0;font-family:\'Jost\',sans-serif">Ver más ('+rest.length+') ↓</button>';
  }
  return html;
}

function pDeleteReview(reviewId, cardEl){
  if(!reviewId) return;
  _pConfirm('¿Eliminar esta reseña?', async function(){
    _initSupabase();
    if(sbClient){
      try{ await sbClient.from('reviews').delete().eq('id', reviewId); }catch(e){}
    }
    if(cardEl){
      cardEl.style.transition = 'opacity .3s';
      cardEl.style.opacity = '0';
      setTimeout(function(){ if(cardEl.parentNode) cardEl.parentNode.removeChild(cardEl); }, 350);
    }
    pToast('🗑️','Reseña eliminada');
  });
}

