function _happyQueueLoad(){
  var q = []; try{ q = JSON.parse(safeLS('get','velo_happy_queue')||'[]'); }catch(e){}
  return q;
}
function _happyQueueSave(q){
  safeLS('set','velo_happy_queue', JSON.stringify(q));
}

// Called on every render: expire old posts and promote queue
function _processHappyQueue(){
  var now    = Date.now();
  var posts  = _happyLoad();
  var before = posts.length;
  posts = posts.filter(function(p){ return (p.ts + HAPPY_TTL) > now; });
  var freed  = before - posts.length;

  var queue  = _happyQueueLoad();
  var notified = [];
  for(var i = 0; i < freed && queue.length > 0; i++){
    var next = queue.shift();
    next.ts = now;  // publish now
    posts.unshift(next);
    notified.push(next);
  }
  _happySave(posts);
  _happyQueueSave(queue);

  // Notify users whose posts just published
  notified.forEach(function(p){
    if(p.userId === _myUserId()){
      pToast('☀️','¡Tu publicación se publicó en el Muro! 💛');
      var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
      inbox.unshift({ id:'hpub-'+Date.now(), tipo:'muro', icon:'☀️', remitente:'Muro de la Felicidad',
        asunto:'¡Tu publicación ya está en el Muro! ☀️',
        extracto:'Se liberó un lugar y tu momento de alegría ya es visible para toda la comunidad.',
        leido:false, fecha:new Date().toLocaleDateString('es',{day:'2-digit',month:'short'}) });
      safeLS('set','velo_inbox', JSON.stringify(inbox.slice(0,100)));
      _updateInboxDot();
    }
  });

  return posts;
}

async function pRenderHappy(){
  var _tok = _navToken;
  var list = document.getElementById('happyList');
  if(!list) return;
  // Only reset form if user hasn't started typing
  var _ta = document.getElementById('happyPostTa');
  if(!_ta || !_ta.value.trim()) pOpenHappyPost();
  var myId = _myUserId();

  // Show cached posts immediately — filter expired ones (>24h) before displaying
  var _hCutoff = Date.now() - 24*60*60*1000;
  var _hCached = null;
  try{ _hCached = JSON.parse(safeLS('get','velo_happy_feed_cache')||'null'); }catch(e){}
  var _hCachedFresh = _hCached ? _hCached.filter(function(h){ return h.ts > _hCutoff; }) : null;
  if(_sbHappy && _sbHappy.length){
    _renderAllHappy(list, _sbHappy.filter(function(h){ return h.ts > _hCutoff; }));
  } else if(_hCachedFresh && _hCachedFresh.length){
    _renderAllHappy(list, _hCachedFresh);
  } else {
    list.innerHTML = '<div style="text-align:center;padding:30px;font-size:14px;color:var(--ink4)">Cargando ☀️…</div>';
  }

  // Load from Supabase (shared wall) or fall back to localStorage
  var _happyQ1 = function(q){
    var cutoff = new Date(Date.now()-24*60*60*1000).toISOString();
    return q.gte('created_at',cutoff).order('created_at',{ascending:false}).limit(50);
  };
  var sbRows = await _sbLoad('happy_posts_full', _happyQ1);       // vista con máscara
  if(sbRows === null) sbRows = await _sbLoad('happy_posts', _happyQ1); // fallback si la vista no existe aún
  if(_navToken !== _tok) return;
  var posts, usingSB = false;
  if(sbRows !== null){
    usingSB = true;
    posts = sbRows.map(_sbHappyRow).filter(function(h){ return !_isBlocked(h.userId); });
    // Merge own local posts that failed to insert to Supabase (survives page refresh)
    var _cutoffMs = Date.now() - 24*60*60*1000;
    var _localOwn = _happyLoad().filter(function(p){ return p.ts > _cutoffMs && p.userId === myId; });
    _localOwn.forEach(function(lp){
      // Match by id OR by timestamp (Supabase may auto-generate a different id)
      var sbMatch = posts.find(function(p){ return String(p.id) === String(lp.id) || p.ts === lp.ts; });
      if(!sbMatch){
        posts.unshift(lp);
      } else if(!sbMatch.photo && lp.photo){
        // SB post exists but photo column was empty — restore from local cache
        sbMatch.photo = lp.photo;
      }
    });
    // Merge post that was just submitted; Supabase may not have returned it yet
    if(_pendingHappyPost){
      var pendingIdx = posts.findIndex(function(p){ return p.id === _pendingHappyPost.id; });
      if(pendingIdx < 0){
        posts.unshift(_pendingHappyPost);
      } else {
        // Post found in SB — if photo is missing (column not supported or empty), preserve from pending
        if(!posts[pendingIdx].photo && _pendingHappyPost.photo){
          posts[pendingIdx].photo = _pendingHappyPost.photo;
        }
        _pendingHappyPost = null;
      }
    }
    _sbHappy = posts;
    // Persist fresh posts to localStorage so next open is instant (strip large fields)
    try{ safeLS('set','velo_happy_feed_cache', JSON.stringify(posts.slice(0,20).map(function(h){ return {id:h.id,userId:h.userId,name:h.name,av:h.av,anon:h.anon,emoji:h.emoji,text:h.text,ts:h.ts}; }))); }catch(e){}
    // Batch-fetch names/avatars for non-anon authors (also fixes posts saved with empty user_name)
    if(sbClient){
      var _hpUnknown = posts.filter(function(h){ return !h.anon && h.userId && h.userId!=='anon'; }).map(function(h){ return h.userId; }).filter(function(id,i,a){ return a.indexOf(id)===i; });
      if(_hpUnknown.length){ try{
        var _hpr = await sbClient.from('profiles').select('id,username,nombre,avatar').in('id',_hpUnknown);
        if(_hpr.data) _hpr.data.forEach(function(p){
          _uFill(p.id, p.username);
          var realName = p.nombre || (p.username ? '@'+p.username : '');
          posts.forEach(function(h){
            if(h.userId !== p.id || h.anon) return;
            // Update name if stored as empty / placeholder
            if(realName && (!h.name || h.name === 'Usuario' || h.name === '')) h.name = realName;
            // Update avatar if DB had emoji placeholder but profiles has a real photo
            if(p.avatar && !(h.av && (h.av.startsWith('data:') || h.av.startsWith('http')))) h.av = p.avatar;
          });
        });
      }catch(e){} }
    }
  } else {
    posts = _processHappyQueue();
  }

  // Auto-save own active posts to local history + backfill happy_history in Supabase
  var _hEmail2 = safeLS('get','velo_user_email')||'';
  if(usingSB && myId && myId.indexOf('guest-') !== 0){
    try{
      var _hKeyAuto = 'velo_happy_history_'+myId;
      var _histAuto = []; try{ _histAuto = JSON.parse(safeLS('get',_hKeyAuto)||'[]'); }catch(e){}
      var _histAutoIds = {};
      _histAuto.forEach(function(e){ _histAutoIds[e.id]=true; });
      var _ownWall = posts.filter(function(p){
        return p.userId === myId || (_hEmail2 && p.userId === _hEmail2);
      });
      var _autoAdded = false;
      _ownWall.forEach(function(p){
        if(!_histAutoIds[p.id]){
          _histAuto.unshift({ id:p.id, emoji:p.emoji, text:p.text, ts:p.ts, name:p.name });
          _autoAdded = true;
        }
      });
      if(_autoAdded){ try{ safeLS('set',_hKeyAuto, JSON.stringify(_histAuto.slice(0,500))); }catch(e){} }
      // Backfill Supabase happy_history with own posts not yet stored there
      _initSupabase();
      if(sbClient && _ownWall.length){
        var _hisUidB = safeLS('get','velo_user_id')||_hEmail2||'';
        if(_hisUidB){
          _ownWall.forEach(function(p){
            sbClient.from('happy_history').upsert({
              id:p.id, user_id:_hisUidB, emoji:p.emoji||'☀️', text:p.text||''
            },{ onConflict:'id', ignoreDuplicates:true }).then(function(){}).catch(function(err){
              // Retry without emoji if the column doesn't exist yet
              if(String((err&&err.message)||err).indexOf('emoji') >= 0){
                sbClient.from('happy_history').upsert({
                  id:p.id, user_id:_hisUidB, text:p.text||''
                },{ onConflict:'id', ignoreDuplicates:true }).then(function(){}).catch(function(){});
              }
            });
          });
        }
      }
    }catch(e){}
  }

  // Queue notice (only in localStorage mode)
  var queueNote = document.getElementById('happyQueueNote');
  if(queueNote){
    if(!usingSB){
      var queue = _happyQueueLoad();
      var myQueued = queue.find(function(p){ return p.userId === myId; });
      if(myQueued){
        var pos = queue.indexOf(myQueued)+1;
        queueNote.style.display='';
        queueNote.innerHTML='⏳ Tu publicación está en lista de espera (posición '+pos+' de '+queue.length+').';
      } else { queueNote.style.display='none'; }
    } else { queueNote.style.display='none'; }
  }

  var counter = document.getElementById('happyCounter');
  if(counter) counter.textContent = posts.length+' publicaciones activas';

  // Update history entries with live stats from Supabase
  if(usingSB && myId){
    try{
      var _hKeyU = 'velo_happy_history_'+myId;
      var hist = JSON.parse(safeLS('get',_hKeyU)||safeLS('get','velo_happy_history')||'[]');
      var dirty = false;
      hist.forEach(function(he){
        var live = posts.find(function(p){ return p.id === he.id; });
        if(live){
          he.reactions = live.reactions;
          he.commentCount = (live.comments||[]).length;
          dirty = true;
        }
      });
      if(dirty) safeLS('set',_hKeyU, JSON.stringify(hist));
    }catch(e){}
  }

  var queue = usingSB ? [] : _happyQueueLoad();
  if(_happyActiveTab === 'mine'){
    _renderMyHappy(list, posts, queue, myId);
  } else if(_happyActiveTab === 'history'){
    await _renderHappyHistory(list, posts, myId);
  } else {
    _renderAllHappy(list, posts);
  }
}

function _renderAllHappy(list, posts){
  var all = posts;
  if(!all.length){
    list.innerHTML = '<div class="p-empty" style="grid-column:1/-1"><span class="p-empty-emoji">☀️</span><div class="p-empty-title">El muro está vacío</div><div class="p-empty-sub">¡Sé el primero en compartir un momento de alegría!</div></div>';
    return;
  }
  var _myId = _myUserId ? _myUserId() : '';
  list.innerHTML = all.map(function(h){ return _happyPostCard(h, !!(_myId && h.userId === _myId)); }).join('');
}

function _renderMyHappy(list, posts, queue, myId){
  var mine = posts.filter(function(p){ return p.userId === myId; });
  var myQueued = queue.filter(function(p){ return p.userId === myId; });

  if(!mine.length && !myQueued.length){
    list.innerHTML = '<div class="p-empty" style="grid-column:1/-1"><span class="p-empty-emoji">📌</span>'
      +'<div class="p-empty-title">No tenés publicación activa</div>'
      +'<div class="p-empty-sub">Publicá algo en el Muro de la Felicidad para verla aquí ☀️</div></div>';
    return;
  }

  var html = '';
  if(mine.length){
    html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:14px">'
      +'<span style="font-size:18px">📌</span>'
      +'<span style="font-size:14px;font-weight:700;color:var(--sage);letter-spacing:.3px">Tus publicaciones activas</span>'
      +'<span style="font-size:12px;color:var(--ink5);margin-left:auto">'+mine.length+' activa'+(mine.length>1?'s':(mine.length===1?'':'')+'')+' · desaparecen a las 24h</span>'
      +'</div>';
    mine.forEach(function(p){ html += _happyPostCard(p, true); html += '<div style="height:10px"></div>'; });
  }
  myQueued.forEach(function(p){
    html += '<div class="happy-card" style="border:1.5px dashed rgba(255,200,50,.4);opacity:.8;margin-top:12px">'
      +'<div style="font-size:13px;font-weight:700;color:rgba(255,180,30,.8);margin-bottom:8px;display:flex;align-items:center;gap:6px">⏳ En lista de espera</div>'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">'
      +'<div style="font-size:26px;width:42px;height:42px;border-radius:13px;background:var(--sun3);display:flex;align-items:center;justify-content:center">'+p.emoji+'</div>'
      +'<div><div style="font-size:15px;font-weight:600;color:var(--ink)">'+_escHtml(p.name)+'</div>'
      +'<div style="font-size:12px;color:var(--ink5)">Enviado '+_happyRelTime(p.ts)+'</div></div></div>'
      +'<p style="font-size:15px;color:var(--ink3);line-height:1.6;font-family:\'Cormorant Garamond\',serif;font-style:italic">"'+_escHtml(p.text)+'"</p>'
      +'</div>';
  });
  list.innerHTML = html;
}

async function _renderHappyHistory(list, wallPosts, wallMyId){
  var _hUid = wallMyId || (_myUserId ? _myUserId() : (safeLS('get','velo_user_id')||''));
  var _hKey = _hUid ? 'velo_happy_history_'+_hUid : 'velo_happy_history';
  var history = []; try{ history = JSON.parse(safeLS('get',_hKey)||'[]'); }catch(e){}
  // Migrate legacy base64 photos and resave to free up localStorage space
  var _migDirty = false;
  history = history.map(function(e){ if(e.photo && String(e.photo).length > 100){ e.hasPhoto = true; delete e.photo; _migDirty = true; } return e; });
  if(_migDirty){ try{ safeLS('set',_hKey, JSON.stringify(history)); }catch(e){} }

  // Immediate fallback: merge own active posts from the already-loaded wall (passed or _sbHappy global)
  var _activePosts = wallPosts || _sbHappy || [];
  var _hUidNow = _hUid || '';
  var _hEmailNow = safeLS('get','velo_user_email')||'';
  if(_activePosts.length && _hUidNow && _hUidNow.indexOf('guest-') !== 0){
    var _existIds = {};
    history.forEach(function(e){ _existIds[e.id]=true; });
    var _ownNow = _activePosts.filter(function(p){
      return p.userId === _hUidNow || (_hEmailNow && p.userId === _hEmailNow);
    });
    var _nowAdded = false;
    _ownNow.forEach(function(p){
      if(!_existIds[p.id]){
        history.push({ id:p.id, emoji:p.emoji, text:p.text, ts:p.ts, name:p.name });
        _nowAdded = true;
      }
    });
    if(_nowAdded){
      history.sort(function(a,b){ return b.ts - a.ts; });
      try{ safeLS('set',_hKey, JSON.stringify(history.slice(0,500))); }catch(e){}
    }
  }

  // Cross-device sync: query happy_history (permanent table, no 24h expiry)
  var sbUid   = safeLS('get','velo_user_id')||'';
  var sbEmail = safeLS('get','velo_user_email')||'';
  _initSupabase();
  if((sbUid||sbEmail) && sbClient){
    if(!history.length) list.innerHTML = '<div style="text-align:center;padding:30px 0;color:var(--ink5);font-size:15px">Sincronizando historial…</div>';
    try{
      // Use UUID when available, fall back to email — no .or() to avoid PostgREST parse errors
      var _hUidFilter = sbUid || sbEmail;
      // Primary: happy_history (permanent, cross-device)
      var qh = sbClient.from('happy_history').select('id,emoji,text,created_at').eq('user_id', _hUidFilter);
      var sh = await qh.order('created_at',{ascending:false}).limit(500);
      // If emoji column missing (schema mismatch), retry without it
      if(sh.error && sh.error.message && sh.error.message.indexOf('emoji') >= 0){
        sh = await sbClient.from('happy_history').select('id,text,created_at')
          .eq('user_id', _hUidFilter).order('created_at',{ascending:false}).limit(500);
      }
      // Fallback: happy_posts (only last 24h, but covers very recent posts not yet in history)
      var sp = await sbClient.from('happy_posts').select('id,emoji,text,created_at')
        .eq('user_id', _hUidFilter).order('created_at',{ascending:false}).limit(50);
      var merged = [].concat(sh.error ? [] : (sh.data||[]), sp.error ? [] : (sp.data||[]));
      if(merged.length){
        var existIds = {};
        history.forEach(function(e){ existIds[e.id]=true; });
        merged.forEach(function(r){
          if(existIds[r.id]) return;
          existIds[r.id] = true;
          history.push({ id:r.id, emoji:r.emoji||'☀️', text:r.text||'', ts:new Date(r.created_at).getTime(), name:'' });
        });
        history.sort(function(a,b){ return b.ts - a.ts; });
        try{ safeLS('set',_hKey, JSON.stringify(history.slice(0,500))); }catch(e){}
      }
      if(sh.error) console.warn('[history happy_history]', sh.error.message);
    }catch(e){ console.warn('[history sb]', e); }
  }

  if(!history.length){
    var _noUid = !sbUid && !sbEmail;
    var _dbgSb = sbClient ? ('SB:uid='+!!sbUid+' email='+!!sbEmail) : 'SB:no-client';
    list.innerHTML = '<div class="p-empty" style="grid-column:1/-1"><span class="p-empty-emoji">📅</span>'
      +'<div class="p-empty-title">Tu historial está vacío</div>'
      +'<div class="p-empty-sub">'+(_noUid ? 'Iniciá sesión para sincronizar tu historial entre dispositivos 🔑' : 'Cuando publiques algo en el Muro, quedará guardado aquí para siempre 🌟')+'</div>'
      +'<div style="font-size:12px;color:var(--ink5);margin-top:8px;opacity:.5">'+_dbgSb+'</div></div>';
    return;
  }

  // Group by calendar date
  var groups = {}; // { 'YYYY-MM-DD': { label, entries[] } }
  var order  = [];
  var today  = new Date(); today.setHours(0,0,0,0);
  var yest   = new Date(today); yest.setDate(yest.getDate()-1);
  history.forEach(function(h){
    var d = new Date(h.ts);
    var key = d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
    if(!groups[key]){
      d.setHours(0,0,0,0);
      var label;
      if(d.getTime() === today.getTime())      label = 'Hoy';
      else if(d.getTime() === yest.getTime())  label = 'Ayer';
      else label = new Date(h.ts).toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
      // Capitalize first letter
      label = label.charAt(0).toUpperCase()+label.slice(1);
      groups[key] = { label:label, entries:[] };
      order.push(key);
    }
    groups[key].entries.push(h);
  });

  var clearBtn = '<div style="text-align:right;margin-bottom:16px">'
    +'<button onclick="pClearHappyHistory()" style="padding:6px 14px;background:rgba(220,60,60,.06);border:1px solid rgba(220,60,60,.18);border-radius:100px;font-size:14px;color:rgba(200,60,60,.7);cursor:pointer;font-family:\'Jost\',sans-serif;font-weight:600">🗑️ Borrar historial</button>'
    +'</div>';

  var html = clearBtn;
  order.forEach(function(key, gi){
    var g = groups[key];
    var count = g.entries.length;
    var isFirst = gi === 0;
    html += '<details'+(isFirst?' open':'')+' style="margin-bottom:10px;border-radius:14px;overflow:hidden;'
      +'background:rgba(255,255,255,.55);border:1.5px solid rgba(255,200,50,.2);backdrop-filter:blur(4px)">'
      +'<summary style="list-style:none;cursor:pointer;padding:12px 16px;display:flex;align-items:center;gap:10px;user-select:none;'
      +'font-size:15px;font-weight:700;color:var(--ink2)">'
      +'<span style="font-size:16px">📅</span>'
      +'<span style="flex:1">'+_escHtml(g.label)+'</span>'
      +'<span style="font-size:13px;font-weight:600;color:var(--sage2);background:rgba(116,198,157,.15);'
      +'border:1px solid rgba(116,198,157,.3);border-radius:100px;padding:2px 9px;flex-shrink:0">'
      +count+' publicación'+(count>1?'es':'')+'</span>'
      +'<span class="hist-chevron" style="font-size:14px;color:var(--ink4);flex-shrink:0;transition:transform .2s">▼</span>'
      +'</summary>'
      +'<div style="padding:0 12px 12px;display:flex;flex-direction:column;gap:8px">';

    g.entries.forEach(function(h){
      var timeStr = new Date(h.ts).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'});
      var rxTotal = 0;
      if(h.reactions) rxTotal = Object.keys(h.reactions).reduce(function(a,k){ return a+(h.reactions[k]||0); }, 0);
      html += '<div style="background:rgba(255,255,255,.7);border-radius:12px;padding:12px 14px;border:1px solid rgba(255,200,50,.15)">'
        +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:'+(h.text?'10':'0')+'px">'
        +'<div style="font-size:22px;width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,rgba(255,224,102,.3),rgba(253,233,244,.5));'
        +'display:flex;align-items:center;justify-content:center;flex-shrink:0">'+h.emoji+'</div>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:12px;color:var(--ink4);margin-bottom:1px">'+timeStr+'</div>'
        +(h.hasPhoto ? '<div style="font-size:12px;color:var(--sage2);font-weight:600">📷 Incluyó foto</div>' : '')
        +'</div>'
        +(rxTotal>0 ? '<span style="font-size:12px;background:rgba(255,224,102,.25);border-radius:100px;padding:2px 8px;font-weight:600;color:rgba(140,100,0,.8);flex-shrink:0">💛 '+rxTotal+'</span>' : '')
        +(h.commentCount>0 ? '<span style="font-size:12px;background:rgba(116,198,157,.15);border-radius:100px;padding:2px 8px;font-weight:600;color:var(--sage);flex-shrink:0;margin-left:4px">💬 '+h.commentCount+'</span>' : '')
        +'</div>'
        +(h.text ? '<p style="font-size:14px;color:var(--ink2);line-height:1.65;margin:0;font-family:\'Cormorant Garamond\',serif;font-style:italic;font-weight:500">"'+_escHtml(h.text)+'"</p>' : '')
        +'</div>';
    });

    html += '</div></details>';
  });

  list.innerHTML = html;

  // Rotate chevron when details opens/closes
  list.querySelectorAll('details').forEach(function(det){
    det.addEventListener('toggle', function(){
      var ch = det.querySelector('.hist-chevron');
      if(ch) ch.style.transform = det.open ? 'rotate(180deg)' : '';
    });
  });
}

function pClearHappyHistory(){
  _pConfirm('¿Borrar todo tu historial del Muro de la Felicidad? Esta acción no se puede deshacer.', function(){
    var _hUid2 = _myUserId ? _myUserId() : (safeLS('get','velo_user_id')||'');
    var _hKey2 = _hUid2 ? 'velo_happy_history_'+_hUid2 : 'velo_happy_history';
    safeLS('set',_hKey2,'[]');
    pRenderHappy();
    pToast('🗑️','Historial borrado');
  });
}

function _happyPostCard(h, isOwn){
  var timeLeft = _happyTimeLeft(h.ts);
  var relTime  = _happyRelTime(h.ts);
  var expColor = timeLeft && timeLeft.toLowerCase().indexOf('min') > -1 ? 'var(--rose)' : 'var(--ink5)';
  var myReacted = safeLS('get','velo_happy_rx_'+h.id) || '';

  // Reaction bar
  var rxBar = _happyReactEmojis.map(function(e){
    var cnt = (h.reactions && h.reactions[e]) || 0;
    var active = myReacted === e;
    return '<button onclick="pHappyReact(\''+h.id+'\',\''+e+'\')" style="padding:5px 12px;background:'+(active?'rgba(222,162,36,.45)':'rgba(222,162,36,.11)')+';border:1.5px solid '+(active?'rgba(222,162,36,.80)':'rgba(222,162,36,.30)')+';border-radius:100px;font-size:15px;cursor:pointer;font-family:\'Jost\',sans-serif;font-weight:700;transition:all .15s;box-shadow:'+(active?'0 2px 14px rgba(222,162,36,.32)':'none')+'">'+e+(cnt?' <span style="font-size:13px;color:rgba(255,218,70,.90)">'+cnt+'</span>':'')+'</button>';
  }).join('');

  // Comments
  var comments = h.comments || [];
  var commCount = comments.length;
  var shownComments = isOwn ? comments : comments.slice(0, 5);
  var _hcDark = document.body.classList.contains('r-dark');
  var _cmtNameCol = _hcDark ? 'rgba(255,222,78,.90)' : 'rgba(140,92,4,.92)';
  var _cmtTextCol = _hcDark ? 'rgba(255,255,255,.80)' : 'rgba(28,22,2,.82)';
  var commHtml = '';
  if(commCount > 0){
    commHtml = '<div style="margin-bottom:10px">';
    commHtml += '<div style="font-size:13px;font-weight:700;color:var(--ink4);margin-bottom:8px;display:flex;align-items:center;gap:5px"><span>💬</span><span>'+commCount+' comentario'+(commCount>1?'s':'')+'</span></div>';
    shownComments.forEach(function(c){
      var cAnon = !c.userId || c.name === 'Usuario Anónimo' || c.name === 'Anónimo';
      var cClickAttr = !cAnon
        ? ' onclick="pQuickProfile('+_jsAttr(c.name||'Usuario')+','+_jsAttr(c.av||'🧑')+',\'\',\'\','+_jsAttr(c.userId)+')"'
        : '';
      var avHtml = cAnon
        ? '<div style="font-size:15px;width:26px;height:26px;border-radius:50%;background:var(--cream2);display:flex;align-items:center;justify-content:center;flex-shrink:0">👤</div>'
        : '<div style="flex-shrink:0;cursor:pointer"'+cClickAttr+'>'+_avInline(c.av||'🧑',26)+'</div>';
      commHtml += '<div style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px">'
        + avHtml
        +'<div style="background:rgba(222,162,36,.10);border-radius:0 12px 12px 12px;padding:7px 11px;flex:1;min-width:0;border-left:2px solid rgba(222,162,36,.42)">'
        +'<div class="happy-cmt-name" style="font-size:13px;font-weight:700;color:'+_cmtNameCol+';margin-bottom:2px'+(cAnon?'':';cursor:pointer')+'"'+cClickAttr+'>'+_escHtml(c.name||'Usuario')+'</div>'
        +'<div class="happy-cmt-text" style="font-size:14px;color:'+_cmtTextCol+';line-height:1.45;word-break:break-word">'+_escHtml(c.text)+'</div>'
        +'</div></div>';
    });
    if(!isOwn && commCount > 5){
      commHtml += '<div style="font-size:13px;color:var(--sage);text-align:center;padding:4px 0;font-weight:600">+ '+(commCount-5)+' comentarios más</div>';
    }
    commHtml += '</div>';
  }
  var moreComments = '';

  // Avatar: profile photo or emoji avatar for non-anon; mood emoji for anon
  var hasPhoto = h.av && (h.av.startsWith('data:') || h.av.startsWith('http'));
  var hasEmojiAv = !h.anon && h.av && h.av !== '' && !hasPhoto;
  var avatarHtml;
  if(hasPhoto){
    avatarHtml = '<div style="position:relative;width:44px;height:44px;flex-shrink:0">'
      +'<img src="'+_escHtml(h.av)+'" style="width:44px;height:44px;border-radius:12px;object-fit:cover;display:block">'
      +'<span style="position:absolute;bottom:-3px;right:-3px;font-size:14px;line-height:1">'+h.emoji+'</span>'
      +'</div>';
  } else if(hasEmojiAv){
    avatarHtml = '<div style="position:relative;font-size:26px;width:44px;height:44px;border-radius:12px;background:rgba(255,224,102,.25);display:flex;align-items:center;justify-content:center;flex-shrink:0">'
      +h.av
      +'<span style="position:absolute;bottom:-3px;right:-3px;font-size:14px;line-height:1">'+h.emoji+'</span>'
      +'</div>';
  } else {
    avatarHtml = '<div style="font-size:26px;width:44px;height:44px;border-radius:12px;background:var(--sun3);display:flex;align-items:center;justify-content:center;flex-shrink:0">'+h.emoji+'</div>';
  }

  var canClick = !!(h.userId && h.userId !== 'anon' && !h.anon);
  var authorClick = canClick ? ' style="cursor:pointer" onclick="pQuickProfile('+_jsAttr(h.name||'Usuario')+','+_jsAttr(h.av||'')+',\'\',\'\','+_jsAttr(h.userId||'')+')"' : '';
  return '<div class="happy-card" data-id="'+h.id+'">'
    // header
    +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">'
    +'<div'+authorClick+'>'+avatarHtml+'</div>'
    +'<div style="flex:1;min-width:0">'
    +'<div style="font-size:15px;font-weight:600;color:var(--ink)'+(canClick?';cursor:pointer':'')+'"'+(canClick?' onclick="pQuickProfile('+_jsAttr(h.name||'Usuario')+','+_jsAttr(h.av||'')+',\'\',\'\','+_jsAttr(h.userId||'')+')"':'')+'>'+_escHtml(h.name||'Usuario Anónimo')+'</div>'
    +(!h.anon && h.userId && h.userId!=='anon' ? _uAt(h.userId) : '')
    +'<div style="font-size:12px;color:var(--ink5);margin-top:1px">'+relTime+(isOwn?' · <strong style="color:var(--sage)">Tuya</strong>':'')+'</div>'
    +'</div>'
    +(isOwn
      ? '<button onclick="pDeleteHappyPost(\''+h.id+'\')" style="padding:5px 10px;background:rgba(255,80,80,.07);border:1px solid rgba(255,80,80,.18);border-radius:100px;color:rgba(200,60,60,.7);font-size:13px;cursor:pointer;font-family:\'Jost\',sans-serif;flex-shrink:0" title="Eliminar publicación">🗑️</button>'
      : '<button onclick="pReportContent(\'happy\','+_jsAttr(h.id)+','+_jsAttr((h.text||'').slice(0,80))+')" style="padding:4px 9px;background:rgba(200,50,50,.12);border:1px solid rgba(200,50,50,.25);border-radius:100px;color:rgba(180,50,50,.88);font-size:12px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif;flex-shrink:0">🚩</button>')
    +(timeLeft ? '<span style="font-size:12px;color:'+expColor+';font-weight:600;white-space:nowrap;flex-shrink:0">⏳ '+timeLeft+'</span>' : '')
    +'</div>'
    // photo with tap-to-zoom hint overlay
    +(h.photo
      ? '<div style="position:relative;margin-bottom:14px;border-radius:12px;overflow:hidden">'
        +'<img src="'+_escHtml(h.photo)+'" onclick="pZoomPhoto(this.src)" style="width:100%;max-height:260px;object-fit:cover;display:block;cursor:zoom-in">'
        +'<div style="position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent,rgba(0,0,0,.50));padding:18px 12px 8px;pointer-events:none;display:flex;align-items:center;justify-content:center">'
        +'<span style="background:rgba(0,0,0,.42);color:rgba(255,255,255,.82);font-size:11px;font-weight:700;letter-spacing:.4px;border-radius:100px;padding:3px 11px;font-family:Jost,sans-serif;backdrop-filter:blur(6px)">🔍 Toca para ampliar</span>'
        +'</div>'
        +'</div>'
      : '')
    // text
    +(h.text ? '<p style="font-size:16px;color:var(--ink2);line-height:1.7;margin-bottom:14px;font-family:\'Cormorant Garamond\',serif;font-style:italic;font-weight:500">"'+_escHtml(h.text)+'"</p>' : '')
    // reactions
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">'+rxBar+'</div>'
    // divider + comments
    +(commHtml ? '<div style="border-top:1px solid var(--border2);padding-top:12px;margin-bottom:12px">'+commHtml+'</div>' : '<div style="border-top:1px solid var(--border2);margin-bottom:12px"></div>')
    // comment input
    +'<div style="display:flex;gap:8px;align-items:center">'
    +'<input id="cmt-'+h.id+'" class="p-input" style="flex:1;font-size:14px;padding:7px 12px;height:auto;border-radius:100px" placeholder="Dejar un comentario…" maxlength="120" onkeydown="if(event.key===\'Enter\')pHappyComment(\''+h.id+'\')">'
    +'<button onclick="pHappyComment(\''+h.id+'\')" style="padding:7px 14px;background:linear-gradient(135deg,rgba(222,162,36,.48),rgba(200,136,16,.36));border:1.5px solid rgba(222,162,36,.72);border-radius:100px;font-size:14px;cursor:pointer;color:rgba(255,228,82,.97);font-family:\'Jost\',sans-serif;font-weight:700;flex-shrink:0;white-space:nowrap;box-shadow:0 2px 14px rgba(222,162,36,.24)">Enviar ✨</button>'
    +'</div>'
    +(safeLS('get','velo_incognito')==='true' ? '<div style="font-size:12px;color:var(--ink5);line-height:1.5;margin-top:6px;font-style:italic">En tu perfil tenés activo el modo incógnito. Si querés comentar con tu perfil público, desactivá esa opción.</div>' : '')
    +'</div>';
}

function pDeleteHappyPost(postId){
  _pConfirm('¿Eliminar esta publicación del Muro?', async function(){
    _initSupabase();
    try{ await _ensureSbSession(); }catch(e){}
    if(sbClient){
      var _delUid = safeLS('get','velo_user_id')||'';
      try{
        var _q = sbClient.from('happy_posts').delete().eq('id', postId);
        if(_delUid) _q = _q.eq('user_id', _delUid);
        var _delRes = await _q;
        if(_delRes && _delRes.error) console.error('[happy delete]', _delRes.error.message);
      }catch(e){ console.error('[happy delete catch]', e); }
    }
    if(_sbHappy) _sbHappy = _sbHappy.filter(function(h){ return String(h.id) !== String(postId); });
    _pendingHappyPost = null;
    var _lc = _happyLoad().filter(function(p){ return String(p.id) !== String(postId); });
    _happySave(_lc);
    var card = document.querySelector('.happy-card[data-id="'+postId+'"]');
    if(card){ card.style.transition='opacity .3s'; card.style.opacity='0'; setTimeout(function(){ pRenderHappy(); },350); }
    else { pRenderHappy(); }
    pToast('✅','Publicación eliminada');
  });
}

function pToggleHappyFav(btn, userId, name, av){
  if(!userId) return;
  if(pIsFav(userId)){
    pRemoveFav(userId);
  } else {
    pAddFav(userId, name, av);
  }
  // Re-read actual state after toggle so the button always reflects reality
  var nowFav = pIsFav(userId);
  if(btn){
    btn.textContent = nowFav ? '⭐' : '☆';
    btn.style.background  = nowFav ? 'rgba(255,200,50,.2)'  : 'rgba(255,200,50,.06)';
    btn.style.borderColor = nowFav ? 'rgba(255,200,50,.5)'  : 'rgba(255,200,50,.2)';
  }
}

function pToggleHappyProfile(tog){
  tog.classList.toggle('on');
  var isOn = tog.classList.contains('on');
  var chk = document.getElementById('happyShowProfile');
  if(chk) chk.checked = isOn;
  var emojiRow = document.getElementById('happyEmojiRow');
  var profileAvRow = document.getElementById('happyProfileAvRow');
  if(isOn){
    if(emojiRow) emojiRow.style.display = 'none';
    if(!profileAvRow){
      profileAvRow = document.createElement('div');
      profileAvRow.id = 'happyProfileAvRow';
      profileAvRow.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:8px;padding:6px 10px;background:rgba(255,255,255,.6);border-radius:10px;border:1px solid rgba(255,200,50,.3)';
      var av = safeLS('get','velo_user_av') || '🧑';
      var name = safeLS('get','velo_user_name') || '';
      var avHtml = (av.startsWith('data:') || av.startsWith('http'))
        ? '<img src="'+av+'" style="width:34px;height:34px;border-radius:50%;object-fit:cover;display:block">'
        : '<span style="font-size:26px;line-height:1">'+av+'</span>';
      profileAvRow.innerHTML = avHtml + '<span style="font-size:14px;font-weight:600;color:var(--ink2)">'+_escHtml(name)+'</span>'
        + '<span style="font-size:12px;color:var(--sage2);margin-left:auto;font-weight:600">Perfil visible</span>';
      if(emojiRow && emojiRow.parentNode) emojiRow.parentNode.insertBefore(profileAvRow, emojiRow);
    } else {
      profileAvRow.style.display = 'flex';
    }
  } else {
    if(emojiRow) emojiRow.style.display = '';
    if(profileAvRow) profileAvRow.style.display = 'none';
  }
}

function pHappyTab(tab, el){
  _happyActiveTab = tab;
  document.querySelectorAll('.happy-tab').forEach(function(b){ b.classList.remove('active'); });
  if(el) el.classList.add('active');
  pRenderHappy();
}

function pHappyReact(postId, emoji){
  var myReacted = safeLS('get','velo_happy_rx_'+postId);
  if(myReacted === emoji){ pToast('💛','Ya reaccionaste con '+emoji); return; }
  // Supabase-loaded post → update in memory + persist to Supabase
  var sbPost = (_sbHappy||[]).find(function(p){ return String(p.id) === String(postId); });
  if(sbPost){
    if(!sbPost.reactions) sbPost.reactions = {};
    if(myReacted && sbPost.reactions[myReacted] > 0) sbPost.reactions[myReacted]--;
    sbPost.reactions[emoji] = (sbPost.reactions[emoji] || 0) + 1;
    sbUpdateHappyPost(postId, { reactions: sbPost.reactions });
    safeLS('set','velo_happy_rx_'+postId, emoji);
    pToast(emoji,'¡Alegría compartida!');
    var _rxCard = document.querySelector('.happy-card[data-id="'+postId+'"]');
    if(_rxCard){ _rxCard.outerHTML = _happyPostCard(sbPost, sbPost.userId === _myUserId()); }
    else { setTimeout(pRenderHappy, 600); }
    return;
  }
  var posts = _happyLoad();
  var post  = posts.find(function(p){ return p.id === postId; });
  var isMock = false;
  if(!post){
    post = _happyMock.find(function(p){ return p.id === postId; });
    isMock = true;
  }
  if(!post) return;
  if(!post.reactions) post.reactions = {};
  if(myReacted && post.reactions[myReacted] > 0) post.reactions[myReacted]--;
  post.reactions[emoji] = (post.reactions[emoji] || 0) + 1;
  if(!isMock){
    _happySave(posts);
    if(post.userId === _myUserId()) _happyStatIncr('reactionsReceived');
  }
  safeLS('set','velo_happy_rx_'+postId, emoji);
  pToast(emoji,'¡Alegría compartida!');
  pRenderHappy();
}

function pHappyComment(postId){
  var inp = document.getElementById('cmt-'+postId);
  if(!inp || !inp.value.trim()) return;
  var text = inp.value.trim();
  // A comment is anonymous ONLY if the user has incognito mode enabled
  var incognito = safeLS('get','velo_incognito') === 'true';
  var myName = incognito ? 'Usuario Anónimo' : _myDisplayName();
  var myAv   = incognito ? '' : (safeLS('get','velo_user_av')||'🧑');
  var myId   = incognito ? '' : _myUserId();
  var comment = { name:myName, text:text, ts:Date.now(), userId:myId, av:myAv };
  // Supabase-loaded post → update in memory + persist to Supabase
  var sbPost = (_sbHappy||[]).find(function(p){ return String(p.id) === String(postId); });
  if(sbPost){
    if(!sbPost.comments) sbPost.comments = [];
    sbPost.comments.push(comment);
    sbUpdateHappyPost(postId, { comments: sbPost.comments });
    inp.value = '';
    pToast('💬','Comentario enviado 🌿');
    var _cmtCard = document.querySelector('.happy-card[data-id="'+postId+'"]');
    if(_cmtCard){ _cmtCard.outerHTML = _happyPostCard(sbPost, sbPost.userId === _myUserId()); }
    else { setTimeout(pRenderHappy, 600); }
    return;
  }
  var posts = _happyLoad();
  var post  = posts.find(function(p){ return p.id === postId; });
  var isMock = false;
  if(!post){
    post = _happyMock.find(function(p){ return p.id === postId; });
    isMock = true;
  }
  if(!post) return;
  if(!post.comments) post.comments = [];
  post.comments.push(comment);
  if(!isMock){
    _happySave(posts);
    if(post.userId === _myUserId()) _happyStatIncr('commentsReceived');
  }
  inp.value = '';
  pToast('💬','Comentario enviado 🌿');
  pRenderHappy();
}

