function pOpenEditProfile(){
  var en = document.getElementById('editName');
  var em = document.getElementById('editMotto');
  var eu = document.getElementById('editUsername');
  if(en) en.value = safeLS('get','velo_user_name')  || '';
  if(em) em.value = safeLS('get','velo_user_motto') || '';
  var uname = safeLS('get','velo_username') || '';
  if(eu){ eu.value = uname; eu.disabled = false; }
  var _unCh   = parseInt(safeLS('get','velo_username_changes')||'0', 10);
  var _unLeft = Math.max(0, 2 - _unCh);
  var _unHint = document.getElementById('usernameChangesHint');
  if(_unHint) _unHint.innerHTML = _unLeft === 0 ? ' · <span style="color:#E05C5C">sin cambios restantes</span>' : ' · <strong>'+_unLeft+'</strong> cambio'+ (_unLeft===1?'':'s')+' restante'+(_unLeft===1?'':'s');
  if(_unLeft === 0 && eu) eu.disabled = true;
  var noteEl = document.getElementById('editUsernameChangesNote');
  var leftEl  = document.getElementById('editUsernameChangesLeft');
  if(noteEl) noteEl.style.display = 'block';
  if(leftEl){
    if(_unLeft === 0) leftEl.innerHTML = ' <strong style="color:#E05C5C">Ya usaste los 2 cambios disponibles.</strong>';
    else leftEl.innerHTML = ' Te quedan <strong>'+_unLeft+'</strong> cambio'+(_unLeft===1?'':'s')+'.';
  }
  // Push notification toggle
  var _pushRow = document.getElementById('editPushRow');
  if(_pushRow && 'Notification' in window) { _pushRow.style.display = 'block'; _updateEditPushUI(); }
  openModal('editProfileOv');
}

function _updateEditPushUI(){
  var perm   = ('Notification' in window) ? Notification.permission : 'unavailable';
  var hasSub = !!safeLS('get','velo_push_sub');
  // Update both the edit-profile modal and the profile page toggles
  ['edit','profile'].forEach(function(prefix){
    var btn    = document.getElementById(prefix+'PushBtn');
    var status = document.getElementById(prefix+'PushStatus');
    if(!btn || !status) return;
    if(perm === 'unavailable'){
      status.textContent = 'Agregá Velo a tu pantalla de inicio para activar notificaciones';
      btn.textContent = '¿Cómo?'; btn.disabled = false;
      btn.style.cssText = 'flex-shrink:0;padding:7px 14px;border-radius:10px;border:none;font-size:14px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;background:rgba(116,198,157,.15);color:rgba(80,160,110,.9)';
    } else if(perm === 'denied'){
      status.textContent = 'Bloqueadas — activálas en ajustes del navegador';
      btn.textContent = '—'; btn.disabled = true;
      btn.style.cssText = 'flex-shrink:0;padding:7px 14px;border-radius:10px;border:none;font-size:14px;font-weight:700;font-family:Jost,sans-serif;cursor:not-allowed;background:rgba(128,128,128,.12);color:var(--ink4)';
    } else if(perm === 'granted' && hasSub){
      status.textContent = 'Activadas — recibís 3 avisos por día ✓';
      btn.textContent = 'Desactivar'; btn.disabled = false;
      btn.style.cssText = 'flex-shrink:0;padding:7px 14px;border-radius:10px;border:none;font-size:14px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;background:rgba(220,80,80,.12);color:rgba(200,60,60,.9)';
    } else if(perm === 'granted' && !hasSub){
      status.textContent = 'Permiso concedido — tocá Activar para recibirlas';
      btn.textContent = 'Activar'; btn.disabled = false;
      btn.onclick = function(){ _tryRecoverPushSub(); };
      btn.style.cssText = 'flex-shrink:0;padding:7px 14px;border-radius:10px;border:none;font-size:14px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;background:linear-gradient(135deg,rgba(116,198,157,.25),rgba(74,160,110,.30));color:rgba(80,160,110,.95)';
    } else {
      status.textContent = 'No activadas — te avisamos 3 veces al día';
      btn.textContent = 'Activar'; btn.disabled = false;
      btn.style.cssText = 'flex-shrink:0;padding:7px 14px;border-radius:10px;border:none;font-size:14px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;background:linear-gradient(135deg,rgba(116,198,157,.25),rgba(74,160,110,.30));color:rgba(80,160,110,.95)';
    }
  });
}

function _tryRecoverPushSub(){
  var _hasSW  = 'serviceWorker' in navigator;
  var _hasPM  = 'PushManager' in window;
  var _hasNot = 'Notification' in window;
  var _isSA   = !!(window.navigator.standalone || window.matchMedia('(display-mode: standalone)').matches);
  var _perm   = _hasNot ? Notification.permission : 'n/a';
  if(!_hasSW || !_hasPM){
    var _dbg = new Error('SW:'+_hasSW+' PM:'+_hasPM+' Notif:'+_hasNot+' SA:'+_isSA+' perm:'+_perm);
    _showPushFixModal('noSW', _dbg); return;
  }
  // Always resolve fresh from ready — handles null _swReg and SW transitions
  navigator.serviceWorker.ready.then(function(reg){
    _swReg = reg;
    return reg.pushManager.getSubscription().then(function(_existing){
      // Unsubscribe any existing (possibly stale/corrupted) sub before re-subscribing.
      // On iOS this clears internal SW push state that can cause subscribe() to fail.
      var _unsub = _existing ? _existing.unsubscribe().catch(function(){}) : Promise.resolve();
      return _unsub.then(function(){
        return reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: _urlBase64ToUint8Array(_VAPID_PUBLIC_KEY)
        });
      }).then(function(_sub){
        if(!_sub){ pToast('⚠️','No se pudo crear la suscripción'); return; }
        safeLS('set','velo_push_sub', JSON.stringify(_sub));
        safeLS('set','velo_push_sub_key', _VAPID_PUBLIC_KEY);
        _updateEditPushUI();
        _savePushSubscriptionToSupabase(_sub).catch(function(){});
        try{ _renderHomePushBanner(); }catch(_be){}
        pToast('🔔','¡Notificaciones activadas! 💚');
      }).catch(function(e){
        console.warn('[push sub]', e.name, e.message);
        if(e.name === 'NotAllowedError') _showPushFixModal('denied', e);
        else _showPushFixModal('error', e);
      });
    });
  }).catch(function(e){ _showPushFixModal('noSW', e); });
}

function _showPushFixModal(reason, err){
  var existing = document.getElementById('pushFixOv');
  if(existing) existing.remove();
  var steps = reason === 'denied'
    ? '1. Abrí <strong>Ajustes iOS</strong><br>2. Buscá <strong>Notificaciones → Velo</strong><br>3. Activá "Permitir notificaciones"<br>4. Volvé a Velo y tocá Reconectar'
    : '1. Deslizá Velo hacia arriba en el <strong>App Switcher</strong><br>2. Volvé a abrir Velo desde tu pantalla de inicio<br>3. Andá a Perfil → Notificaciones<br>4. Tocá <strong>Activar</strong>';
  var title = reason === 'denied' ? '🔕 Notificaciones bloqueadas' : '🔔 Reiniciá Velo para activar';
  // Show the actual error so it can be reported without needing a debug console
  var errInfo = '';
  if(err && reason !== 'denied'){
    var _eName = (err.name || 'Error');
    var _eMsg  = (err.message || '').slice(0, 200);
    errInfo = '<div style="margin-top:14px;padding:10px 12px;background:rgba(0,0,0,.45);border-radius:10px;border:1px solid rgba(255,200,100,.25);font-size:14px;color:rgba(255,210,120,.9);word-break:break-all;font-family:monospace;line-height:1.6"><strong style="color:rgba(255,200,80,1)">Error técnico (mandá foto):</strong><br>'+_escHtml(_eName)+'<br>'+_escHtml(_eMsg)+'</div>';
  }
  var ov = document.createElement('div');
  ov.id = 'pushFixOv';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:99990;display:flex;align-items:flex-end;justify-content:center;padding:0';
  ov.innerHTML = '<div style="background:#0e1f14;border-radius:20px 20px 0 0;padding:24px 20px calc(28px + env(safe-area-inset-bottom,0px));width:100%;max-width:480px;font-family:Jost,sans-serif;border-top:1.5px solid rgba(116,198,157,.22)">'
    +'<div style="font-size:17px;font-weight:700;color:#d8eed8;text-align:center;margin-bottom:12px">'+title+'</div>'
    +'<div style="font-size:15px;color:rgba(200,230,210,.8);line-height:1.9;margin-bottom:18px;text-align:left">'+steps+errInfo+'</div>'
    +(reason !== 'denied' ? '<button onclick="window.location.reload()" style="width:100%;padding:13px;border-radius:100px;border:none;background:rgba(116,198,157,.9);color:#0e1f14;font-family:Jost,sans-serif;font-size:15px;font-weight:800;cursor:pointer;margin-bottom:10px">🔄 Reiniciar Velo ahora</button>' : '')
    +'<button onclick="document.getElementById(\'pushFixOv\').remove()" style="width:100%;padding:12px;border-radius:100px;border:1.5px solid rgba(116,198,157,.25);background:none;color:rgba(180,220,180,.7);font-family:Jost,sans-serif;font-size:14px;cursor:pointer">Cerrar</button>'
    +'</div>';
  document.body.appendChild(ov);
}

function _showIOSPushModal(){
  var ov = document.getElementById('iosPushInstrOv');
  if(ov) ov.style.display = 'flex';
}
function _closeIOSPushModal(){
  var ov = document.getElementById('iosPushInstrOv');
  if(ov) ov.style.display = 'none';
}

function _showAndroidPushModal(){
  var ov = document.getElementById('androidPushInstrOv');
  if(ov) ov.style.display = 'flex';
}
function _closeAndroidPushModal(){
  var ov = document.getElementById('androidPushInstrOv');
  if(ov) ov.style.display = 'none';
}
async function _androidPushConfirm(){
  _closeAndroidPushModal();
  var _p = await Notification.requestPermission();
  if(_p !== 'granted'){ _updateEditPushUI(); return; }
  await _doPushSubscribe();
}
async function _doPushSubscribe(){
  safeLS('set','velo_push_granted','1');
  try{
    var _reg = await navigator.serviceWorker.ready;
    // Unsubscribe any stale/corrupted sub first — clears SW internal push state (iOS fix)
    var _oldSub = await _reg.pushManager.getSubscription();
    if(_oldSub){ try{ await _oldSub.unsubscribe(); }catch(_){ } }
    var _sub = await _reg.pushManager.subscribe({ userVisibleOnly:true, applicationServerKey:_urlBase64ToUint8Array(_VAPID_PUBLIC_KEY) });
    if(!_sub) throw new Error('no subscription returned');
    safeLS('set','velo_push_sub', JSON.stringify(_sub));
    safeLS('set','velo_push_sub_key', _VAPID_PUBLIC_KEY);
    await _savePushSubscriptionToSupabase(_sub);
    pToast('🔔','¡Notificaciones activadas! 💚');
  }catch(e){
    console.warn('[push subscribe]', e && e.name, e && e.message);
    safeLS('del','velo_push_granted');
    if(e && e.name === 'NotAllowedError') _showPushFixModal('denied', e);
    else _showPushFixModal('error', e);
  }
  _updateEditPushUI();
  _renderHomePushBanner();
}

async function pTogglePushNotifications(){
  var isIOS = /iPhone|iPad|iPod/.test(navigator.userAgent);
  var isStandalone = !!(window.navigator.standalone || window.matchMedia('(display-mode: standalone)').matches);
  var hasNotifAPI = 'Notification' in window && 'serviceWorker' in navigator && 'PushManager' in window;

  // iOS Safari (browser, not PWA): must install first
  if(isIOS && !isStandalone){ _showIOSPushModal(); return; }

  // iOS installed as PWA but OS/browser doesn't support Web Push (< iOS 16.4)
  if(isIOS && isStandalone && !hasNotifAPI){
    pToast('📱','Tu versión de iOS no soporta notificaciones. Actualizá a iOS 16.4 o superior.'); return;
  }

  // Non-iOS without Notification API (very old browser)
  if(!hasNotifAPI){ pToast('🔕','Tu navegador no soporta notificaciones push'); return; }

  var hasSub = !!safeLS('get','velo_push_sub');
  var perm   = Notification.permission;
  if(perm === 'denied'){ pToast('🔕','Bloqueadas — activálas en Configuración > Safari/Notificaciones'); return; }
  if(hasSub){
    safeLS('del','velo_push_sub');
    safeLS('del','velo_push_granted');
    var _uid = safeLS('get','velo_user_id');
    if(sbClient && _uid){
      try{ await _ensureSbSession(); }catch(e){}
      try{ await sbClient.from('profiles').update({ push_subscription: null }).eq('id',_uid); }catch(e){}
    }
    pToast('🔕','Notificaciones desactivadas');
    _updateEditPushUI(); return;
  }
  if(perm === 'default'){
    if(isIOS && isStandalone){
      // On iOS PWA, request permission directly without the Android pre-permission modal
      var _ip = await Notification.requestPermission();
      if(_ip !== 'granted'){ _updateEditPushUI(); return; }
      await _doPushSubscribe();
      return;
    }
    _showAndroidPushModal(); return;
  }
  // perm === 'granted' but no local subscription yet
  await _doPushSubscribe();
}

async function pSaveProfile(){
  var nameEl  = document.getElementById('editName');
  var mottoEl = document.getElementById('editMotto');
  var name  = nameEl ? nameEl.value.trim() : '';
  var motto = mottoEl ? mottoEl.value.trim() : '';
  if(!name){ pToast('⚠️','Ingresá tu nombre'); return; }
  if(name)  safeLS('set','velo_user_name', name);
  if(motto) safeLS('set','velo_user_motto', motto);
  if(_selectedAv) safeLS('set','velo_user_av', _selectedAv);
  // Handle @username change
  var unameInput = document.getElementById('editUsername');
  var newUname = unameInput ? unameInput.value.toLowerCase().replace(/[^a-z0-9.\-_]/g,'').trim() : '';
  var curUname = safeLS('get','velo_username') || '';
  // Sync to Supabase so profile persists across devices
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(sbClient){
    try{
      var {data:_spSd} = await sbClient.auth.getSession();
      if(_spSd && _spSd.session && _spSd.session.user && _spSd.session.user.id){
        uid = _spSd.session.user.id;
        safeLS('set','velo_user_id', uid);
      }
    }catch(e){}
  }
  if(sbClient && uid){
    // Handle username update if changed
    if(newUname && newUname !== curUname){
      var _unChanges = parseInt(safeLS('get','velo_username_changes')||'0', 10);
      var _isFirstSet = curUname === ''; // first-time set doesn't count as a change
      if(!_isFirstSet && _unChanges >= 2){ pToast('⚠️','Solo podés cambiar tu @usuario 2 veces en total'); return; }
      if(newUname.length < 5 || newUname.length > 20){
        pToast('⚠️','El @usuario debe tener entre 5 y 20 caracteres'); return;
      }
      // Check uniqueness (always lowercase)
      try{
        var _rU = await sbClient.from('profiles').select('id').eq('username', newUname).neq('id', uid).limit(1);
        if(_rU.data && _rU.data.length){ pToast('⚠️','Ese @usuario ya está tomado, elegí otro'); return; }
        var _newCount = _isFirstSet ? _unChanges : (_unChanges + 1); // only increment on replacement
        var _rUpd = await sbClient.from('profiles').update({ username: newUname, username_changes: _newCount }).eq('id', uid);
        if(!_rUpd.error){
          safeLS('set','velo_username', newUname);
          safeLS('set','velo_username_changes', String(_newCount));
        } else { console.error('[pSaveProfile username]', _rUpd.error); pToast('⚠️','Error al guardar @usuario'); return; }
      }catch(e){ console.error('[pSaveProfile username catch]', e); }
    }
    var _rawAv = safeLS('get','velo_user_av') || '';
    var av = _rawAv.length > 8000 ? '' : _rawAv;
    // If user still has a base64 avatar, upload it to Storage now so it syncs cross-device
    if(_rawAv.startsWith('data:')){
      _uploadAvatarToStorage(null, _rawAv, function(pub){ if(pub){ safeLS('set','velo_user_av', pub); _syncAvatarToSb(pub); } });
    }
    var email = safeLS('get','velo_user_email') || '';
    // Upsert with full fields; on 400 (missing column) retry with core fields only
    var _fullRow = {
      id:uid, nombre:name, avatar:av, motto:motto, email:email,
      status_music:  safeLS('get','velo_status_music')||'',
      status_book:   safeLS('get','velo_status_book')||'',
      status_phrase: safeLS('get','velo_status_phrase')||'',
      status_film:   safeLS('get','velo_status_film')||''
    };
    var _coreRow = { id:uid, nombre:name, avatar:av, motto:motto };
    sbClient.from('profiles').upsert(_fullRow,{ onConflict:'id' })
    .then(function(r){
      if(r && r.error){
        // Retry with minimal columns — extended columns may not exist in schema yet
        return sbClient.from('profiles').upsert(_coreRow,{ onConflict:'id' })
          .then(function(r2){
            if(!r2 || !r2.error){ pToast('✅','Perfil actualizado 💚'); }
            else { pToast('⚠️','Perfil guardado localmente (error de sincronización)'); }
          });
      } else {
        pToast('✅','Perfil actualizado 💚');
      }
    })
    .catch(function(){
      pToast('⚠️','Perfil guardado localmente (sin conexión).');
    });
  }
  closeModal('editProfileOv');
  pLoadProfile();
  _propagateAvatarUI(safeLS('get','velo_user_av') || '🧑');
}

// ── @USERNAME PICKER ──────────────────────────────────────────────
var _usernameCheckTimer = null;
function pCheckUsername(val){
  var statusEl = document.getElementById('pickUsernameStatus');
  var btn = document.getElementById('pickUsernameBtn');
  if(btn) btn.disabled = true;
  // Auto-sanitize: lowercase, only allowed chars
  val = val.toLowerCase().replace(/[^a-z0-9.\-_]/g,'');
  var inputEl = document.getElementById('pickUsernameInput');
  if(inputEl && inputEl.value !== val) inputEl.value = val;
  if(!val || val.length < 5){
    if(statusEl) statusEl.innerHTML = val.length > 0 ? '<span style="color:#E05C5C">Mínimo 5 caracteres</span>' : '';
    return;
  }
  if(val.length > 20){
    if(statusEl) statusEl.innerHTML = '<span style="color:#E05C5C">Máximo 20 caracteres</span>';
    return;
  }
  if(statusEl) statusEl.innerHTML = '<span style="color:var(--ink4)">Verificando…</span>';
  clearTimeout(_usernameCheckTimer);
  _usernameCheckTimer = setTimeout(async function(){
    _initSupabase();
    if(!sbClient){ if(btn) btn.disabled = false; return; }
    try{
      var r = await sbClient.from('profiles').select('id').eq('username', val).limit(1);
      var taken = r.data && r.data.length > 0;
      if(statusEl) statusEl.innerHTML = taken
        ? '<span style="color:#E05C5C">❌ Ya está tomado, elegí otro</span>'
        : '<span style="color:var(--sage2)">✓ Disponible</span>';
      if(btn){ btn.disabled = taken; btn.style.opacity = taken ? '.5' : '1'; }
    }catch(e){ if(btn){ btn.disabled = false; btn.style.opacity='1'; } }
  }, 500);
}

async function pSaveUsername(){
  var inputEl = document.getElementById('pickUsernameInput');
  if(!inputEl) return;
  var val = inputEl.value.toLowerCase().replace(/[^a-z0-9.\-_]/g,'').trim();
  if(!val || val.length < 5 || val.length > 20){
    pToast('⚠️','El @usuario debe tener entre 5 y 20 caracteres'); return;
  }
  _initSupabase();
  var uid = safeLS('get','velo_user_id');
  if(sbClient){
    try{
      var {data:_puSd} = await sbClient.auth.getSession();
      if(_puSd && _puSd.session && _puSd.session.user && _puSd.session.user.id){
        uid = _puSd.session.user.id;
        safeLS('set','velo_user_id', uid);
      }
    }catch(e){}
  }
  if(sbClient && uid){
    try{
      // Final uniqueness check
      var rChk = await sbClient.from('profiles').select('id').eq('username', val).neq('id', uid).limit(1);
      if(rChk.data && rChk.data.length){ pToast('⚠️','Ese @usuario ya está tomado'); return; }
      var rSave = await sbClient.from('profiles').upsert({ id: uid, username: val }, { onConflict: 'id' });
      if(rSave.error){ console.error('[pSaveUsername]', rSave.error); pToast('⚠️','Error al guardar. Intentá de nuevo.'); return; }
    }catch(e){ console.error('[pSaveUsername catch]', e); pToast('⚠️','Error de conexión'); return; }
  }
  safeLS('set','velo_username', val);
  safeLS('set','velo_onboarding_done','1');
  pToast('✨','@'+val+' guardado 🎉');
  // Navigate: if came from registration flow → verify-email, else home
  var fromReg = safeLS('get','velo_pick_username_from_reg');
  if(fromReg === '1'){
    safeLS('set','velo_pick_username_from_reg','');
    var veEl = document.getElementById('verifyEmailAddr');
    var em = safeLS('get','velo_user_email') || '';
    if(veEl) veEl.textContent = em;
    pGoTo('verify-email');
  } else {
    pGoTo('home');
    setTimeout(function(){
      _loadHomeData();
      _updateSidebarUser();
    }, 100);
  }
}

// Variant for edit profile modal (uses editUsernameStatus element)
var _editUsernameCheckTimer = null;
function pCheckEditUsername(val){
  var statusEl = document.getElementById('editUsernameStatus');
  var inputEl = document.getElementById('editUsername');
  // Always force lowercase
  val = val.toLowerCase().replace(/[^a-z0-9.\-_]/g,'');
  if(inputEl && inputEl.value !== val) inputEl.value = val;
  // Enforce change limit
  var _ch = parseInt(safeLS('get','velo_username_changes')||'0', 10);
  var curUname = safeLS('get','velo_username') || '';
  if(_ch >= 3 && val !== curUname){
    if(statusEl) statusEl.innerHTML = '<span style="color:#E05C5C">Límite de 3 cambios alcanzado</span>';
    return;
  }
  if(!val){ if(statusEl) statusEl.innerHTML = ''; return; }
  if(val === curUname){ if(statusEl) statusEl.innerHTML = ''; return; }
  if(val.length < 5){ if(statusEl) statusEl.innerHTML = '<span style="color:#E05C5C">Mínimo 5 caracteres</span>'; return; }
  if(val.length > 20){ if(statusEl) statusEl.innerHTML = '<span style="color:#E05C5C">Máximo 20 caracteres</span>'; return; }
  if(statusEl) statusEl.innerHTML = '<span style="color:var(--ink4)">Verificando…</span>';
  clearTimeout(_editUsernameCheckTimer);
  _editUsernameCheckTimer = setTimeout(async function(){
    _initSupabase(); if(!sbClient) return;
    var uid = safeLS('get','velo_user_id');
    try{
      var r = await sbClient.from('profiles').select('id').eq('username', val)
        .neq('id', uid||'').limit(1);
      var taken = r.data && r.data.length > 0;
      if(statusEl) statusEl.innerHTML = taken
        ? '<span style="color:#E05C5C">❌ Ya está tomado</span>'
        : '<span style="color:var(--sage2)">✓ Disponible</span>';
    }catch(e){}
  }, 500);
}

// Search users by @username or display name
async function pSearchUsers(query){
  if(!query || query.length < 2) return [];
  _initSupabase();
  if(!sbClient) return [];
  try{
    var q = query.replace(/^@+/,'');
    var r = await sbClient.from('profiles')
      .select('id,nombre,avatar,username,motto,role')
      .or('username.ilike.'+q+'%,nombre.ilike.'+q+'%')
      .limit(12);
    var list = r.data || [];
    // v1464: "Perfil destacado" (Velo Plus) — los usuarios Plus aparecen primero.
    list.sort(function(a,b){
      var ap = a && a.role === 'plus' ? 0 : 1;
      var bp = b && b.role === 'plus' ? 0 : 1;
      return ap - bp;
    });
    return list;
  }catch(e){ return []; }
}

