function pToggleIncognito(){
  var isOn = safeLS('get','velo_incognito') === 'true';
  var next = !isOn;
  safeLS('set','velo_incognito', next ? 'true' : 'false');
  // Sync incognito preference to Supabase so other devices pick it up
  _initSupabase();
  var _incUid = safeLS('get','velo_user_id');
  if(sbClient && _incUid){
    sbClient.from('profiles').update({ incognito: next }).eq('id', _incUid)
      .then(function(){}).catch(function(){});
  }
  var tog = document.getElementById('incognitoTog');
  if(tog){ tog.classList.remove('on'); if(next) tog.classList.add('on'); }
  var tog2 = document.getElementById('homeIncognitoTog');
  if(tog2){ tog2.classList.remove('on'); if(next) tog2.classList.add('on'); }
  // Sync to Supabase so other users see the change immediately
  if(safeLS('get','velo_is_guardian') === 'true'){
    var realAvail = safeLS('get','velo_user_status') || 'disponible';
    var newStatus = next ? ('incognito_' + realAvail) : realAvail;
    safeLS('set','velo_guardian_status', newStatus);
    _myGuardianStatus = newStatus;
    _updateGuardianPresence(newStatus).then(function(){
      if(_curPage === 'guardians') pRenderGuardians();
    });
  }
  _renderMyStatusBar();
  _renderHomeStatusToggle();
  pToast(isOn ? '👁️' : '🕵️', isOn ? 'Modo incógnito desactivado' : 'Modo incógnito activado');
}

