function _closeVibeInstant(){
  var ov = document.getElementById('vibeInstantOv');
  if(!ov) return;
  var prev = ov.dataset.prevHtmlBg || '';
  document.documentElement.style.backgroundColor = prev;
  ov.remove();
}
function _vibeTimeLeft(expiresAtIso){
  var d = new Date(expiresAtIso).getTime() - Date.now();
  if(d <= 0) return 'caducado';
  if(d < 3600000) return Math.max(1, Math.floor(d/60000)) + ' min';
  return Math.floor(d/3600000) + ' h';
}
// Aggregado de reacciones para el grupo actualmente abierto: {vibeId: {reactionKey: count}}
var _vibeReactionAgg = {};
// Mi reacción para cada vibe: {vibeId: reactionKey}
var _vibeMyReactions = {};
// Calcula el tint RGB pesado según reacciones recibidas
function _vibeTintFromReactions(counts){
  if(!counts) return null;
  var r=0,g=0,b=0,total=0;
  VIBE_REACTIONS.forEach(function(reaction){
    var c = counts[reaction.key]||0;
    if(!c) return;
    var hex = reaction.tint; // '#f5c76a'
    r += parseInt(hex.slice(1,3),16) * c;
    g += parseInt(hex.slice(3,5),16) * c;
    b += parseInt(hex.slice(5,7),16) * c;
    total += c;
  });
  if(!total) return null;
  return { r:Math.round(r/total), g:Math.round(g/total), b:Math.round(b/total), total:total };
}
// Frase resumen sin números
function _vibeSummaryPhrase(counts){
  if(!counts) return '';
  var total = 0, dominant = null, dmax = 0, distinct = 0;
  VIBE_REACTIONS.forEach(function(reaction){
    var c = counts[reaction.key]||0;
    if(c > 0){ total += c; distinct++; if(c > dmax){ dmax = c; dominant = reaction.key; } }
  });
  if(total === 0) return '';
  if(distinct >= 5) return 'Recibió mucho amor 💚';
  var phrase = {
    alegria: 'Recibió mucha alegría 🌞',
    abrazo: 'Muchos abrazos 🤗',
    acompano: 'Encontraron calma acá 🕊️',
    fuerzas: 'Muchas fuerzas 💪',
    gracias: 'Muchas gracias por compartir 🙏',
    me_hace_bien: 'Le hizo bien a muchos ✨',
    animos: 'Muchos ánimos 💚',
    me_inspira: 'Inspiró a muchos 🌱'
  }[dominant] || '';
  return phrase;
}
function _vibeCardHtml(v){
  var ago = _timeAgoDM ? _timeAgoDM(new Date(v.created_at).getTime()) : '';
  var left = _vibeTimeLeft(v.expires_at);
  // Tint dinámico basado en reacciones actuales
  var counts = _vibeReactionAgg[v.id] || {};
  var tint = _vibeTintFromReactions(counts);
  var borderColor = tint ? 'rgba('+tint.r+','+tint.g+','+tint.b+',.65)' : 'rgba(116,198,157,.32)';
  var glow = tint ? '0 12px 32px rgba('+tint.r+','+tint.g+','+tint.b+',.30), 0 3px 10px rgba('+tint.r+','+tint.g+','+tint.b+',.22)' : '0 8px 26px rgba(0,0,0,.35), 0 2px 8px rgba(60,140,90,.14)';
  var mine = _vibeMyReactions[v.id] || '';
  var summary = _vibeSummaryPhrase(counts);
  // Reacciones ahora muestran EMOJI + LABEL debajo, y glow del tint cuando están seleccionadas
  var reactionPicker = '<div class="vibe-rx-row" style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:10px 12px 12px;background:rgba(0,0,0,.22);border-top:1px solid rgba(116,198,157,.12)">'
    + VIBE_REACTIONS.map(function(reaction){
        var sel = mine === reaction.key;
        var r = parseInt(reaction.tint.slice(1,3),16);
        var g = parseInt(reaction.tint.slice(3,5),16);
        var b = parseInt(reaction.tint.slice(5,7),16);
        var bg = sel ? 'rgba('+r+','+g+','+b+',.28)' : 'rgba(255,255,255,.04)';
        var brd = sel ? reaction.tint : 'rgba(255,255,255,.12)';
        var shadow = sel ? 'box-shadow:0 0 18px rgba('+r+','+g+','+b+',.55), inset 0 0 12px rgba('+r+','+g+','+b+',.18);' : '';
        return '<button type="button" onclick="pVibeReact(\''+v.id+'\',\''+reaction.key+'\',this)" title="'+_escHtml(reaction.label)+'" style="background:'+bg+';border:1.5px solid '+brd+';border-radius:12px;padding:8px 4px 6px;cursor:pointer;transition:all .25s;display:flex;flex-direction:column;align-items:center;gap:3px;line-height:1;'+shadow+'"><span style="font-size:19px">'+reaction.emoji+'</span><span style="font-family:Jost,sans-serif;font-size:9.5px;font-weight:700;color:'+(sel?reaction.tint:'rgba(220,240,225,.65)')+';letter-spacing:.2px;text-align:center;line-height:1.15">'+_escHtml(reaction.label)+'</span></button>';
      }).join('')
    + '</div>';
  var summaryChip = summary
    ? '<div style="padding:10px 16px 12px;font-family:Jost,sans-serif;font-size:12px;font-weight:800;letter-spacing:.4px;color:'+(tint?'rgba('+tint.r+','+tint.g+','+tint.b+',.98)':'rgba(180,220,195,.75)')+';text-transform:uppercase">'+_escHtml(summary)+'</div>'
    : '';
  // Chip del grupo — muestra dónde está publicado el momento (junto al emoji)
  var groupChip = '';
  try{
    var _grInfo = null;
    if(v.group_id){
      _grInfo = (_vibesGroupsCache||[]).find(function(g){ return g.id === v.group_id; });
    }
    if(_grInfo){
      var _grName = _grInfo.title || 'Grupo';
      var _grEmoji = (_grInfo.emoji||'').trim() || (_grInfo.slug && _VIBE_SLUG_EMOJIS[_grInfo.slug]) || '🌊';
      groupChip = '<div style="display:inline-flex;align-items:center;gap:5px;padding:3px 9px;background:rgba(116,198,157,.16);border:1px solid rgba(116,198,157,.42);border-radius:100px;font-family:Jost,sans-serif;font-size:10.5px;font-weight:700;color:rgba(180,235,205,.98);letter-spacing:.2px;margin-top:4px;max-width:100%"><span style="font-size:12px;flex-shrink:0">'+_escHtml(_grEmoji)+'</span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">en '+_escHtml(_grName)+'</span></div>';
    } else if(v.instant_scope){
      var _instLbl = v.instant_scope === 'private' ? '🔒 Instantáneo privado' : '✨ Instantáneo';
      groupChip = '<div style="display:inline-flex;align-items:center;gap:5px;padding:3px 9px;background:rgba(220,170,60,.20);border:1px solid rgba(220,170,60,.55);border-radius:100px;font-family:Jost,sans-serif;font-size:10.5px;font-weight:700;color:rgba(255,225,150,.98);letter-spacing:.2px;margin-top:4px">'+_escHtml(_instLbl)+'</div>';
    }
  }catch(_grE){}
  var _isMineVibe = v.user_id && v.user_id === (safeLS('get','velo_user_id')||'');
  // Banderita "guardar en mi historial" — solo en MIS momentos. Permite archivar
  // el momento después de publicado (por si olvidé tildar "guardar" al subir).
  var _arch = !!v.archived;
  var vibeSaveBtn = _isMineVibe
    ? '<button onclick="event.stopPropagation();pVibeToggleArchive('+_jsAttr(v.id)+',this)" data-vibe-archived="'+(_arch?'1':'0')+'" title="Guardá este momento en tu historial personal — lo ves siempre en tu perfil, aunque pasen las 24 h" style="background:'+(_arch?'rgba(240,200,92,.20)':'rgba(255,255,255,.06)')+';border:1.5px solid '+(_arch?'rgba(240,200,92,.60)':'rgba(200,230,215,.30)')+';border-radius:100px;color:'+(_arch?'#f0c85c':'rgba(210,235,220,.88)')+';font-family:Jost,sans-serif;font-size:11px;font-weight:800;cursor:pointer;padding:6px 11px;flex-shrink:0;line-height:1;display:inline-flex;align-items:center;gap:4px;letter-spacing:.2px"><span style="font-size:13px">🔖</span><span data-vibe-arch-lbl>'+(_arch?'Guardado':'Guardar')+'</span></button>'
    : '';
  var vibeMenuBtn = '<button onclick="event.stopPropagation();pVibeCardMenu('+_jsAttr(v.id)+','+(_isMineVibe?'true':'false')+')" style="background:none;border:none;color:rgba(200,230,215,.55);font-size:18px;cursor:pointer;padding:4px 6px;flex-shrink:0;line-height:1">⋯</button>';
  return '<div class="vibe-card" data-vibe-id="'+v.id+'" style="background:linear-gradient(180deg,rgba(20,40,26,.92),rgba(10,26,18,.95));border:1.5px solid '+borderColor+';border-radius:22px;overflow:hidden;margin-bottom:14px;box-shadow:'+glow+';transition:box-shadow .5s, border-color .5s">'
    + '<div onclick="_vibeOpenUserProfile('+_jsAttr(v.user_id||'')+','+_jsAttr(v.user_name||'Usuario')+','+_jsAttr(v.user_av||'🧑')+')" style="display:flex;align-items:center;gap:10px;padding:12px 14px 8px;cursor:pointer" title="Ver perfil de '+_escHtml(v.user_name||'Usuario')+'"><span style="font-size:28px;flex-shrink:0">'+_avInline(v.user_av||'🧑', 36)+'</span><div style="flex:1;min-width:0"><div style="font-family:Jost,sans-serif;font-size:13.5px;font-weight:800;color:#fff">'+_escHtml(v.user_name||'Usuario')+'</div><div class="vibe-uname" data-vibe-uname="'+_escHtml(v.user_id||'')+'" style="font-family:Jost,sans-serif;font-size:10.5px;color:rgba(180,220,195,.80);font-weight:700;letter-spacing:.2px">'+(function(){ try{ var _u=_uLook(v.user_id); return _u?'@'+_escHtml(_u):''; }catch(_){ return ''; } })()+'</div>'+groupChip+'<div style="font-family:Jost,sans-serif;font-size:10.5px;color:rgba(180,220,195,.62);font-weight:600;letter-spacing:.4px;margin-top:3px">'+(v.mood?'<span style="color:rgba(255,215,120,.95);font-weight:800">'+_escHtml(v.mood+' '+_vibeMoodLabel(v.mood))+'</span> · ':'')+ago+' · caduca en '+left+'</div></div>'+vibeSaveBtn+vibeMenuBtn+'</div>'
    + (_vibeIsVideoUrl(v.media_url)
        ? '<video src="'+_escHtml((v.media_url||'').replace('/video/upload/','/video/upload/q_auto/'))+'" controls playsinline preload="metadata" style="width:100%;max-height:520px;display:block;background:#000"></video>'
        : '<img data-vibe-src="'+_escHtml(v.media_url||'')+'" data-vibe-w="900" alt="momento" style="width:100%;max-height:520px;object-fit:cover;display:block;background:rgba(0,0,0,.35)" onerror="this.style.opacity=\'.35\'">')
    + (v.caption ? '<div style="padding:12px 16px 14px;font-family:\'Cormorant Garamond\',serif;font-size:15.5px;font-style:italic;color:rgba(240,250,240,.95);line-height:1.5">"'+_escHtml(v.caption)+'"</div>' : '')
    + summaryChip
    + reactionPicker
    // Botón de comentar + preview de comentarios
    + '<div style="padding:8px 14px 12px;border-top:1px solid rgba(116,198,157,.10)">'
      + '<button onclick="pOpenVibeComments(\''+v.id+'\')" style="width:100%;padding:9px 12px;background:rgba(255,255,255,.05);border:1px solid rgba(180,220,195,.22);border-radius:12px;color:rgba(220,240,225,.85);font-family:Jost,sans-serif;font-size:12.5px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;letter-spacing:.3px">💬 <span data-vibe-comment-count="'+v.id+'">Ver comentarios</span></button>'
    + '</div>'
  + '</div>';
}
// Guardar/quitar un momento propio de "mi historial personal" (campo archived).
// Permite marcarlo DESPUÉS de publicado, por si se olvidó tildar al subir. v1424
function _vibeArchStyle(btn, on){
  if(!btn) return;
  btn.setAttribute('data-vibe-archived', on?'1':'0');
  btn.style.background = on ? 'rgba(240,200,92,.20)' : 'rgba(255,255,255,.06)';
  btn.style.borderColor = on ? 'rgba(240,200,92,.60)' : 'rgba(200,230,215,.30)';
  btn.style.color = on ? '#f0c85c' : 'rgba(210,235,220,.88)';
  var lbl = btn.querySelector('[data-vibe-arch-lbl]');
  if(lbl) lbl.textContent = on ? 'Guardado' : 'Guardar';
}
var VIBE_FREE_SAVE_LIMIT = 5; // momentos guardados gratis; Plus = ilimitado
async function pVibeToggleArchive(vibeId, btn){
  _initSupabase();
  var myId = safeLS('get','velo_user_id')||'';
  if(!sbClient || !myId){ pToast('⚠️','Necesitás estar conectado'); return; }
  var wasArch = btn && btn.getAttribute('data-vibe-archived') === '1';
  var next = !wasArch;
  // v1464: guardar en "Mis momentos guardados" es ilimitado con Velo Plus; en el
  // plan gratuito hasta VIBE_FREE_SAVE_LIMIT. Si querés guardar uno más, ofrecemos Plus.
  if(next && !_isPremium()){
    try{
      var cRes = await sbClient.from('vibes').select('id', { count:'exact', head:true }).eq('user_id', myId).eq('archived', true);
      var savedCount = (cRes && typeof cRes.count === 'number') ? cRes.count : 0;
      if(savedCount >= VIBE_FREE_SAVE_LIMIT){
        pToast('🔒','Llegaste al máximo de '+VIBE_FREE_SAVE_LIMIT+' momentos guardados (plan gratuito)');
        try{ setTimeout(pShowPlusModal, 600); }catch(_){}
        return;
      }
    }catch(_){}
  }
  _vibeArchStyle(btn, next); // feedback optimista
  try{
    try{ if(typeof _ensureSbSession === 'function') await _ensureSbSession(); }catch(_){}
    var r = await sbClient.from('vibes').update({ archived: next }).eq('id', vibeId).eq('user_id', myId).select('id').maybeSingle();
    if(r && r.error) throw r.error;
    if(r && r.data){
      if(next) pToast('🔖','Guardado en tu perfil → “Mis momentos guardados”');
      else pToast('✓','Quitado de tu historial');
    } else {
      // 0 filas: sin sesión válida / no es tu momento
      throw new Error('sin permiso o sin sesión');
    }
  }catch(e){
    _vibeArchStyle(btn, wasArch); // revertir
    pToast('⚠️','No se pudo guardar — recargá e intentá de nuevo');
    console.warn('[vibe-archive]', e && (e.message||e));
  }
}
// Menú "⋯" de un momento: borrar (si es mío) o reportar (si es de otro) — v1375
function pVibeCardMenu(vibeId, isMine){
  var ex = document.getElementById('vibeCardMenuOv'); if(ex) ex.remove();
  var ov = document.createElement('div');
  ov.id = 'vibeCardMenuOv';
  ov.className = 'p-modal-ov show';
  // v1376: .p-modal-ov trae z-index:800 por CSS — muy por debajo de los
  // overlays de vibes (#vibeGroupOv/#vibeInstantOv usan 10014, los
  // comentarios 10030). Sin este override el menú se creaba pero quedaba
  // tapado y sin recibir toques hasta cerrar la foto (que sacaba el overlay
  // de encima y "revelaba" este menú).
  ov.style.zIndex = '10040';
  ov.onclick = function(e){ if(e.target===ov) ov.remove(); };
  var opts = isMine
    ? '<button onclick="document.getElementById(\'vibeCardMenuOv\').remove();pDeleteVibe('+_jsAttr(vibeId)+')" style="width:100%;padding:13px;background:none;border:none;border-bottom:1px solid var(--border);color:var(--sos);font-family:Jost,sans-serif;font-size:15px;font-weight:700;cursor:pointer;text-align:left">🗑️ Borrar momento</button>'
    : '<button onclick="document.getElementById(\'vibeCardMenuOv\').remove();pReportVibe('+_jsAttr(vibeId)+')" style="width:100%;padding:13px;background:none;border:none;border-bottom:1px solid var(--border);color:var(--ink3);font-family:Jost,sans-serif;font-size:15px;font-weight:700;cursor:pointer;text-align:left">⚠️ Reportar momento</button>';
  opts += '<button onclick="document.getElementById(\'vibeCardMenuOv\').remove()" style="width:100%;padding:13px;background:none;border:none;color:var(--ink4);font-family:Jost,sans-serif;font-size:14px;cursor:pointer;text-align:left">Cancelar</button>';
  ov.innerHTML = '<div class="p-sheet" style="max-width:420px;margin:auto">'+opts+'</div>';
  document.body.appendChild(ov);
}
function pDeleteVibe(vibeId){
  _pConfirm('¿Borrar este momento? No se puede deshacer.', async function(){
    _initSupabase(); if(!sbClient) return;
    try{
      // Capturar la media_url antes de borrar la fila, para limpiar Storage
      var mediaUrl = '';
      try{ var vRow = await sbClient.from('vibes').select('media_url').eq('id', vibeId).maybeSingle(); if(vRow && vRow.data) mediaUrl = vRow.data.media_url || ''; }catch(_){}
      var r = await sbClient.from('vibes').delete().eq('id', vibeId);
      if(r.error){ pToast('⚠️','Error al borrar'); return; }
      // Best-effort: borrar también el archivo del bucket (fotos y videos).
      // La policy vibes_owner_delete permite borrar solo dentro de mi carpeta.
      try{
        var mIdx = mediaUrl.indexOf('/object/public/vibes/');
        if(mIdx > 0){
          var storPath = decodeURIComponent(mediaUrl.slice(mIdx + '/object/public/vibes/'.length).split('?')[0]);
          if(storPath) sbClient.storage.from('vibes').remove([storPath]).then(function(){}).catch(function(){});
        }
      }catch(_){}
      pToast('🗑️','Momento borrado');
      var card = document.querySelector('.vibe-card[data-vibe-id="'+vibeId+'"]');
      if(card){ card.style.transition='opacity .3s'; card.style.opacity='0'; setTimeout(function(){ card.remove(); }, 320); }
      try{ _renderHomeVibesCard(); }catch(_){}
    }catch(e){ pToast('⚠️','Error al borrar'); }
  });
}
async function pReportVibe(vibeId){
  _initSupabase(); if(!sbClient) return;
  var preview = 'Momento (vibe)';
  try{ var r = await sbClient.from('vibes').select('caption').eq('id',vibeId).maybeSingle(); if(r && r.data && r.data.caption) preview = r.data.caption; }catch(_){}
  pReportContent('vibe', vibeId, preview);
}
// Abrir modal de comentarios de una vibe. Carga los últimos y permite escribir uno.
async function pOpenVibeComments(vibeId){
  _initSupabase(); if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  var ov = document.getElementById('vibeCommentsOv'); if(ov) ov.remove();
  ov = document.createElement('div');
  ov.id = 'vibeCommentsOv';
  ov.style.cssText = 'position:fixed;inset:0;z-index:10030;background:rgba(0,0,0,.72);display:flex;align-items:flex-end;justify-content:center';
  ov.onclick = function(e){ if(e.target===ov) ov.remove(); };
  ov.innerHTML = '<div class="p-sheet" style="max-width:560px;width:100%;padding:18px 18px calc(20px + env(safe-area-inset-bottom,0px));background:linear-gradient(180deg,rgba(20,40,26,.98),rgba(10,26,18,.99));border:1.5px solid rgba(116,198,157,.35);border-radius:22px 22px 0 0;max-height:88vh;display:flex;flex-direction:column">'
    + '<div class="p-sheet-handle" style="background:rgba(180,220,195,.35)"></div>'
    + '<div style="text-align:center;padding:4px 0 8px">'
      + '<div style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:#fff;font-style:italic">💬 Comentarios</div>'
    + '</div>'
    + '<div style="background:linear-gradient(135deg,rgba(255,180,80,.14),rgba(220,140,60,.10));border:1.5px solid rgba(255,180,80,.32);border-radius:12px;padding:10px 12px;margin-bottom:12px;font-family:Jost,sans-serif;font-size:11.5px;color:rgba(255,220,170,.90);line-height:1.5">🌿 <strong>La consigna:</strong> mensajes de apoyo, agradecimiento o afecto. Si vas a dejar otro tipo de mensaje, mejor no comentar.</div>'
    + '<div id="vibeCommentsList" style="flex:1;overflow-y:auto;margin-bottom:12px;min-height:80px">Cargando…</div>'
    + '<textarea id="vibeCommentInput" placeholder="Un mensaje de apoyo, agradecimiento o afecto…" rows="2" maxlength="500" style="width:100%;padding:11px 12px;background:rgba(0,0,0,.32);border:1.5px solid rgba(116,198,157,.28);border-radius:12px;color:#fff;font-family:Jost,sans-serif;font-size:14px;resize:vertical;box-sizing:border-box;outline:none;line-height:1.4;margin-bottom:8px"></textarea>'
    + '<div style="display:flex;gap:8px">'
      + '<button onclick="document.getElementById(\'vibeCommentsOv\').remove()" style="flex:1;padding:11px;background:rgba(0,0,0,.28);border:1.5px solid rgba(180,220,195,.20);border-radius:12px;color:rgba(200,230,215,.68);font-family:Jost,sans-serif;font-size:13.5px;font-weight:700;cursor:pointer">Cerrar</button>'
      + '<button onclick="pSendVibeComment(\''+vibeId+'\')" style="flex:2;padding:11px;background:linear-gradient(135deg,rgba(116,198,157,.92),rgba(74,160,110,.98));border:none;border-radius:12px;color:#071409;font-family:Jost,sans-serif;font-size:13.5px;font-weight:800;cursor:pointer">💬 Enviar</button>'
    + '</div>'
  + '</div>';
  document.body.appendChild(ov);
  // Cargar comentarios existentes
  try{
    var res = await sbClient.from('vibe_comments').select('id,user_id,user_name,user_av,text,created_at').eq('vibe_id', vibeId).order('created_at',{ascending:false}).limit(60);
    var listEl = document.getElementById('vibeCommentsList');
    if(!listEl) return;
    var data = (res && res.data) || [];
    var myId = safeLS('get','velo_user_id')||'';
    // Corazones por comentario (batch) — quién y cuántos
    var heartCounts = {}, myHearts = {};
    if(data.length){
      try{
        var cIds = data.map(function(c){ return c.id; });
        var hRes = await sbClient.from('vibe_comment_reactions').select('comment_id,user_id').in('comment_id', cIds);
        (hRes.data||[]).forEach(function(h){
          heartCounts[h.comment_id] = (heartCounts[h.comment_id]||0)+1;
          if(h.user_id === myId) myHearts[h.comment_id] = true;
        });
      }catch(_){}
    }
    if(!data.length){
      listEl.innerHTML = '<div style="text-align:center;padding:20px;color:rgba(200,230,215,.55);font-family:Jost,sans-serif;font-size:12.5px;font-style:italic">Sin comentarios · sé el primero en dejar un mensaje 🌱</div>';
    } else {
      listEl.innerHTML = data.map(function(c){
        var when = c.created_at ? _timeAgoDM(new Date(c.created_at).getTime()) : '';
        var isMine = !!(myId && c.user_id === myId);
        var hCount = heartCounts[c.id] || 0;
        var hMine = !!myHearts[c.id];
        var actionBtn = isMine
          ? '<button onclick="pDeleteVibeComment('+_jsAttr(c.id)+','+_jsAttr(vibeId)+')" style="background:none;border:none;color:rgba(255,140,140,.65);font-size:11px;font-family:Jost,sans-serif;cursor:pointer;padding:2px 4px">🗑️ Borrar</button>'
          : '<button onclick="pReportVibeComment('+_jsAttr(c.id)+','+_jsAttr(c.text||'')+')" style="background:none;border:none;color:rgba(200,230,215,.40);font-size:11px;font-family:Jost,sans-serif;cursor:pointer;padding:2px 4px">⚠️ Reportar</button>';
        return '<div data-comment-id="'+_escHtml(c.id)+'" style="padding:10px 12px;background:rgba(255,255,255,.03);border:1px solid rgba(180,220,195,.14);border-radius:12px;margin-bottom:6px;font-family:Jost,sans-serif">'
          + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">'
            + '<span style="font-size:18px;flex-shrink:0">'+_avInline(c.user_av||'🧑', 22)+'</span>'
            + '<span style="font-size:12.5px;font-weight:800;color:rgba(220,240,225,.95)">'+_escHtml(c.user_name||'Usuario')+'</span>'
            + '<span style="font-size:10px;color:rgba(180,220,195,.55);margin-left:auto">'+when+'</span>'
          + '</div>'
          + '<div style="font-size:13px;color:rgba(230,245,235,.90);line-height:1.5;padding-left:30px;margin-bottom:6px">'+_escHtml(c.text||'')+'</div>'
          + '<div style="display:flex;align-items:center;gap:12px;padding-left:30px">'
            // v1381: estado sin corazón usa ♡ (glifo de texto, toma color CSS)
            // en vez del emoji 🤍 que quedaba blanco-invisible sobre el fondo
            // cream del modo claro (los emojis ignoran la propiedad color).
            + '<button onclick="pToggleVibeCommentHeart('+_jsAttr(c.id)+','+_jsAttr(vibeId)+')" style="background:none;border:none;color:'+(hMine?'#ff6b9d':'rgba(200,230,215,.80)')+';font-size:'+(hMine?'12px':'17px')+';font-family:Jost,sans-serif;cursor:pointer;padding:2px 4px;display:flex;align-items:center;gap:3px;line-height:1">'+(hMine?'❤️':'♡')+(hCount>0?'<span style="font-size:12px">'+hCount+'</span>':'')+'</button>'
            + actionBtn
          + '</div>'
        + '</div>';
      }).join('');
    }
  }catch(e){ console.warn('[vibe-comments load]', e); }
}
async function pSendVibeComment(vibeId){
  _initSupabase(); if(!sbClient) return;
  var inp = document.getElementById('vibeCommentInput');
  var text = (inp && inp.value || '').trim().slice(0, 500);
  if(!text){ pToast('✍️','Escribí algo primero'); return; }
  var myId = safeLS('get','velo_user_id')||'';
  var myName = safeLS('get','velo_user_name')||'Usuario';
  var myAv = safeLS('get','velo_user_av')||'🧑';
  if(!myId){ pToast('⚠️','Iniciá sesión'); return; }
  // Moderación blanda con Gemini (async — no bloquea el envío, pero borra si es tóxico)
  try{ _geminiModerateContent(text, 'vibe-comment'); }catch(_){}
  try{
    var r = await sbClient.from('vibe_comments').insert({
      vibe_id: vibeId, user_id: myId, user_name: myName, user_av: myAv, text: text
    }).select('id,user_id,user_name,user_av,text,created_at').single();
    if(r && r.data){
      inp.value = '';
      pToast('💚','Comentario enviado');
      // Recargar la lista
      pOpenVibeComments(vibeId);
      // Avisarle al dueño del momento (Actividad) — v1375
      try{
        var vOwn = await sbClient.from('vibes').select('user_id').eq('id', vibeId).maybeSingle();
        if(vOwn && vOwn.data && vOwn.data.user_id){
          _createVeloNotif(vOwn.data.user_id, 'vibe_comment', myName+' comentó tu momento', text.slice(0,80), vibeId);
        }
      }catch(_){}
    } else {
      pToast('⚠️','No se pudo enviar');
    }
  }catch(e){ console.warn('[vibe-comment insert]', e); pToast('⚠️','Error al enviar'); }
}
