async function pToggleVibeCommentHeart(commentId, vibeId){
  _initSupabase(); if(!sbClient) return;
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId){ pToast('⚠️','Iniciá sesión'); return; }
  try{
    var ex = await sbClient.from('vibe_comment_reactions').select('id').eq('comment_id',commentId).eq('user_id',myId).maybeSingle();
    // v1377: antes ignoraba .error de cada llamada — si faltaba la tabla
    // (SQL no corrido) o la RLS rechazaba el insert, el corazón "no hacía
    // nada" sin ningún aviso (reportado como "no deja marcar y no es
    // predecible"). Ahora se revisa cada error y se avisa.
    // v1392: si la tabla/query falla, degradar en silencio (un corazón que no
    // guarda no debe naggear al usuario con un error técnico) — solo console.warn.
    if(ex && ex.error){ console.warn('[vibe-heart] select error:', ex.error.message); return; }
    if(ex && ex.data){
      var delRes = await sbClient.from('vibe_comment_reactions').delete().eq('id', ex.data.id);
      if(delRes.error){ console.warn('[vibe-heart] delete error:', delRes.error.message); return; }
    } else {
      var insRes = await sbClient.from('vibe_comment_reactions').insert({ comment_id: commentId, user_id: myId });
      if(insRes.error){ console.warn('[vibe-heart] insert error:', insRes.error.message); return; }
      // v1381: avisarle al autor del comentario (Actividad) — "le gustó tu comentario"
      try{
        var cRow = await sbClient.from('vibe_comments').select('user_id,text').eq('id', commentId).maybeSingle();
        if(cRow && cRow.data && cRow.data.user_id){
          var myName = safeLS('get','velo_user_name')||'Alguien';
          _createVeloNotif(cRow.data.user_id, 'vibe_comment_like', 'A '+myName+' le gustó tu comentario', (cRow.data.text||'').slice(0,80), vibeId);
        }
      }catch(_){}
    }
    pOpenVibeComments(vibeId);
  }catch(e){ pToast('⚠️','Error'); }
}
// ✨ Animación de burst de emojis al reaccionar — 20 emojis del mismo tipo
// flotan desde el fondo hacia arriba con drift y rotación, se auto-destruyen.
function _vibeReactBurst(emoji){
  try{
    // Contenedor lo pinta por 2.6 seg y desaparece
    var wrap = document.createElement('div');
    wrap.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:10030;overflow:hidden';
    var count = 22;
    for(var i=0;i<count;i++){
      var el = document.createElement('div');
      var startX = 5 + Math.random()*90;              // 5-95vw
      var endX = startX + (Math.random()*40 - 20);    // drift ±20vw
      var size = 24 + Math.random()*32;               // 24-56 px
      var dur = 1.6 + Math.random()*1.0;              // 1.6-2.6 s
      var delay = Math.random()*0.35;                 // stagger 0-350ms
      var rotate = (Math.random()*720 - 360)|0;       // rotation
      el.textContent = emoji;
      el.style.cssText =
        'position:absolute;left:'+startX+'vw;bottom:-60px;font-size:'+size+'px;'+
        'transform:translateX(0) translateY(0) rotate(0deg);opacity:0;'+
        'will-change:transform,opacity;filter:drop-shadow(0 3px 8px rgba(0,0,0,.35))';
      wrap.appendChild(el);
      // Trigger animation on next frame
      (function(node, ex, sx, r, d, delayMs){
        setTimeout(function(){
          node.style.transition = 'transform '+d+'s cubic-bezier(.2,.7,.4,1), opacity '+d+'s ease-out';
          node.style.transform = 'translateX('+((ex-sx))+'vw) translateY(-110vh) rotate('+r+'deg)';
          node.style.opacity = '1';
          // Fade out en la segunda mitad
          setTimeout(function(){ node.style.opacity = '0'; }, d*700);
        }, delayMs);
      })(el, endX, startX, rotate, dur, delay*1000);
    }
    document.body.appendChild(wrap);
    setTimeout(function(){ try{ wrap.remove(); }catch(_){} }, 3200);
  }catch(_){}
}

// Abre un momento guardado en overlay full-screen (individual)
async function _openSavedVibe(vibeId){
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  if(!vibeId){ pToast('⚠️','ID de momento inválido'); return; }
  console.log('[saved-vibe] opening', vibeId);
  var v = null;
  try{
    var res = await sbClient.from('vibes').select('*').eq('id', vibeId).limit(1);
    if(res && res.data && res.data[0]) v = res.data[0];
    else if(res && res.error) console.warn('[saved-vibe query]', res.error.message);
  }catch(e){ console.warn('[saved-vibe fetch]', e && e.message); }
  if(!v){ pToast('⚠️','No se pudo cargar el momento'); return; }
  // Cargar reacciones para este vibe
  _vibeReactionAgg = _vibeReactionAgg || {};
  try{
    var rRes = await sbClient.from('vibe_reactions').select('user_id,reaction').eq('vibe_id', vibeId);
    _vibeReactionAgg[vibeId] = {};
    (rRes.data||[]).forEach(function(r){
      _vibeReactionAgg[vibeId][r.reaction] = (_vibeReactionAgg[vibeId][r.reaction]||0)+1;
      var myId = safeLS('get','velo_user_id')||'';
      if(myId && r.user_id === myId) _vibeMyReactions[vibeId] = r.reaction;
    });
  }catch(_){}
  var ov = document.getElementById('savedVibeOv'); if(ov) ov.remove();
  ov = document.createElement('div');
  ov.id = 'savedVibeOv';
  ov.style.cssText = 'position:fixed;inset:0;z-index:10018;background:linear-gradient(180deg,#0a1810,#050f08);display:flex;flex-direction:column;overflow:hidden;color:#fff';
  var header = '<div style="display:flex;align-items:center;gap:12px;padding:calc(14px + env(safe-area-inset-top,0px)) 16px 14px;background:rgba(4,10,7,.94);border-bottom:1px solid rgba(255,215,80,.20);flex-shrink:0"><button onclick="document.getElementById(\'savedVibeOv\').remove()" style="background:rgba(255,255,255,.10);border:1.5px solid rgba(255,255,255,.20);color:#fff;border-radius:10px;padding:6px 12px;font-size:16px;cursor:pointer;font-weight:800">←</button><div style="flex:1;min-width:0"><div style="font-family:\'Cormorant Garamond\',serif;font-size:19px;font-style:italic;color:rgba(255,240,180,.98)">🌟 Momento guardado</div><div style="font-size:11px;color:rgba(230,210,140,.65);margin-top:2px;font-family:Jost,sans-serif">De mi historial personal</div></div></div>';
  ov.innerHTML = header + '<div id="savedVibeBody" style="flex:1;overflow-y:auto;padding:14px 16px 30px"></div>';
  document.body.appendChild(ov);
  var container = document.getElementById('savedVibeBody');
  if(container){
    container.innerHTML = _vibeCardHtml(v);
    _vibeFillUsernames(container);
    _hydrateVibeImgs(container); // v1502: hidratación centralizada con miniaturas
  }
}

