var _dmEmojiList = ['😂','❤️','🙏','💪','✨','🌿','🤗','😢','😔','💙','🌸','🍃','🌈','🕊️','💚','🫂'];
function pToggleDMEmojis(){
  var panel = document.getElementById('dmEmojiPanel');
  if(!panel) return;
  // Populate lazily on first open
  if(!panel.hasChildNodes()){
    _dmEmojiList.forEach(function(em){
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = em;
      btn.style.cssText = 'font-size:22px;background:none;border:none;cursor:pointer;padding:4px';
      btn.onclick = function(){
        var inp = document.getElementById('dmInput');
        if(!inp) return;
        var pos = inp.selectionStart != null ? inp.selectionStart : inp.value.length;
        inp.value = inp.value.slice(0, pos) + em + inp.value.slice(pos);
        inp.selectionStart = inp.selectionEnd = pos + em.length;
        inp.dispatchEvent(new Event('input', {bubbles:true}));
        inp.focus();
      };
      panel.appendChild(btn);
    });
  }
  var hidden = !panel.style.display || panel.style.display === 'none';
  panel.style.display = hidden ? 'flex' : 'none';
}

function pClearDMChat(){
  if(!_dmPeer) return;
  _pConfirm('¿Borrar toda la conversación con '+_dmPeer.name+'? Esta acción es permanente.', function(){
    var myId = safeLS('get','velo_user_id')||'';
    var el = document.getElementById('dmMessages');
    if(el) el.innerHTML = '<div style="text-align:center;padding:30px 0;color:var(--ink5);font-size:15px">Conversación eliminada</div>';
    _initSupabase();
    if(sbClient && myId && _dmPeer){
      sbClient.from('direct_messages').delete()
        .or('and(from_id.eq.'+myId+',to_id.eq.'+_dmPeer.id+'),and(from_id.eq.'+_dmPeer.id+',to_id.eq.'+myId+')')
        .then(function(){}).catch(function(){});
    }
    safeLS('del','velo_dm_req_sent_'+_dmPeer.id);
    safeLS('del','velo_dm_accepted_'+_dmPeer.id);
    pToast('🗑️','Conversación eliminada');
  });
}

