var _dmPeer = null; // { id, name, av }
var _dmPendingToId = null; // userId of pending outgoing request (waiting for acceptance)

function _showDMSenderWaiting(toId, toName){
  var existing = document.getElementById('dmWaitOv');
  if(existing) existing.remove();
  _dmPendingToId = toId;
  var ov = document.createElement('div');
  ov.id = 'dmWaitOv';
  ov.style.cssText = 'position:fixed;inset:0;z-index:9100;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.55);backdrop-filter:blur(4px)';
  ov.innerHTML = '<div style="background:var(--cream);border-radius:20px;padding:28px 24px;max-width:320px;width:90%;text-align:center;box-shadow:0 16px 48px rgba(0,0,0,.3)">'
    +'<div style="font-size:36px;margin-bottom:12px">💬</div>'
    +'<div style="font-size:16px;font-weight:700;color:var(--ink);margin-bottom:8px">Solicitud enviada</div>'
    +'<div style="font-size:15px;color:var(--ink4);line-height:1.5;margin-bottom:20px">Esperando que <strong>'+_escHtml(toName)+'</strong> acepte tu invitación a chatear…</div>'
    +'<button onclick="_cancelDMRequest(\''+toId+'\')" style="width:100%;padding:12px;background:rgba(255,80,80,.1);border:1.5px solid rgba(255,80,80,.3);border-radius:12px;color:rgba(220,60,60,.85);font-size:15px;font-weight:700;cursor:pointer;font-family:\'Jost\',sans-serif">Cancelar solicitud</button>'
    +'</div>';
  document.body.appendChild(ov);
}

function _cancelDMRequest(toId){
  var myId = safeLS('get','velo_user_id')||'';
  _initSupabase();
  if(myId && sbClient){
    sbClient.from('direct_messages').delete()
      .eq('from_id', myId).eq('to_id', toId).eq('text','__velo_chat_req__')
      .then(function(){}).catch(function(){});
  }
  var ov = document.getElementById('dmWaitOv');
  if(ov) ov.remove();
  _dmPendingToId = null;
}

function _dmOpenPeerProfile(){
  if(_dmPeer) pQuickProfile(_dmPeer.name, _dmPeer.av, '', '', _dmPeer.id);
}

// Internal: enter DM chat without busy-check (used when accepting a request)
function _enterDMChat(toId, toName, toAv){
  _prevChatStatus = _presenceStatus();
  _inActiveChat = true;
  _updateGuardianPresence('ocupado');
  _dmPeer = { id:toId, name:toName||'Usuario', av:toAv||'🧑' };
  // v1602 (PRIVACIDAD): descartar cualquier adjunto pendiente del chat ANTERIOR.
  // _dmPendingImage/_dmRecordedBlob son globales por tipo de chat, no por peer, y
  // ni pLeaveDM ni esta función los limpiaban: una foto adjuntada para A (y no
  // enviada) quedaba en el compositor y se enviaba a B al abrir su chat.
  try{
    if(_dmRec && _dmRec.state !== 'inactive'){ try{ _dmRec.stop(); }catch(_){} }
    if(_dmRecStream){ try{ _dmRecStream.getTracks().forEach(function(t){ t.stop(); }); }catch(_){} _dmRecStream = null; }
    if(_dmRecTimerHandle){ clearTimeout(_dmRecTimerHandle); _dmRecTimerHandle = null; }
    _dmPendingImage = null;
    _dmRecordedBlob = null;
    var _pv = document.getElementById('dmVoicePreview'); if(_pv) _pv.remove();
    var _pi = document.getElementById('dmImgPreview');   if(_pi) _pi.remove();
    try{ _dmSetMicBtnState(false); }catch(_){}
  }catch(_){}
  _dmLastMsgId    = null;
  _dmReactHash    = '';
  _dmSessionStart = new Date().toISOString(); // only show messages from this session onward
  var unread = {}; try{ unread = JSON.parse(safeLS('get','velo_dm_unread')||'{}'); }catch(e){}
  delete unread[toId];
  safeLS('set','velo_dm_unread', JSON.stringify(unread));
  // v1391: marca local "leí hasta ahora" para ESTE peer. _dmBackfillUnread la
  // respeta: aunque el UPDATE read=true de la base no se haya persistido
  // (sesión expirada, race), el badge no vuelve a aparecer porque el usuario
  // YA abrió el chat. Antes el backfill recontaba read=false y revivía el "1".
  try{
    var _ru = JSON.parse(safeLS('get','velo_dm_read_until')||'{}');
    _ru[toId] = Date.now();
    safeLS('set','velo_dm_read_until', JSON.stringify(_ru));
  }catch(_){}
  _updateFavBadge();
  try{ _refreshChatBadges(); }catch(_){}
  // Clean up stale state from any previous session
  var oldBanner = document.getElementById('dmExitBanner');
  if(oldBanner) oldBanner.remove();
  var inp = document.getElementById('dmInput');
  if(inp){
    inp.disabled = false;
    inp.placeholder = 'Escribí algo con amor...';
    inp.value = '';
    var inputRow = inp.closest('.feed-input-area') || inp.closest('.feed-input-row');
    if(inputRow) inputRow.style.display = '';
  }
  var msgEl = document.getElementById('dmMessages');
  if(msgEl) msgEl.innerHTML = '';
  var hdr = document.getElementById('dmPeerName');
  if(hdr) hdr.textContent = toName||'Usuario';
  var hdrAv = document.getElementById('dmPeerAv');
  if(hdrAv) hdrAv.innerHTML = _avInline(toAv||'🧑',36);
  var _dmUnEl = document.getElementById('dmPeerUsername');
  if(_dmUnEl){
    var _dmCached = _uLook(toId);
    if(_dmCached){ _dmUnEl.textContent = '@'+_dmCached; }
    else {
      _dmUnEl.textContent = 'Mensaje directo · privado';
      if(sbClient && toId){
        sbClient.from('profiles').select('username').eq('id',toId).limit(1)
          .then(function(r){
            if(r.data && r.data[0] && r.data[0].username){
              _uFill(toId, r.data[0].username);
              var el2 = document.getElementById('dmPeerUsername');
              if(el2) el2.textContent = '@'+r.data[0].username;
            }
          }).catch(function(){});
      }
    }
  }
  pGoTo('dm-chat');
  setTimeout(function(){
    _renderDMThread();
    _subscribeToDMThread();
    _dmMarkAsRead(toId);
    _dmSetupTypingSend();
    _dmSubscribeToTyping(toId);
    _dmSubscribeToReadReceipts(toId);
  }, 100);
  // Header con presencia
  _startDMPresenceRefresh();
}
// ── Read receipts genéricos — usados por DM, Guardián chat y Sala de Ayuda.
// Los 3 chats usan la misma tabla `direct_messages`, así que la lógica es
// idéntica; solo cambia el container DOM donde va el "✓✓ Visto" y el peerId.
var _chatReadChannels = {}; // { containerId → channel }
async function _chatShowVistoIndicator(peerId, containerId){
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId || !peerId || !sbClient) return;
  var el = document.getElementById(containerId);
  if(!el) return;
  try{
    var res = await sbClient.from('direct_messages')
      .select('id,read,read_at,created_at')
      .eq('from_id', myId).eq('to_id', peerId).eq('read', true)
      .order('created_at',{ascending:false}).limit(1);
    // v1403: si read_at no existe como columna, reintentar sin ella
    if(res && res.error){
      res = await sbClient.from('direct_messages')
        .select('id,read,created_at')
        .eq('from_id', myId).eq('to_id', peerId).eq('read', true)
        .order('created_at',{ascending:false}).limit(1);
    }
    if(!res || !res.data || !res.data[0]) return;
    var lastReadId = 'direct_messages:'+res.data[0].id;
    var readAt = res.data[0].read_at ? new Date(res.data[0].read_at) : null;
    el.querySelectorAll('.dm-read-indicator').forEach(function(x){ x.remove(); });
    var bubble = el.querySelector('[data-sb-id="'+lastReadId+'"]');
    if(!bubble) return;
    var ind = document.createElement('div');
    ind.className = 'dm-read-indicator';
    ind.style.cssText = 'text-align:right;font-family:Jost,sans-serif;font-size:10.5px;font-weight:700;color:rgba(116,198,157,.85);margin:2px 6px 6px;letter-spacing:.3px';
    ind.innerHTML = '✓✓ Visto'+(readAt?' · '+String(readAt.getHours()).padStart(2,'0')+':'+String(readAt.getMinutes()).padStart(2,'0'):'');
    bubble.appendChild(ind);
  }catch(e){}
}
// v1403: BUG RAÍZ de "sigue apareciendo como no leído" + "no aparece el Visto":
// direct_messages NO tiene columna read_at en la DB — el UPDATE con
// {read, read_at} fallaba en silencio SIEMPRE, así que ningún mensaje quedaba
// marcado como leído en la base (el badge revivía en cada reinstalación y el
// ✓✓ Visto jamás se mostraba). Este helper intenta con read_at y, si la
// columna falta, reintenta solo con {read:true} — que es lo que importa.
function _dmMarkReadInDB(myId, peerId){
  return sbClient.from('direct_messages')
    .update({ read: true, read_at: new Date().toISOString() })
    .eq('to_id', myId).eq('from_id', peerId).eq('read', false)
    .then(function(r){
      if(r && r.error){
        console.warn('[dm mark-read] retry sin read_at:', r.error.message);
        return sbClient.from('direct_messages')
          .update({ read: true })
          .eq('to_id', myId).eq('from_id', peerId).eq('read', false);
      }
      return r;
    });
}
function _chatSetupReadReceipts(peerId, containerId){
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId || !peerId || !sbClient) return;
  // 1) Marcar todos los mensajes del peer como leídos
  _dmMarkReadInDB(myId, peerId).then(function(){}).catch(function(){});
  // 2) Suscribirse a UPDATE de mis mensajes salientes → actualiza "✓✓ Visto"
  if(_chatReadChannels[containerId]){
    try{ sbClient.removeChannel(_chatReadChannels[containerId]); }catch(e){}
    delete _chatReadChannels[containerId];
  }
  var ch = sbClient.channel('velo:read:'+myId+':'+peerId+':'+containerId)
    .on('postgres_changes', { event:'UPDATE', schema:'public', table:'direct_messages' }, function(payload){
      var m = payload.new || {};
      if(m.from_id !== myId || m.to_id !== peerId) return;
      if(m.read){ _chatShowVistoIndicator(peerId, containerId); }
    })
    .subscribe();
  _chatReadChannels[containerId] = ch;
  // 3) Render inmediato si ya había mensajes leídos
  setTimeout(function(){ _chatShowVistoIndicator(peerId, containerId); }, 400);
}
function _chatTeardownReadReceipts(containerId){
  if(_chatReadChannels[containerId] && sbClient){
    try{ sbClient.removeChannel(_chatReadChannels[containerId]); }catch(e){}
    delete _chatReadChannels[containerId];
  }
}

// ── Read receipts: marca los DMs recibidos como leídos ────────────
async function _dmMarkAsRead(peerId){
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId || !peerId || !sbClient) return;
  try{
    await _dmMarkReadInDB(myId, peerId); // v1403: con retry sin read_at
  }catch(e){}
}
// Suscripción a UPDATE en mis mensajes salientes — cuando el peer los lee,
// aparece "Visto HH:MM" abajo del último bubble mío
var _dmReadCh = null;
var _dmReadPollTmr = null;
function _dmSubscribeToReadReceipts(peerId){
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId || !peerId || !sbClient) return;
  if(_dmReadCh){ try{ sbClient.removeChannel(_dmReadCh); }catch(e){} _dmReadCh = null; }
  _dmReadCh = sbClient.channel('velo:dm:read:'+myId+':'+peerId)
    .on('postgres_changes', { event:'UPDATE', schema:'public', table:'direct_messages' }, function(payload){
      var m = payload.new || {};
      if(m.from_id !== myId || m.to_id !== peerId) return;
      if(m.read){ _dmUpdateReadIndicators(); }
    })
    .subscribe();
  // v1389: chequeo inicial (si el peer ya había leído antes de abrir el chat)
  // + poll liviano cada 6s — así el "Visto" funciona aunque la replicación de
  // UPDATE de direct_messages no esté habilitada en Realtime (solo INSERT).
  setTimeout(_dmUpdateReadIndicators, 500);
  if(_dmReadPollTmr) clearInterval(_dmReadPollTmr);
  _dmReadPollTmr = setInterval(function(){
    var cur = document.querySelector('.p-page.active');
    if(!cur || cur.id !== 'pg-dm-chat' || !_dmPeer){ clearInterval(_dmReadPollTmr); _dmReadPollTmr = null; return; }
    _dmUpdateReadIndicators();
  }, 6000);
}
// Recorre las bubbles mías y marca la última leída con "Visto"
async function _dmUpdateReadIndicators(){
  if(!_dmPeer) return;
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId || !sbClient) return;
  try{
    var res = await sbClient.from('direct_messages')
      .select('id,read,read_at,created_at')
      .eq('from_id', myId).eq('to_id', _dmPeer.id).eq('read', true)
      .order('created_at',{ascending:false}).limit(1);
    // v1403: si read_at no existe como columna, reintentar sin ella
    if(res && res.error){
      res = await sbClient.from('direct_messages')
        .select('id,read,created_at')
        .eq('from_id', myId).eq('to_id', _dmPeer.id).eq('read', true)
        .order('created_at',{ascending:false}).limit(1);
    }
    if(!res || !res.data || !res.data[0]) return;
    var lastReadId = 'direct_messages:'+res.data[0].id;
    var readAt = res.data[0].read_at ? new Date(res.data[0].read_at) : null;
    // Quitar indicadores anteriores
    document.querySelectorAll('#dmMessages .dm-read-indicator').forEach(function(el){ el.remove(); });
    var bubble = document.querySelector('#dmMessages [data-sb-id="'+lastReadId+'"]');
    if(!bubble) return;
    var ind = document.createElement('div');
    ind.className = 'dm-read-indicator';
    ind.style.cssText = 'text-align:right;font-family:Jost,sans-serif;font-size:10.5px;font-weight:700;color:rgba(116,198,157,.85);margin:2px 6px 6px;letter-spacing:.3px';
    ind.innerHTML = '✓✓ Visto'+(readAt?' · '+String(readAt.getHours()).padStart(2,'0')+':'+String(readAt.getMinutes()).padStart(2,'0'):'');
    bubble.appendChild(ind);
  }catch(e){}
}

// ── Typing indicator ─────────────────────────────────
var _dmTypingSendCh = null, _dmTypingRecvCh = null, _dmTypingThrottle = 0, _dmTypingHideTmr = null;
// v1389: suscribir el canal de ENVÍO de "escribiendo" al entrar al chat, para
// que ya esté listo cuando llegue la primera tecla (antes se creaba recién en
// el primer keystroke y Supabase descartaba ese primer send porque el canal
// no había terminado de suscribirse — el indicador "arrancaba tarde").
function _dmSetupTypingSend(){
  if(!sbClient) return;
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId) return;
  if(_dmTypingSendCh){ try{ sbClient.removeChannel(_dmTypingSendCh); }catch(e){} _dmTypingSendCh = null; }
  _dmTypingSendCh = sbClient.channel('velo:dm:typing:'+myId);
  _dmTypingSendCh.subscribe();
}
function _dmSignalTyping(){
  if(!_dmPeer || !sbClient) return;
  var now = Date.now();
  if(now - _dmTypingThrottle < 2000) return;
  _dmTypingThrottle = now;
  var myId = safeLS('get','velo_user_id')||'';
  if(!myId) return;
  if(!_dmTypingSendCh) _dmSetupTypingSend();
  try{
    _dmTypingSendCh.send({ type:'broadcast', event:'typing', payload:{ from: myId, to: _dmPeer.id, ts: now } });
  }catch(e){}
}
function _dmSubscribeToTyping(peerId){
  if(!sbClient) return;
  if(_dmTypingRecvCh){ try{ sbClient.removeChannel(_dmTypingRecvCh); }catch(e){} _dmTypingRecvCh = null; }
  var myId = safeLS('get','velo_user_id')||'';
  _dmTypingRecvCh = sbClient.channel('velo:dm:typing:'+peerId)
    .on('broadcast', { event:'typing' }, function(msg){
      var p = msg.payload || {};
      if(p.to === myId){ _dmShowTypingBubble(); }
    })
    .subscribe();
}
function _dmShowTypingBubble(){
  var container = document.getElementById('dmMessages');
  if(!container || !_dmPeer) return;
  var ex = document.getElementById('dmTypingBubble');
  if(!ex){
    var bubble = document.createElement('div');
    bubble.id = 'dmTypingBubble';
    bubble.className = 'feed-msg';
    bubble.style.cssText = 'display:flex;gap:8px;padding:6px 8px';
    bubble.innerHTML = '<div class="feed-av" style="flex-shrink:0">'+_avInline(_dmPeer.av||'🧑',30)+'</div>'
      + '<div class="feed-bubble" style="display:inline-flex;align-items:center;gap:5px;padding:10px 14px;background:rgba(100,120,110,.28);border-radius:18px;max-width:min-content">'
      + '<span class="dm-typing-dot"></span><span class="dm-typing-dot"></span><span class="dm-typing-dot"></span>'
      + '</div>';
    container.appendChild(bubble);
    container.scrollTop = container.scrollHeight;
    if(!document.getElementById('_dmTypingKf')){
      var kf = document.createElement('style'); kf.id = '_dmTypingKf';
      kf.textContent = '.dm-typing-dot{width:6px;height:6px;border-radius:50%;background:rgba(180,220,195,.85);display:inline-block;animation:dmTypingBlink 1.2s infinite ease-in-out}.dm-typing-dot:nth-child(2){animation-delay:.15s}.dm-typing-dot:nth-child(3){animation-delay:.3s}@keyframes dmTypingBlink{0%,80%,100%{opacity:.3;transform:scale(.85)}40%{opacity:1;transform:scale(1.1)}}';
      document.head.appendChild(kf);
    }
  }
  if(_dmTypingHideTmr) clearTimeout(_dmTypingHideTmr);
  _dmTypingHideTmr = setTimeout(function(){
    var el = document.getElementById('dmTypingBubble'); if(el) el.remove();
    _dmTypingHideTmr = null;
  }, 3200);
}
function _dmStopTypingChannels(){
  if(_dmTypingSendCh && sbClient){ try{ sbClient.removeChannel(_dmTypingSendCh); }catch(e){} _dmTypingSendCh = null; }
  if(_dmTypingRecvCh && sbClient){ try{ sbClient.removeChannel(_dmTypingRecvCh); }catch(e){} _dmTypingRecvCh = null; }
  if(_dmReadCh && sbClient){ try{ sbClient.removeChannel(_dmReadCh); }catch(e){} _dmReadCh = null; }
  if(_dmReadPollTmr){ clearInterval(_dmReadPollTmr); _dmReadPollTmr = null; }
  if(_dmTypingHideTmr){ clearTimeout(_dmTypingHideTmr); _dmTypingHideTmr = null; }
  var el = document.getElementById('dmTypingBubble'); if(el) el.remove();
}

// ── Presence en header del DM ─────────────────────────────
var _dmPresenceTmr = null;
function _updateDMPeerPresenceHeader(){
  if(!_dmPeer) return;
  var el = document.getElementById('dmPeerPresence');
  if(!el) return;
  var info = _presenceInfo(_dmPeer.id);
  var color = info.on ? info.color : 'rgba(200,220,210,.55)';
  var dot = '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:'+color+(info.on && info.label==='En línea'?';box-shadow:0 0 6px rgba(91,191,135,.75)':'')+';flex-shrink:0"></span>';
  var label;
  if(info.on){
    label = info.label; // "En línea" o "Ocupado/a"
  } else if(info.lastSeen){
    label = 'Últ. vez ' + _lastSeenLabel(info.lastSeen);
  } else {
    label = 'Desconectado';
  }
  el.style.display = 'inline-flex';
  el.style.color = info.on && info.label==='En línea' ? 'rgba(91,191,135,.98)' : 'rgba(200,220,210,.78)';
  el.innerHTML = dot + '<span>'+_escHtml(label)+'</span>';
}
function _startDMPresenceRefresh(){
  if(_dmPresenceTmr){ clearInterval(_dmPresenceTmr); _dmPresenceTmr = null; }
  _refreshPresenceCache().then(_updateDMPeerPresenceHeader);
  _dmPresenceTmr = setInterval(function(){
    if(!_dmPeer){ _stopDMPresenceRefresh(); return; }
    _refreshPresenceCache().then(_updateDMPeerPresenceHeader);
  }, 30000);
}
function _stopDMPresenceRefresh(){
  if(_dmPresenceTmr){ clearInterval(_dmPresenceTmr); _dmPresenceTmr = null; }
  var el = document.getElementById('dmPeerPresence');
  if(el){ el.style.display = 'none'; el.innerHTML = ''; }
}

function pOpenDM(toId, toName, toAv){
  // Estilo Instagram: si la persona ya es MI favorita, entro directo (sin request
  // y sin importar si está online, ocupada u offline). El mensaje queda esperando
  // en direct_messages y le llega cuando abra la app. El chat request queda solo
  // para primer contacto con extraños (quick profile → DM).
  var isMyFav = false;
  try{ isMyFav = pIsFav(toId); }catch(e){}
  if(isMyFav){
    _enterDMChat(toId, toName, toAv);
    return;
  }
  // Block if target user is currently busy in another chat (extraños)
  var tp = _presenceCache[toId];
  if(tp && tp.status === 'ocupado' && tp.last_seen && (Date.now() - new Date(tp.last_seen).getTime()) < 5*60*1000){
    pToast('⏳', (toName||'Este usuario') + ' está ocupado/a en otro chat, intentá más tarde');
    return;
  }
  // Non-fav: chat request (flujo original)
  var myId   = safeLS('get','velo_user_id')||'';
  var myName = safeLS('get','velo_user_name')||'';
  var myAv   = safeLS('get','velo_user_av')||'🧑';
  _initSupabase();
  if(myId && toId && sbClient){
    sbClient.from('direct_messages').insert({
      from_id:myId, from_name:myName, from_av:myAv, to_id:toId, text:'__velo_chat_req__'
    }).then(function(){}).catch(function(){});
  }
  _showDMSenderWaiting(toId, toName||'Usuario');
}

async function _renderDMThread(){
  var el = document.getElementById('dmMessages');
  if(!el || !_dmPeer) return;
  var myId = safeLS('get','velo_user_id')||'';
  _initSupabase();
  if(!sbClient){ el.innerHTML = '<div class="p-empty" style="padding:30px 0">Sin conexión</div>'; return; }
  try{
    var {data} = await sbClient.from('direct_messages')
      .select('*')
      .or('and(from_id.eq.'+myId+',to_id.eq.'+_dmPeer.id+'),and(from_id.eq.'+_dmPeer.id+',to_id.eq.'+myId+')')
      .order('created_at',{ascending:true}).limit(100);
    var sentinels = ['__velo_chat_req__','__velo_accompany_req__','__velo_chat_acc__','__velo_chat_rej__','__velo_chat_busy__'];
    var msgs = (data||[]).filter(function(m){
      var t=m.text||'';
      if(sentinels.indexOf(t)>=0||t.startsWith('__velo_typing__:')||t.startsWith('__velo_guardian_req__:')||t.startsWith('__velo_guardian_acc__:')||t.startsWith('__velo_guardian_rej__:')||t.startsWith('__velo_guardian_bye__:')||t.startsWith('__velo_dm_bye__:')||t.startsWith('__velo_help_bye__:')) return false;
      // v1372: NO filtrar por _dmSessionStart — el DM de favoritos es persistente
      // (estilo Instagram), no una sesión efímera. Filtrar por sesión ocultaba
      // TODO el historial anterior, incluido el mensaje recién recibido que
      // disparó la apertura del chat (bug: "no veo el mensaje que me enviaron").
      return true;
    });
    if(!msgs.length){
      if(!el.querySelector('.dm-empty-state')){
        el.innerHTML = '<div class="dm-empty-state" style="text-align:center;padding:40px 16px 20px">'
          +'<div style="margin-bottom:12px">'+_avInline((_dmPeer&&_dmPeer.av)||'🧑',56)+'</div>'
          +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:18px;color:var(--ink);margin-bottom:8px">'+_escHtml((_dmPeer&&_dmPeer.name)||'Usuario')+'</div>'
          +'<div style="font-size:14px;color:var(--ink5);line-height:1.6">Tu conversación es privada 🔒<br>Solo vos y '+_escHtml(((_dmPeer&&_dmPeer.name)||'esta persona').split(' ')[0])+' pueden leer estos mensajes.</div>'
          +'</div>';
        _dmLastMsgId = null;
      }
      return;
    }
    var lastId = msgs[msgs.length-1].id;
    var reactHash = msgs.map(function(m){ var r=m.reactions; return m.id+(r&&Object.keys(r).length?JSON.stringify(r):''); }).join('');
    // Nothing changed (no new messages AND no reaction updates) — skip re-render
    if(lastId === _dmLastMsgId && reactHash === _dmReactHash) return;
    var onlyReactChanged = (lastId === _dmLastMsgId);
    var wasAtBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    // Incremental append only when new messages arrived (not reaction-only updates)
    if(!onlyReactChanged && _dmLastMsgId){
      var lastIdx = msgs.findIndex(function(m){ return m.id === _dmLastMsgId; });
      if(lastIdx >= 0 && lastIdx < msgs.length - 1){
        var emptyEl = el.querySelector('.dm-empty-state');
        if(emptyEl) emptyEl.remove();
        msgs.slice(lastIdx + 1).forEach(function(m){
          var tmp = document.createElement('div');
          var isOwn = m.from_id === myId;
          tmp.innerHTML = _buildMsgBubble(m.text||'', isOwn, isOwn?'':(m.from_av||'🧑'), isOwn?'':(m.from_name||''), 'dmInput', 'dmReplyBar', '', m.reactions||{}, 'direct_messages:'+m.id, isOwn?'':(m.from_id||''));
          while(tmp.firstChild) el.appendChild(tmp.firstChild);
        });
        _dmLastMsgId = lastId;
        _dmReactHash = reactHash;
        if(wasAtBottom) el.scrollTop = el.scrollHeight;
        return;
      }
    }
    // Full render (first load, reaction update, or incremental path not applicable)
    el.innerHTML = msgs.map(function(m){
      var isOwn = m.from_id === myId;
      return _buildMsgBubble(m.text||'', isOwn, isOwn?'':(m.from_av||'🧑'), isOwn?'':(m.from_name||''), 'dmInput', 'dmReplyBar', '', m.reactions||{}, 'direct_messages:'+m.id, isOwn?'':(m.from_id||''));
    }).join('');
    _dmLastMsgId = lastId;
    _dmReactHash = reactHash;
    if(wasAtBottom) el.scrollTop = el.scrollHeight;
    // Refrescar "Visto" en la última bubble mía leída
    try{ _dmUpdateReadIndicators(); }catch(e){}
  }catch(e){ el.innerHTML = '<div class="p-empty" style="padding:30px 0">Error al cargar mensajes</div>'; }
}

function _subscribeToDMThread(){
  if(_dmRtCh && sbClient){ try{ sbClient.removeChannel(_dmRtCh); }catch(e){} _dmRtCh = null; }
  if(!sbClient || !_dmPeer) return;
  var myId = safeLS('get','velo_user_id')||'';
  var _dmRel = function(m){ return (m.from_id===myId&&m.to_id===_dmPeer.id)||(m.from_id===_dmPeer.id&&m.to_id===myId); };
  _dmRtCh = sbClient.channel('velo:dm:'+myId+':'+_dmPeer.id)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages'},function(payload){
      var m = payload.new||{};
      if(!_dmRel(m)) return;
      if(m.from_id === myId) return; // already rendered optimistically — skip to avoid duplicate
      _renderDMThread();
    })
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'direct_messages'},function(payload){
      var m = payload.new||{};
      if(!_dmRel(m) || !m.id) return;
      // Inline reaction chip update — avoids full re-render and scroll jump
      var bubble = document.querySelector('[data-sb-id="direct_messages:'+m.id+'"]');
      if(!bubble){ _dmReactHash = ''; _renderDMThread(); return; } // fallback: reset hash so render runs
      var oldBar = bubble.querySelector('.msg-rx-bar');
      if(oldBar) oldBar.remove();
      if(m.reactions && typeof m.reactions === 'object'){
        var chips = Object.keys(m.reactions).map(function(e){
          var cnt = m.reactions[e]||1;
          return '<span class="msg-reaction" data-emoji="'+e+'" data-cnt="'+cnt+'" onclick="_msgReact(\''+e+'\',this)">'+e+' '+cnt+'</span>';
        }).join('');
        if(chips){
          var newBar = document.createElement('div');
          newBar.className = 'msg-rx-bar';
          newBar.innerHTML = chips;
          bubble.appendChild(newBar);
        }
      }
      _dmReactHash = ''; // mark hash stale so next poll re-computes
    }).subscribe();
  // Reaction poll fallback — catches cases where Supabase UPDATE events don't arrive
  if(_dmReactPollTmr) clearInterval(_dmReactPollTmr);
  _dmReactPollTmr = setInterval(function(){
    if(!_dmPeer){ clearInterval(_dmReactPollTmr); _dmReactPollTmr = null; return; }
    _dmReactHash = ''; // force reaction re-check
    _renderDMThread();
  }, 8000);
}

function pLeaveDM(){
  var _dmMyName = safeLS('get','velo_user_name') || 'Alguien';
  var _dmMyAv   = safeLS('get','velo_user_av')   || '🧑';
  var _dmMyId   = safeLS('get','velo_user_id') || '';
  _initSupabase();
  // v1382: el DM con un FAVORITO es persistente (estilo Instagram) — "Salir"
  // solo cierra la pantalla. El comportamiento viejo (sentinel bye + DELETE de
  // TODA la conversación para ambos lados) era del flujo efímero con extraños
  // y acá destruía el historial completo con solo tocar Salir.
  var _dmIsFav = false;
  try{ _dmIsFav = !!(_dmPeer && _dmPeer.id && pIsFav(_dmPeer.id)); }catch(_){}
  if(_dmIsFav){
    if(_dmRtCh && sbClient){ try{ sbClient.removeChannel(_dmRtCh); }catch(e){} _dmRtCh = null; }
    if(_dmReactPollTmr){ clearInterval(_dmReactPollTmr); _dmReactPollTmr = null; }
    _stopDMPresenceRefresh();
    _dmStopTypingChannels();
    _dmPeer = null;
    _dmLastMsgId = null;
    _dmReactHash = '';
    _inActiveChat = false;
    _updateGuardianPresence(_prevChatStatus || _presenceStatus());
    _prevChatStatus = null;
    pGoTo('contacts');
    return;
  }
  // Insert bye sentinel, then delete all OTHER messages (exclude bye so recipient receives it)
  if(sbClient && _dmMyId && _dmPeer && _dmPeer.id){
    var _delToId = _dmPeer.id;
    var _delMyId = _dmMyId;
    var _delMyName = _dmMyName;
    var _delMyAv   = _dmMyAv;
    sbClient.from('direct_messages').insert({
      from_id: _delMyId, from_name: _delMyName, from_av: _delMyAv, to_id: _delToId,
      text: '__velo_dm_bye__:'+JSON.stringify({ name:_delMyName, av:_delMyAv })
    }).select('id').then(function(res){
      var byeId = (res && res.data && res.data[0]) ? res.data[0].id : null;
      var q = sbClient.from('direct_messages').delete()
        .or('and(from_id.eq.'+_delMyId+',to_id.eq.'+_delToId+'),and(from_id.eq.'+_delToId+',to_id.eq.'+_delMyId+')');
      if(byeId) q = q.neq('id', byeId);
      q.then(function(){}).catch(function(){});
    }).catch(function(){
      sbClient.from('direct_messages').delete()
        .or('and(from_id.eq.'+_delMyId+',to_id.eq.'+_delToId+'),and(from_id.eq.'+_delToId+',to_id.eq.'+_delMyId+')')
        .then(function(){}).catch(function(){});
    });
  }
  if(_dmRtCh && sbClient){ try{ sbClient.removeChannel(_dmRtCh); }catch(e){} _dmRtCh = null; }
  if(_dmReactPollTmr){ clearInterval(_dmReactPollTmr); _dmReactPollTmr = null; }
  _stopDMPresenceRefresh();
  _dmStopTypingChannels();
  // Clear accepted flag so a new session requires a fresh chat request
  if(_dmPeer && _dmPeer.id) safeLS('del', 'velo_dm_accepted_'+_dmPeer.id);
  _dmPeer = null;
  _dmLastMsgId = null;
  _dmReactHash = '';
  _inActiveChat = false;
  _updateGuardianPresence(_prevChatStatus || _presenceStatus());
  _prevChatStatus = null;
  pGoTo('contacts');
}

// ═══════════════════════════════════════════════════════════════
// AUDIO + FOTO GENÉRICOS para CUALQUIER CHAT (help / guardian / círculo / DM)
// ═══════════════════════════════════════════════════════════════
// Config por chat — key: prefijo canónico | ids de elementos HTML
var CHAT_ATTACH_CONFIGS = {
  dm:     { textareaId:'dmInput',       micBtnId:'dmMicBtn',       imgInputId:'dmImageInput',       voicePrevId:'dmVoicePreview',       recIndId:'dmRecIndicator',       imgPrevId:'dmImgPreview' },
  help:   { textareaId:'helpChatInput', micBtnId:'helpChatMicBtn', imgInputId:'helpChatImageInput', voicePrevId:'helpChatVoicePreview', recIndId:'helpChatRecIndicator', imgPrevId:'helpChatImgPreview' },
  gc:     { textareaId:'gcInput',       micBtnId:'gcMicBtn',       imgInputId:'gcImageInput',       voicePrevId:'gcVoicePreview',       recIndId:'gcRecIndicator',       imgPrevId:'gcImgPreview' },
  circle: { textareaId:'feedInput',     micBtnId:'circleMicBtn',   imgInputId:'circleImageInput',   voicePrevId:'circleVoicePreview',   recIndId:'circleRecIndicator',   imgPrevId:'circleImgPreview' }
};
var _chatAttachStates = {};
function _chatSt(key){ if(!_chatAttachStates[key]) _chatAttachStates[key] = {}; return _chatAttachStates[key]; }
function _chatFindArea(key){
  var cfg = CHAT_ATTACH_CONFIGS[key]; if(!cfg) return null;
  var ta = document.getElementById(cfg.textareaId);
  return ta ? ta.closest('.feed-input-area') : null;
}
function _chatSetMicBtnUI(key, recording){
  var cfg = CHAT_ATTACH_CONFIGS[key]; if(!cfg) return;
  var btn = document.getElementById(cfg.micBtnId);
  if(!btn) return;
  btn.textContent = recording ? '⏹' : '🎙';
  btn.style.background = recording ? 'rgba(220,60,60,.32)' : 'transparent';
  btn.style.color = recording ? '#fff' : '';
  btn.title = recording ? 'Detener grabación' : 'Grabar audio';
}
async function pChatToggleVoiceRec(key){
  var cfg = CHAT_ATTACH_CONFIGS[key]; if(!cfg) return;
  var st = _chatSt(key);
  if(st.rec && st.rec.state !== 'inactive'){ try{ st.rec.stop(); }catch(e){} return; }
  if(!navigator.mediaDevices){ pToast('⚠️','Grabación no soportada'); return; }
  try{
    st.stream = await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
    st.mime = _pickRecorderMime && _pickRecorderMime();
    if(!st.mime){ pToast('⚠️','MediaRecorder no soportado'); try{st.stream.getTracks().forEach(function(t){t.stop();});}catch(e){} st.stream=null; return; }
    st.chunks = [];
    st.rec = new MediaRecorder(st.stream, { mimeType: st.mime });
    st.rec.ondataavailable = function(e){ if(e.data && e.data.size > 0) st.chunks.push(e.data); };
    st.rec.onstop = function(){
      var blob = new Blob(st.chunks, { type: st.mime || 'audio/mp4' });
      try{ st.stream.getTracks().forEach(function(t){ t.stop(); }); }catch(e){}
      st.stream = null;
      _chatSetMicBtnUI(key, false);
      _chatHideRecIndicator(key);
      if(st.timerHandle){ clearTimeout(st.timerHandle); st.timerHandle = null; }
      if(!blob || blob.size < 500){ pToast('⚠️','Grabación muy corta'); st.blob = null; return; }
      if(blob.size > 10 * 1024 * 1024){ pToast('⚠️','Audio muy largo (máx ~1 min)'); st.blob = null; return; }
      st.blob = blob;
      _chatShowVoicePreview(key, blob);
    };
    st.rec.start(); // v1404: sin timeslice — iOS fMP4 fragmentado solo decodificaba ~1er fragmento (audio "cortado")
    st.startTs = Date.now();
    _chatSetMicBtnUI(key, true);
    pToast('🎙️','Grabando… tocá stop cuando termines');
    st.timerHandle = setTimeout(function(){
      if(st.rec && st.rec.state !== 'inactive'){ try{ st.rec.stop(); }catch(e){} pToast('⏱️','Máx 60 s'); }
    }, 60000);
    _chatShowRecIndicator(key);
  }catch(e){
    console.warn('[chat-rec]', e);
    if(e && e.name === 'NotAllowedError') pToast('⚠️','Bloqueaste el micrófono');
    else pToast('⚠️','No pude acceder al micrófono');
    _chatSetMicBtnUI(key, false);
  }
}
function _chatShowVoicePreview(key, blob){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  var area = _chatFindArea(key); if(!area || !area.parentNode) return;
  var ex = document.getElementById(cfg.voicePrevId); if(ex) ex.remove();
  var st = _chatSt(key);
  var sizeKb = Math.round(blob.size/1024);
  var dur = Math.round((Date.now() - (st.startTs||Date.now()))/1000);
  var wrap = document.createElement('div');
  wrap.id = cfg.voicePrevId;
  wrap.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 14px;background:rgba(200,158,56,.14);border-top:1.5px solid rgba(200,158,56,.42);font-family:Jost,sans-serif;font-size:13px;color:var(--ink2);flex-shrink:0';
  wrap.innerHTML = '<span style="font-size:18px">🎙️</span><span style="flex:1;font-weight:700">Audio listo · '+dur+'s · '+sizeKb+' KB</span><button onclick="_chatDeleteVoice(\''+key+'\')" title="Descartar" style="background:rgba(220,60,60,.20);border:1.5px solid rgba(220,60,60,.42);color:#a02020;border-radius:8px;padding:6px 10px;font-size:14px;font-weight:800;cursor:pointer">🗑️</button>';
  area.parentNode.insertBefore(wrap, area);
}
function _chatDeleteVoice(key){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  _chatSt(key).blob = null;
  var ex = document.getElementById(cfg.voicePrevId); if(ex) ex.remove();
}
function _chatShowRecIndicator(key){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  _chatHideRecIndicator(key);
  var area = _chatFindArea(key); if(!area || !area.parentNode) return;
  var st = _chatSt(key);
  var wrap = document.createElement('div');
  wrap.id = cfg.recIndId;
  wrap.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 14px;background:linear-gradient(90deg,rgba(220,60,60,.20),rgba(190,40,40,.15));border-top:1.5px solid rgba(220,60,60,.55);font-family:Jost,sans-serif;font-size:13px;color:#e83a3a;font-weight:800;letter-spacing:.4px;flex-shrink:0';
  wrap.innerHTML = '<span style="width:10px;height:10px;border-radius:50%;background:#e83a3a;box-shadow:0 0 10px rgba(220,60,60,.75);flex-shrink:0;animation:dmRecBlink 1s infinite"></span>'
    + '<span style="text-transform:uppercase">Grabando</span>'
    + '<span class="chat-rec-time" style="margin-left:auto;font-family:Jost,monospace;color:#f0a0a0;font-weight:700">0:00 / 1:00</span>'
    + '<button onclick="_chatCancelRec(\''+key+'\')" title="Cancelar" style="background:rgba(0,0,0,.15);border:1px solid rgba(255,255,255,.20);color:#fff;border-radius:8px;padding:5px 10px;font-size:11.5px;font-weight:800;cursor:pointer;font-family:Jost,sans-serif;flex-shrink:0">Cancelar</button>';
  area.parentNode.insertBefore(wrap, area);
  if(!document.getElementById('_dmRecKf')){
    var kf = document.createElement('style'); kf.id = '_dmRecKf';
    kf.textContent = '@keyframes dmRecBlink{0%,50%{opacity:1}51%,100%{opacity:.35}}';
    document.head.appendChild(kf);
  }
  st.indicatorTmr = setInterval(function(){
    var el = document.getElementById(cfg.recIndId); if(!el) return;
    var timeEl = el.querySelector('.chat-rec-time');
    if(!timeEl || !st.startTs) return;
    var elapsed = Math.floor((Date.now() - st.startTs)/1000);
    var m = Math.floor(elapsed/60), s = elapsed % 60;
    timeEl.textContent = m+':'+String(s).padStart(2,'0')+' / 1:00';
  }, 300);
}
function _chatHideRecIndicator(key){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  var st = _chatSt(key);
  if(st.indicatorTmr){ clearInterval(st.indicatorTmr); st.indicatorTmr = null; }
  var el = document.getElementById(cfg.recIndId); if(el) el.remove();
}
function _chatCancelRec(key){
  var st = _chatSt(key);
  try{
    if(st.rec && st.rec.state !== 'inactive'){
      st.rec.onstop = function(){ try{ st.stream && st.stream.getTracks().forEach(function(t){t.stop();}); }catch(e){} st.stream=null; };
      st.rec.stop();
    } else if(st.stream){ try{ st.stream.getTracks().forEach(function(t){t.stop();}); }catch(e){} st.stream=null; }
  }catch(e){}
  st.blob = null;
  _chatSetMicBtnUI(key, false);
  _chatHideRecIndicator(key);
  if(st.timerHandle){ clearTimeout(st.timerHandle); st.timerHandle = null; }
  pToast('🗑️','Grabación cancelada');
}
function pChatAttachImage(key){
  var cfg = CHAT_ATTACH_CONFIGS[key]; if(!cfg) return;
  var inp = document.getElementById(cfg.imgInputId);
  if(inp){ inp.value = ''; inp.click(); }
}
async function _chatHandleImageInput(key, input){
  if(!input || !input.files || !input.files[0]) return;
  var f = input.files[0];
  if(!f.type.startsWith('image/')){ pToast('⚠️','Solo imágenes'); return; }
  if(/heic|heif/i.test(f.type||'') || /\.(heic|heif)$/i.test(f.name||'')){
    pToast('⚠️','HEIC no soportado — convertí a JPG en Ajustes iOS'); return;
  }
  if(f.size > 12*1024*1024){ pToast('⚠️','Imagen muy grande (>12 MB)'); return; }
  pToast('📷','Procesando imagen…');
  try{
    var b64 = await _resizeImageToBase64(f, 1200);
    _chatSt(key).image = b64;
    _chatShowImagePreview(key, b64);
    pToast('✓','Foto lista');
  }catch(e){ pToast('⚠️', (e && e.message) || 'No pude procesar la imagen'); }
}
function _chatShowImagePreview(key, b64){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  var area = _chatFindArea(key); if(!area || !area.parentNode) return;
  var ex = document.getElementById(cfg.imgPrevId); if(ex) ex.remove();
  var wrap = document.createElement('div');
  wrap.id = cfg.imgPrevId;
  wrap.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 14px;background:rgba(180,155,240,.14);border-top:1.5px solid rgba(180,155,240,.42);font-family:Jost,sans-serif;font-size:13px;color:var(--ink2);flex-shrink:0';
  var thumb = document.createElement('img');
  thumb.style.cssText = 'width:44px;height:44px;object-fit:cover;border-radius:8px;flex-shrink:0';
  try{
    var arr = b64.split(','); var mm = arr[0].match(/:(.*?);/); var mime = mm?mm[1]:'image/jpeg';
    var bstr = atob(arr[1]||''); var u8 = new Uint8Array(bstr.length);
    for(var _i=0;_i<bstr.length;_i++) u8[_i] = bstr.charCodeAt(_i);
    thumb.src = URL.createObjectURL(new Blob([u8],{type:mime}));
  }catch(e){ thumb.src = b64; }
  wrap.appendChild(thumb);
  var lbl = document.createElement('span');
  lbl.style.cssText = 'flex:1;font-weight:700';
  lbl.textContent = 'Foto lista para enviar';
  wrap.appendChild(lbl);
  var btn = document.createElement('button');
  btn.type = 'button';
  btn.onclick = function(){ _chatDeleteImage(key); };
  btn.style.cssText = 'background:rgba(220,60,60,.20);border:1.5px solid rgba(220,60,60,.42);color:#a02020;border-radius:8px;padding:6px 10px;font-size:14px;font-weight:800;cursor:pointer';
  btn.textContent = '🗑️';
  wrap.appendChild(btn);
  area.parentNode.insertBefore(wrap, area);
}
function _chatDeleteImage(key){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  _chatSt(key).image = null;
  var ex = document.getElementById(cfg.imgPrevId); if(ex) ex.remove();
}
// v1404 — Sube el blob de audio a Storage (bucket 'vibes', carpeta del uid) y
// devuelve la URL pública, o null si falla. Meter el audio como base64 en la
// fila del mensaje rompía con audios largos (fila gigante → insert que falla,
// realtime que lo trunca) — con URL el tamaño deja de importar.
async function _chatUploadAudioToStorage(blob){
  try{
    if(!sbClient || !sbClient.storage) return null;
    var uid = safeLS('get','velo_user_id') || 'anon';
    var mime = blob.type || 'audio/mp4';
    var ext = mime.indexOf('webm') >= 0 ? 'webm' : (mime.indexOf('ogg') >= 0 ? 'ogg' : 'mp4');
    var path = uid + '/audio-' + Date.now() + '-' + Math.random().toString(36).slice(2,8) + '.' + ext;
    var up = await sbClient.storage.from('vibes').upload(path, blob, { cacheControl: '86400', upsert: false, contentType: mime });
    if(up && up.error){ console.warn('[chat-audio-upload]', up.error.message); return null; }
    var pub = sbClient.storage.from('vibes').getPublicUrl(path);
    return (pub && pub.data && pub.data.publicUrl) ? pub.data.publicUrl : null;
  }catch(e){ console.warn('[chat-audio-upload]', e && e.message); return null; }
}
// Prepara el payload de un audio: intenta Storage (v=2|url); si falla y el
// audio es chico, cae a base64 embebido (v=1|dataURL); si es grande, null.
async function _chatAudioPayload(blob){
  var url = await _chatUploadAudioToStorage(blob);
  if(url) return '__velo_dm_audio__:v=2|' + url;
  if(blob.size <= 700*1024){
    try{ return '__velo_dm_audio__:v=1|' + (await _blobToBase64(blob)); }catch(_){ return null; }
  }
  return null;
}
// Consume audio/foto pendientes y llama insertFn(text) por cada uno.
// insertFn debe ser async y persistir el mensaje en la tabla correcta.
async function _chatConsumeAttachments(key, insertFn){
  var cfg = CHAT_ATTACH_CONFIGS[key];
  var st = _chatSt(key);
  if(st.blob){
    try{
      var payload = await _chatAudioPayload(st.blob);
      if(payload) await insertFn(payload);
      else pToast('⚠️','No pude subir el audio — probá de nuevo');
    }catch(e){ console.warn('[chat-audio]', e && e.message); pToast('⚠️','No pude enviar el audio'); }
    st.blob = null;
    var vp = document.getElementById(cfg.voicePrevId); if(vp) vp.remove();
  }
  if(st.image){
    try{
      await insertFn('__velo_dm_image__:v=1|' + st.image);
    }catch(e){ pToast('⚠️','No pude enviar la foto'); }
    st.image = null;
    var ip = document.getElementById(cfg.imgPrevId); if(ip) ip.remove();
  }
}

// ── DM audio/foto attachments (estilo IG) ──────────────────
var _dmRec = null, _dmRecStream = null, _dmRecChunks = [], _dmRecMime = '';
var _dmRecordedBlob = null, _dmPendingImage = null, _dmRecTimerHandle = null, _dmRecStartTs = 0;
var _dmAttachAudioState = {}; // key → { ctx, buffer, source, playing, offset, startedAt, duration, btn, statusEl }

// Player para audios embebidos en bubbles (usa WebAudio decodeAudioData —
// resuelve el fMP4 de iOS Safari MediaRecorder que <audio> no puede reproducir).
async function _dmPlayAttachAudio(btn){
  var wrap = btn.closest('.dm-attach--audio');
  if(!wrap) return;
  var key = wrap.getAttribute('data-attach-ts') || 'k'+Date.now();
  var statusEl = wrap.querySelector('.dm-attach-status');
  var dataUrl = wrap.getAttribute('data-attach-audio');
  if(!dataUrl) return;
  // Toggle si ya está en curso
  var st = _dmAttachAudioState[key];
  if(st && st.playing){
    try{ if(st.source) st.source.stop(0); }catch(e){}
    st.playing = false;
    btn.textContent = '▶';
    if(statusEl) statusEl.textContent = 'Pausado';
    return;
  }
  // Parar cualquier otro audio
  Object.keys(_dmAttachAudioState).forEach(function(k){
    var s = _dmAttachAudioState[k];
    if(s && s.playing){ try{ s.source.stop(0); }catch(e){} s.playing = false; if(s.btn) s.btn.textContent='▶'; }
  });
  try{
    var AC = window.AudioContext || window.webkitAudioContext;
    if(!AC){ pToast('⚠️','Tu navegador no soporta reproducir audio'); return; }
    if(!st || !st.buffer){
      if(!st){ st = { playing:false, offset:0, btn:btn, statusEl:statusEl }; _dmAttachAudioState[key] = st; }
      st.ctx = new AC();
      if(statusEl) statusEl.textContent = 'Cargando…';
      // v1404: soporta ambos formatos — v=2 (URL de Storage) y v=1 (data URL)
      var _rawBuf;
      if(dataUrl.indexOf('http') === 0){
        var _resp = await fetch(dataUrl);
        if(!_resp.ok) throw new Error('audio fetch '+_resp.status);
        _rawBuf = await _resp.arrayBuffer();
      } else {
        var arr = dataUrl.split(','); var bstr = atob(arr[1]||'');
        var u8 = new Uint8Array(bstr.length);
        for(var _i=0; _i<bstr.length; _i++) u8[_i] = bstr.charCodeAt(_i);
        _rawBuf = u8.buffer.slice(0);
      }
      st.buffer = await new Promise(function(resolve, reject){
        try{
          var p = st.ctx.decodeAudioData(_rawBuf, resolve, reject);
          if(p && typeof p.then === 'function') p.then(resolve, reject);
        }catch(err){ reject(err); }
      });
      st.duration = st.buffer.duration;
    }
    if(st.ctx.state === 'suspended') try{ await st.ctx.resume(); }catch(e){}
    var src = st.ctx.createBufferSource();
    src.buffer = st.buffer;
    src.connect(st.ctx.destination);
    src.start(0, st.offset || 0);
    st.source = src;
    st.playing = true;
    st.startedAt = st.ctx.currentTime - (st.offset || 0);
    btn.textContent = '⏸';
    var mm = Math.floor(st.duration/60), ss = Math.floor(st.duration%60);
    var tick = function(){
      if(!st.playing) return;
      var elapsed = st.ctx.currentTime - st.startedAt;
      if(elapsed >= st.duration){ st.playing = false; btn.textContent='▶'; st.offset = 0; if(statusEl) statusEl.textContent = mm+':'+String(ss).padStart(2,'0')+' / '+mm+':'+String(ss).padStart(2,'0'); return; }
      var em = Math.floor(elapsed/60), es = Math.floor(elapsed%60);
      if(statusEl) statusEl.textContent = em+':'+String(es).padStart(2,'0')+' / '+mm+':'+String(ss).padStart(2,'0');
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
    src.onended = function(){ if(st.playing){ st.playing=false; btn.textContent='▶'; st.offset = 0; } };
  }catch(e){
    console.warn('[dm-audio-play]', e && e.message);
    if(statusEl) statusEl.textContent = 'No se pudo reproducir';
    btn.textContent = '▶';
  }
}

