async function _adminLoadModerationStats(){
  var el = document.getElementById('adminModerationStats');
  if(!el) return;
  _initSupabase();
  if(!sbClient){ el.innerHTML = '<p style="font-size:13px;color:rgba(255,255,255,.3)">Sin conexión</p>'; return; }
  try{
    // Total pendientes
    var pendRes = await sbClient.from('content_reports').select('id',{count:'exact',head:true}).eq('resolved', false);
    var totalPending = pendRes.count || 0;
    // Los 5 usuarios más reportados
    var topRes = await sbClient.from('content_reports')
      .select('response_user_id').eq('resolved', false).not('response_user_id','is',null).limit(500);
    var counts = {};
    (topRes.data||[]).forEach(function(r){
      if(r.response_user_id){ counts[r.response_user_id] = (counts[r.response_user_id]||0) + 1; }
    });
    var top = Object.keys(counts).map(function(uid){ return {uid:uid, n:counts[uid]}; })
      .sort(function(a,b){ return b.n - a.n; }).slice(0,5);
    var pmap = {};
    if(top.length){
      var uids = top.map(function(t){ return t.uid; });
      var pr = await sbClient.from('profiles').select('id,nombre,username').in('id', uids);
      if(pr && pr.data) pr.data.forEach(function(p){ pmap[p.id] = p; });
    }
    var topHtml = top.length
      ? top.map(function(t){
          var p = pmap[t.uid] || {};
          var nm = p.nombre || (t.uid.slice(0,10)+'…');
          var un = p.username ? ' @'+p.username : '';
          return '<div style="display:flex;align-items:center;justify-content:space-between;background:rgba(220,120,120,.05);border:1px solid rgba(220,120,120,.18);border-radius:10px;padding:9px 12px;margin-bottom:5px"><span style="font-size:13px;color:rgba(255,220,220,.88);font-family:Jost,sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><strong>'+_escHtml(nm)+'</strong><span style="opacity:.55">'+_escHtml(un)+'</span></span><span style="font-size:13px;font-weight:800;color:rgba(255,150,150,.95);font-family:Jost,sans-serif;flex-shrink:0">🚩 '+t.n+'</span></div>';
        }).join('')
      : '<div style="padding:12px;background:rgba(255,255,255,.03);border:1px dashed rgba(255,255,255,.10);border-radius:10px;text-align:center;font-size:12px;color:rgba(255,255,255,.35);font-family:Jost,sans-serif;font-style:italic">Sin usuarios reportados 🌿</div>';
    el.innerHTML = '<div style="background:rgba(220,120,120,.08);border:1px solid rgba(220,120,120,.20);border-radius:14px;padding:12px 14px;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between"><div><div style="font-size:11px;font-weight:800;letter-spacing:1.4px;color:rgba(255,180,180,.75);text-transform:uppercase">Reportes pendientes</div><div style="font-size:24px;font-weight:800;color:rgba(255,150,150,.98);font-family:Jost,sans-serif">'+totalPending+'</div></div><div style="font-size:38px;opacity:.55">🚩</div></div>'
      + '<div style="font-size:11px;font-weight:700;letter-spacing:1.4px;color:rgba(255,220,220,.55);text-transform:uppercase;margin:12px 0 6px">Top usuarios reportados</div>'
      + topHtml;
  }catch(e){ el.innerHTML = '<p style="font-size:13px;color:rgba(255,255,255,.3)">Error cargando reportes</p>'; }
}

async function _adminLoadUsageStats(){
  var el = document.getElementById('adminUsageStats');
  if(!el) return;
  _initSupabase();
  if(!sbClient){ el.innerHTML = '<p style="font-size:13px;color:rgba(255,255,255,.3)">Sin conexión</p>'; return; }
  var stats = { users:0, moods:0, btPosts:0, btComments:0, helpPosts:0, dqResponses:0, dqComments:0, momentos:0, momentoComments:0, dmMessages:0 };
  var qs = [
    ['profiles', 'users'],
    ['mood_entries', 'moods'],
    ['bitacora_posts', 'btPosts'],
    ['bitacora_comments', 'btComments'],
    ['help_posts', 'helpPosts'],
    ['daily_responses', 'dqResponses'],
    ['dq_comments', 'dqComments'],
    ['momentos', 'momentos'],
    ['momento_comments', 'momentoComments'],
    ['direct_messages', 'dmMessages'],
  ];
  await Promise.all(qs.map(async function(t){
    try{
      var r = await sbClient.from(t[0]).select('id',{count:'exact',head:true});
      if(!r.error) stats[t[1]] = r.count || 0;
    }catch(e){}
  }));
  // Última semana
  var weekAgoISO = new Date(Date.now() - 7*86400000).toISOString();
  var week = { moods:0, btPosts:0, helpPosts:0, dqResponses:0, momentos:0 };
  var wqs = [
    ['mood_entries', 'moods'],
    ['bitacora_posts', 'btPosts'],
    ['help_posts', 'helpPosts'],
    ['daily_responses', 'dqResponses'],
    ['momentos', 'momentos'],
  ];
  await Promise.all(wqs.map(async function(t){
    try{
      var r = await sbClient.from(t[0]).select('id',{count:'exact',head:true}).gte('created_at', weekAgoISO);
      if(!r.error) week[t[1]] = r.count || 0;
    }catch(e){}
  }));
  // Render
  var card = function(icon, label, value, weekVal, colHex){
    var wk = weekVal!==undefined ? '<div style="font-size:10.5px;color:'+colHex+';opacity:.72;margin-top:3px">+'+weekVal+' esta semana</div>' : '';
    return '<div style="background:rgba(255,255,255,.03);border:1px solid '+colHex+'22;border-left:3px solid '+colHex+';border-radius:10px;padding:11px 12px;display:flex;align-items:center;gap:10px">'
      +'<div style="font-size:22px;flex-shrink:0">'+icon+'</div>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:10.5px;font-weight:700;letter-spacing:.9px;color:rgba(255,255,255,.42);text-transform:uppercase">'+label+'</div>'
      +'<div style="font-size:20px;font-weight:800;color:'+colHex+';font-family:Jost,sans-serif;line-height:1;margin-top:3px">'+value.toLocaleString('es')+'</div>'
      +wk
      +'</div></div>';
  };
  el.innerHTML =
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    + card('👥','Usuarios totales', stats.users, undefined, '#74c69d')
    + card('💚','Ánimos registrados', stats.moods, week.moods, '#95d5b2')
    + card('📖','Historias Bitácora', stats.btPosts, week.btPosts, '#a790e0')
    + card('💬','Comentarios Bitácora', stats.btComments, undefined, '#c7b8f0')
    + card('🆘','Pedidos Sala Ayuda', stats.helpPosts, week.helpPosts, '#e07a5f')
    + card('❓','Respuestas DQ', stats.dqResponses, week.dqResponses, '#e9b949')
    + card('✨','Comentarios DQ', stats.dqComments, undefined, '#f2c95f')
    + card('🌸','Momentos', stats.momentos, week.momentos, '#f0a8c8')
    + card('💌','Comentarios Momentos', stats.momentoComments, undefined, '#f3b8d0')
    + card('📩','Mensajes directos', stats.dmMessages, undefined, '#7ab4d8')
    + '</div>'
    + '<p style="font-size:11px;color:rgba(255,255,255,.28);margin-top:10px;line-height:1.5">Data en vivo desde Supabase. Los stats de encuestas más abajo son solo de usuarios que respondieron la encuesta trimestral.</p>';
}

function _adminTransferHtml(){
  var transfers=[]; try{transfers=JSON.parse(safeLS('get','velo_pending_transfers')||'[]');}catch(e){}
  var pending=transfers.filter(function(t){ return t.ended&&!t.paid; });
  if(!pending.length) return '<p style="font-size:14px;color:rgba(255,255,255,.3);padding:8px 0">Sin transferencias pendientes.</p>';
  return pending.map(function(t,i){
    var pro=_proData.find(function(p){ return p.id===t.proId; });
    var proAmt=Math.round((t.amount||0)*0.8*100)/100;
    var veloAmt=Math.round((t.amount||0)*0.2*100)/100;
    return '<div style="background:rgba(200,162,0,.07);border:1px solid rgba(200,162,0,.2);border-radius:12px;padding:14px;margin-bottom:8px">'
      +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px"><div style="font-size:22px">'+(pro?pro.av:'🩺')+'</div>'
      +'<div style="flex:1"><div style="font-size:15px;font-weight:700;color:rgba(255,255,255,.82)">'+(pro?pro.name:'Profesional')+'</div>'
      +'<div style="font-size:13px;color:rgba(255,255,255,.4)">'+new Date(t.ts).toLocaleDateString('es',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+'</div></div>'
      +'<div style="text-align:right"><div style="font-size:16px;font-weight:800;color:rgba(200,162,0,.9)">$'+t.amount+' '+(t.currency||'USD')+'</div>'
      +'<div style="font-size:12px;color:rgba(255,255,255,.3)">Pro: $'+proAmt+' · Velo: $'+veloAmt+'</div></div></div>'
      +'<button onclick="pApproveTransfer('+i+')" style="width:100%;padding:8px;background:rgba(200,162,0,.2);border:1px solid rgba(200,162,0,.35);color:rgba(200,162,0,.9);border-radius:8px;cursor:pointer;font-family:\'Jost\',sans-serif;font-size:14px;font-weight:700">✅ Aprobar transferencia</button></div>';
  }).join('');
}

// Fecha en que se lanzó Velo — meses anteriores no aparecen en el historial admin
var _VELO_LAUNCH = {year:2026, month:5}; // Mayo 2026
function _adminMonthlyReportTracker(){
  var history=[]; try{history=JSON.parse(safeLS('get','velo_monthly_reports')||'[]');}catch(e){}
  var now=new Date();
  var months=[];
  for(var i=0;i<24;i++){
    var d=new Date(now.getFullYear(),now.getMonth()-i,1);
    // Cortar antes del launch de la app (mayo 2026)
    if(d.getFullYear() < _VELO_LAUNCH.year) break;
    if(d.getFullYear() === _VELO_LAUNCH.year && (d.getMonth()+1) < _VELO_LAUNCH.month) break;
    var key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    var sent=history.find(function(r){ return r.month===key; });
    months.push({key:key,label:d.toLocaleString('es',{month:'long',year:'numeric'}),sent:sent});
  }
  return '<div style="font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:rgba(116,198,157,.6);margin-bottom:10px">📅 INFORME MENSUAL — HISTORIAL</div>'
    +'<p style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:12px;line-height:1.5">Enviá el resumen personalizado de cada mes. Se envía a todos los usuarios y cada uno ve sus propios datos. Meses ya enviados aparecen con ✅.</p>'
    +'<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px">'
    +months.map(function(m){
        return '<div style="background:'+(m.sent?'rgba(116,198,157,.1)':'rgba(180,140,220,.05)')+';border:1px solid '+(m.sent?'rgba(116,198,157,.3)':'rgba(180,140,220,.20)')+';border-radius:10px;padding:10px;display:flex;align-items:center;justify-content:space-between;gap:8px">'
          +'<div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:600;color:rgba(255,255,255,'+(m.sent?'.85':'.75')+')">'+m.label+'</div>'
          +(m.sent
            ? '<div style="font-size:11px;color:rgba(116,198,157,.6)">✓ '+new Date(m.sent.ts).toLocaleDateString('es',{day:'2-digit',month:'short'})+'</div>'
            : '<div style="font-size:11px;color:rgba(180,140,220,.55)">Pendiente</div>')+'</div>'
          +(m.sent
            ? '<button onclick="if(confirm(\'¿Re-enviar el resumen de '+m.label.replace(/[\\\']/g,' ')+'? Los usuarios que ya lo leyeron pueden recibirlo otra vez.\')) pAdminSendMonthlyReport(\''+m.key+'\')" style="flex-shrink:0;font-size:11px;padding:4px 8px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.55);border-radius:6px;cursor:pointer;font-family:Jost,sans-serif">↻ Re-enviar</button>'
            : '<button onclick="pAdminSendMonthlyReport(\''+m.key+'\')" style="flex-shrink:0;font-size:11px;padding:5px 10px;background:rgba(180,140,220,.20);border:1px solid rgba(180,140,220,.45);color:rgba(210,180,240,.95);border-radius:6px;cursor:pointer;font-family:Jost,sans-serif;font-weight:700">📤 Enviar</button>')
          +'</div>';
      }).join('')+'</div>';
}

function pAdminMarkMonthlyReport(monthKey){
  var history=[]; try{history=JSON.parse(safeLS('get','velo_monthly_reports')||'[]');}catch(e){}
  if(!history.find(function(r){ return r.month===monthKey; })){
    history.unshift({month:monthKey,ts:Date.now(),sentBy:_ADMIN_EMAIL||'admin'});
    safeLS('set','velo_monthly_reports',JSON.stringify(history.slice(0,24)));
  }
  pToast('✅','Informe de '+monthKey+' marcado como enviado');
  _switchAdminTab('finanzas');
}

async function pAdminSendMonthlyReport(overrideMonth){
  var mn = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  var month, mLabel;
  if(overrideMonth && /^\d{4}-\d{2}$/.test(overrideMonth)){
    month = overrideMonth;
    var _yr = parseInt(month.split('-')[0]);
    var _mo = parseInt(month.split('-')[1]) - 1;
    mLabel = mn[_mo]+' '+_yr;
  } else {
    // Default: el mes ANTERIOR (el resumen es del mes que terminó, no del que corre).
    // Bug previo: usaba el mes en curso → el 1 de julio mandaba "julio".
    var d = new Date(); d.setDate(1); d.setMonth(d.getMonth()-1);
    month = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    mLabel = mn[d.getMonth()]+' '+d.getFullYear();
  }
  // Guard duro: nunca permitir enviar el resumen de un mes que aún no terminó
  var _nowG = new Date();
  var _curYM = _nowG.getFullYear()+'-'+String(_nowG.getMonth()+1).padStart(2,'0');
  if(month >= _curYM){
    pToast('⚠️','No podés enviar el resumen de '+mLabel+' — el mes todavía no terminó');
    return;
  }
  if(!confirm('¿Enviar el resumen personalizado de '+mLabel+' a todos los usuarios?\n\nCada usuario recibirá un análisis individual en su buzón generado con sus propios datos.')) return;
  _initSupabase();
  var saved = await sbSaveBroadcast('users','📊 Tu resumen de '+mLabel,'__MONTHLY_REPORT__'+month,'📊','Velo — Resumen Mensual','');
  var history=[]; try{history=JSON.parse(safeLS('get','velo_monthly_reports')||'[]');}catch(e){}
  if(!history.find(function(r){ return r.month===month; })){
    history.unshift({month:month,ts:Date.now(),sentBy:_ADMIN_EMAIL||'admin'});
    safeLS('set','velo_monthly_reports',JSON.stringify(history.slice(0,24)));
  }
  pToast('📊', saved ? 'Resumen de '+mLabel+' enviado a todos los usuarios ✅' : 'Guardado localmente (sin conexión)');
  _switchAdminTab('gestion');
}

// Wrapper para enviar el mes ANTERIOR (para admins que se olvidan el 1°)
function pAdminSendPreviousMonthReport(){
  var d = new Date();
  d.setDate(1); d.setMonth(d.getMonth()-1); // primer día del mes anterior
  var prevKey = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
  pAdminSendMonthlyReport(prevKey);
}

async function pAdminSendWeeklyReport(){
  var today = new Date();
  var dateKey = today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
  var dayNames = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
  var dayLabel = dayNames[today.getDay()];
  if(!confirm('¿Enviar el resumen semanal personalizado de hoy ('+dayLabel+' '+dateKey+') a todos los usuarios?\n\nCada usuario verá sus propios ánimos y estadísticas de la semana al abrir el mensaje.')) return;
  _initSupabase();
  var saved = await sbSaveBroadcast('users','📊 Tu resumen semanal — '+dateKey,'__WEEKLY_REPORT__'+dateKey,'📊','Velo — Resumen Semanal','');
  pToast('📊', saved ? 'Resumen semanal enviado a todos los usuarios ✅' : 'Guardado localmente (sin conexión)');
  // v1577: registrar en historial (por semana = domingo de esta semana) para mostrar
  // "✅ ya enviado esta semana" en el panel, igual que el mensual.
  try{
    var _sun=new Date(today); _sun.setDate(today.getDate()-today.getDay());
    var _wk=_sun.getFullYear()+'-'+String(_sun.getMonth()+1).padStart(2,'0')+'-'+String(_sun.getDate()).padStart(2,'0');
    var _wh=[]; try{_wh=JSON.parse(safeLS('get','velo_weekly_reports')||'[]');}catch(_){}
    _wh=_wh.filter(function(r){ return r.week!==_wk; });
    _wh.unshift({week:_wk, ts:Date.now()});
    safeLS('set','velo_weekly_reports', JSON.stringify(_wh.slice(0,12)));
  }catch(_){}
  _switchAdminTab('gestion');
}

async function pOpenWeeklyReportBroadcast(dateStr, readKey, cardEl){
  if(readKey) safeLS('set',readKey,'1');
  if(cardEl){ cardEl.classList.remove('unread'); var dot=cardEl.querySelector('.p-inbox-dot'); if(dot) dot.remove(); }
  _updateInboxDot();

  // Parse reference date (end of the week being summarized)
  var parts = (dateStr||'').split('-');
  var refDate = parts.length===3 ? new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2])) : new Date();

  // Build Supabase fallback map for that week
  var _wsMonths = {};
  for(var _wmi=0; _wmi<7; _wmi++){
    var _wmd = new Date(refDate.getFullYear(), refDate.getMonth(), refDate.getDate()-_wmi);
    var _wmk = _wmd.getFullYear()+'-'+String(_wmd.getMonth()+1).padStart(2,'0');
    if(!_wsMonths[_wmk]) _wsMonths[_wmk] = {year:_wmd.getFullYear(), month:_wmd.getMonth()+1};
  }
  var _wsSbMap = {};
  await Promise.all(Object.values(_wsMonths).map(async function(m){
    var sbData = await sbLoadAllMoods(m.year, m.month);
    if(sbData) sbData.forEach(function(e){ _wsSbMap[e.date_key] = e; });
  }));

  // Collect 7-day timeline + stats
  var dayNamesShort = ['Do','Lu','Ma','Mi','Ju','Vi','Sa'];
  var _moodScore = _VELO_MOOD_SCORE;
  var _moodLbl   = _VELO_MOOD_LABEL;
  var dayNamesLong = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  var timeline = [], weekMoods = [];
  for(var _j=6; _j>=0; _j--){
    var _dj = new Date(refDate.getFullYear(), refDate.getMonth(), refDate.getDate()-_j);
    var _kj = _dj.getFullYear()+'-'+String(_dj.getMonth()+1).padStart(2,'0')+'-'+String(_dj.getDate()).padStart(2,'0');
    var _mj = null; try{ _mj = JSON.parse(safeLS('get','velo_mood_'+_kj)||'null'); }catch(e){}
    if(!_mj && _wsSbMap[_kj]) _mj = _wsSbMap[_kj];
    timeline.push({ dayName: dayNamesShort[_dj.getDay()], mood: _mj, isToday: _j===0 });
    if(_mj) weekMoods.push(_mj);
  }
  var diary = []; try{ diary = JSON.parse(safeLS('get','velo_diary')||'[]'); }catch(e){}
  var refTs = refDate.getTime();
  var weekDiary = diary.filter(function(e){ return e.ts && e.ts <= refTs && (refTs-e.ts) < 7*86400000; });
  // Use mood-registration streak (account-scoped) — visit-day count can be stale
  var streak = _getMoodStreak ? _getMoodStreak() : weekMoods.length;
  var moodCount = {}; weekMoods.forEach(function(m){ if(m&&m.emoji){ moodCount[m.emoji]=(moodCount[m.emoji]||0)+1; } });
  var dominantMood = Object.keys(moodCount).sort(function(a,b){ return moodCount[b]-moodCount[a]; })[0]||null;
  var totalReg = weekMoods.length;
  var consistenciaPct = Math.round((totalReg/7)*100);
  var distribLines = Object.keys(moodCount).sort(function(a,b){ return moodCount[b]-moodCount[a]; }).map(function(e){
    return e+' '+(_moodLbl[e]||e)+': '+moodCount[e]+' día'+(moodCount[e]!==1?'s':'')+' ('+Math.round((moodCount[e]/totalReg)*100)+'%)';
  });

  // ── Actividad rica de la semana: Bitácora, Sala de Ayuda, DQ, Momentos, comparación ──
  var _myUidWk = safeLS('get','velo_user_id') || '';
  var weekStartTs = refTs - 7*86400000;
  var prevWeekStartTs = weekStartTs - 7*86400000;
  var weekISO = new Date(weekStartTs).toISOString();
  var prevISO = new Date(prevWeekStartTs).toISOString();
  var activity = {
    btPosted:0, btReactionsReceived:0, btCommentsReceived:0,
    btReactionsGiven:0, btCommentsGiven:0,
    helpPosted:0, helpOffered:0,
    dqAnswered:0, dqComments:0,
    momentosPosted:0, vibesPosted:0, vibeReactionsReceived:0,
    prevWeekReg:0, prevAvgScore:0, thisAvgScore:0,
    hasBuddy:false, buddyName:'', buddyDaysTogether:0, buddyDmsSent:0, buddyDmsReceived:0
  };
  if(sbClient && _myUidWk){
    try{
      // Bitácora — mis posts publicados esta semana
      var _btP = await sbClient.from('bitacora_posts').select('id,created_at').eq('user_id',_myUidWk).gte('created_at', weekISO).lte('created_at', new Date(refTs).toISOString());
      if(!_btP.error && _btP.data){
        activity.btPosted = _btP.data.length;
        var _btIds = _btP.data.map(function(p){return p.id;});
        if(_btIds.length){
          // Reacciones a mis posts esta semana
          var _btRxR = await sbClient.from('bitacora_reactions').select('id').in('post_id',_btIds).gte('created_at', weekISO);
          if(!_btRxR.error && _btRxR.data) activity.btReactionsReceived = _btRxR.data.length;
          // Comentarios a mis posts esta semana
          var _btCmR = await sbClient.from('bitacora_comments_full').select('id').in('post_id',_btIds).gte('created_at', weekISO);
          if(!_btCmR.error && _btCmR.data) activity.btCommentsReceived = _btCmR.data.length;
        }
      }
      // Reacciones y comentarios QUE DÍ esta semana en bitácora
      var _btRxG = await sbClient.from('bitacora_reactions').select('id',{count:'exact',head:true}).eq('user_id',_myUidWk).gte('created_at', weekISO);
      if(!_btRxG.error) activity.btReactionsGiven = _btRxG.count || 0;
      var _btCmG = await sbClient.from('bitacora_comments_full').select('id',{count:'exact',head:true}).eq('user_id',_myUidWk).gte('created_at', weekISO);
      if(!_btCmG.error) activity.btCommentsGiven = _btCmG.count || 0;
      // Sala de Ayuda — pedidos que hice
      var _hp = await sbClient.from('help_posts').select('id',{count:'exact',head:true}).eq('user_id',_myUidWk).gte('created_at', weekISO);
      if(!_hp.error) activity.helpPosted = _hp.count || 0;
      // Ayuda ofrecida (Guardián — chats iniciados como acompañante)
      try{
        var _gr = await sbClient.from('guardian_requests').select('id',{count:'exact',head:true}).eq('guardian_id',_myUidWk).gte('created_at', weekISO);
        if(!_gr.error) activity.helpOffered = _gr.count || 0;
      }catch(e){}
      // DQ — respuestas propias esta semana
      var _dqR = await sbClient.from('daily_responses').select('id',{count:'exact',head:true}).eq('user_id',_myUidWk).gte('created_at', weekISO);
      if(!_dqR.error) activity.dqAnswered = _dqR.count || 0;
      // Comentarios que hice en DQ
      try{
        var _dqC = await sbClient.from('dq_comments_feed').select('id',{count:'exact',head:true}).eq('user_id',_myUidWk).gte('created_at', weekISO);
        if(!_dqC.error) activity.dqComments = _dqC.count || 0;
      }catch(e){}
      // Momentos publicados
      try{
        var _mo = await sbClient.from('momentos').select('id',{count:'exact',head:true}).eq('user_id',_myUidWk).gte('created_at', weekISO);
        if(!_mo.error) activity.momentosPosted = _mo.count || 0;
      }catch(e){}
      // Vibes de hoy publicadas + reacciones recibidas
      try{
        var _vb = await sbClient.from('vibes').select('id').eq('user_id',_myUidWk).gte('created_at', weekISO);
        if(!_vb.error && _vb.data){
          activity.vibesPosted = _vb.data.length;
          var _vbIds = _vb.data.map(function(v){return v.id;});
          if(_vbIds.length){
            var _vRx = await sbClient.from('vibe_reactions').select('id').in('vibe_id',_vbIds).gte('created_at', weekISO);
            if(!_vRx.error && _vRx.data) activity.vibeReactionsReceived = _vRx.data.length;
          }
        }
      }catch(e){}
      // Buddy — mi compañero/a de bienestar (si tengo)
      try{
        var _bdMe = await sbClient.from('profiles').select('buddy_id,buddy_name,buddy_started_at').eq('id',_myUidWk).maybeSingle();
        if(_bdMe && _bdMe.data && _bdMe.data.buddy_id){
          activity.hasBuddy = true;
          activity.buddyName = (_bdMe.data.buddy_name||'').split(' ')[0] || 'tu compañero/a';
          if(_bdMe.data.buddy_started_at){
            activity.buddyDaysTogether = Math.max(0, Math.floor((refTs - new Date(_bdMe.data.buddy_started_at).getTime()) / 86400000));
          }
          var _bdId = _bdMe.data.buddy_id;
          // DMs enviados por mí al buddy esta semana (filtrar sentinels internos)
          var _dmS = await sbClient.from('direct_messages').select('id,text').eq('from_id',_myUidWk).eq('to_id',_bdId).gte('created_at', weekISO);
          if(!_dmS.error && _dmS.data) activity.buddyDmsSent = _dmS.data.filter(function(m){ return m.text && m.text.indexOf('__velo_')!==0; }).length;
          // DMs recibidos del buddy esta semana
          var _dmR = await sbClient.from('direct_messages').select('id,text').eq('from_id',_bdId).eq('to_id',_myUidWk).gte('created_at', weekISO);
          if(!_dmR.error && _dmR.data) activity.buddyDmsReceived = _dmR.data.filter(function(m){ return m.text && m.text.indexOf('__velo_')!==0; }).length;
        }
      }catch(e){}
      // Comparación con semana anterior. La semana previa puede CRUZAR un fin de
      // mes (ej. 29 ene – 4 feb): cargar un solo mes dejaba afuera los días del otro
      // y subcontaba prevWeekReg. Cargamos ambos meses candidatos y unimos por date_key.
      var _pwS = new Date(prevWeekStartTs), _pwE = new Date(weekStartTs - 1);
      var _prevMoodsRaw = (await sbLoadAllMoods(_pwS.getFullYear(), _pwS.getMonth()+1)) || [];
      if(_pwE.getMonth() !== _pwS.getMonth() || _pwE.getFullYear() !== _pwS.getFullYear()){
        var _extraM = (await sbLoadAllMoods(_pwE.getFullYear(), _pwE.getMonth()+1)) || [];
        var _seenK = {}; _prevMoodsRaw.forEach(function(m){ if(m.date_key) _seenK[m.date_key]=1; });
        _extraM.forEach(function(m){ if(m.date_key && !_seenK[m.date_key]) _prevMoodsRaw.push(m); });
      }
      if(_prevMoodsRaw){
        var _prevScores = [];
        _prevMoodsRaw.forEach(function(m){
          if(!m.emoji || !m.date_key) return;
          var _mdKey = new Date(m.date_key).getTime();
          if(_mdKey >= prevWeekStartTs && _mdKey < weekStartTs){
            _prevScores.push(_moodScore[m.emoji]||3);
            activity.prevWeekReg++;
          }
        });
        if(_prevScores.length) activity.prevAvgScore = _prevScores.reduce(function(a,b){return a+b;},0)/_prevScores.length;
      }
    }catch(e){ console.warn('[weekly] activity fetch error:', e); }
  }
  var scores = timeline.filter(function(d){ return d.mood; }).map(function(d){ return _moodScore[d.mood.emoji]||3; });
  if(scores.length) activity.thisAvgScore = scores.reduce(function(a,b){return a+b;},0)/scores.length;
  var half = Math.ceil(scores.length/2);
  var avgF = scores.slice(0,half).reduce(function(a,b){return a+b;},0)/(half||1);
  var avgS = scores.slice(half).reduce(function(a,b){return a+b;},0)/((scores.length-half)||1);
  var trendVal = scores.length<2?0:avgS-avgF;
  var trendTxt = trendVal>0.4?'↗ Mejoró a lo largo de la semana (+'+(Math.round(trendVal*20))+'%)'
               : trendVal<-0.4?'↘ Descendió en la segunda mitad (-'+(Math.round(Math.abs(trendVal)*20))+'%)'
               : '→ Se mantuvo estable durante la semana';
  var bestDay=null, worstDay=null;
  timeline.forEach(function(d){ if(!d.mood) return; var sc=_moodScore[d.mood.emoji]||3;
    if(!bestDay||sc>(_moodScore[bestDay.mood.emoji]||3)) bestDay=d;
    if(!worstDay||sc<(_moodScore[worstDay.mood.emoji]||3)) worstDay=d; });

  var userName = (safeLS('get','velo_user_name')||'').split(' ')[0]||'';

  if(totalReg === 0){
    pShowWeeklySummary({ timeline:timeline, dominantMood:null, checkIns:0, diaryEntries:0, streak:streak, aiText:'Esta semana no registraste estados de ánimo. ¡La próxima podés empezar cualquier día! 🌱' });
    return;
  }

  var _wkDiaryDays = [];
  weekDiary.forEach(function(e){ if(e.ts){ var _dd=dayNamesLong[new Date(e.ts).getDay()].slice(0,2); if(_wkDiaryDays.indexOf(_dd)<0) _wkDiaryDays.push(_dd); } });
  var aiRes = await _generateWeeklySummaryAI(timeline, dominantMood, streak, totalReg, weekDiary.length, userName, distribLines, trendTxt, bestDay, worstDay, activity, _wkDiaryDays);
  if(!aiRes) aiRes = { narrative:'', insight:'', intention:'' };
  var _avgThisB = scores.length ? scores.reduce(function(a,b){return a+b;},0)/scores.length : 0;
  var _wbB = Math.max(0, Math.min(100, Math.round((_avgThisB/5)*80 + (totalReg/7)*20)));
  var _prevRegB = activity.prevWeekReg||0;
  var _prevWbB = _prevRegB>0 ? Math.max(0, Math.min(100, Math.round(((activity.prevAvgScore||0)/5)*80 + (_prevRegB/7)*20))) : null;
  pShowWeeklySummary({ timeline:timeline, dominantMood:dominantMood, checkIns:totalReg, diaryEntries:weekDiary.length, streak:streak, aiText:aiRes.narrative, aiInsight:aiRes.insight, aiIntention:aiRes.intention, wellbeing:_wbB, prevWellbeing:_prevWbB, distribLines:distribLines, consistenciaPct:consistenciaPct, trendTxt:trendTxt, bestDay:bestDay, worstDay:worstDay, activity:activity });
}

// ── TAB: PRIVACIDAD (GDPR / Ley 25.326) ──────────────────────────────
function _adminTabPrivacidad(panel){
  panel.innerHTML = '<div style="font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:rgba(180,140,220,.85);margin-bottom:12px">🔒 SOLICITUDES DE DATOS PERSONALES</div>'
    +'<p style="font-size:14px;color:rgba(255,255,255,.45);margin-bottom:16px;line-height:1.6">Cuando un usuario pide sus datos (Ley 25.326 / GDPR), Velo IA prepara el informe. Lo revisás antes de confirmar el envío.</p>'
    +'<div style="background:rgba(180,140,220,.07);border:1px solid rgba(180,140,220,.2);border-radius:14px;padding:14px;margin-bottom:16px">'
    +'<label style="font-size:13px;font-weight:700;color:rgba(255,255,255,.5);display:block;margin-bottom:6px">CORREO DEL USUARIO SOLICITANTE</label>'
    +'<div style="display:flex;gap:8px">'
    +'<input type="email" id="gdprEmail" placeholder="usuario@email.com" style="flex:1;padding:10px 14px;background:rgba(255,255,255,.07);border:1.5px solid rgba(255,255,255,.12);border-radius:12px;color:#fff;font-size:15px;font-family:\'Jost\',sans-serif;box-sizing:border-box">'
    +'<button onclick="pAdminPrepareGDPR()" id="gdprBtn" style="padding:10px 16px;background:rgba(180,140,220,.2);border:1.5px solid rgba(180,140,220,.35);border-radius:12px;color:rgba(180,140,220,.95);font-size:14px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer;white-space:nowrap;flex-shrink:0">🔍 Preparar informe</button>'
    +'</div></div>'
    +'<div id="gdprResult"></div>'
    +'<div style="margin-top:20px"><div style="font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:10px">📋 HISTORIAL DE SOLICITUDES</div>'
    +'<div id="gdprHistory">'+_renderGDPRHistory()+'</div></div>';
}

async function pAdminPrepareGDPR(){
  var emailEl=document.getElementById('gdprEmail');
  if(!emailEl||!emailEl.value.trim()){ pToast('⚠️','Ingresá el correo del usuario'); return; }
  var email=emailEl.value.trim().toLowerCase();
  var btn=document.getElementById('gdprBtn'); var resultEl=document.getElementById('gdprResult');
  if(btn){btn.disabled=true;btn.textContent='🔍 Preparando…';}
  if(resultEl) resultEl.innerHTML='<p style="font-size:13px;color:rgba(255,255,255,.4);font-style:italic;padding:8px 0">Velo IA está preparando el informe…</p>';

  _initSupabase();
  var userData={email:email,perfil:null,diarioCount:0,estadosCount:0};
  if(sbClient){
    try{ var pRes=await sbClient.from('profiles_full').select('*').eq('email',email).limit(1); if(pRes.data&&pRes.data[0]) userData.perfil=pRes.data[0]; }catch(e){}
    if(userData.perfil){
      var uid=userData.perfil.id;
      try{ var dRes=await sbClient.from('diary_entries').select('id',{count:'exact',head:true}).eq('user_id',uid); userData.diarioCount=dRes.count||0; }catch(e){}
      try{ var mRes=await sbClient.from('moods').select('id',{count:'exact',head:true}).eq('user_id',uid); userData.estadosCount=mRes.count||0; }catch(e){}
    }
  }
  var p=userData.perfil;
  var context='Datos del usuario en Velo:\n'
    +'Email: '+email+'\nNombre: '+(p?p.nombre||'—':'No encontrado')+'\nUsuario: @'+(p?p.username||'—':'—')
    +'\nRol: '+(p?p.role||'user':'—')+'\nRegistro: '+(p&&p.created_at?new Date(p.created_at).toLocaleDateString('es'):'—')
    +'\nTérminos: '+(p&&p.terms_accepted_at?new Date(p.terms_accepted_at).toLocaleDateString('es'):'No registrado')
    +'\nEntradas diario: '+userData.diarioCount+'\nRegistros de ánimo: '+userData.estadosCount+'\n';

  var prompt='Sos el sistema de compliance de Velo, app de bienestar emocional argentina.\n'
    +'Un usuario solicitó sus datos bajo la Ley 25.326 / GDPR.\n'
    +'Redactá un informe formal con:\n'
    +'1. Responsable del tratamiento (Heyvelo / Velo App)\n'
    +'2. Datos almacenados (con los datos reales del contexto)\n'
    +'3. Finalidad del tratamiento\n'
    +'4. Base legal\n'
    +'5. Derechos: rectificación, cancelación, oposición, portabilidad\n'
    +'6. Contacto: consultas@heyvelo.app\n'
    +'Español formal, sin código, máximo 350 palabras.\n\n'+context;

  var report=await _geminiCall(prompt,{maxOutputTokens:600});
  if(btn){btn.disabled=false;btn.textContent='🔍 Preparar informe';}
  if(!report){ if(resultEl) resultEl.innerHTML='<p style="font-size:13px;color:rgba(255,100,100,.6);padding:6px 0">No se pudo preparar. Verificá la conexión.</p>'; return; }

  if(resultEl){
    var encoded=encodeURIComponent(report).slice(0,2000);
    resultEl.innerHTML='<div style="background:rgba(180,140,220,.07);border:1.5px solid rgba(180,140,220,.3);border-radius:14px;padding:16px;margin-top:8px">'
      +'<div style="font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:rgba(180,140,220,.8);margin-bottom:10px">📋 INFORME — REVISÁ ANTES DE CONFIRMAR</div>'
      +'<div style="font-size:14px;color:rgba(255,255,255,.8);line-height:1.7;white-space:pre-line;max-height:300px;overflow-y:auto;margin-bottom:14px;padding-right:4px">'+_escHtml(report)+'</div>'
      +'<p style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:12px">⚠️ Enviá este informe manualmente al usuario: <strong>'+_escHtml(email)+'</strong></p>'
      +'<div style="display:flex;gap:8px">'
      +'<button onclick="pAdminConfirmGDPR(\''+_escHtml(email)+'\',\''+encoded+'\')" style="flex:1;padding:10px;background:rgba(116,198,157,.2);border:1.5px solid rgba(116,198,157,.4);border-radius:12px;color:#fff;font-size:14px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer">✅ Confirmar — registrar envío</button>'
      +'<button onclick="document.getElementById(\'gdprResult\').innerHTML=\'\'" style="padding:10px 16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:12px;color:rgba(255,255,255,.6);font-size:14px;font-family:\'Jost\',sans-serif;cursor:pointer">Cancelar</button>'
      +'</div></div>';
  }
}

async function pAdminConfirmGDPR(email, encoded){
  var report=''; try{report=decodeURIComponent(encoded);}catch(e){report=encoded;}
  _initSupabase();
  if(sbClient){ try{await sbClient.from('data_requests').insert({email:email,report_summary:report.slice(0,500),sent_at:new Date().toISOString(),sent_by:_ADMIN_EMAIL||'admin'});}catch(e){} }
  var history=[]; try{history=JSON.parse(safeLS('get','velo_gdpr_requests')||'[]');}catch(e){}
  history.unshift({email:email,ts:Date.now(),sentBy:_ADMIN_EMAIL||'admin'});
  safeLS('set','velo_gdpr_requests',JSON.stringify(history.slice(0,100)));
  var resultEl=document.getElementById('gdprResult');
  if(resultEl) resultEl.innerHTML='<div style="background:rgba(116,198,157,.08);border:1px solid rgba(116,198,157,.2);border-radius:10px;padding:12px;font-size:14px;color:rgba(116,198,157,.9)">✅ Registrado. Enviá el informe manualmente a: <strong>'+_escHtml(email)+'</strong></div>';
  var histEl=document.getElementById('gdprHistory');
  if(histEl) histEl.innerHTML=_renderGDPRHistory();
  pToast('🔒','Solicitud GDPR registrada');
}

function _renderGDPRHistory(){
  var history=[]; try{history=JSON.parse(safeLS('get','velo_gdpr_requests')||'[]');}catch(e){}
  if(!history.length) return '<p style="font-size:13px;color:rgba(255,255,255,.25);font-style:italic">Sin solicitudes previas</p>';
  return history.slice(0,20).map(function(r){
    var d=new Date(r.ts).toLocaleString('es',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
    return '<div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.05)">'
      +'<span style="font-size:15px">📤</span>'
      +'<div style="flex:1"><div style="font-size:14px;color:rgba(255,255,255,.65)">'+_escHtml(r.email)+'</div>'
      +'<div style="font-size:12px;color:rgba(255,255,255,.25)">'+d+'</div></div>'
      +'<span style="font-size:12px;color:rgba(116,198,157,.7);font-weight:700">✓ Enviado</span></div>';
  }).join('');
}

// ── v1506: USO DE SECCIONES (7 días) — para decidir con datos ────────
async function _adminLoadUsage(){
  var el = document.getElementById('adminUsageBlock');
  if(!el) return;
  _initSupabase();
  if(!sbClient){ el.innerHTML = '<p style="font-size:12px;color:rgba(255,255,255,.3)">Sin conexión</p>'; return; }
  try{
    var since = new Date(Date.now() - 7*86400000).toISOString();
    var r = await sbClient.from('usage_events').select('meta,user_id').eq('event','page').gte('created_at', since).limit(8000);
    if(r.error){ el.innerHTML = '<p style="font-size:12px;color:rgba(255,180,80,.7)">Falta la tabla usage_events (corré la migración)</p>'; return; }
    var rows = r.data||[];
    if(!rows.length){ el.innerHTML = '<p style="font-size:12.5px;color:rgba(255,255,255,.35);font-style:italic">Todavía sin datos — se llena solo a medida que la gente navega.</p>'; return; }
    var _lbl = { home:'🏠 Inicio', vibes:'✨ Vibes', guardians:'🛡️ Guardianes', help:'💬 Sala de Ayuda', bitacora:'📖 Bitácora', news:'🌞 Buenas Noticias', diary:'📔 Diario', circles:'☮️ Círculos', contacts:'⭐ Contactos', 'calm-ai':'🤖 Velo IA', profile:'👤 Perfil', inbox:'💌 Buzón', momento:'🌸 Momentos', 'dm-chat':'💬 Chats 1a1', mood:'💚 Registro de ánimo', respira:'🌬️ Respira', 'donate-cta':'💛 Apoyá a Velo' };
    var agg = {}, users = {};
    rows.forEach(function(x){
      if(!x.meta) return;
      var a = agg[x.meta] = agg[x.meta] || { n:0, u:{} };
      a.n++; if(x.user_id) a.u[x.user_id] = 1;
      if(x.user_id) users[x.user_id] = 1;
    });
    var list = Object.keys(agg).map(function(k){ return { k:k, n:agg[k].n, u:Object.keys(agg[k].u).length }; })
      .sort(function(a,b){ return b.n - a.n; }).slice(0, 12);
    var max = list[0] ? list[0].n : 1;
    el.innerHTML = '<div style="font-size:12px;color:rgba(255,255,255,.45);margin-bottom:10px">'+rows.length+' aperturas · '+Object.keys(users).length+' usuario'+(Object.keys(users).length!==1?'s':'')+' activos en 7 días</div>'
      + list.map(function(x){
          var pct = Math.max(4, Math.round(x.n/max*100));
          return '<div style="margin-bottom:7px">'
            + '<div style="display:flex;justify-content:space-between;font-size:12.5px;color:rgba(255,255,255,.75);font-family:Jost,sans-serif;margin-bottom:3px"><span>'+(_lbl[x.k]||('· '+_escHtml(x.k)))+'</span><span style="color:rgba(116,198,157,.85);font-weight:700">'+x.n+' <span style="color:rgba(255,255,255,.35);font-weight:400">('+x.u+' 👤)</span></span></div>'
            + '<div style="height:5px;border-radius:3px;background:rgba(255,255,255,.07)"><div style="height:100%;width:'+pct+'%;border-radius:3px;background:linear-gradient(90deg,rgba(116,198,157,.85),rgba(116,198,157,.45))"></div></div>'
            + '</div>';
        }).join('');
  }catch(e){ el.innerHTML = '<p style="font-size:12px;color:rgba(255,255,255,.3)">Error cargando uso</p>'; }
}

