async function _adminLoadCircleChats(){
  var el = document.getElementById('adminCircleChatList');
  if(!el) return;
  _initSupabase();
  if(!sbClient){ el.innerHTML='<div style="font-size:13px;color:rgba(255,100,100,.5)">Sin conexión a Supabase</div>'; return; }

  // Count messages per circle for official ones
  var officialRows = _officialCircles.map(function(c){ return {id:c.id,name:c.name,emoji:c.emoji,official:true,count:null}; });
  var userCircles = [];

  try{
    var ucRes = await sbClient.from('circles').select('id,name,emoji').eq('official',false).order('created_at',{ascending:false}).limit(100);
    userCircles = (ucRes.data||[]).map(function(r){ return {id:r.id,name:r.name||'Sin nombre',emoji:r.emoji||'💬',official:false,count:null}; });
  }catch(e){}

  // Batch-count messages for each circle
  var allCircles = officialRows.concat(userCircles);
  await Promise.all(allCircles.map(async function(c){
    try{
      var r = await sbClient.from('circle_messages').select('id',{count:'exact',head:true}).eq('circle_id',c.id);
      c.count = r.count || 0;
    }catch(e){ c.count = '?'; }
  }));

  var _btnStyle = 'font-size:12px;padding:5px 12px;border-radius:8px;cursor:pointer;font-family:\'Jost\',sans-serif;font-weight:700;white-space:nowrap;';

  el.innerHTML = '<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:8px">🛡️ SALAS OFICIALES</div>'
    + officialRows.map(function(c){
        return '<div style="display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.06)">'
          +'<span style="font-size:18px">'+c.emoji+'</span>'
          +'<div style="flex:1;min-width:0">'
          +'<div style="font-size:14px;font-weight:600;color:rgba(255,255,255,.75)">'+_escHtml(c.name)+'</div>'
          +'<div style="font-size:12px;color:rgba(255,255,255,.3)">'+c.count+' mensaje'+(c.count!==1?'s':'')+'</div>'
          +'</div>'
          +(c.count > 0
            ? '<button onclick="pAdminClearCircleChat(\''+c.id+'\',\''+_escHtml(c.name)+'\')" style="'+_btnStyle+'background:rgba(231,76,60,.18);border:1px solid rgba(231,76,60,.35);color:rgba(255,130,130,.9)">🗑️ Limpiar</button>'
            : '<span style="font-size:12px;color:rgba(255,255,255,.2)">Vacío</span>')
          +'</div>';
      }).join('')
    + (userCircles.length
        ? '<div style="font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:rgba(255,255,255,.3);margin:14px 0 8px">👥 CÍRCULOS DE USUARIOS</div>'
          + userCircles.map(function(c){
              return '<div style="display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.06)">'
                +'<span style="font-size:18px">'+c.emoji+'</span>'
                +'<div style="flex:1;min-width:0">'
                +'<div style="font-size:14px;font-weight:600;color:rgba(255,255,255,.75)">'+_escHtml(c.name)+'</div>'
                +'<div style="font-size:12px;color:rgba(255,255,255,.3)">'+c.count+' mensaje'+(c.count!==1?'s':'')+'</div>'
                +'</div>'
                +(c.count > 0
                  ? '<button onclick="pAdminClearCircleChat(\''+c.id+'\',\''+_escHtml(c.name)+'\')" style="'+_btnStyle+'background:rgba(231,76,60,.18);border:1px solid rgba(231,76,60,.35);color:rgba(255,130,130,.9)">🗑️ Limpiar</button>'
                  : '<span style="font-size:12px;color:rgba(255,255,255,.2)">Vacío</span>')
                +'</div>';
            }).join('')
        : '')
    + '<div style="margin-top:12px">'
    + '<button onclick="pAdminClearAllOfficialChats()" style="'+_btnStyle+'width:100%;padding:9px;background:rgba(231,76,60,.12);border:1px solid rgba(231,76,60,.25);color:rgba(255,130,130,.75)">🧹 Limpiar TODAS las salas oficiales</button>'
    + '</div>';
}

async function pAdminClearCircleChat(circleId, circleName){
  if(!confirm('¿Eliminar TODOS los mensajes de "'+circleName+'"?\n\nEsta acción no se puede deshacer.')) return;
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión a Supabase'); return; }
  try{
    var res = await sbClient.from('circle_messages').delete().eq('circle_id', circleId);
    if(res.error) throw res.error;
    // Clear local cache too
    safeLS('del', 'velo_circle_'+circleId);
    pToast('🗑️','Chat "'+circleName+'" limpiado');
    _adminLoadCircleChats();
  }catch(e){ pToast('❌','Error: '+e.message); }
}

async function pAdminClearAllOfficialChats(){
  if(!confirm('¿Eliminar TODOS los mensajes de las 5 salas oficiales de Velo?\n\nEsta acción no se puede deshacer.')) return;
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión a Supabase'); return; }
  var errors = [];
  for(var i=0; i<_officialCircles.length; i++){
    var c = _officialCircles[i];
    try{
      var res = await sbClient.from('circle_messages').delete().eq('circle_id', c.id);
      if(res.error) errors.push(c.name);
      safeLS('del', 'velo_circle_'+c.id);
    }catch(e){ errors.push(c.name); }
  }
  if(errors.length) pToast('⚠️','Error en: '+errors.join(', '));
  else pToast('🧹','Todas las salas oficiales limpiadas');
  _adminLoadCircleChats();
}

// ── NEW: Warn user ────────────────────────────────────────────────────
function pAdminWarnUser(userId, email){
  var ov=document.createElement('div'); ov.className='p-modal-ov show'; ov.id='adminWarnOv'; ov.style.zIndex='9999';
  ov.innerHTML='<div class="p-sheet p-sheet-dark" style="background:#0F2016 !important;color:#fff;border:1px solid rgba(230,180,40,.2);overflow-y:auto;max-height:90vh">'
    +'<div style="font-size:28px;margin-bottom:8px">⚠️</div>'
    +'<div style="font-family:\'Cormorant Garamond\',serif;font-size:20px;color:#fff;margin-bottom:6px">Advertencia formal</div>'
    +'<p style="font-size:14px;color:rgba(255,255,255,.45);margin-bottom:16px;line-height:1.5">El mensaje llegará al buzón del usuario como advertencia oficial de Velo.</p>'
    +(email?'<p style="font-size:13px;color:rgba(255,255,255,.3);margin-bottom:12px">Usuario: '+_escHtml(email)+'</p>':'')
    +'<div style="margin-bottom:12px"><label style="font-size:13px;font-weight:700;color:rgba(255,255,255,.5);display:block;margin-bottom:6px">MOTIVO</label>'
    +'<select id="warnReason" style="width:100%;padding:9px;background:rgba(255,255,255,.07);border:1.5px solid rgba(255,255,255,.15);border-radius:10px;color:#fff;font-size:15px;font-family:\'Jost\',sans-serif">'
    +'<option value="acoso">Acoso o bullying hacia otro usuario</option>'
    +'<option value="spam">Spam o autopromocción</option>'
    +'<option value="lenguaje">Lenguaje agresivo o inapropiado</option>'
    +'<option value="contenido">Contenido dañino o inapropiado</option>'
    +'<option value="otro">Otro</option></select></div>'
    +'<div style="margin-bottom:14px"><label style="font-size:13px;font-weight:700;color:rgba(255,255,255,.5);display:block;margin-bottom:6px">MENSAJE ADICIONAL (opcional)</label>'
    +'<textarea id="warnMessage" rows="3" placeholder="Detalle adicional…" maxlength="400" style="width:100%;padding:10px 14px;background:rgba(255,255,255,.07);border:1.5px solid rgba(255,255,255,.12);border-radius:12px;color:#fff;font-size:15px;font-family:\'Jost\',sans-serif;resize:vertical;box-sizing:border-box"></textarea></div>'
    +'<div style="display:flex;gap:8px">'
    +'<button onclick="pAdminSendWarning(\''+_escHtml(userId||'')+'\',\''+_escHtml(email||'')+'\')" style="flex:1;padding:11px;background:rgba(230,180,40,.2);border:1.5px solid rgba(230,180,40,.4);border-radius:14px;color:#fff;font-size:15px;font-weight:700;font-family:\'Jost\',sans-serif;cursor:pointer">⚠️ Enviar advertencia</button>'
    +'<button onclick="document.getElementById(\'adminWarnOv\').remove()" style="padding:11px 16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:14px;color:rgba(255,255,255,.6);font-size:15px;font-family:\'Jost\',sans-serif;cursor:pointer">Cancelar</button>'
    +'</div></div>';
  document.body.appendChild(ov);
}

async function pAdminSendWarning(userId, email){
  var reasonEl=document.getElementById('warnReason'); var msgEl=document.getElementById('warnMessage');
  var reason=reasonEl?reasonEl.value:'otro'; var extra=msgEl?msgEl.value.trim():'';
  var labels={acoso:'acoso o bullying',spam:'spam o autopromocción',lenguaje:'lenguaje agresivo',contenido:'contenido inapropiado',otro:'comportamiento contrario a las normas'};
  var warnText='⚠️ Tu cuenta recibió una advertencia formal de Velo por '+(labels[reason]||reason)+'. '+(extra?extra+' ':'')+'Si el comportamiento continúa, tu cuenta puede ser suspendida. Consultas: consultas@heyvelo.app.';
  var target=userId?'user:'+userId:(email?'email:'+email:'user');
  var saved=await sbSaveBroadcast(target,'⚠️ Advertencia formal de Velo',warnText,'⚠️','Velo — Moderación');
  var ov=document.getElementById('adminWarnOv'); if(ov) ov.remove();
  pToast('⚠️',saved?'Advertencia enviada al usuario':'Guardado localmente (sin conexión)');
}

async function pAdminResolveReport(id, src){
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  try{
    var table = src || 'reportes';
    if(table === 'reportes'){
      await sbClient.from('reportes').update({estado:'resuelto',resolved_at:new Date().toISOString()}).eq('id',id);
    } else if(table === 'content_reports'){
      await sbClient.from('content_reports').update({resolved:true,resolved_at:new Date().toISOString()}).eq('id',id);
    } else if(table === 'bitacora_reports'){
      await sbClient.from('bitacora_reports').delete().eq('id',id);
    }
    var card=document.getElementById('report-'+id); if(card) card.remove();
    pToast('✅','Reporte resuelto');
  }catch(e){ pToast('⚠️','Error al resolver el reporte'); }
}

async function pAdminResolveBitacoraReport(reportId, postId, reporterUid, verdict){
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  try{
    // Fetch post owner before deleting
    var ownerUid = null;
    if(postId){
      var pRes = await sbClient.from('bitacora_posts').select('user_id').eq('id',postId).maybeSingle();
      if(!pRes.error && pRes.data) ownerUid = pRes.data.user_id;
    }
    // Remove the report record
    await sbClient.from('bitacora_reports').delete().eq('id',reportId);
    // Act on post
    if(verdict==='valido' && postId){
      await sbClient.from('bitacora_posts').delete().eq('id',postId);
    }
    // Notifications
    var sender = {n:'Velo — Moderación', i:'system', a:'', u:''};
    if(reporterUid){
      var rSubj = verdict==='valido' ? 'Reporte resuelto ✅' : 'Reporte revisado ℹ️';
      var rMsg  = verdict==='valido'
        ? 'Verificamos que el reporte es válido. La publicación fue removida. Gracias por ayudar a mantener la comunidad segura. 🙏'
        : 'Verificamos que el reporte no procede. La publicación cumple las normas de la comunidad y permanece visible.';
      await sbSaveBroadcast('user:'+reporterUid, rSubj, rMsg, verdict==='valido'?'✅':'ℹ️', sender);
    }
    if(ownerUid && ownerUid!==reporterUid){
      var oSubj = verdict==='valido' ? 'Tu publicación fue removida 🚩' : 'Tu publicación fue revisada ✅';
      var oMsg  = verdict==='valido'
        ? 'Revisamos el reporte sobre tu publicación y determinamos que no cumple las normas de la comunidad. Fue removida. Consultas: consultas@heyvelo.app'
        : 'Revisamos el reporte sobre tu publicación y no encontramos violaciones a las normas. Tu publicación permanece visible en Bitácora. ✅';
      await sbSaveBroadcast('user:'+ownerUid, oSubj, oMsg, verdict==='valido'?'🚩':'✅', sender);
    }
    // Remove card from admin UI
    var card = document.getElementById('report-'+reportId);
    if(card){ card.style.transition='opacity .3s'; card.style.opacity='0'; setTimeout(function(){ card.remove(); },300); }
    pToast('✅', verdict==='valido' ? 'Publicación removida · Usuarios notificados' : 'Reporte resuelto · Publicación restaurada');
  }catch(e){ pToast('⚠️','Error: '+(e.message||'desconocido')); }
}

async function pAdminDeleteContent(contentId, contentType){
  if(!contentId){ pToast('⚠️','Sin ID de contenido'); return; }
  if(!window.confirm('¿Eliminar este contenido? Esta acción no se puede deshacer.')) return;
  _initSupabase();
  if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  var tableMap={post:'posts',circle_message:'circle_messages',bottle:'bottles',help_post:'help_posts',review:'reviews',bitacora:'bitacora_posts'};
  var table=tableMap[contentType]||contentType;
  if(!table){ pToast('⚠️','Tipo desconocido: '+contentType); return; }
  try{ await sbClient.from(table).delete().eq('id',contentId); pToast('🗑️','Contenido eliminado'); }
  catch(e){ pToast('⚠️','Error: '+e.message); }
}

function pCreateProvisionalPass(){
  var emailEl = document.getElementById('adminProvEmail');
  if(!emailEl || !emailEl.value.trim()){ pToast('⚠️','Ingresá el correo del usuario'); return; }
  var email = emailEl.value.trim().toLowerCase();
  var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
  var pass  = '';
  for(var i = 0; i < 10; i++) pass += chars[Math.floor(Math.random()*chars.length)];
  var expiry = Date.now() + 72*3600*1000;
  var key = 'velo_prov_'+email.replace(/[^a-z0-9]/g,'_');
  try{ localStorage.setItem(key, JSON.stringify({pass:pass, expiry:expiry})); }catch(e){}
  var resEl = document.getElementById('adminProvResult');
  if(resEl) resEl.innerHTML = '✅ Contraseña provisional: <code style="background:rgba(255,255,255,.12);padding:2px 8px;border-radius:4px;font-family:monospace;letter-spacing:1px">'+pass+'</code><br><span style="color:rgba(255,255,255,.4);font-size:12px">Válida 72 horas · Compartila de forma segura con el usuario</span>';
  pToast('🔑','Contraseña provisional creada');
}

var _adminContactsCache = [];
var _adminReplyTarget = null;
var _adminContactFilter = 'all';

function _renderAdminContactsList(msgs){
  _adminContactsCache = msgs || [];
  var el = document.getElementById('adminContactsList');
  if(!el) return;

  var unread = (msgs||[]).filter(function(m){ return !m.leido; }).length;
  var preLogin = (msgs||[]).filter(function(m){ return m.source === 'pre-login'; }).length;
  var loggedIn = (msgs||[]).filter(function(m){ return m.source === 'logged-in'; }).length;

  // Tab bar
  var tabs = [
    { id:'all',      label:'Todos',          count:(msgs||[]).length },
    { id:'unread',   label:'Sin leer',       count:unread },
    { id:'pre-login',label:'Pre-login',      count:preLogin },
    { id:'logged-in',label:'Usuarios',       count:loggedIn }
  ];
  var tabsHtml = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">'
    + tabs.map(function(t){
        var active = _adminContactFilter === t.id;
        return '<button onclick="pAdminFilterContacts(\''+t.id+'\')" style="font-size:12px;padding:4px 10px;border-radius:20px;cursor:pointer;font-family:\'Jost\',sans-serif;font-weight:700;transition:all .15s;'
          +(active ? 'background:rgba(116,198,157,.25);border:1.5px solid rgba(116,198,157,.5);color:rgba(116,198,157,.9)'
                   : 'background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.45)')
          +'">'+t.label+(t.count ? ' <span style="opacity:.7">('+t.count+')</span>' : '')+'</button>';
      }).join('')
    +'</div>';

  var filtered = (msgs||[]).filter(function(m){
    if(_adminContactFilter === 'unread')    return !m.leido;
    if(_adminContactFilter === 'pre-login') return m.source === 'pre-login';
    if(_adminContactFilter === 'logged-in') return m.source === 'logged-in';
    return true;
  });

  if(!filtered.length){
    el.innerHTML = tabsHtml + '<p style="font-size:14px;color:rgba(255,255,255,.3);padding:12px 0">Sin mensajes en esta categoría.</p>';
    return;
  }

  el.innerHTML = tabsHtml + filtered.map(function(m, idx){
    var realIdx = _adminContactsCache.indexOf(m);
    var texto    = m.mensaje || m.msg || '';
    var mid      = m.id || '';
    var fecha    = m.fecha ? new Date(m.fecha).toLocaleString('es',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
    var email    = m.user_email || m.email || '';
    var name     = m.user_name  || '';
    var hasEmail = email && email !== 'anónimo';
    var isPreLogin = m.source === 'pre-login';
    var sourceBadge = isPreLogin
      ? '<span style="font-size:11px;padding:2px 6px;background:rgba(200,162,0,.15);border:1px solid rgba(200,162,0,.3);border-radius:20px;color:rgba(200,162,0,.8);font-weight:700">Pre-login</span>'
      : '<span style="font-size:11px;padding:2px 6px;background:rgba(116,198,157,.12);border:1px solid rgba(116,198,157,.25);border-radius:20px;color:rgba(116,198,157,.7);font-weight:700">Usuario</span>';

    return '<div class="a-row" style="flex-direction:column;align-items:flex-start;gap:8px;border-left:3px solid '+(m.leido?'rgba(255,255,255,.06)':'rgba(116,198,157,.5)')+';padding-left:10px;margin-bottom:2px">'
      // Header row
      +'<div style="display:flex;width:100%;align-items:flex-start;gap:10px">'
      +'<div style="width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0">'+(m.leido?'✉️':'📬')+'</div>'
      +'<div style="flex:1;min-width:0">'
        +'<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:3px">'
          +'<span style="font-size:15px;font-weight:700;color:rgba(255,255,255,.9)">'+_escHtml(name || email.split('@')[0] || 'Sin nombre')+'</span>'
          + sourceBadge
          +(m.leido ? '' : '<span style="font-size:11px;padding:2px 6px;background:rgba(255,160,50,.15);border:1px solid rgba(255,160,50,.3);border-radius:20px;color:rgba(255,180,80,.9);font-weight:700">NUEVO</span>')
        +'</div>'
        +(hasEmail ? '<div style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:2px">📧 '+_escHtml(email)+'</div>' : '')
        +'<div style="display:flex;align-items:center;gap:8px">'
          +'<span style="font-size:13px;font-weight:700;color:rgba(180,150,255,.7)">'+_escHtml(m.topic||'Consulta')+'</span>'
          +'<span style="font-size:12px;color:rgba(255,255,255,.25)">'+fecha+'</span>'
        +'</div>'
      +'</div>'
      +'</div>'
      // Message preview
      +(texto ? '<div style="font-size:14px;color:rgba(255,255,255,.55);line-height:1.55;padding:9px 12px;background:rgba(255,255,255,.03);border-radius:8px;border:1px solid rgba(255,255,255,.06);width:100%;box-sizing:border-box">'+_escHtml(texto.slice(0,300))+(texto.length>300?'…':'')+'</div>' : '')
      // Admin reply preview
      +(m.reply ? '<div style="font-size:13px;color:rgba(116,198,157,.7);padding:7px 10px;background:rgba(116,198,157,.06);border-radius:8px;width:100%;box-sizing:border-box"><strong>Tu respuesta:</strong> '+_escHtml(m.reply.slice(0,150))+'</div>' : '')
      // Action buttons
      +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
      +(!m.leido ? '<button onclick="pAdminMarkContactRead(\''+mid+'\')" style="font-size:12px;padding:4px 9px;background:rgba(116,198,157,.1);border:1px solid rgba(116,198,157,.2);color:rgba(116,198,157,.7);border-radius:6px;cursor:pointer;font-family:\'Jost\',sans-serif">✓ Marcar leído</button>' : '')
      +(hasEmail ? '<button onclick="pAdminOpenReply('+realIdx+')" style="font-size:12px;padding:4px 9px;background:rgba(200,162,0,.12);border:1px solid rgba(200,162,0,.25);color:rgba(220,185,60,.85);border-radius:6px;cursor:pointer;font-family:\'Jost\',sans-serif;font-weight:600">📧 Responder</button>' : '<span style="font-size:12px;color:rgba(255,255,255,.2);padding:4px 0">Sin email de respuesta</span>')
      +'<button onclick="pAdminDeleteContact(\''+mid+'\')" style="font-size:12px;padding:4px 9px;background:rgba(220,50,50,.08);border:1px solid rgba(220,50,50,.18);color:rgba(220,100,100,.7);border-radius:6px;cursor:pointer;font-family:\'Jost\',sans-serif">🗑️</button>'
      +'</div>'
      +'</div>';
  }).join('');
}

function pAdminFilterContacts(filter){
  _adminContactFilter = filter;
  _renderAdminContactsList(_adminContactsCache);
}

async function pAdminDeleteContact(id){
  if(!confirm('¿Eliminar este mensaje de contacto?')) return;
  _initSupabase();
  if(sbClient){ sbClient.from('contacts').delete().eq('id',id).then(function(){}).catch(function(){}); }
  _adminContactsCache = _adminContactsCache.filter(function(m){ return m.id !== id; });
  // Also remove from localStorage
  var local = []; try{ local = JSON.parse(safeLS('get','velo_admin_contacts')||'[]'); }catch(e){}
  safeLS('set','velo_admin_contacts', JSON.stringify(local.filter(function(m){ return m.id !== id; })));
  _renderAdminContactsList(_adminContactsCache);
}

function pAdminOpenReply(idx){
  var m = _adminContactsCache[idx];
  if(!m) return;
  _adminReplyTarget = m;
  var preview = document.getElementById('adminReplyPreview');
  var txt     = document.getElementById('adminReplyText');
  var toggle  = document.getElementById('adminReplyAllowToggle');
  var name    = m.user_name || '';
  var email   = m.user_email || m.email || 'anónimo';
  var isPreLogin = m.source === 'pre-login';
  if(preview) preview.innerHTML =
    '<div style="margin-bottom:6px"><strong style="color:var(--ink)">Destinatario:</strong> '
      +_escHtml(name ? name+' &lt;'+email+'&gt;' : email)
      +' <span style="font-size:12px;background:'+(isPreLogin?'rgba(200,162,0,.15)':'rgba(116,198,157,.12)')+';border-radius:10px;padding:2px 6px;color:'+(isPreLogin?'#b8920a':'var(--sage)')+';">'+(isPreLogin?'Pre-login':'Usuario')+'</span></div>'
    +'<div style="margin-bottom:6px"><strong style="color:var(--ink)">Asunto:</strong> '+_escHtml(m.topic||'Consulta')+'</div>'
    +'<div style="border-top:1px solid var(--border2);padding-top:8px;margin-top:6px"><em style="font-size:13px;color:var(--ink4)">Mensaje original:</em><br>'
      +'<span style="font-size:14px;color:var(--ink3)">'+_escHtml((m.mensaje||m.msg||'').slice(0,300))+'</span></div>';
  if(txt)    txt.value = name ? 'Hola '+name+',\n\n' : '';
  if(toggle) toggle.checked = false;
  openModal('adminReplyOv');
}

async function pAdminSendReply(){
  if(!_adminReplyTarget){ pToast('⚠️','Sin destinatario'); return; }
  var txt    = document.getElementById('adminReplyText');
  var toggle = document.getElementById('adminReplyAllowToggle');
  if(!txt || !txt.value.trim()){ pToast('✍️','Escribí tu respuesta'); return; }
  var toEmail = _adminReplyTarget.user_email || _adminReplyTarget.email;
  var toName  = _adminReplyTarget.user_name  || '';
  if(!toEmail || toEmail === 'anónimo'){ pToast('⚠️','Este usuario no tiene email registrado'); return; }
  var btn = document.querySelector('#adminReplyOv .p-btn--primary');
  if(btn){ btn.disabled = true; btn.textContent = 'Enviando...'; }
  try{
    var r = await fetch('/api/send-email',{
      method:'POST', headers:_aiHeaders(),
      body: JSON.stringify({ email:toEmail, name:toName, type:'admin-reply',
        topic:_adminReplyTarget.topic||'Consulta', reply:txt.value.trim(), allowReply:!!(toggle&&toggle.checked) })
    });
    var json = await r.json();
    if(json.ok){
      pToast('💌','Respuesta enviada');
      closeModal('adminReplyOv');
      if(_adminReplyTarget.id){
        sbUpdateContactReply(_adminReplyTarget.id, txt.value.trim(), !!(toggle&&toggle.checked));
        pAdminMarkContactRead(_adminReplyTarget.id);
      }
    } else {
      pToast('⚠️','Error: '+(json.error||'desconocido'));
    }
  } catch(e){ pToast('⚠️','Error de conexión'); }
  finally{ if(btn){ btn.disabled=false; btn.textContent='Enviar respuesta 💌'; } }
}

async function pAdminMarkContactRead(id){
  // Try Supabase first
  await sbMarkContactRead(id);
  // Reload contacts
  var sbMsgs = await sbLoadContacts();
  if(sbMsgs){ _renderAdminContactsList(sbMsgs); return; }
  // Fallback: localStorage
  var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_admin_contacts')||'[]'); }catch(e){}
  var m = msgs.find(function(x){ return x.id === id; });
  if(m) m.leido = true;
  safeLS('set','velo_admin_contacts', JSON.stringify(msgs));
  _renderAdminContactsList(msgs);
}

function pAdminResolveFlag(id){ pAdminModerateFlag(id, 'accept'); }

// ── CONSENT LOG ─────────────────────────────────────────────
var _consentAllRecords = [];

async function pAdminLoadConsent(){
  _initSupabase();
  var el = document.getElementById('adminConsentLog');
  if(!el) return;
  if(!sbClient){ el.innerHTML = '<p style="font-size:14px;color:rgba(255,80,80,.5)">Sin conexión a Supabase.</p>'; return; }
  el.innerHTML = '<p style="font-size:14px;color:rgba(255,255,255,.3)">Cargando…</p>';
  try{
    var res = await sbClient.from('terms_acceptance').select('*').order('accepted_at',{ascending:false}).limit(500);
    _consentAllRecords = res.data || [];
    var inp = document.getElementById('consentSearch');
    _filterConsentLog(inp ? inp.value : '');
  }catch(e){
    el.innerHTML = '<p style="font-size:14px;color:rgba(255,80,80,.5)">Error al cargar: '+_escHtml(String(e))+'</p>';
  }
}

function _filterConsentLog(query){
  var el = document.getElementById('adminConsentLog');
  if(!el) return;
  var q = (query||'').toLowerCase().trim();
  var rows = q
    ? _consentAllRecords.filter(function(r){
        return (r.nombre||'').toLowerCase().includes(q) || (r.email||'').toLowerCase().includes(q);
      })
    : _consentAllRecords;
  if(!rows.length){
    el.innerHTML = '<p style="font-size:14px;color:rgba(255,255,255,.3);padding:8px 0">'+(q?'Sin resultados para "'+_escHtml(q)+'"':'Sin registros aún.')+'</p>';
    return;
  }
  var rolColor = { pro:'rgba(116,198,210,.8)', plus:'#c8a23e', user:'rgba(255,255,255,.3)' };
  el.innerHTML = '<div style="font-size:12px;color:rgba(255,255,255,.3);margin-bottom:8px">'+rows.length+' registro'+(rows.length!==1?'s':'')+'</div>'
    + rows.map(function(r){
      var d   = r.accepted_at ? new Date(r.accepted_at) : null;
      var dateStr = d ? (d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')
        +' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')+':'+String(d.getSeconds()).padStart(2,'0')+' UTC') : '—';
      var rol = r.rol||'user';
      var ver = r.version||'TOS-v1';
      return '<div style="background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);border-radius:10px;padding:11px 13px;margin-bottom:7px">'
        +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">'
        +'<span style="font-size:14px;font-weight:700;color:rgba(255,255,255,.8);flex:1">'+_escHtml(r.nombre||'—')+'</span>'
        +'<span style="font-size:11px;border:1px solid;border-radius:5px;padding:1px 6px;color:'+(rolColor[rol]||rolColor.user)+';border-color:'+(rolColor[rol]||rolColor.user)+'">'+rol.toUpperCase()+'</span>'
        +'<span style="font-size:11px;background:rgba(116,198,157,.1);color:rgba(116,198,157,.7);border-radius:5px;padding:1px 6px">'+ver+'</span>'
        +'<span style="font-size:12px;color:rgba(116,198,157,.7);font-weight:700">✓</span>'
        +'</div>'
        +'<div style="font-size:13px;color:rgba(255,255,255,.4);margin-bottom:3px">✉ '+_escHtml(r.email||'—')+'</div>'
        +'<div style="font-size:12px;color:rgba(255,255,255,.22);font-family:monospace">🕐 '+dateStr+'</div>'
        +'</div>';
    }).join('');
}

// action: 'accept' (contenido OK) · 'alert' (alertar al usuario) · 'delete' (eliminar) · 'alertdelete'
function pAdminModerateFlag(id, action){
  _initSupabase();
  if(!sbClient) return;
  var labels = { accept:'Reporte aceptado — contenido OK', alert:'Usuario alertado ⚠️',
    'delete':'Contenido eliminado 🗑️', alertdelete:'Usuario alertado y contenido eliminado' };
  sbClient.from('moderation_flags').update({ resolved:true, resolution:action, resolved_by:safeLS('get','velo_user_id')||'admin', resolved_at:new Date().toISOString() }).eq('id',id)
    .then(function(res){
      if(res&&res.error){ pToast('⚠️','Error al moderar: '+res.error.message); return; }
      var card = document.getElementById('modflag-'+id);
      if(card) card.remove();
      pToast('✅', labels[action] || 'Reporte resuelto');
      // Audit trail — log action in local audit log
      var _al=[]; try{_al=JSON.parse(safeLS('get','velo_audit_log')||'[]');}catch(e){}
      _al.unshift({tipo:'admin_moderation',ts:Date.now(),motivo:'Acción "'+action+'" en flag '+String(id).slice(0,8),detail:labels[action]||''});
      safeLS('set','velo_audit_log',JSON.stringify(_al.slice(0,100)));
    }).catch(function(){ pToast('⚠️','Error de conexión al moderar'); });
}

function pApproveTransfer(idx){
  var all = []; try{ all = JSON.parse(safeLS('get','velo_pending_transfers')||'[]'); }catch(e){}
  var pending = all.filter(function(t){ return t.ended && !t.paid; });
  if(!pending[idx]) return;
  var t = pending[idx];
  t.paid = true; t.paidAt = Date.now();
  var updated = all.map(function(x){ return x.ts===t.ts ? t : x; });
  safeLS('set','velo_pending_transfers', JSON.stringify(updated));
  var pro = _proData.find(function(p){ return p.id===t.proId; });
  var proAmt = Math.round((t.amount||0)*0.8*100)/100;
  pToast('💸','Transferencia $'+proAmt+' aprobada para '+(pro?pro.name:'el profesional')+' ✅');
  var inbox = []; try{ inbox = JSON.parse(safeLS('get','velo_inbox')||'[]'); }catch(e){}
  inbox.unshift({ id:'tr-'+Date.now(), tipo:'pago', icon:'💸', remitente:'Velo Admin', asunto:'Transferencia aprobada — $'+proAmt, extracto:'Tu pago de $'+proAmt+' fue aprobado.', cuerpo:'El pago por tu sesión del '+new Date(t.ts).toLocaleDateString('es')+' fue aprobado. Recibirás $'+proAmt+' '+(t.currency||'USD')+' en tu cuenta registrada.', leido:false, fecha:new Date().toLocaleDateString('es',{day:'2-digit',month:'short'}) });
  safeLS('set','velo_inbox', JSON.stringify(inbox.slice(0,100)));
  _updateInboxDot();
  _renderAdmin();
}

function pResolveAudit(idx){
  var audit = []; try{ audit = JSON.parse(safeLS('get','velo_audit_log')||'[]'); }catch(e){}
  if(audit[idx]){ audit[idx].resolved = true; audit[idx].resolvedAt = Date.now(); }
  safeLS('set','velo_audit_log', JSON.stringify(audit));
  pToast('✅','Evento resuelto');
  _renderAdmin();
}

function pResolveCrisis(localIdx){
  var audit = []; try{ audit = JSON.parse(safeLS('get','velo_audit_log')||'[]'); }catch(e){}
  var crisisEvents = audit.filter(function(a){ return a.tipo === 'crisis_detect'; });
  var target = crisisEvents[localIdx];
  if(target){
    var globalIdx = audit.indexOf(target);
    if(globalIdx >= 0){ audit[globalIdx].resolved = true; audit[globalIdx].resolvedAt = Date.now(); }
    safeLS('set','velo_audit_log', JSON.stringify(audit));
  }
  // Also try to update in Supabase
  if(sbClient && target){
    sbClient.from('reportes').update({estado:'resuelto'})
      .like('categoria','crisis%')
      .eq('created_at', new Date(target.ts).toISOString())
      .then(function(){}).catch(function(){});
  }
  pToast('✅','Crisis marcada como atendida');
  _renderAdmin();
}

async function _loadAdminCrisisFromSupabase(){
  var el = document.getElementById('adminCrisisSupabase');
  if(!el) return;
  var events = await sbLoadCrisisEvents();
  if(!events || !events.length){
    el.innerHTML = '';
    return;
  }
  el.innerHTML = '<div style="font-size:12px;color:rgba(255,180,80,.7);margin-bottom:8px;font-weight:600">📡 Desde servidor (todas las sesiones):</div>'
    + events.map(function(e){
        var date = new Date(e.created_at);
        var dateStr = date.toLocaleDateString('es',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
        var isOpen = e.estado === 'abierto';
        return '<div style="background:rgba(220,50,50,.06);border:1px solid rgba(220,50,50,.2);border-radius:8px;padding:10px;margin-bottom:6px">'
          +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">'
          +'<span style="font-size:12px;font-weight:700;color:'+(e.categoria==='crisis_alto'?'#ff4444':'#ffbb33')+'">'+e.categoria.replace('_',' ').toUpperCase()+'</span>'
          +'<span style="font-size:12px;color:rgba(255,255,255,.3)">'+dateStr+'</span>'
          +'</div>'
          +'<div style="font-size:13px;color:rgba(255,255,255,.5);line-height:1.45">'+_escHtml((e.mensaje||'').slice(0,150))+'</div>'
          +(isOpen ? '<button onclick="pSbResolveCrisis(\''+e.id+'\')" style="margin-top:8px;font-size:12px;padding:3px 10px;background:rgba(116,198,157,.15);border:1px solid rgba(116,198,157,.3);color:rgba(116,198,157,.85);border-radius:6px;cursor:pointer;font-family:\'Jost\',sans-serif">Marcar atendida</button>'
            : '<span style="font-size:12px;color:rgba(116,198,157,.7);font-weight:700;display:block;margin-top:6px">✓ Atendida</span>')
          +'</div>';
      }).join('');
}

async function pSbResolveCrisis(id){
  if(!sbClient) return;
  try{
    await sbClient.from('reportes').update({estado:'resuelto'}).eq('id', id);
    pToast('✅','Crisis atendida y registrada');
    _loadAdminCrisisFromSupabase();
  }catch(e){ pToast('⚠️','Error al actualizar'); }
}

async function pRunAiScan(){
  pToast('🤖','Gemini analizando contenido...');
  var allCircleIds = ['c1','c2','c3','c4','c5'];
  var userCircles = []; try{ userCircles = JSON.parse(safeLS('get','velo_circles')||'[]'); }catch(e){}
  var allIds = allCircleIds.concat(userCircles.map(function(c){ return c.id; }));

  // Collect recent messages
  var samples = [];
  allIds.forEach(function(cid){
    var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_circle_'+cid)||'[]'); }catch(e){}
    msgs.slice(0,20).forEach(function(m){
      if(m.text && m.text.trim()) samples.push({ cid:cid, text:m.text.slice(0,200) });
    });
  });
  // Also scan bottle messages (Mensajes al Mar)
  var bottles = []; try{ bottles = JSON.parse(safeLS('get','velo_my_bottles')||'[]'); }catch(e){}
  bottles.slice(0,20).forEach(function(b){
    if(b.text) samples.push({ cid:'mensajes-al-mar', text:b.text.slice(0,200) });
  });
  // Also scan help posts
  var helpPosts = []; try{ helpPosts = JSON.parse(safeLS('get','velo_help_posts')||'[]'); }catch(e){}
  helpPosts.slice(0,20).forEach(function(p){
    if(p.preview) samples.push({ cid:'sala-ayuda-posts', text:p.preview.slice(0,200) });
  });

  if(!samples.length){ pToast('✅','Sin mensajes para analizar.'); _renderAdmin(); return; }

  var prompt = 'Sos el sistema de moderación de Velo, una app de bienestar emocional entre pares.\n'
    +'Analizá estos mensajes de usuarios y detectá: (1) crisis suicidas o autolesiones, (2) acoso o agresión, (3) contenido inapropiado.\n'
    +'Para cada mensaje problemático respondé en formato JSON array:\n'
    +'[{"idx": N, "tipo": "crisis|acoso|inapropiado", "gravedad": "alta|media|baja", "razon": "...breve..."}]\n'
    +'Si no hay problemas respondé: []\n\n'
    +'Mensajes (índice | sala | texto):\n'
    + samples.map(function(s,i){ return i+'|'+s.cid+'|'+s.text; }).join('\n');

  var aiResult = await _geminiCall(prompt);
  var flagged = [];
  if(aiResult){
    try{
      var match = aiResult.match(/\[[\s\S]*\]/);
      if(match){ flagged = JSON.parse(match[0]); }
    }catch(e){}
  }

  if(flagged.length){
    var audit = []; try{ audit = JSON.parse(safeLS('get','velo_audit_log')||'[]'); }catch(e){}
    flagged.forEach(function(f){
      var sample = samples[f.idx] || {};
      audit.unshift({ ts:Date.now(), tipo:'abuse_detect', circle:sample.cid||'?',
        motivo:'Gemini IA — '+f.tipo+' (gravedad: '+f.gravedad+'): '+f.razon,
        detail:(sample.text||'').slice(0,80) });
    });
    safeLS('set','velo_audit_log', JSON.stringify(audit.slice(0,500)));
    pToast('⚠️','Gemini detectó '+flagged.length+' evento(s). Ver auditoría.');
  } else {
    pToast('✅','Gemini: contenido limpio. Sin alertas.');
  }
  _renderAdmin();
}

function pViewPatterns(){
  var audit = []; try{ audit = JSON.parse(safeLS('get','velo_audit_log')||'[]'); }catch(e){}
  var circles = 0;
  ['c1','c2','c3','c4','c5'].forEach(function(cid){
    var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_circle_'+cid)||'[]'); }catch(e){}
    circles += msgs.length;
  });
  pToast('📊','Círculos: '+circles+' mensajes · Reportes: '+audit.length+'. Patrón saludable. 🌿');
}

