  // ── AI narrative ──
  html+='<div style="font-size:14px;color:rgba(255,255,255,.78);line-height:1.85;white-space:pre-line;margin-bottom:20px;border-left:2px solid rgba(180,140,220,.3);padding-left:14px">'+_escHtml(data.narrative||'')+'</div>';

  // ── Affirmation / mantra ──
