  var moodBgs    = {'😄':'rgba(116,198,157,.22)','😊':'rgba(149,213,178,.18)','😐':'rgba(233,185,73,.18)','😞':'rgba(224,122,95,.15)','😢':'rgba(212,91,91,.18)'};
