function pSendContactModal(ov){
  var msg        = ov ? ov.querySelector('[data-cus-msg]')   : null;
  var topic      = ov ? ov.querySelector('[data-cus-topic]') : null;
  var emailInput = ov ? ov.querySelector('[data-cus-email]') : null;
  var nameInput  = ov ? ov.querySelector('[data-cus-name]')  : null;
  var email = safeLS('get','velo_user_email') || (emailInput ? emailInput.value.trim() : '');
  var name  = safeLS('get','velo_user_name')  || (nameInput  ? nameInput.value.trim()  : '');
  if(nameInput  && !name){ pToast('👤','Ingresá tu nombre'); return; }
  if(emailInput && (!email || !email.includes('@'))){ pToast('📧','Ingresá un correo válido para responderte'); return; }
  if(!msg || !msg.value.trim()){ pToast('✍️','Escribí tu mensaje'); return; }
  var text     = msg.value.trim();
  var topicVal = topic ? topic.value : 'Consulta general';
  var userId   = safeLS('get','velo_user_id') || '';
  var source   = _authenticated ? 'logged-in' : 'pre-login';
  var ts = Date.now();
  var msgs = []; try{ msgs = JSON.parse(safeLS('get','velo_admin_contacts')||'[]'); }catch(e){}
  msgs.unshift({ id:'c-'+ts, topic:topicVal, mensaje:text, user_email:email||'anónimo', user_name:name, user_id:userId, source:source, fecha:new Date().toISOString(), leido:false });
  safeLS('set','velo_admin_contacts', JSON.stringify(msgs.slice(0,200)));
  sbSaveContact(topicVal, text, email||'anónimo', name, userId, source).catch(function(){});
  if(ov) ov.remove();
  pToast('💌','¡Mensaje enviado'+(name ? ', '+name:'')+'! Te respondemos pronto 💚');
}

// Fake live counters removed — real-time data requires Supabase presence channels

// ── SCROLL REVEAL (landing) ───────────────────────────────────
function _initReveal(){
  if(!window.IntersectionObserver) return;
  var obs = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){
        e.target.classList.add('visible');
        obs.unobserve(e.target);
      }
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
  document.querySelectorAll('.reveal').forEach(function(el){ obs.observe(el); });
}

// ── PER-PAGE INIT DISPATCHER ──────────────────────────────────
function _onPageEnter(id){
  if(id !== 'home'){
    _stopHomeRefresh(); // stop live refresh when leaving home
    if(_homeVibesRtCh){ _sbUnsub(_homeVibesRtCh); _homeVibesRtCh = null; }
    // v1515: la Pregunta del Día vive en el home — al salir, frenar sus polls
    // (feed 15s, reacciones 20s) y el tick del countdown (60s). Antes seguían
    // consultando la base desde cualquier sección (batería/datos).
    try{ _stopDqReactPoll(); }catch(_){}
    if(_dqTimerInterval){ clearInterval(_dqTimerInterval); _dqTimerInterval = null; }
  }
  if(id !== 'dm-chat'){
    // v1515: al salir de un DM por la barra de nav (sin "Salir"), frenar los
    // polls (reacciones 8s, presencia 30s) que quedaban zombies. Se conserva
    // _dmPeer y el canal realtime para re-entrar sin perder el hilo.
    if(_dmReactPollTmr){ clearInterval(_dmReactPollTmr); _dmReactPollTmr = null; }
    try{ _stopDMPresenceRefresh(); }catch(_){}
  }
  if(id !== 'meditacion') pCloseMeditation(); // stop audio/timers when leaving meditation
  if(id !== 'guardians' && _guardianListPollTmr){ clearInterval(_guardianListPollTmr); _guardianListPollTmr = null; }
  switch(id){
    case 'landing':     _initReveal(); break;
    case 'register':    _botGuardInit(); break;
    case 'pro-reg':     _botGuardInit(); break;
    case 'home':
      _loadHomeData(); _startHomeRefresh(); try{ _renderHomeVibesCard(); }catch(_){}
      _initSupabase();
      if(_homeVibesRtCh){ _sbUnsub(_homeVibesRtCh); _homeVibesRtCh = null; }
      if(sbClient) _homeVibesRtCh = _sbSub('velo:home:vibes', 'vibes', function(){
        // v1374: real-time — si alguien publica un vibe mientras estoy en el
        // home, el widget "Vibes de hoy" se actualiza solo, sin necesitar
        // cambiar de sección. Debounce corto por si llegan varios INSERTs juntos.
        if(_curPage !== 'home') return;
        if(_homeVibesRtTmr) clearTimeout(_homeVibesRtTmr);
        _homeVibesRtTmr = setTimeout(function(){ try{ _renderHomeVibesCard(); }catch(_){} }, 600);
      });
      break;
    case 'guardians':
      _initSupabase();
      // Always re-subscribe so a stale/dropped channel doesn't silently miss re-activation events.
      if(_guardianRtCh){ _sbUnsub(_guardianRtCh); _guardianRtCh = null; }
      if(sbClient) _guardianRtCh = _sbSub('velo:guardians', 'guardian_presence', function(){
        // v1601: no re-renderizar si ya no estás en la sección (el canal sigue vivo
        // toda la sesión) — antes consultaba la DB y reconstruía la lista desde
        // cualquier otra pantalla, gastando datos/batería y reseteando el scroll.
        if(_curPage !== 'guardians') return;
        pRenderGuardians();
      });
      // Re-create broadcast channel if it was CLOSED/nulled (e.g. WebSocket drop).
      _initSupabase(); _createGuardianBcastCh();
      pRenderGuardians();
      if(_guardianListPollTmr){ clearInterval(_guardianListPollTmr); _guardianListPollTmr = null; }
      _guardianListPollTmr = setInterval(function(){
        if(_curPage !== 'guardians'){ clearInterval(_guardianListPollTmr); _guardianListPollTmr = null; return; }
        pRenderGuardians();
      }, 15000);
      break;
    case 'professionals': pRenderProfessionals(); break;
    case 'help':
      _initSupabase();
      // v1434: SIEMPRE re-suscribir (un canal viejo/caído dejaba de traer los
      // pedidos nuevos en vivo → solo aparecían al refrescar).
      if(_helpRtCh){ _sbUnsub(_helpRtCh); _helpRtCh = null; }
      if(sbClient) _helpRtCh = _sbSub('velo:help', 'help_posts', function(){ if(_curPage !== 'help') return; pRenderHelp(); }); // v1601: guard de sección
      // Re-suscribir al seeker a SU pedido pendiente para recibir ofertas de
      // guardián en vivo aunque haya navegado y vuelto (incluye pedidos anónimos).
      // v1441: suscribir SIEMPRE (por seeker_id) — así recibís ofertas de guardián
      // de cualquiera de tus pedidos activos, aunque los hayas hecho en otro momento
      // o dispositivo, y sin importar si fueron públicos o anónimos.
      try{ if(sbClient) _subscribeSeekerToGuardianRequest(safeLS('get','velo_my_help_post_id')||''); }catch(_){}
      pRenderHelp();
      _checkPendingSupportMessages();
      break;
    case 'help-chat':   /* initialized by pAccompanyHelp */ break;
    case 'bottle':
      _initSupabase();
      // v1450: SIEMPRE re-suscribir — un canal viejo/caído dejaba de traer
      // botellas nuevas en vivo (solo aparecían al refrescar).
      if(_bottleRtCh){ _sbUnsub(_bottleRtCh); _bottleRtCh = null; }
      if(sbClient) _bottleRtCh = _sbSub('velo:bottles', 'bottles', function(){ if(_curPage !== 'bottle') return; pRenderBottle(); }); // v1601: guard de sección
      pRenderBottle();
      try{ setTimeout(function(){ _maybeShowFeatureHints('bottle'); }, 1400); }catch(e){}
      break;
    case 'diary':       pInitDiary(); break;
    case 'momento':     _loadMomentoPageFeed(); _initMomentoPage(); break;
    case 'mood':        pInitMood(); break;
    case 'respira':     pInitRespira(); break;
    case 'meditacion':  pInitMeditacion(); break;
    case 'vela':        pInitVela(); break;
    case 'circles':     pRenderCircles(); break;
    case 'bitacora':    pInitBitacora(); break;
    case 'feed':        _renderCircleMessages(); break;
    case 'happy':
      _initSupabase();
      // v1450: SIEMPRE re-suscribir (canal viejo/caído dejaba de traer posts en vivo).
      if(_happyRtCh){ _sbUnsub(_happyRtCh); _happyRtCh = null; }
      if(sbClient) _happyRtCh = _sbSub('velo:happy', 'happy_posts', function(){ if(_curPage !== 'happy') return; pRenderHappy(); }); // v1601: guard de sección
      pRenderHappy();
      break;
    case 'profile':
      pLoadProfile();
      (function(){ var _pgUid = safeLS('get','velo_user_id'); if(_pgUid) _sbSyncProfile(_pgUid).then(function(){ pLoadProfile(); }).catch(function(){}); })();
      break;
    case 'inbox':       pRenderInbox(); break;
    case 'contacts':    pRenderContacts(); break;
    case 'vibes':       pRenderVibesHome(); break;
    case 'dm-chat':
      // v1462: la pantalla se abre normalmente vía _enterDMChat (que renderiza),
      // pero al VOLVER a entrar (back, cambio de sección y regreso, restauración)
      // esto no corría y el chat quedaba EN BLANCO. Si hay un peer activo,
      // re-renderizamos el hilo y re-suscribimos (idempotente). Si no hay peer
      // (p.ej. restauración tras recarga), evitamos la pantalla vacía.
      if(_dmPeer && _dmPeer.id){
        try{ _renderDMThread(); }catch(_){}
        try{ _subscribeToDMThread(); }catch(_){}
        try{ _dmSubscribeToTyping(_dmPeer.id); _dmSubscribeToReadReceipts(_dmPeer.id); }catch(_){}
      } else {
        pGoTo('contacts');
      }
      break;
    case 'donation-exit': pInitDonation(); break;
    case 'session-room': pInitSessionRoom(); break;
    case 'post-chat':   pInitPostChat(); break;
    case 'pro-panel':   switchProPanel('inicio', document.querySelector('.pro-nav-item')); break;
    case 'admin':          _renderAdmin(); break;
    case 'contact':        _initContactPage(); break;
    case 'news':           pRenderNews(); break;
    case 'calm-ai':        _initCalmAIPage(); break;
    case 'guardian-chat':  _gcInit(); break;
    case 'change-password':
      var cpBack = document.getElementById('changePassBackRow');
      if(cpBack) cpBack.style.display = safeLS('get','velo_needs_pw_change') === '1' ? 'none' : 'block';
      break;
    case 'pick-username':
      // Reset form state when entering pick-username page
      var puInp = document.getElementById('pickUsernameInput');
      var puSt  = document.getElementById('pickUsernameStatus');
      var puBtn = document.getElementById('pickUsernameBtn');
      if(puInp) puInp.value = '';
      if(puSt)  puSt.innerHTML = '';
      if(puBtn){ puBtn.disabled = true; puBtn.style.opacity = '.5'; }
      break;
  }
}

// ── UTILITY ───────────────────────────────────────────────────
function _setEl(id, html){
  var el = document.getElementById(id);
  if(el) el.innerHTML = html;
}
function _escHtml(str){
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// ── INIT ON LOAD ──────────────────────────────────────────────
// ── MESSAGE REACTIONS + REPLY ────────────────────────────────────
var _msgCounter  = 0;
var _msgPopupData = null;

function _nextMsgId(){ return 'vmsg-'+(++_msgCounter); }

function _initMsgActions(){
  if(document.getElementById('msgActionsPopup')) return;
  var pop = document.createElement('div');
  pop.id = 'msgActionsPopup';
  pop.className = 'msg-actions-popup';
  pop.innerHTML = ['❤️','😢','💪','🙏','🌿','✨'].map(function(e){
    return '<button onclick="_msgReact(\''+e+'\')" title="'+e+'">'+e+'</button>';
  }).join('')
    +'<span class="msg-actions-divider"></span>'
    +'<button class="msg-reply-btn" onclick="_msgReplyAct()">↩ Responder</button>'
    +'<button class="msg-del-btn" onclick="_msgDeleteAct()" title="Borrar mensaje" style="display:none;background:none;border:none;color:rgba(220,80,80,.92);font-family:Jost,sans-serif;font-size:12.5px;font-weight:800;padding:6px 10px;cursor:pointer;border-radius:8px">🗑️ Borrar</button>';
  document.body.appendChild(pop);
  document.addEventListener('click', function(e){
    if(!e.target.closest('#msgActionsPopup') && !e.target.closest('.msg-action-btn')){
      pop.style.display = 'none'; _msgPopupData = null;
    }
  });
}
// Borrar mensaje mío del chat (borra para ambos vía DELETE en Supabase)
async function _msgDeleteAct(){
  var pop = document.getElementById('msgActionsPopup');
  if(pop) pop.style.display = 'none';
  var data = _msgPopupData; _msgPopupData = null;
  if(!data || !data.msgId) return;
  var msgEl = document.getElementById(data.msgId);
  if(!msgEl) return;
  var sbId = msgEl.getAttribute('data-sb-id') || '';
  // Confirmar (excepto para el propio flujo en curso)
  if(!confirm('¿Borrar este mensaje? Se elimina para vos y para tu contacto.')) return;
  // UI optimista
  msgEl.style.transition = 'opacity .18s';
  msgEl.style.opacity = '.35';
  // DELETE en Supabase — RLS solo deja borrar los propios
  if(sbId && sbClient){
    var parts = sbId.split(':');
    var table = parts[0], id = parts[1];
    if(table && id){
      try{
        var r = await sbClient.from(table).delete().eq('id', id);
        if(r && r.error){
          msgEl.style.opacity = '1';
          pToast('⚠️','No se pudo borrar — sólo podés borrar los mensajes que enviaste');
          return;
        }
      }catch(e){
        msgEl.style.opacity = '1';
        pToast('⚠️','Sin conexión');
        return;
      }
    }
  }
  // Quitar del DOM + refrescar cache del preview
  msgEl.remove();
  if(_dmPeer && _dmPeer.id){
    // Refrescar el último mensaje de la cache leyendo el último bubble visible
    var msgs = document.querySelectorAll('#dmMessages [data-sb-id]');
    if(msgs.length){
      var last = msgs[msgs.length-1];
      var lastBubble = last.querySelector('.feed-bubble');
      var lastTxt = lastBubble ? (lastBubble.textContent||'').replace(/\s+\d{1,2}:\d{2}\s*$/,'').trim().slice(0,140) : '';
      var isOwn = last.classList.contains('feed-msg--own');
      _dmCacheSet(_dmPeer.id, lastTxt || '(vacío)', isOwn);
    } else {
      // No queda ningún mensaje — limpiar cache
      var cache = _dmCacheGet(); delete cache[_dmPeer.id];
      try{ safeLS('set','velo_dm_last_msgs', JSON.stringify(cache)); }catch(e){}
    }
  }
  pToast('🗑️','Mensaje eliminado');
}

function pShowMsgActions(btn, msgId, text, inputId, replyBarId, senderName){
  _initMsgActions();
  _msgPopupData = { msgId:msgId, text:text, inputId:inputId, replyBarId:replyBarId, senderName:senderName||'' };
  var pop = document.getElementById('msgActionsPopup');
  if(!pop) return;
  // Mostrar "Borrar" solo si el mensaje es mío (feed-msg--own)
  var msgEl = document.getElementById(msgId);
  var isOwn = msgEl && msgEl.classList.contains('feed-msg--own');
  var delBtn = pop.querySelector('.msg-del-btn');
  if(delBtn) delBtn.style.display = isOwn ? 'inline-flex' : 'none';
  pop.style.display = 'flex';
  // v1405: clampear con el ANCHO/ALTO REAL del popup (ya visible) para que
  // nunca se salga de la pantalla en ningún eje.
  var rect = btn.getBoundingClientRect();
  var pw = pop.offsetWidth || 320, ph = pop.offsetHeight || 120;
  var left = rect.left + rect.width/2 - pw/2;
  left = Math.max(8, Math.min(window.innerWidth - pw - 8, left));
  var top = rect.top - ph - 8;
  if(top < 8) top = Math.min(rect.bottom + 8, window.innerHeight - ph - 8);
  pop.style.top  = Math.max(8, top) + 'px';
  pop.style.left = left + 'px';
}

function _msgReact(emoji, chipEl){
  var pop = document.getElementById('msgActionsPopup');
  if(pop) pop.style.display = 'none';
  var msgId = _msgPopupData ? _msgPopupData.msgId : null;
  // When called from an existing chip click, find the parent message element
  if(!msgId && chipEl){
    var _chipParent = chipEl.closest ? chipEl.closest('[data-sb-id]') : null;
    msgId = _chipParent ? _chipParent.id : null;
  }
  if(!msgId) return;
  var msgEl = document.getElementById(msgId);
  if(!msgEl) return;
  var rxBar = msgEl.querySelector('.msg-rx-bar');
  if(!rxBar){
    rxBar = document.createElement('div');
    rxBar.className = 'msg-rx-bar';
    var bubble = msgEl.querySelector('.feed-bubble');
    if(bubble) bubble.after(rxBar); else msgEl.appendChild(rxBar);
  }
  var existing = rxBar.querySelector('[data-emoji="'+emoji+'"]');
  if(existing){
    var c = parseInt(existing.getAttribute('data-cnt')||'1',10)+1;
    existing.setAttribute('data-cnt',c);
    existing.textContent = emoji+' '+c;
  } else {
    var chip = document.createElement('span');
    chip.className = 'msg-reaction mine';
    chip.setAttribute('data-emoji', emoji);
    chip.setAttribute('data-cnt', '1');
    chip.textContent = emoji+' 1';
    chip.onclick = function(){ _msgReactFromChip(chip, msgId); };
    rxBar.appendChild(chip);
  }
  // Save to Supabase (circle_messages or direct_messages)
  var sbId = msgEl.getAttribute('data-sb-id');
  if(sbId && sbClient){
    var updatedReactions = {};
    rxBar.querySelectorAll('.msg-reaction').forEach(function(ch){
      var e2 = ch.getAttribute('data-emoji');
      var c2 = parseInt(ch.getAttribute('data-cnt')||'1',10);
      if(e2) updatedReactions[e2] = c2;
    });
    var sbParts = sbId.split(':');
    var sbTable = sbParts.length > 1 ? sbParts[0] : 'circle_messages';
    var sbRowId = sbParts.length > 1 ? sbParts.slice(1).join(':') : sbId;
    sbClient.from(sbTable).update({ reactions: updatedReactions }).eq('id', sbRowId)
      .then(function(){}).catch(function(){});
  }
  _msgPopupData = null;
}

function _msgReactFromChip(chip, msgId){
  var cc = parseInt(chip.getAttribute('data-cnt')||'1',10)+1;
  chip.setAttribute('data-cnt',cc);
  chip.textContent = chip.getAttribute('data-emoji')+' '+cc;
  var msgEl = document.getElementById(msgId);
  var sbId = msgEl ? msgEl.getAttribute('data-sb-id') : null;
  if(sbId && sbClient){
    var updatedReactions = {};
    var rxBar = msgEl.querySelector('.msg-rx-bar');
    if(rxBar) rxBar.querySelectorAll('.msg-reaction').forEach(function(ch){
      var e2 = ch.getAttribute('data-emoji');
      var c2 = parseInt(ch.getAttribute('data-cnt')||'1',10);
      if(e2) updatedReactions[e2] = c2;
    });
    var sbParts2 = sbId.split(':');
    var sbTable2 = sbParts2.length > 1 ? sbParts2[0] : 'circle_messages';
    var sbRowId2 = sbParts2.length > 1 ? sbParts2.slice(1).join(':') : sbId;
    sbClient.from(sbTable2).update({ reactions: updatedReactions }).eq('id', sbRowId2)
      .then(function(){}).catch(function(){});
  }
}

function _msgReplyAct(){
  var pop = document.getElementById('msgActionsPopup');
  if(pop) pop.style.display = 'none';
  if(!_msgPopupData) return;
  var bar = document.getElementById(_msgPopupData.replyBarId);
  if(bar){
    bar.style.display = 'flex';
    var textEl = bar.querySelector('.reply-preview-text');
    var preview = _msgPopupData.text.length > 70 ? _msgPopupData.text.slice(0,70)+'…' : _msgPopupData.text;
    var namePrefix = _msgPopupData.senderName ? _msgPopupData.senderName+': ' : '';
    if(textEl) textEl.textContent = '↩  '+namePrefix+preview;
    bar.setAttribute('data-reply-text', _msgPopupData.text);
    bar.setAttribute('data-reply-name', _msgPopupData.senderName||'');
  }
  var inp = document.getElementById(_msgPopupData.inputId);
  if(inp){ inp.focus(); }
}

function pClearReplyBar(barId){
  var bar = document.getElementById(barId);
  if(!bar) return;
  bar.style.display = 'none';
  bar.removeAttribute('data-reply-text');
  bar.removeAttribute('data-reply-name');
}

function _getReplyQuote(barId){
  var bar = document.getElementById(barId);
  if(!bar || bar.style.display === 'none') return '';
  var text = bar.getAttribute('data-reply-text') || '';
  var name = bar.getAttribute('data-reply-name') || '';
  if(!text) return '';
  return name ? name+': '+text : text;
}

function _highlightMentions(text){
  var escaped = _escHtml(text);
  return escaped.replace(/@([\wÀ-ɏ]+)/g, '<span class="msg-mention">@$1</span>');
}

function _buildMsgBubble(text, isUser, av, senderName, inputId, replyBarId, quoteText, reactions, sbId, senderId){
  var id  = _nextMsgId();
  var t   = new Date();
  var ts  = t.getHours()+':'+(t.getMinutes()<10?'0':'')+t.getMinutes();
  var quotePart = quoteText ? '<div class="reply-quote">'+_escHtml(quoteText.slice(0,80)+(quoteText.length>80?'…':''))+'</div>' : '';
  // Detección de attachments de DM (audio / foto embebidos como marker + dataURL)
  // Se renderiza el contenido especial en vez del texto plano. El wrap normal
  // (avatar, timestamp, acciones, reacciones) se conserva.
  var attachHtml = '';
  var isAudioAttach = false, isImageAttach = false;
  if(typeof text === 'string'){
    var _audIdx = text.indexOf('__velo_dm_audio__:');
    var _imgIdx = text.indexOf('__velo_dm_image__:');
    if(_audIdx >= 0){
      var _audPipe = text.indexOf('|', _audIdx);
      var _audData = _audPipe >= 0 ? text.slice(_audPipe+1) : '';
      if(_audData){
        isAudioAttach = true;
        // Colores según lado del mensaje: own (verde) → texto cream, otro (dark) → texto ámbar
        // v1405: color legible según TEMA (no según lado). En claro el fondo
        // de la burbuja es blanco/verde pálido → ámbar oscuro; en oscuro →
        // ámbar claro. Antes usaba ámbar claro siempre → invisible en claro.
        var _isDarkTheme = document.body.classList.contains('r-dark');
        var _lblCol = _isDarkTheme ? '#f0d798' : '#8a5a08';
        var _subCol = _isDarkTheme ? 'rgba(240,215,155,.75)' : 'rgba(120,80,15,.90)';
        var _btnBg  = isUser ? 'rgba(255,220,120,.30)' : 'rgba(200,158,56,.32)';
        var _btnBrd = isUser ? 'rgba(255,240,180,.65)' : 'rgba(255,220,120,.55)';
        attachHtml = '<div class="dm-attach dm-attach--audio" data-attach-audio="'+_escHtml(_audData)+'" data-attach-ts="'+id+'"><div style="display:flex;align-items:center;gap:10px;padding:8px 4px;min-width:180px"><button type="button" onclick="_dmPlayAttachAudio(this)" style="width:38px;height:38px;border-radius:50%;background:'+_btnBg+';border:1.5px solid '+_btnBrd+';color:#fff;font-size:16px;cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center;padding:0">▶</button><div style="flex:1;font-family:Jost,sans-serif;font-size:12.5px;font-weight:800;color:'+_lblCol+';letter-spacing:.3px">🎙️ Nota de voz<div class="dm-attach-status" style="font-size:11px;font-weight:600;color:'+_subCol+';margin-top:2px">Tocá play para escuchar</div><div style="font-size:10px;font-weight:600;color:'+_subCol+';opacity:.8;margin-top:3px">🔕 Para escucharla, sacá el teléfono de silencio</div></div></div></div>';
      }
    } else if(_imgIdx >= 0){
      var _imgPipe = text.indexOf('|', _imgIdx);
      var _imgData = _imgPipe >= 0 ? text.slice(_imgPipe+1) : '';
      if(_imgData){
        isImageAttach = true;
        // Convertimos data URL → blob URL (iOS Safari).
        // v1599: CACHÉ por mensaje. El chat se re-renderiza entero en cada cambio
        // de reacción; antes eso creaba un blob NUEVO por cada imagen en cada
        // render sin liberar los viejos → fuga de memoria que crecía en chats con
        // fotos. Ahora se reutiliza el blob ya creado para ese mensaje.
        var _iBlobUrl = '';
        try{
          if(!window._dmImgBlobCache) window._dmImgBlobCache = {};
          var _ikey = sbId || (id ? String(id) : '') || _imgData.slice(-64);
          if(window._dmImgBlobCache[_ikey]){
            _iBlobUrl = window._dmImgBlobCache[_ikey];
          } else {
            var _ia = _imgData.split(','); var _im = _ia[0].match(/:(.*?);/); var _imime = _im?_im[1]:'image/jpeg';
            var _ib = atob(_ia[1]||''); var _iu8 = new Uint8Array(_ib.length);
            for(var _ii=0;_ii<_ib.length;_ii++) _iu8[_ii] = _ib.charCodeAt(_ii);
            _iBlobUrl = URL.createObjectURL(new Blob([_iu8],{type:_imime}));
            window._dmImgBlobCache[_ikey] = _iBlobUrl;
            // Tope del caché: liberar los más viejos para no crecer sin límite
            var _ick = Object.keys(window._dmImgBlobCache);
            if(_ick.length > 60){
              for(var _ic=0; _ic<_ick.length-40; _ic++){
                try{ URL.revokeObjectURL(window._dmImgBlobCache[_ick[_ic]]); }catch(_){}
                delete window._dmImgBlobCache[_ick[_ic]];
              }
            }
          }
        }catch(e){}
        attachHtml = '<div class="dm-attach dm-attach--img"><img src="'+_escHtml(_iBlobUrl || _imgData)+'" onclick="pOpenImageLightbox(this.src)" style="max-width:220px;max-height:280px;border-radius:12px;display:block;cursor:zoom-in;border:1.5px solid rgba(180,155,240,.45)"></div>';
      }
    }
  }
  var bodyContent = attachHtml || _highlightMentions(text);
  var actionText = (isAudioAttach || isImageAttach) ? (isAudioAttach ? '🎙️ Nota de voz' : '📷 Foto') : text;
  var actionBtn = '<button class="msg-action-btn" onclick="pShowMsgActions(this,'+_jsAttr(id)+','+_jsAttr(actionText)+','+_jsAttr(inputId)+','+_jsAttr(replyBarId)+','+_jsAttr(isUser?'':senderName||'')+',\'\')" aria-label="Acciones">•••</button>';
  var sbAttr = sbId ? ' data-sb-id="'+sbId+'"' : '';
  var rxHtml = '';
  if(reactions && typeof reactions === 'object'){
    var chips = Object.keys(reactions).map(function(e){
      var cnt = reactions[e]||1;
      return '<span class="msg-reaction" data-emoji="'+e+'" data-cnt="'+cnt+'" onclick="_msgReact(\''+e+'\',this)">'+e+' '+cnt+'</span>';
    }).join('');
    if(chips) rxHtml = '<div class="msg-rx-bar">'+chips+'</div>';
  }
  if(isUser){
    safeLS('set','velo_total_msgs', String(parseInt(safeLS('get','velo_total_msgs')||'0',10)+1));
    return '<div class="feed-msg feed-msg--own" id="'+id+'"'+sbAttr+' style="position:relative">'
      +'<div class="msg-wrap">'
      +actionBtn
      +'<div class="feed-bubble feed-bubble--own">'+quotePart+bodyContent+'<span class="feed-time">'+ts+'</span></div>'
      +'</div>'+rxHtml+'</div>';
  } else {
    var _isAnonSender = !senderName || senderName === 'Usuario Anónimo' || senderName === 'Anónimo' || senderName === 'Guardián Anónimo';
    var canProfile = !_isAnonSender;
    var avClickAttr = canProfile
      ? ' style="cursor:pointer" onclick="pQuickProfile('+_jsAttr(senderName)+','+_jsAttr(av||'🌿')+',\'\',\'\','+_jsAttr(senderId||'')+')"'
      : '';
    // Never look up the real username for anonymous senders — the UID would expose their identity.
    var _sUname = (!_isAnonSender && senderId) ? _uLook(senderId) : '';
    var _sUnameTag = _sUname ? '<span style="font-size:11px;display:block;color:var(--ink5);font-weight:500;margin-top:0px;line-height:1.2">@'+_escHtml(_sUname)+'</span>' : '';
    var senderHtml = canProfile
      ? '<div class="feed-sender" style="font-size:13px;color:var(--ink4);cursor:pointer;line-height:1.2" onclick="pQuickProfile('+_jsAttr(senderName)+','+_jsAttr(av||'🌿')+',\'\',\'\','+_jsAttr(senderId||'')+')">'+_escHtml(senderName)+_sUnameTag+'</div>'
      : '<div class="feed-sender" style="font-size:13px;color:var(--ink4)">'+(senderName||'')+'</div>';
    return '<div class="feed-msg" id="'+id+'"'+sbAttr+' style="position:relative">'
      +'<div class="feed-av"'+avClickAttr+'>'+_avInline(av||'🌿',36)+'</div>'
      +'<div>'+senderHtml
      +'<div class="msg-wrap">'
      +'<div class="feed-bubble">'+quotePart+bodyContent+'<span class="feed-time">'+ts+'</span></div>'
      +actionBtn
      +'</div>'+rxHtml+'</div></div>';
  }
}

// ── BITÁCORA ─────────────────────────────────────────────────────
var _btPosts = {apoyo:[],superacion:[],debate:[],mio:[]};
// Helper: empty reaction map entry — keeps postura vote and emoji reaction independent
function _btEmptyRx(prev){ return {resuena:0,ayudo:0,cambio:0,apoyo_a:0,apoyo_b:0,apoyo_te:0,entiendo:0,abrazo:0,acompano:0,inspiro:0,concuerdo:0,no_concuerdo:0,neutral:0,mine_postura:(prev?prev.mine_postura:''),mine_rx:(prev?prev.mine_rx:''),mine_gen:(prev?prev.mine_gen:'')}; }
function _btIsPostura(t){ return t==='apoyo_a'||t==='apoyo_b'; }
function _btIsGenRx(t){ return t==='concuerdo'||t==='no_concuerdo'||t==='neutral'||t==='ayudo'; }
// Category reaction buttons for apoyo/superacion — used by _btOpenDetail and _btReact inline refresh
function _btGenCatRxHtml(postId,category,rx,c){
  if(category==='apoyo'){
    var _dA=[{key:'apoyo_te',emoji:'🫂',label:'Te apoyo'},{key:'entiendo',emoji:'💙',label:'Te entiendo'},{key:'abrazo',emoji:'🤗',label:'Te abrazo'},{key:'acompano',emoji:'🕊️',label:'Te acompaño'}];
    return '<div id="btCatRx_'+postId+'" style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:14px">'
      +_dA.map(function(rd){ var act=rx.mine_rx===rd.key; var n=rx[rd.key]||0;
        return '<button onclick="_btReact(\''+postId+'\',\''+rd.key+'\')" style="padding:7px 8px;border-radius:10px;border:1.5px solid '+c.border.replace(/[\d.]+\)$/,(act?'.70':'.22)'))+';background:'+(act?c.strip:'rgba(255,255,255,.05)')+';color:'+c.label+';font-family:Jost,sans-serif;cursor:pointer;display:flex;align-items:center;gap:6px;-webkit-tap-highlight-color:transparent;touch-action:manipulation"><span style="font-size:16px;line-height:1;flex-shrink:0">'+rd.emoji+'</span><span style="font-size:13px;font-weight:700;flex:1;text-align:left">'+rd.label+'</span>'+(n>0?'<span style="font-size:11px;opacity:.60;flex-shrink:0">'+n+'</span>':'')+'</button>';
      }).join('')+'</div>';
  }
  var _dS=[{key:'resuena',emoji:'✨',label:'Resuena'},{key:'inspiro',emoji:'🌟',label:'Me inspiró'},{key:'cambio',emoji:'💡',label:'Me cambió'}];
  return '<div id="btCatRx_'+postId+'" style="display:flex;gap:6px;margin-bottom:14px">'
    +_dS.map(function(rd){ var act=rx.mine_rx===rd.key; var n=rx[rd.key]||0;
      return '<button onclick="_btReact(\''+postId+'\',\''+rd.key+'\')" style="flex:1;padding:7px 4px;border-radius:10px;border:1.5px solid '+c.border.replace(/[\d.]+\)$/,(act?'.65':'.22)'))+';background:'+(act?c.strip:'rgba(255,255,255,.05)')+';color:'+c.label+';font-family:Jost,sans-serif;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;-webkit-tap-highlight-color:transparent;touch-action:manipulation"><span style="font-size:15px;line-height:1">'+rd.emoji+'</span><span style="font-size:13px;font-weight:700">'+rd.label+'</span>'+(n>0?'<span style="font-size:11px;opacity:.65"> '+n+'</span>':'')+'</button>';
    }).join('')+'</div>';
}
// Global postura card builder — used by _btOpenDetail and _btReact inline refresh
function _btMkPosturaCard(postId,key,label,desc,pct,active,c){
  var bord=c.border.replace(/[\d.]+\)$/,(active?'.65':'.25)'));
  var bg=active?c.strip:'rgba(255,255,255,.05)';
  var rxData=_btReactMap[postId]||_btEmptyRx();
  var hasVoted=rxData.mine_postura;
  var voteCount=rxData[key]||0;
  var voteTxt=voteCount===0?'Sin votos':voteCount+(voteCount===1?' persona':' personas');
  return '<div onclick="_btReact(\''+postId+'\',\''+key+'\')" style="flex:1;border:1.5px solid '+bord+';border-radius:14px;background:'+bg+';cursor:pointer;overflow:hidden">'
    +'<div style="padding:10px 12px 8px">'
      +'<div style="font-size:11px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:rgba(255,255,255,.50);font-family:Jost,sans-serif;margin-bottom:5px">'+label+'</div>'
      +(desc?'<div style="font-size:14px;color:rgba(255,255,255,.92);font-family:\'Cormorant Garamond\',serif;font-style:italic;line-height:1.4;margin-bottom:8px">'+_escHtml(desc)+'</div>':'')
      +'<div style="display:flex;align-items:center;justify-content:space-between">'
        +'<div style="height:4px;flex:1;border-radius:2px;background:rgba(255,255,255,.12);overflow:hidden;margin-right:8px">'
          +'<div style="height:100%;width:'+pct+'%;background:'+c.strip+';border-radius:2px"></div>'
        +'</div>'
        +'<span style="font-size:13px;font-weight:800;color:rgba(255,255,255,.90);font-family:Jost,sans-serif">'+pct+'%</span>'
      +'</div>'
      +'<div style="font-size:11px;color:rgba(255,255,255,.38);font-family:Jost,sans-serif;margin-top:4px">'+voteTxt+'</div>'
    +'</div>'
    +(active
      ?'<div style="background:'+c.strip+';padding:4px 12px;text-align:center;font-size:12px;font-weight:700;color:rgba(255,255,255,.95);font-family:Jost,sans-serif">✓ Tu voto</div>'
      :(hasVoted?'':'<div style="padding:4px 12px;text-align:center;font-size:11px;color:rgba(255,255,255,.35);font-family:Jost,sans-serif">Toca para votar</div>')
    )
  +'</div>';
}
