function _btTabBtn(type,label){
  var isLight=!document.body.classList.contains('r-dark');
  var c=isLight?(_btColorsLight[type]||_btColorsLight.apoyo):(_btColors[type]||_btColors.apoyo);
  return '<button id="btTab-'+type+'" onclick="_btSwitchTab(\''+type+'\')" style="flex-shrink:0;padding:9px 12px;border-radius:14px;border:1.5px solid '+c.border+';background:'+c.bg+';color:'+c.label+';font-size:13px;font-weight:700;font-family:Jost,sans-serif;cursor:pointer;opacity:.50;transition:opacity .2s,box-shadow .2s,transform .2s;white-space:nowrap">'+label+'</button>';
}

var _btTabDescs = {
  apoyo:      '🫂 ¿Estás pasando un momento difícil? Compartí tu historia o dejá un mensaje de aliento a quien lo necesita. Aquí nadie juzga.',
  superacion: '⭐ Historias de personas que superaron algo muy duro. Compartí lo que te costó y lo que aprendiste — puede cambiarle la vida a alguien.',
  debate:     '💬 Temas que generan perspectivas distintas. Publicá un dilema, elegí dos posturas y que la comunidad vote y opine con respeto.',
  mio:        '📝 Tus publicaciones en Bitácora — las historias y mensajes que compartiste con la comunidad.',
  guardados:  '📌 Las publicaciones que seguís — guardadas para volver a ellas cuando quieras.'
};

function _btSwitchTab(type){
  _btCurrentTab=type;
  _btTemaFilter='';
  _btSearchQ='';
  _btSortMode='recent';
  var isLight=!document.body.classList.contains('r-dark');
  ['apoyo','superacion','debate','mio','guardados'].forEach(function(t){
    var btn=document.getElementById('btTab-'+t);
    if(!btn) return;
    if(t==='guardados'){
      if(t===type){ btn.style.opacity='1'; btn.style.boxShadow='0 4px 18px rgba(165,95,230,.30),inset 0 1px 0 rgba(255,255,255,.12)'; btn.style.transform='translateY(-1px)'; }
      else { btn.style.opacity='.48'; btn.style.boxShadow='none'; btn.style.transform='none'; }
      return;
    }
    var c=isLight?(_btColorsLight[t]||_btColorsLight.apoyo):(_btColors[t]||_btColors.apoyo);
    if(t===type){ btn.style.opacity='1'; btn.style.boxShadow='0 4px 18px '+c.glow+',inset 0 1px 0 rgba(255,255,255,.12)'; btn.style.transform='translateY(-1px)'; }
    else { btn.style.opacity='.48'; btn.style.boxShadow='none'; btn.style.transform='none'; }
  });
  var desc=document.getElementById('btTabDesc');
  if(desc) desc.textContent=_btTabDescs[type]||'';
  var srch=document.getElementById('btSearch');
  if(srch) srch.value='';
  if(type==='guardados'){
    _btUpdateTemaFilter();
    _btRenderGuardados();
    return;
  }
  _btUpdateTemaFilter();
  // Always reload — render cached immediately then refresh from DB
  _btLoadTab(type,false);
}

function _btLoadTab(type,refresh){
  if(!sbClient) return;
  var feed=document.getElementById('btFeed');
  // Always render cached immediately — even when a prior load is in progress
  if(_btPosts[type]&&_btPosts[type].length){
    if(_btCurrentTab===type) _btRenderFeed(type);
  } else if(!_btLoading&&feed&&_btCurrentTab===type){
    var _ldCl=!document.body.classList.contains('r-dark')?'rgba(40,75,55,.50)':'rgba(180,200,190,.40)';
    feed.innerHTML='<div style="text-align:center;padding:40px 0;color:'+_ldCl+';font-family:Jost,sans-serif;font-size:15px">Cargando...</div>';
  }
  if(_btLoading){ return; }
  _btLoading=true;
  // Safety: clear the flag after 12s in case a query hangs
  var _btSafetyTimer=setTimeout(function(){ _btLoading=false; },12000);
  var query;
  if(type==='mio'){
    var uid0=safeLS('get','velo_user_id');
    if(!uid0){ clearTimeout(_btSafetyTimer); _btLoading=false; _btRenderFeed(type); return; }
    query=sbClient.from('bitacora_posts_full').select('*').eq('user_id',uid0).order('created_at',{ascending:false}).limit(50);
  } else {
    query=sbClient.from('bitacora_posts_full').select('*').eq('categoria',type).order('created_at',{ascending:false}).limit(15);
  }
  query.then(function(res){
    if(res.error){ clearTimeout(_btSafetyTimer); _btLoading=false; if(_btCurrentTab===type) _btRenderFeed(type); return; }
    _btPosts[type]=res.data||[];
    var ids=_btPosts[type].map(function(p){ return p.id; });
    if(!ids.length){ clearTimeout(_btSafetyTimer); _btLoading=false; if(_btCurrentTab===type) _btRenderFeed(type); return; }
    var uid=safeLS('get','velo_user_id');
    // Reset reaction counts (prevents accumulation on refresh), preserve mine_postura/mine_rx
    ids.forEach(function(id){
      _btReactMap[id]=_btEmptyRx(_btReactMap[id]);
    });
    var rxDone=false, cmtDone=false;
    function tryRender(){
      if(!rxDone||!cmtDone) return;
      clearTimeout(_btSafetyTimer);
      _btLoading=false;
      if(_btCurrentTab===type) _btRenderFeed(type);
    }
    sbClient.from('bitacora_reactions').select('post_id,reaction_type,user_id').in('post_id',ids)
      .then(function(rxRes){
        if(rxRes.data){
          rxRes.data.forEach(function(rx){
            var m=_btReactMap[rx.post_id];
            if(!m) return;
            if(typeof m[rx.reaction_type]==='number') m[rx.reaction_type]++;
            if(uid&&String(rx.user_id)===String(uid)){
              if(_btIsPostura(rx.reaction_type)) m.mine_postura=rx.reaction_type;
              else if(_btIsGenRx(rx.reaction_type)) m.mine_gen=rx.reaction_type;
              else m.mine_rx=rx.reaction_type;
            }
          });
        }
        rxDone=true; tryRender();
      }).catch(function(){ rxDone=true; tryRender(); });
    ids.forEach(function(id){ _btCommentCounts[id]=0; });
    sbClient.from('bitacora_comments_full').select('post_id').in('post_id',ids)
      .then(function(cmtRes){
        if(cmtRes.data){
          cmtRes.data.forEach(function(c){ _btCommentCounts[c.post_id]=(_btCommentCounts[c.post_id]||0)+1; });
        }
        cmtDone=true; tryRender();
      }).catch(function(){ cmtDone=true; tryRender(); });
  }).catch(function(){ clearTimeout(_btSafetyTimer); _btLoading=false; if(_btCurrentTab===type) _btRenderFeed(type); });
}

function _btRenderFeed(type){
  var feed=document.getElementById('btFeed');
  if(!feed) return;
  var posts=_btPosts[type]||[];
  var uid=safeLS('get','velo_user_id');
  posts=posts.filter(function(p){ return !_btHiddenIds.has(String(p.id))||String(p.user_id)===String(uid); });
  // Filtrar usuarios bloqueados
  posts=posts.filter(function(p){ return !_isBlocked(p.user_id); });
  // Apply tema filter
  if(_btTemaFilter){
    posts=posts.filter(function(p){
      var t=p.tema||_btAutoTema((p.titulo||'')+' '+(p.contenido||''));
      return t===_btTemaFilter;
    });
  }
  // Apply search filter
  if(_btSearchQ){
    posts=posts.filter(function(p){
      var haystack=((p.titulo||'')+' '+(p.contenido||'')+' '+(p.author_name||'')).toLowerCase();
      return haystack.indexOf(_btSearchQ)>=0;
    });
  }
  // Sort by relevance or recency
  if(_btSortMode==='relevante'){
    posts=posts.slice().sort(function(a,b){ return _btRelevanceScore(b)-_btRelevanceScore(a); });
  }
  if(!posts.length){
    var c0=_btColors[type]||_btColors.apoyo;
    var _esCl=!document.body.classList.contains('r-dark')?'rgba(40,75,55,.60)':'rgba(180,200,190,.50)';
    feed.innerHTML='<div style="text-align:center;padding:50px 0">'
      +'<div style="font-size:36px;margin-bottom:12px">'+c0.emoji+'</div>'
      +'<div style="font-size:15px;color:'+_esCl+';font-family:Jost,sans-serif;line-height:1.5">'+(_btSearchQ||_btTemaFilter?'Sin resultados para ese filtro.':'Aún no hay historias aquí.<br>¡Sé el primero en compartir!')+'</div>'
      +(!_btSearchQ&&!_btTemaFilter?'<button onclick="_btOpenCompose(\''+type+'\')" style="margin-top:16px;background:rgba(116,198,157,.10);border:1.5px solid rgba(116,198,157,.30);color:rgba(175,245,210,.88);font-size:14px;font-weight:700;font-family:Jost,sans-serif;border-radius:20px;padding:8px 20px;cursor:pointer">✦ Publicar</button>':'')
      +'</div>';
    return;
  }
  feed.innerHTML=posts.map(function(p,i){ return _btCard(p,i,uid); }).join('');
  var cards=feed.querySelectorAll('.bt-card');
  cards.forEach(function(c,i){ c.style.animationDelay=(i*0.06)+'s'; });
}

function _btRenderGuardados(){
  var feed = document.getElementById('btFeed');
  if(!feed) return;
  if(!_btSavedIds.length){
    feed.innerHTML = '<div style="text-align:center;padding:48px 16px;color:rgba(100,100,120,.55);font-size:14px">Todavía no seguís ninguna publicación.<br>Tocá <b>Seguir</b> en cualquier post para guardarlo acá.</div>';
    return;
  }
  // Collect all posts from all tabs
  var allPosts = (_btPosts.apoyo||[]).concat(_btPosts.superacion||[]).concat(_btPosts.debate||[]);
  var saved = allPosts.filter(function(p){ return _btSavedIds.indexOf(String(p.id)) >= 0; });
  if(!saved.length){
    // Posts not loaded yet — show loading message and load apoyo first
    feed.innerHTML = '<div style="text-align:center;padding:32px;color:rgba(100,100,120,.55);font-size:15px">Cargando publicaciones seguidas...</div>';
    return;
  }
  var _myUidBt=safeLS('get','velo_user_id');
  feed.innerHTML = saved.map(function(p){ return _btCard(p,0,_myUidBt); }).join('');
}

function _btCard(p,idx,uid){
  var isLight=!document.body.classList.contains('r-dark');
  var c=isLight?(_btColorsLight[p.categoria]||_btColorsLight.apoyo):(_btColors[p.categoria]||_btColors.apoyo);
  var titleColor=isLight?c.title:'rgba(255,255,255,.95)';
  var bodyColor=isLight?c.preview:'rgba(255,255,255,.80)';
  var debTrackColor=isLight?'rgba(0,0,0,.08)':'rgba(255,255,255,.10)';
  var reportBg=isLight?'rgba(0,0,0,.05)':'rgba(255,255,255,.06)';
  var reportBorder=isLight?'rgba(0,0,0,.10)':'rgba(255,255,255,.10)';
  var reportColor=isLight?'rgba(0,0,0,.30)':'rgba(255,255,255,.28)';
  var rx=_btReactMap[p.id]||_btEmptyRx();
  var isOwn=uid&&p.user_id&&String(p.user_id)===String(uid);
  var cmtCount=_btCommentCounts[p.id]||0;
  var name=p.is_anon?'Anónimo/a':(p.author_name||'Alguien');
  var avUrl=p.is_anon?'':(p.author_avatar||'');
  var avHtml;
  if(avUrl&&avUrl.startsWith('http')){
    avHtml='<img src="'+_escHtml(avUrl)+'" style="width:32px;height:32px;border-radius:50%;object-fit:cover;border:2px solid '+c.border+';flex-shrink:0">';
  } else if(avUrl&&!p.is_anon){
    avHtml='<div style="width:32px;height:32px;border-radius:50%;background:'+c.strip+';border:2px solid '+c.border+';display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0">'+_escHtml(avUrl)+'</div>';
  } else {
    avHtml='<div style="width:32px;height:32px;border-radius:50%;background:'+c.strip+';border:2px solid '+c.border+';display:flex;align-items:center;justify-content:center;font-size:15px;flex-shrink:0">'+c.emoji+'</div>';
  }
  var totRx=['resuena','ayudo','cambio','apoyo_te','entiendo','abrazo','acompano','inspiro','concuerdo','no_concuerdo','neutral','apoyo_a','apoyo_b'].reduce(function(s,k){ return s+(rx[k]||0); },0);
  // Username for @handle display
  var _btUname = !p.is_anon ? (p.author_username||_uLook(p.user_id)||'') : '';
  // Clickable author profile
  var _btCanClick = !p.is_anon && p.user_id;
  var _btProfileClick = _btCanClick
    ? 'event.stopPropagation();pQuickProfile('+_jsAttr(name)+','+_jsAttr(avUrl||'')+',\'\',\'\','+_jsAttr(p.user_id)+')'
    : '';
  // Extract debate posturas — columns first, then embedded backup in contenido
  var _pA=p.postura_a||'', _pB=p.postura_b||'';
  if(p.categoria==='debate'&&p.contenido){
    var _pm=p.contenido.match(/\[posturas:a=(.*?)\|b=(.*?)\]/);
    if(_pm){ if(!_pA) _pA=(_pm[1]||'').trim(); if(!_pB) _pB=(_pm[2]||'').trim(); }
  }
  var debBar='';
  if(p.categoria==='debate'){
    var totAB=(rx.apoyo_a||0)+(rx.apoyo_b||0);
    var pA=totAB>0?Math.round((rx.apoyo_a||0)/totAB*100):50;
    var pB=100-pA;
    var _pBox='border:1px solid '+c.border.replace(/[\d.]+\)$/,'.28)')+';border-radius:10px;padding:7px 9px;flex:1;min-width:0';
    debBar='<div style="margin:8px 0 4px;display:flex;gap:7px">'
      +'<div style="'+_pBox+'">'
        +'<div style="font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:'+c.label.replace(/[\d.]+\)$/,'.55)')+';font-family:Jost,sans-serif;margin-bottom:3px">Postura A</div>'
        +(_pA?'<div style="font-size:13px;color:'+bodyColor+';font-family:\'Cormorant Garamond\',serif;font-style:italic;line-height:1.35;margin-bottom:5px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">'+_escHtml(_pA)+'</div>':'')
        +'<div style="display:flex;align-items:center;gap:4px">'
          +'<div style="flex:1;height:3px;border-radius:2px;background:'+debTrackColor+';overflow:hidden"><div style="height:100%;width:'+pA+'%;background:'+c.strip+';border-radius:2px;transition:width .4s"></div></div>'
          +'<span style="font-size:11px;font-weight:700;color:'+c.label+';font-family:Jost,sans-serif">'+pA+'%</span>'
        +'</div>'
      +'</div>'
      +'<div style="'+_pBox+'">'
        +'<div style="font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:'+c.label.replace(/[\d.]+\)$/,'.55)')+';font-family:Jost,sans-serif;margin-bottom:3px">Postura B</div>'
        +(_pB?'<div style="font-size:13px;color:'+bodyColor+';font-family:\'Cormorant Garamond\',serif;font-style:italic;line-height:1.35;margin-bottom:5px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">'+_escHtml(_pB)+'</div>':'')
        +'<div style="display:flex;align-items:center;gap:4px">'
          +'<div style="flex:1;height:3px;border-radius:2px;background:'+debTrackColor+';overflow:hidden"><div style="height:100%;width:'+pB+'%;background:'+c.strip+';border-radius:2px;transition:width .4s"></div></div>'
          +'<span style="font-size:11px;font-weight:700;color:'+c.label+';font-family:Jost,sans-serif">'+pB+'%</span>'
        +'</div>'
      +'</div>'
    +'</div>';
  }
  return '<div class="bt-card" id="btCard_'+_escHtml(String(p.id))+'" onclick="_btOpenDetail('+_jsAttr(p.id)+')"'
    +' style="background:'+c.bg+';border:1px solid '+c.border.replace(/[\d.]+\)$/,'.25)')+';border-left:3px solid '+c.border+';box-shadow:0 3px 18px '+c.glow+';border-radius:16px;padding:14px 16px;cursor:pointer">'
    +'<div style="display:flex;align-items:center;gap:9px;margin-bottom:10px">'
      +(_btCanClick ? '<div onclick="'+_btProfileClick+'" style="cursor:pointer;flex-shrink:0">'+avHtml+'</div>' : '<div style="flex-shrink:0">'+avHtml+'</div>')
      +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:13px;font-weight:800;color:'+c.label+';font-family:Jost,sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap'+(_btCanClick?';cursor:pointer':'')+'"'
          +(_btCanClick?' onclick="'+_btProfileClick+'"':'')+'>'+_escHtml(name)+'</div>'
        +(_btUname ? '<div style="font-size:11px;color:'+c.label.replace(/[\d.]+\)$/,'.52)')+';font-family:Jost,sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-bottom:1px'+(_btCanClick?';cursor:pointer':'')+'"'
          +(_btCanClick?' onclick="'+_btProfileClick+'"':'')+'>@'+_escHtml(_btUname)+'</div>' : '')
        +'<div style="font-size:12px;color:'+c.label.replace(/[\d.]+\)$/,'.45)')+';font-family:Jost,sans-serif">'+_momentoAgo(p.created_at||'')+(p.is_anon?' · 👤':'')+'</div>'
      +'</div>'
      +'<div style="display:flex;align-items:center;gap:4px;flex-shrink:0">'
        +(isOwn?'<button onclick="event.stopPropagation();_btDeletePost(\''+_escHtml(String(p.id))+'\',\''+p.categoria+'\')" style="background:rgba(255,80,80,.12);border:1px solid rgba(255,80,80,.25);color:rgba(200,40,40,.80);font-size:12px;font-weight:700;font-family:Jost,sans-serif;border-radius:10px;padding:3px 7px;cursor:pointer">🗑</button>':'')
+(function(){ var _isSaved=_btSavedIds.indexOf(String(p.id))>=0; return '<button id="btSave-'+_escHtml(String(p.id))+'" onclick="_btToggleSave(\''+_escHtml(String(p.id))+'\',event)" style="'+(_isSaved?'background:rgba(80,110,230,.85);color:#fff;border:none;':'background:transparent;color:rgba(80,110,230,.9);border:1.5px solid rgba(80,110,230,.5);')+'border-radius:20px;padding:4px 12px;font-size:13px;font-weight:600;cursor:pointer;white-space:nowrap;font-family:Jost,sans-serif">'+(_isSaved?'✓ Siguiendo':'+ Seguir')+'</button>'; })()
        +'<button onclick="event.stopPropagation();_btOpenDetail('+_jsAttr(p.id)+')" style="background:'+c.badge+';border:1px solid '+c.border.replace(/[\d.]+\)$/,'.30)')+';color:'+c.label+';font-size:12px;font-weight:700;font-family:Jost,sans-serif;border-radius:10px;padding:3px 8px;cursor:pointer">💬 Comentar</button>'
        +(!isOwn?'<button onclick="event.stopPropagation();_btReport(\''+_escHtml(String(p.id))+'\',null)" style="background:rgba(220,60,60,.12);border:1px solid rgba(220,60,60,.22);color:rgba(255,100,100,.75);font-size:12px;border-radius:10px;padding:3px 7px;cursor:pointer" title="Reportar contenido">🚩</button>':'')
      +'</div>'
    +'</div>'
    +(p.titulo?'<div style="font-size:15px;font-weight:700;color:'+titleColor+';font-family:Jost,sans-serif;margin-bottom:6px;line-height:1.3">'+_escHtml(p.titulo)+'</div>':'')
    +'<div style="font-size:15px;font-family:\'Cormorant Garamond\',serif;font-style:italic;color:'+bodyColor+';line-height:1.55;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin-bottom:10px">'+_escHtml(_btCleanContenido(p.contenido))+'</div>'
    +debBar
    +(function(){
      var _em={apoyo_te:'🫂',entiendo:'💙',abrazo:'🤗',acompano:'🕊️',resuena:'✨',inspiro:'🌟',cambio:'💡',concuerdo:'👍',no_concuerdo:'👎',neutral:'🫥',ayudo:'🙏'};
      var _ks=Object.keys(_em).filter(function(k){return (rx[k]||0)>0;}).slice(0,5);
      var _rxArr=_ks.map(function(k){return _em[k]+' '+rx[k];});
      var _dv=(rx.apoyo_a||0)+(rx.apoyo_b||0);
      if(p.categoria==='debate'&&_dv>0) _rxArr.unshift('🗳️ '+_dv);
      var _rxStr=_rxArr.slice(0,5).join('  ');
      return '<div style="display:flex;align-items:center;gap:6px;border-top:1px solid '+c.border.replace(/[\d.]+\)$/,'.15)')+';padding-top:8px;margin-top:'+(debBar?'8':'0')+'px">'
        +'<div style="flex:1;display:flex;align-items:center;gap:8px;flex-wrap:wrap">'
          +'<span style="font-size:14px;color:'+c.label.replace(/[\d.]+\)$/,'.80)')+';font-family:Jost,sans-serif;letter-spacing:.2px">'+(_rxStr||((rx.mine_postura||rx.mine_rx)?'✓':'')||'—')+'</span>'
          +'<span style="font-size:13px;color:'+c.label.replace(/[\d.]+\)$/,'.65)')+';font-family:Jost,sans-serif">'+cmtCount+' 💬</span>'
        +'</div>'
        +(isOwn ? '<button onclick="event.stopPropagation();_btShareToInstant(\''+_escHtml(String(p.id))+'\',event)" style="background:transparent;border:1px solid '+c.border.replace(/[\d.]+\)$/,'.25)')+';color:'+c.label.replace(/[\d.]+\)$/,'.60)')+';font-size:12px;border-radius:10px;padding:3px 8px;cursor:pointer;font-family:Jost,sans-serif" title="Compartir en instantáneas">🌊</button>' : '')
        +'<button onclick="event.stopPropagation();_btSharePost(\''+_escHtml(String(p.id))+'\',event)" style="background:transparent;border:1px solid '+c.border.replace(/[\d.]+\)$/,'.25)')+';color:'+c.label.replace(/[\d.]+\)$/,'.60)')+';font-size:12px;border-radius:10px;padding:3px 8px;cursor:pointer;font-family:Jost,sans-serif" title="Compartir">📤</button>'
        +'<span style="font-size:12px;font-weight:700;color:'+c.label+';font-family:Jost,sans-serif;background:'+c.badge+';border:1px solid '+c.border.replace(/[\d.]+\)$/,'.30)')+';border-radius:20px;padding:3px 10px">'+(p.categoria==='debate'?'🗳 Debatir':'✨ Reaccionar')+'</span>'
      +'</div>';
    })()
  +'</div>';
}

// Compartir un post de Bitácora como INSTANTÁNEA (historia) dentro de Velo.
// Crea un vibe instant (group_id null, scope público) con un sentinel en
// media_url que el reproductor detecta para mostrar una tarjeta "Nuevo en
// Bitácora" con el título y un botón para abrir el post.
// Abre un banner explicando qué hace "compartir en instantáneas" (el 🌊 solo
// no se entiende) y ofrece Compartir / Cancelar antes de publicar la historia.
function _btShareToInstant(id,ev){
  if(ev){ try{ ev.stopPropagation(); }catch(_){} }
  var p=null;
  ['apoyo','superacion','debate','mio'].forEach(function(t){ (_btPosts[t]||[]).forEach(function(x){ if(String(x.id)===String(id)) p=x; }); });
  if(!p){ pToast('⚠️','No encontré ese post'); return; }
  // Solo el AUTOR puede compartir su propio post (consentimiento + atribución).
  var _myId=safeLS('get','velo_user_id')||'';
  if(!(p.user_id && _myId && String(p.user_id)===String(_myId))){ pToast('🔒','Solo podés compartir tus propios posts'); return; }
  var title=(p.titulo||'Una historia en Bitácora').slice(0,120);
  var ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.62);z-index:99999;display:flex;align-items:flex-end;justify-content:center';
  ov.innerHTML='<div style="background:#0e1f14;border-radius:20px 20px 0 0;padding:24px 20px calc(26px + env(safe-area-inset-bottom,0px));width:100%;max-width:480px;font-family:Jost,sans-serif;border-top:1.5px solid rgba(90,166,224,.25)">'
    +'<div style="text-align:center;font-size:38px;line-height:1;margin-bottom:12px">🌊</div>'
    +'<div style="text-align:center;font-family:\'Cormorant Garamond\',serif;font-size:23px;font-style:italic;color:#fff;margin-bottom:10px">Compartir en instantáneas</div>'
    +'<p style="font-size:13.5px;color:rgba(200,225,245,.82);text-align:center;margin:0 0 16px;line-height:1.6">Vas a crear una <b style="color:#fff">historia efímera (24&nbsp;h)</b> que le avisa a la comunidad sobre este post. Muestra el título y, al tocarla, lleva directo al post.</p>'
    +'<div style="background:rgba(90,166,224,.10);border:1.5px solid rgba(90,166,224,.30);border-radius:14px;padding:12px 14px;margin-bottom:20px;display:flex;align-items:center;gap:10px">'
    +'<span style="font-size:20px;flex-shrink:0">📖</span>'
    +'<span style="font-size:13px;color:#eaf3fb;font-weight:600;line-height:1.4;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">'+_escHtml(title)+'</span>'
    +'</div>'
    +'<div style="display:flex;gap:12px">'
    +'<button id="_btsiNo" style="flex:1;padding:13px;border-radius:100px;border:1.5px solid rgba(255,255,255,.22);background:transparent;color:rgba(220,235,250,.85);font-family:Jost,sans-serif;font-size:14px;cursor:pointer">Cancelar</button>'
    +'<button id="_btsiYes" style="flex:1.3;padding:13px;border-radius:100px;border:none;background:linear-gradient(135deg,#5aa6e0,#3f7fc0);color:#fff;font-family:Jost,sans-serif;font-size:14px;font-weight:800;cursor:pointer">🌊 Compartir</button>'
    +'</div></div>';
  document.body.appendChild(ov);
  function _close(){ if(ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelector('#_btsiNo').addEventListener('click',function(e){ e.stopPropagation(); e.preventDefault(); _close(); });
  ov.querySelector('#_btsiYes').addEventListener('click',function(e){ e.stopPropagation(); e.preventDefault(); _close(); _btDoShareToInstant(id); });
  ov.addEventListener('click',function(e){ if(e.target===ov){ e.stopPropagation(); _close(); } });
}
// Publica realmente la instantánea (tras confirmar en el banner).
function _btDoShareToInstant(id){
  var p=null;
  ['apoyo','superacion','debate','mio'].forEach(function(t){ (_btPosts[t]||[]).forEach(function(x){ if(String(x.id)===String(id)) p=x; }); });
  if(!p){ pToast('⚠️','No encontré ese post'); return; }
  _initSupabase(); if(!sbClient){ pToast('⚠️','Sin conexión'); return; }
  var myId=safeLS('get','velo_user_id')||'';
  // Guard de propiedad (defensa en profundidad).
  if(!(p.user_id && myId && String(p.user_id)===String(myId))){ pToast('🔒','Solo podés compartir tus propios posts'); return; }
  var myName=safeLS('get','velo_user_name')||'Alguien';
  var myAv=safeLS('get','velo_user_av')||'📖';
  var title=(p.titulo||'Una historia en Bitácora').slice(0,120);
  var _cat=(p.categoria && _btColors[p.categoria]) ? p.categoria : '';
  var payload={
    user_id:myId, user_name:myName, user_av:myAv,
    media_url:_cat ? ('velo:bitacora:'+_cat+':'+id) : ('velo:bitacora:'+id),
    caption:title,
    instant_scope:'public',
    instant_member_ids:[]
  };
  sbClient.from('vibes').insert(payload).select('id').single().then(function(r){
    if(r && r.data && r.data.id){
      pToast('🌊','Compartido en instantáneas ✨');
      try{ if(typeof _renderHomeVibesCard==='function') _renderHomeVibesCard(); }catch(_){}
    } else {
      if(r && r.error) console.warn('[bt-share-instant]', r.error.message);
      pToast('⚠️','No se pudo compartir ahora');
    }
  }).catch(function(e){ console.warn('[bt-share-instant]', e); pToast('⚠️','No se pudo compartir ahora'); });
}
// Sentinel de instantánea "Bitácora". Formato nuevo: velo:bitacora:<cat>:<id>
// (cat ∈ apoyo/superacion/debate/mio). Formato viejo (retrocompat): velo:bitacora:<id>.
function _vibeBitacoraParse(u){
  u=String(u||'');
  if(u.indexOf('velo:bitacora:')!==0) return null;
  var rest=u.slice(14);
  var cats={apoyo:1,superacion:1,debate:1,mio:1};
  var ci=rest.indexOf(':');
  if(ci>0 && cats[rest.slice(0,ci)]) return { id:rest.slice(ci+1), cat:rest.slice(0,ci) };
  return { id:rest, cat:null };
}
function _vibeBitacoraRef(u){ var p=_vibeBitacoraParse(u); return p ? p.id : null; }
function _vibeBitacoraCat(u){ var p=_vibeBitacoraParse(u); return p ? p.cat : null; }

function _btSharePost(id,ev){
  if(ev) ev.stopPropagation();
  var p=null;
  ['apoyo','superacion','debate','mio'].forEach(function(t){ (_btPosts[t]||[]).forEach(function(x){ if(String(x.id)===String(id)) p=x; }); });
  if(!p) return;
  var catEmoji={apoyo:'🫂',superacion:'⭐',debate:'💬'};
  var catTag={apoyo:'#Apoyo #SaludMental #HeyVelo',superacion:'#Superación #Crecimiento #HeyVelo',debate:'#Debate #Reflexión #HeyVelo'};
  var excerpt=(p.contenido||'').replace(/\[posturas:[^\]]*\]/g,'').trim();
  excerpt=excerpt.length>220?excerpt.slice(0,217)+'…':excerpt;
  var parts=[];
  if(p.titulo) parts.push((catEmoji[p.categoria]||'💬')+' '+p.titulo);
  parts.push(excerpt);
  parts.push('');
  parts.push('¿Te resonó? Uníte a la conversación 👉 heyvelo.app');
  parts.push(catTag[p.categoria]||'#HeyVelo');
  var shareText=parts.join('\n');
  if(navigator.share){
    navigator.share({title:p.titulo||'Bitácora · Velo',text:shareText,url:'https://heyvelo.app'}).catch(function(){});
  } else {
    try{ navigator.clipboard.writeText(shareText); pToast('📋','Copiado al portapapeles'); }catch(e){ pToast('📤','No se pudo compartir'); }
  }
}
function _btDeletePost(id,type){
  _pConfirm('¿Eliminar esta publicación?',function(){
    if(!sbClient){ pToast('Conectando...'); return; }
    sbClient.from('bitacora_posts').delete().eq('id',id).then(function(res){
      if(res.error){ pToast('Error al eliminar'); return; }
      pToast('Publicación eliminada');
      ['apoyo','superacion','debate','mio'].forEach(function(t){
        _btPosts[t]=(_btPosts[t]||[]).filter(function(p){ return String(p.id)!==String(id); });
      });
      // Close any open detail overlay and clean up realtime subscription
      var _dvOv=document.getElementById('btDetailOv'); if(_dvOv) _dvOv.remove();
      if(_btDetailChannel){try{sbClient.removeChannel(_btDetailChannel);}catch(e){}_btDetailChannel=null;}
      // Ensure we stay on Bitácora page
      if(document.getElementById('pg-bitacora')&&!document.getElementById('pg-bitacora').classList.contains('active')){
        pGoTo('bitacora');
      }
      _btRenderFeed(_btCurrentTab);
    });
  });
}

function _btReport(postId,commentId){
  _pConfirm('¿Reportar esta publicación?',function(){
    var uid=safeLS('get','velo_user_id');
    if(!uid){ pToast('Debés iniciar sesión'); return; }
    if(!sbClient) return;
    // Look up owner from cached posts
    var ownerId=null;
    if(postId){
      var allCached=(_btPosts.apoyo||[]).concat(_btPosts.superacion||[]).concat(_btPosts.debate||[]).concat(_btPosts.mio||[]);
      var found=allCached.find(function(p){ return String(p.id)===String(postId); });
      if(found) ownerId=found.user_id||null;
    }
    var obj={user_id:uid};
    if(postId) obj.post_id=postId;
    if(commentId) obj.comment_id=commentId;
    sbClient.from('bitacora_reports').insert(obj).then(function(res){
      if(res&&res.error){ pToast('⚠️','Error al enviar el reporte'); return; }
      // Globally hide immediately
      if(postId){
        _btHiddenIds.add(String(postId));
        _btRenderFeed(_btCurrentTab);
      }
      // Notify reporter
      sbSaveBroadcast('user:'+uid,
        'Reporte recibido ✅',
        'Recibimos tu reporte. Estamos analizando la situación y te avisaremos el resultado de la revisión.',
        '✅', {n:'Velo', i:'system', a:'', u:''}).catch(function(){});
      // Notify post owner (if not anonymous)
      if(ownerId && ownerId!==uid){
        sbSaveBroadcast('user:'+ownerId,
          'Tu publicación fue reportada 🚩',
          'Tu publicación en Bitácora fue reportada por un usuario. La ocultamos mientras la revisamos. Te avisaremos la resolución en breve.',
          '🚩', {n:'Velo', i:'system', a:'', u:''}).catch(function(){});
      }
      _notifyAdminsNewReport('🚩 Reporte en Bitácora','Un usuario reportó contenido en Bitácora. Revisá el panel de Moderación.');
      pToast('🚩','Reporte enviado. El contenido queda oculto mientras lo revisamos. Gracias 🙏');
    }).catch(function(){ pToast('⚠️','Error al enviar el reporte'); });
  });
}

function _btGenRxHtml(id, rx, c){
  var defs=[
    {key:'concuerdo',   emoji:'👍', label:'Concuerdo'},
    {key:'neutral',     emoji:'🫥', label:'Neutral'},
    {key:'no_concuerdo',emoji:'👎', label:'No concuerdo'},
  ];
  return '<div id="btGenRx_'+id+'" style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap">'
    +defs.map(function(d){
      var act=rx.mine_gen===d.key;
      var n=rx[d.key]||0;
      return '<button onclick="_btReact(\''+id+'\',\''+d.key+'\')" '
        +'style="flex:1;min-width:80px;padding:7px 8px;border-radius:10px;border:1.5px solid '+c.border.replace(/[\d.]+\)$/,(act?'.65':'.20)'))+';background:'+(act?c.strip:'rgba(255,255,255,.05)')+';color:'+c.label+';font-family:Jost,sans-serif;cursor:pointer;display:flex;align-items:center;gap:6px">'
        +'<span style="font-size:16px;line-height:1;flex-shrink:0">'+d.emoji+'</span>'
        +'<span style="font-size:13px;font-weight:700;flex:1;text-align:left">'+d.label+'</span>'
        +(n>0?'<span style="font-size:12px;opacity:.65;flex-shrink:0">'+n+'</span>':'')
        +'</button>';
    }).join('')
    +'</div>';
}

function _btSubscribeDetail(postId){
  if(!sbClient) return;
  if(_btDetailChannel){
    try{ sbClient.removeChannel(_btDetailChannel); }catch(e){}
    _btDetailChannel=null;
  }
  _btDetailChannel=sbClient.channel('bt-detail-'+postId)
    .on('postgres_changes',{event:'*',schema:'public',table:'bitacora_reactions',filter:'post_id=eq.'+postId},function(){
      var uid=safeLS('get','velo_user_id');
      sbClient.from('bitacora_reactions').select('post_id,reaction_type,user_id').eq('post_id',postId)
        .then(function(res){
          if(!res.data) return;
          var m=_btEmptyRx();
          res.data.forEach(function(rx){
            if(typeof m[rx.reaction_type]==='number') m[rx.reaction_type]++;
            if(uid&&String(rx.user_id)===String(uid)){
              if(_btIsPostura(rx.reaction_type)) m.mine_postura=rx.reaction_type;
              else if(_btIsGenRx(rx.reaction_type)) m.mine_gen=rx.reaction_type;
              else m.mine_rx=rx.reaction_type;
            }
          });
          _btReactMap[postId]=m;
          var genEl=document.getElementById('btGenRx_'+postId);
          if(genEl){
            var cat='apoyo';
            var allP=(_btPosts.apoyo||[]).concat(_btPosts.superacion||[]).concat(_btPosts.debate||[]).concat(_btPosts.mio||[]);
            var found=allP.filter(function(p){ return String(p.id)===String(postId); })[0];
            if(found) cat=found.categoria;
            var _c=_btColors[cat]||_btColors.apoyo;
            var newEl=document.createElement('div');
            newEl.innerHTML=_btGenRxHtml(postId,m,_c);
            genEl.parentNode.replaceChild(newEl.firstChild,genEl);
          } else {
            var ov=document.getElementById('btDetailOv');
            if(ov){ ov.remove(); _btOpenDetail(postId); }
          }
        }).catch(function(){});
    })
    .subscribe();
}

function _btOpenDetail(id){
  var post=null;
  var tabs=['apoyo','superacion','debate','mio'];
  for(var ti=0;ti<tabs.length;ti++){
    var f=(_btPosts[tabs[ti]]||[]).find(function(p){ return String(p.id)===String(id); });
    if(f){ post=f; break; }
  }
  if(!post){
    // Not in local cache (e.g. opened from profile page) — fetch from Supabase
    _initSupabase();
    if(!sbClient) return;
    sbClient.from('bitacora_posts_full').select('*').eq('id',id).maybeSingle().then(function(res){
      if(res.error||!res.data) return;
      var p=res.data;
      if(!_btPosts[p.categoria]) _btPosts[p.categoria]=[];
      if(!_btPosts[p.categoria].some(function(x){ return String(x.id)===String(id); })) _btPosts[p.categoria].push(p);
      _btOpenDetail(id);
    }).catch(function(){});
    return;
  }
  var c=_btColors[post.categoria]||_btColors.apoyo;
  var rx=_btReactMap[id]||_btEmptyRx();
  var authorName=post.is_anon?'Anónimo/a':(post.author_name||'Alguien');
  var typeLabel={apoyo:'🫂 APOYO',superacion:'⭐ SUPERACIÓN',debate:'💬 DEBATE'};
  // Extract debate posturas — columns first, then embedded backup in contenido
  var _dpA=post.postura_a||'', _dpB=post.postura_b||'';
  if(post.categoria==='debate'&&post.contenido){
    var _dpm=post.contenido.match(/\[posturas:a=(.*?)\|b=(.*?)\]/);
    if(_dpm){ if(!_dpA) _dpA=(_dpm[1]||'').trim(); if(!_dpB) _dpB=(_dpm[2]||'').trim(); }
  }
  var rxHtml='';
  if(post.categoria==='debate'){
    var totAB=(rx.apoyo_a||0)+(rx.apoyo_b||0);
    var pA=totAB>0?Math.round((rx.apoyo_a||0)/totAB*100):50;
    var pB=100-pA;
    var _mkPosturaCard=function(key,label,desc,pct,active){ return _btMkPosturaCard(id,key,label,desc,pct,active,c); };
    rxHtml='<div style="margin-bottom:16px">'
      +'<div style="font-size:12px;font-weight:800;letter-spacing:1.5px;color:rgba(255,255,255,.45);font-family:Jost,sans-serif;margin-bottom:10px">¿CON QUÉ POSTURA TE IDENTIFICÁS?</div>'
      +'<div id="btPCards_'+id+'" style="display:flex;gap:10px">'
        +_mkPosturaCard('apoyo_a','Postura A',_dpA,pA,rx.mine_postura==='apoyo_a')
        +_mkPosturaCard('apoyo_b','Postura B',_dpB,pB,rx.mine_postura==='apoyo_b')
      +'</div>'
    +'</div>';
  } else if(post.categoria==='apoyo'){
    rxHtml=_btGenCatRxHtml(id,'apoyo',rx,c);
  } else {
    rxHtml=_btGenCatRxHtml(id,post.categoria,rx,c);
  }
  var ov=document.createElement('div');
  ov.id='btDetailOv';
  ov.style.cssText='position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,.75);display:flex;flex-direction:column;justify-content:flex-end';
  var _shBg=c.bg.replace(/[\d.]+\)$/,'.99)');
  var sh='<div id="btDetailSheet" style="background:'+_shBg+';border-radius:26px 26px 0 0;max-height:90vh;overflow-y:auto;padding:0 0 max(20px,env(safe-area-inset-bottom));border-top:3px solid '+c.border.replace(/[\d.]+\)$/,'.55)')+';">';
  sh+='<div style="display:flex;justify-content:center;padding:12px 0 0"><div style="width:36px;height:4px;background:rgba(255,255,255,.15);border-radius:2px"></div></div>';
  var _detUid=safeLS('get','velo_user_id');
  var _detIsOwn=_detUid&&post.user_id&&String(post.user_id)===String(_detUid);
  sh+='<div style="padding:16px 18px 0;display:flex;align-items:center;justify-content:space-between">';
  sh+='<div style="font-size:12px;font-weight:800;letter-spacing:2px;color:'+c.label.replace(/[\d.]+\)$/,'.65)')+';font-family:Jost,sans-serif">'+(typeLabel[post.categoria]||'')+'</div>';
  sh+='<div style="display:flex;align-items:center;gap:7px">'
    +(!_detIsOwn?'<button onclick="document.getElementById(\'btDetailOv\').remove();if(_btDetailChannel){try{sbClient.removeChannel(_btDetailChannel);}catch(e){}_btDetailChannel=null;};_btReport(\''+_escHtml(String(post.id))+'\',null)" style="background:rgba(220,60,60,.12);border:1.5px solid rgba(220,60,60,.22);color:rgba(255,120,120,.80);font-size:13px;font-weight:700;font-family:Jost,sans-serif;border-radius:20px;padding:4px 10px;cursor:pointer">🚩 Reportar</button>':'')
    +'<button onclick="document.getElementById(\'btDetailOv\').remove();if(_btDetailChannel){try{sbClient.removeChannel(_btDetailChannel);}catch(e){}_btDetailChannel=null;}" style="background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.15);border-radius:50%;width:30px;height:30px;color:rgba(255,255,255,.70);font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1">×</button>'
  +'</div>';
  sh+='</div><div style="padding:14px 18px 0">';
  var _dUname = !post.is_anon ? (post.author_username||_uLook(post.user_id)||'') : '';
  var _dCanClick = !post.is_anon && post.user_id;
  var _dAvUrl = !post.is_anon ? (post.author_avatar||'') : '';
  var _dClick = _dCanClick
    ? 'pQuickProfile('+_jsAttr(authorName)+','+_jsAttr(_dAvUrl)+',\'\',\'\','+_jsAttr(post.user_id)+')'
    : '';
  sh+='<div style="display:flex;align-items:center;gap:9px;margin-bottom:10px">';
  // Author avatar in detail
  if(_dAvUrl&&_dAvUrl.startsWith('http')){
    sh+='<img src="'+_escHtml(_dAvUrl)+'" style="width:36px;height:36px;border-radius:50%;object-fit:cover;border:2px solid '+c.border+';flex-shrink:0'+(_dCanClick?';cursor:pointer':'')+'"'+(_dCanClick?' onclick="'+_dClick+'"':'')+'>';
  } else if(_dAvUrl&&_dCanClick){
    sh+='<div onclick="'+_dClick+'" style="width:36px;height:36px;border-radius:50%;background:'+c.strip+';border:2px solid '+c.border+';display:flex;align-items:center;justify-content:center;font-size:19px;flex-shrink:0;cursor:pointer">'+_escHtml(_dAvUrl)+'</div>';
  } else {
    sh+='<div style="width:36px;height:36px;border-radius:50%;background:'+c.strip+';border:2px solid '+c.border+';display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0">'+c.emoji+'</div>';
  }
  sh+='<div style="flex:1;min-width:0">';
  sh+='<div style="font-size:14px;font-weight:700;color:'+c.label+';font-family:Jost,sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap'+(_dCanClick?';cursor:pointer':'')+'"'
    +(_dCanClick?' onclick="'+_dClick+'"':'')+'>'+_escHtml(authorName)+'</div>';
  if(_dUname) sh+='<div style="font-size:12px;color:'+c.label.replace(/[\d.]+\)$/,'.52)')+';font-family:Jost,sans-serif'+(_dCanClick?';cursor:pointer':'')+'"'
    +(_dCanClick?' onclick="'+_dClick+'"':'')+'>@'+_escHtml(_dUname)+'</div>';
  sh+='<div style="font-size:12px;color:'+c.label.replace(/[\d.]+\)$/,'.40)')+';font-family:Jost,sans-serif">'+_momentoAgo(post.created_at||'')+'</div>';
  sh+='</div></div>';
  if(post.titulo) sh+='<div style="font-size:18px;font-weight:800;color:rgba(255,255,255,.97);font-family:Jost,sans-serif;line-height:1.3;margin-bottom:12px">'+_escHtml(post.titulo)+'</div>';
  sh+='<div style="font-size:15px;font-family:\'Cormorant Garamond\',serif;font-style:italic;color:rgba(255,255,255,.88);line-height:1.65;margin-bottom:18px;white-space:pre-wrap">'+_escHtml(_btCleanContenido(post.contenido))+'</div>';
  sh+=rxHtml;
  sh+=_btGenRxHtml(id, rx, c);
  sh+='<div onclick="_btSharePost(\''+_escHtml(String(post.id))+'\',event)" style="cursor:pointer;margin:6px 0 16px;background:'+c.strip.replace(/[\d.]+\)$/,'.18)')+';border:1.5px solid '+c.border.replace(/[\d.]+\)$/,'.38)')+';border-radius:16px;padding:11px 14px;display:flex;align-items:center;gap:12px;transition:opacity .15s" onmouseover="this.style.opacity=\'.8\'" onmouseout="this.style.opacity=\'1\'">'
    +'<div style="font-size:22px;flex-shrink:0">📤</div>'
    +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:14px;font-weight:700;color:'+c.label+';font-family:Jost,sans-serif;line-height:1.3">¿Querés que más gente lo vea?</div>'
      +'<div style="font-size:12px;color:'+c.label.replace(/[\d.]+\)$/,'.52)')+';font-family:Jost,sans-serif;margin-top:1px">Compartilo para que más personas reaccionen o comenten</div>'
    +'</div>'
    +'<div style="font-size:13px;font-weight:800;color:'+c.label+';font-family:Jost,sans-serif;white-space:nowrap">Compartir →</div>'
  +'</div>';
  sh+='<div style="border-top:1px solid rgba(255,255,255,.08);padding-top:14px">';
  sh+='<div style="font-size:12px;font-weight:800;letter-spacing:1.5px;color:rgba(180,200,190,.50);font-family:Jost,sans-serif;margin-bottom:12px">COMENTARIOS</div>';
  sh+='<div id="btCommentsWrap" style="margin-bottom:14px"><div style="text-align:center;padding:20px 0;color:rgba(180,200,190,.35);font-size:14px;font-family:Jost,sans-serif">Cargando...</div></div>';
  sh+='<label for="btCommentAnon" style="display:flex;align-items:center;gap:8px;padding:8px 10px;margin-bottom:8px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.10);border-radius:10px;cursor:pointer;font-family:Jost,sans-serif">'
    +'<input type="checkbox" id="btCommentAnon" style="width:16px;height:16px;accent-color:'+c.label+';cursor:pointer;flex-shrink:0">'
    +'<span style="font-size:12px;color:rgba(255,255,255,.78);line-height:1.3"><strong>🕊️ Comentar como anónimo/a</strong> <span style="opacity:.62">— sin marcar, se muestra tu perfil.</span></span>'
    +'</label>';
  sh+='<div style="display:flex;gap:8px;align-items:flex-end">';
  sh+='<textarea id="btCommentInput" placeholder="Escribí tu comentario..." style="flex:1;background:rgba(255,255,255,.13);border:1.5px solid '+c.border.replace(/[\d.]+\)$/,'.50)')+';border-radius:14px;padding:10px 12px;color:rgba(255,255,255,.95);font-size:15px;font-family:Jost,sans-serif;resize:none;min-height:44px;max-height:120px;outline:none;box-sizing:border-box;box-shadow:inset 0 1px 4px rgba(0,0,0,.18)" rows="1"></textarea>';
  sh+='<button onclick="_btSendComment(\''+_escHtml(String(post.id))+'\')" style="background:'+c.strip+';border:1.5px solid '+c.border.replace(/[\d.]+\)$/,'.60)')+';color:'+c.label+';font-size:14px;font-weight:800;font-family:Jost,sans-serif;border-radius:14px;padding:10px 14px;cursor:pointer;flex-shrink:0">Enviar</button>';
  sh+='</div></div></div></div>';
  ov.innerHTML=sh;
  document.body.appendChild(ov);
  // Reading progress bar sobre el sheet scroll
  try{
    var _sheet = document.getElementById('btDetailSheet');
    if(_sheet && typeof veloAttachReadingProgress === 'function'){
      var _detachProgress = veloAttachReadingProgress(_sheet);
      ov.dataset.detachProgressBound = '1';
      ov.__detachProgress = _detachProgress;
    }
  }catch(e){}
  ov.addEventListener('click',function(e){ if(e.target===ov){ if(ov.__detachProgress) try{ov.__detachProgress();}catch(_){}; ov.remove(); if(_btDetailChannel){try{sbClient.removeChannel(_btDetailChannel);}catch(e2){}_btDetailChannel=null;} } });
  _btSubscribeDetail(id);
  _btLoadComments(post.id);
  // For debate: async-fetch fresh posturas from base table (bypasses stale view/schema cache)
  if(post.categoria==='debate' && sbClient && (!_dpA||!_dpB)){
    sbClient.from('bitacora_posts').select('id,postura_a,postura_b,contenido').eq('id',id).maybeSingle()
      .then(function(fr){
        if(!fr||fr.error||!fr.data) return;
        var d=fr.data, fA=(d.postura_a||'').trim(), fB=(d.postura_b||'').trim();
        if(!fA||!fB){ var fm=(d.contenido||'').match(/\[posturas:a=(.*?)\|b=(.*?)\]/); if(fm){ fA=fA||(fm[1]||'').trim(); fB=fB||(fm[2]||'').trim(); } }
        if(!fA&&!fB) return;
        var pcards=document.getElementById('btPCards_'+id);
        if(!pcards) return;
        var rx2=_btReactMap[id]||_btEmptyRx();
        var totAB2=(rx2.apoyo_a||0)+(rx2.apoyo_b||0);
        var pA2=totAB2>0?Math.round((rx2.apoyo_a||0)/totAB2*100):50;
        pcards.innerHTML=_mkPosturaCard('apoyo_a','Postura A',fA,pA2,rx2.mine_postura==='apoyo_a')
          +_mkPosturaCard('apoyo_b','Postura B',fB,100-pA2,rx2.mine_postura==='apoyo_b');
        // Update cache so re-open doesn't lose posturas
        Object.keys(_btPosts).forEach(function(cat){
          (_btPosts[cat]||[]).forEach(function(p){ if(String(p.id)===String(id)){ p.postura_a=fA; p.postura_b=fB; } });
        });
      }).catch(function(){});
  }
}

async function _btLoadComments(postId){
  if(!sbClient) return;
  await sbClient.from('bitacora_comments_full').select('*').eq('post_id',postId).order('created_at',{ascending:true}).limit(50)
    .then(function(res){
      var wrap=document.getElementById('btCommentsWrap');
      if(!wrap) return;
      if(res.error||!res.data||!res.data.length){
        wrap.innerHTML='<div style="text-align:center;padding:12px 0;color:rgba(180,200,190,.35);font-size:14px;font-family:Jost,sans-serif">Sin comentarios aún. ¡Sé el primero!</div>';
        return;
      }
      var comments=res.data;
      var ids=comments.map(function(c){ return c.id; });
      var uid=safeLS('get','velo_user_id');
      // Hidratar username/avatar/nombre desde profiles para no-anónimos
      var nonAnonUids = comments
        .filter(function(c){ return c.user_id && !c.is_anon; })
        .map(function(c){ return c.user_id; });
      var uniqUids = nonAnonUids.filter(function(u,i,a){ return a.indexOf(u) === i; });
      var hydratePromise = uniqUids.length
        ? sbClient.from('profiles').select('id,username,nombre,avatar').in('id', uniqUids).then(function(pr){
            if(pr && pr.data){
              var pmap = {};
              pr.data.forEach(function(p){ pmap[p.id] = p; });
              comments.forEach(function(c){
                var p = pmap[c.user_id];
                if(p && !c.is_anon){
                  if(p.username) c.username = p.username;
                  if(!c.avatar_url && p.avatar) c.avatar_url = p.avatar;
                  if((!c.author_name || c.author_name === 'Alguien') && p.nombre) c.author_name = p.nombre;
                }
              });
            }
          }).catch(function(){})
        : Promise.resolve();
      hydratePromise.then(function(){
        sbClient.from('bitacora_comment_reactions').select('comment_id,emoji,user_id').in('comment_id',ids)
          .then(function(rxRes){
            _btRenderComments(comments,(rxRes.error||!rxRes.data)?[]:rxRes.data,postId,uid,wrap);
          }).catch(function(){ _btRenderComments(comments,[],postId,uid,wrap); });
      });
    });
}

function _btRenderComments(comments,rxData,postId,uid,wrap){
  // Filtrar comentarios de usuarios bloqueados (excepto anónimos)
  comments = (comments||[]).filter(function(c){ return c.is_anon || !_isBlocked(c.user_id); });
  var rxMap={};
  rxData.forEach(function(rx){
    var cid=String(rx.comment_id);
    if(!rxMap[cid]) rxMap[cid]={};
    var e=rx.emoji;
    if(!rxMap[cid][e]) rxMap[cid][e]={count:0,mine:false};
    rxMap[cid][e].count++;
    if(uid&&String(rx.user_id)===String(uid)) rxMap[cid][e].mine=true;
  });
  var EMOJIS=[{k:'heart',i:'❤️'},{k:'clap',i:'🙌'},{k:'hug',i:'🫂'}];
  wrap.innerHTML=comments.map(function(cm){
    var own=uid&&cm.user_id&&String(cm.user_id)===String(uid)&&!cm.is_anon;
    // Si el comentario es del usuario actual y viene sin nombre/avatar, usar localStorage
    var nm = cm.is_anon ? 'Anónimo/a'
                       : (cm.author_name || (own ? (safeLS('get','velo_user_name')||'Alguien') : 'Alguien'));
    var canClick=!cm.is_anon && cm.user_id;
    var avUrl = cm.avatar_url || cm.av || (own && !cm.is_anon ? (safeLS('get','velo_user_av')||'') : '');
    var uname = cm.username || (own ? (safeLS('get','velo_username')||'') : '');
    var profileArgs=_jsAttr(nm)+','+_jsAttr(avUrl)+',\'\','+_jsAttr(uname||'')+','+_jsAttr(String(cm.user_id||''));
    var avClickAttr=canClick?'onclick="pQuickProfile('+profileArgs+')" style="cursor:pointer;flex-shrink:0"':'style="cursor:default;flex-shrink:0"';
    // Avatar: 40px circle with ring glow
    var ringStyle='width:40px;height:40px;border-radius:50%;flex-shrink:0;border:2px solid rgba(116,198,157,.65);box-shadow:0 0 0 3px rgba(116,198,157,.15),0 2px 8px rgba(0,0,0,.22);';
    var avIsUrl=avUrl&&(avUrl.startsWith('http')||avUrl.startsWith('data:'));
    var avEmoji=!avIsUrl&&avUrl?avUrl:(cm.is_anon?'🕊️':'🌿');
    var avHtml=avIsUrl
      ?'<img src="'+_escHtml(avUrl)+'" '+avClickAttr+' style="'+ringStyle+'object-fit:cover;" />'
      :'<div '+avClickAttr+' style="'+ringStyle+'background:rgba(116,198,157,.20);display:flex;align-items:center;justify-content:center;font-size:20px">'+avEmoji+'</div>';
    // Name + @username clickable cuando no es anon
    var unameLine = (canClick && uname)
      ? '<div style="font-size:11.5px;font-weight:600;color:rgba(10,60,30,.55);font-family:Jost,sans-serif;line-height:1;margin-top:2px">@'+_escHtml(uname)+'</div>'
      : '';
    var nmHtml=canClick
      ?'<div onclick="pQuickProfile('+profileArgs+')" style="cursor:pointer;min-width:0"><span style="font-size:14px;font-weight:700;color:rgba(10,60,30,.90);font-family:Jost,sans-serif;line-height:1.2">'+_escHtml(nm)+'</span>'+unameLine+'</div>'
      :'<div style="min-width:0"><span style="font-size:14px;font-weight:700;color:rgba(10,60,30,.90);font-family:Jost,sans-serif;line-height:1.2">'+_escHtml(nm)+'</span></div>';
    // Reaction buttons — dark text on white bubble
    var cmRx=rxMap[String(cm.id)]||{};
    var cmIdStr=String(cm.id);
    var rxHtml='<div style="display:flex;gap:5px;margin-top:8px;flex-wrap:wrap">'
      +EMOJIS.map(function(e){
        var r=cmRx[e.k]||{count:0,mine:false};
        var rxBg=r.mine?'rgba(116,198,157,.28)':'rgba(0,0,0,.06)';
        var rxBorder=r.mine?'rgba(116,198,157,.70)':'rgba(0,0,0,.12)';
        var rxTxt=r.mine?'rgba(10,80,40,.90)':'rgba(0,0,0,.55)';
        return '<button type="button" onclick="event.stopPropagation();_btCmReact(\''+cmIdStr+'\',\''+e.k+'\',\''+String(postId)+'\')" '
          +'style="display:inline-flex;align-items:center;gap:4px;background:'+rxBg+';border:1.5px solid '+rxBorder+';border-radius:20px;padding:4px 10px;cursor:pointer;-webkit-tap-highlight-color:transparent;touch-action:manipulation;transition:background .15s">'
          +'<span style="font-size:15px;line-height:1">'+e.i+'</span>'
          +'<span style="font-size:13px;font-weight:700;color:'+rxTxt+';font-family:Jost,sans-serif">'+(r.count>0?r.count:'')+'</span>'
          +'</button>';
      }).join('')
      +'</div>';
    // Speech bubble card
    return '<div style="display:flex;align-items:flex-start;gap:9px;margin-bottom:14px">'
      +avHtml
      +'<div class="bt-comment-bubble" style="padding:10px 13px">'
        +'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:5px">'
          +nmHtml
          +'<div style="display:flex;align-items:center;gap:5px;flex-shrink:0">'
            +'<span style="font-size:12px;color:rgba(0,0,0,.38);font-family:Jost,sans-serif">'+_momentoAgo(cm.created_at||'')+'</span>'
            +(own?'<button type="button" onclick="_btDeleteComment(\''+_escHtml(cmIdStr)+'\',\''+_escHtml(String(postId))+'\')" style="background:none;border:none;color:rgba(200,60,60,.65);font-size:14px;cursor:pointer;padding:0 2px;line-height:1">🗑</button>':'')
            +(!own?'<button type="button" onclick="_btReport(null,\''+_escHtml(cmIdStr)+'\')" style="background:none;border:none;color:rgba(180,60,60,.55);font-size:13px;cursor:pointer;padding:0 2px;line-height:1">🚩</button>':'')
          +'</div>'
        +'</div>'
        +'<div style="font-size:15px;color:rgba(10,10,10,.82);font-family:Jost,sans-serif;line-height:1.5;word-break:break-word">'+_escHtml(cm.content)+'</div>'
        +rxHtml
      +'</div>'
    +'</div>';
  }).join('');
}

function _btCmReact(commentId,emoji,postId){
  var uid=safeLS('get','velo_user_id');
  if(!uid){ pToast('Debés iniciar sesión'); return; }
  if(!sbClient) return;
  sbClient.from('bitacora_comment_reactions').select('id').eq('comment_id',commentId).eq('user_id',uid).eq('emoji',emoji).limit(1)
    .then(function(res){
      if(res.error){ pToast('⚠️ '+res.error.message); return; }
      if(res.data&&res.data.length){
        sbClient.from('bitacora_comment_reactions').delete().eq('id',res.data[0].id)
          .then(function(r){ if(r&&r.error) pToast('⚠️ '+r.error.message); else _btLoadComments(postId); });
      } else {
        sbClient.from('bitacora_comment_reactions').insert({comment_id:commentId,user_id:uid,emoji:emoji})
          .then(function(r){ if(r&&r.error) pToast('⚠️ '+r.error.message); else _btLoadComments(postId); });
      }
    }).catch(function(e2){ pToast('⚠️ '+(e2&&e2.message||'Error al reaccionar')); });
}

async function _btSendComment(postId){
  var input=document.getElementById('btCommentInput');
  if(!input) return;
  var text=(input.value||'').trim();
  if(!text) return;
  var uid=safeLS('get','velo_user_id');
  if(!uid){ pToast('Debés iniciar sesión'); return; }
  if(!sbClient) return;
  input.disabled=true;
  var anonChk = document.getElementById('btCommentAnon');
  var _btAnon = !!(anonChk && anonChk.checked);
  // Si NO es anónimo, garantizar que profile.nombre/avatar estén poblados con
  // los valores actuales del usuario — sino la vista bitacora_comments_full
  // devuelve nombre/avatar vacíos y el comentario queda como Alguien + 🌿
  if(!_btAnon){
    var localName = safeLS('get','velo_user_name') || '';
    var localAv   = safeLS('get','velo_user_av') || '';
    if(localName || localAv){
      try{
        var update = {};
        if(localName && localName !== 'Anónimo' && localName !== 'Alguien') update.nombre = localName;
        if(localAv && !localAv.startsWith('data:')) update.avatar = localAv;
        if(Object.keys(update).length){
          await sbClient.from('profiles').update(update).eq('id', uid);
        }
      }catch(e){}
    }
  }
  sbClient.from('bitacora_comments').insert({post_id:postId,user_id:uid,content:text,is_anon:_btAnon}).then(function(res){
    if(input) input.disabled=false;
    if(res.error){ pToast('Error al enviar'); return; }
    if(input) input.value='';
    pToast('Comentario enviado ✓');
    _geminiModerateContent(text, 'bitacora-comment');
    _btCommentCounts[postId]=(_btCommentCounts[postId]||0)+1;
    _btRefreshCard(postId);
    _btLoadComments(postId);
    // v1443: notificar al autor del post (actividad) — respeta el anónimo del comentario
    try{
      sbClient.from('bitacora_posts').select('user_id').eq('id',postId).maybeSingle().then(function(pw){
        if(pw && pw.data && pw.data.user_id){
          var _nm = _btAnon ? 'Alguien' : (safeLS('get','velo_user_name')||'Alguien');
          _createVeloNotif(pw.data.user_id, 'bt_comment', _nm+' comentó tu historia en Bitácora', text.slice(0,80), postId);
        }
      }).catch(function(){});
    }catch(_){}
  }).catch(function(){ if(input) input.disabled=false; pToast('⚠️','Error de conexión'); });
}

function _btDeleteComment(commentId,postId){
  _pConfirm('¿Eliminar comentario?',function(){
    if(!sbClient) return;
    sbClient.from('bitacora_comments').delete().eq('id',commentId).then(function(){
      pToast('Comentario eliminado');
      _btLoadComments(postId);
    });
  });
}

function _btRefreshCard(postId){
  var el=document.getElementById('btCard_'+postId);
  if(!el) return;
  var allP=(_btPosts.apoyo||[]).concat(_btPosts.superacion||[]).concat(_btPosts.debate||[]).concat(_btPosts.mio||[]);
  var post=allP.filter(function(p){ return String(p.id)===String(postId); })[0];
  if(!post) return;
  var uid=safeLS('get','velo_user_id');
  var tmp=document.createElement('div');
  tmp.innerHTML=_btCard(post,0,uid);
  if(tmp.firstChild) el.parentNode.replaceChild(tmp.firstChild,el);
}

function _btReact(postId,type){
  var uid=safeLS('get','velo_user_id');
  if(!uid){ pToast('Debés iniciar sesión'); return; }
  if(!sbClient) return;
  var rx=_btReactMap[postId]||_btEmptyRx();
  var isPostura=_btIsPostura(type);
  var isGenRx=_btIsGenRx(type);
  // Each reaction slot is independent: postura | genRx (concuerdo/neutral) | category (apoyo_te/abrazo/etc)
  var oldMine=isPostura?rx.mine_postura:(isGenRx?rx.mine_gen:rx.mine_rx);
  var _setMine=function(m,val){
    if(isPostura) m.mine_postura=val;
    else if(isGenRx) m.mine_gen=val;
    else m.mine_rx=val;
  };
  var _isToggleOff=(oldMine===type);
  // Only delete reactions within the SAME slot — preserves independent slots
  var _keysToDelete=isPostura
    ?['apoyo_a','apoyo_b']
    :(isGenRx
      ?['concuerdo','no_concuerdo','neutral','ayudo']
      :['apoyo_te','entiendo','abrazo','acompano','resuena','inspiro','cambio']);
  var _genRxKeys=['concuerdo','no_concuerdo','neutral','ayudo'];
  var _refreshDetail=function(){
    _btRefreshCard(postId);
    var _allP=(_btPosts.apoyo||[]).concat(_btPosts.superacion||[]).concat(_btPosts.debate||[]).concat(_btPosts.mio||[]);
    var _fp=_allP.filter(function(p){ return String(p.id)===String(postId); })[0];
    var _fcat=(_fp&&_fp.categoria)||'apoyo';
    var _fc=_btColors[_fcat]||_btColors.apoyo;
    // concuerdo/neutral/no_concuerdo: in-place refresh of genRx row
    if(_genRxKeys.indexOf(type)>=0){
      var genEl=document.getElementById('btGenRx_'+postId);
      if(genEl){
        var _nEl=document.createElement('div');
        _nEl.innerHTML=_btGenRxHtml(postId,_btReactMap[postId]||_btEmptyRx(),_fc);
        genEl.parentNode.replaceChild(_nEl.firstChild,genEl);
        return;
      }
    }
    // apoyo/superacion category buttons: in-place refresh
    var catEl=document.getElementById('btCatRx_'+postId);
    if(catEl){
      var _cEl=document.createElement('div');
      _cEl.innerHTML=_btGenCatRxHtml(postId,_fcat,_btReactMap[postId]||_btEmptyRx(),_fc);
      catEl.parentNode.replaceChild(_cEl.firstChild,catEl);
      return;
    }
    // postura votes: in-place refresh of postura cards
    if(isPostura){
      var pcards=document.getElementById('btPCards_'+postId);
      if(pcards){
        var rx3=_btReactMap[postId]||_btEmptyRx();
        var totAB3=(rx3.apoyo_a||0)+(rx3.apoyo_b||0);
        var pA3=totAB3>0?Math.round((rx3.apoyo_a||0)/totAB3*100):50;
        var pA_txt=(_fp&&_fp.postura_a)||''; var pB_txt=(_fp&&_fp.postura_b)||'';
        pcards.innerHTML=_btMkPosturaCard(postId,'apoyo_a','Postura A',pA_txt,pA3,rx3.mine_postura==='apoyo_a',_fc)
          +_btMkPosturaCard(postId,'apoyo_b','Postura B',pB_txt,100-pA3,rx3.mine_postura==='apoyo_b',_fc);
        return;
      }
    }
    // fallback: re-open overlay
    if(_btDetailChannel){try{sbClient.removeChannel(_btDetailChannel);}catch(e){}_btDetailChannel=null;}
    var ov=document.getElementById('btDetailOv'); if(ov) ov.remove();
    _btOpenDetail(postId);
  };
  // Step 1: delete all reactions in this category (clears stale rows + current selection)
  sbClient.from('bitacora_reactions').delete()
    .eq('post_id',postId).eq('user_id',uid).in('reaction_type',_keysToDelete)
    .then(function(res){
      if(res.error){ pToast('Error al reaccionar'); return; }
      var m=_btReactMap[postId]||_btEmptyRx();
      if(oldMine&&typeof m[oldMine]==='number'&&m[oldMine]>0) m[oldMine]--;
      _setMine(m,''); _btReactMap[postId]=m;
      if(_isToggleOff){ _refreshDetail(); return; }
      // Step 2: insert new reaction
      sbClient.from('bitacora_reactions').insert({post_id:postId,user_id:uid,reaction_type:type})
        .then(function(res2){
          if(res2.error){
            if((res2.error.code||'')==='23505'||(res2.error.message||'').indexOf('duplicate')>=0){
              var m2=_btReactMap[postId]||_btEmptyRx();
              if(typeof m2[type]==='number'){ if(!m2[type]) m2[type]=1; } else m2[type]=1;
              _setMine(m2,type); _btReactMap[postId]=m2; _refreshDetail(); return;
            }
            pToast('Error al guardar reacción'); return;
          }
          var m2=_btReactMap[postId]||_btEmptyRx();
          if(typeof m2[type]==='number') m2[type]++; else m2[type]=1;
          _setMine(m2,type); _btReactMap[postId]=m2;
          _refreshDetail();
          // v1443: notificar al autor del post que alguien reaccionó (actividad)
          try{
            sbClient.from('bitacora_posts').select('user_id').eq('id',postId).maybeSingle().then(function(pw){
              if(pw && pw.data && pw.data.user_id){
                var _nm = safeLS('get','velo_user_name')||'Alguien';
                _createVeloNotif(pw.data.user_id, 'bt_reaction', _nm+' reaccionó a tu historia en Bitácora', '', postId);
              }
            }).catch(function(){});
          }catch(_){}
        }).catch(function(){ pToast('Error de conexión'); });
    }).catch(function(){ pToast('Error de conexión'); });
}

